--
-- Name: resolve(uuid, bytea); Type: FUNCTION; Schema: epss_import; Owner: tm_epss_function
--

CREATE FUNCTION epss_import.resolve(execution uuid, raw bytea) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a evidence.collection_attempts;
BEGIN
 IF execution IS NULL OR raw IS NULL THEN RAISE EXCEPTION 'Execution and input required' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(731904216);
 SELECT * INTO a FROM evidence.collection_attempts WHERE id=execution;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF a.connection_id<>'086b7bfe-d067-4213-9681-97b7ebf2b5c7'::uuid OR a.input_fingerprint IS DISTINCT FROM epss_import.fingerprint(raw) THEN
  RAISE EXCEPTION 'Execution input conflict' USING ERRCODE='22023';
 END IF;
 RETURN epss_import.result(a);
END $$;


