    CONSTRAINT collection_attempts_outcome_check CHECK ((outcome = ANY (ARRAY['running'::text, 'success'::text, 'failure'::text, 'cancelled'::text]))),
    CONSTRAINT collection_attempts_revision_check CHECK ((revision > 0))
);


