--
-- Name: score(jsonb); Type: FUNCTION; Schema: epss_import; Owner: tm_epss_function
--

CREATE FUNCTION epss_import.score(value jsonb) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE t text; n numeric;
BEGIN
 IF value IS NULL OR jsonb_typeof(value)<>'string' THEN RAISE EXCEPTION 'Invalid score' USING ERRCODE='22023'; END IF;
 t:=value#>>'{}';
 IF t !~ '^(0|1)(\.[0-9]+)?$' OR length(split_part(t,'.',2))>16383 THEN RAISE EXCEPTION 'Invalid score' USING ERRCODE='22023'; END IF;
 n:=t::numeric;
 IF n<0 OR n>1 THEN RAISE EXCEPTION 'Invalid score' USING ERRCODE='22023'; END IF;
 RETURN n;
END $_$;


