--
-- Name: submit(uuid, bytea); Type: FUNCTION; Schema: epss_import; Owner: tm_epss_function
--

CREATE FUNCTION epss_import.submit(execution uuid, raw bytea) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
 connection constant uuid:='086b7bfe-d067-4213-9681-97b7ebf2b5c7';
 started timestamptz:=clock_timestamp(); digest text; existing jsonb;
 original json; doc jsonb; item jsonb; fixture text; cve text; stamp text; model text;
 prob numeric; pct numeric; content text; record_key text; revision_id uuid; receipt uuid;
 a evidence.collection_attempts; failure text;
BEGIN
 existing:=epss_import.resolve(execution,raw);
 IF existing IS NOT NULL THEN RETURN existing; END IF;
 digest:=epss_import.fingerprint(raw);
 -- All validation and evidence changes are one subtransaction. Failed evidence rolls back.
 BEGIN
  original:=convert_from(raw,'UTF8')::json;
  IF NOT epss_import.unique_keys(original) THEN RAISE EXCEPTION 'Duplicate keys' USING ERRCODE='22023'; END IF;
  doc:=original::jsonb;
  IF jsonb_typeof(doc)<>'object' OR NOT doc ?& ARRAY['origin','fixture_id','data'] OR doc-ARRAY['origin','fixture_id','data']<>'{}'::jsonb
   OR (doc->>'origin') IS DISTINCT FROM 'synthetic' OR jsonb_typeof(doc->'fixture_id')<>'string'
   OR doc->>'fixture_id' !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$' OR jsonb_typeof(doc->'data')<>'array' THEN
   RAISE EXCEPTION 'Invalid synthetic envelope' USING ERRCODE='22023';
  END IF;
  fixture:=doc->>'fixture_id';
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(doc->'data') r GROUP BY r->>'cve',r->>'date' HAVING count(*)>1) THEN
   RAISE EXCEPTION 'Duplicate records' USING ERRCODE='22023';
  END IF;
  -- Validate the whole input before writing evidence.
  FOR item IN SELECT value FROM jsonb_array_elements(doc->'data') LOOP
   IF jsonb_typeof(item)<>'object' OR NOT item ?& ARRAY['cve','epss','date'] OR item-ARRAY['cve','epss','date','percentile','model_version']<>'{}'::jsonb
    OR jsonb_typeof(item->'cve')<>'string' OR item->>'cve' !~ '^CVE-[0-9]{4}-[0-9]{4,}$'
    OR jsonb_typeof(item->'date')<>'string' OR item->>'date' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
    RAISE EXCEPTION 'Invalid record' USING ERRCODE='22023';
   END IF;
   PERFORM (item->>'date')::date;
   IF (item->>'date')::date<'0001-01-01'::date OR (item->>'date')::date>'9999-12-31'::date THEN RAISE EXCEPTION 'Invalid date' USING ERRCODE='22023'; END IF;
   PERFORM epss_import.score(item->'epss');
   IF item->'percentile' IS NOT NULL AND item->'percentile'<>'null'::jsonb THEN PERFORM epss_import.score(item->'percentile'); END IF;
   IF item->'model_version' IS NOT NULL AND item->'model_version'<>'null'::jsonb THEN
    IF jsonb_typeof(item->'model_version')<>'string' OR item->>'model_version' ~ U&'^[\0009-\000D\001C-\0020\0085\00A0\1680\2000-\200A\2028\2029\202F\205F\3000]*$' OR item->>'model_version' ~ U&'[\0001-\001F]' THEN RAISE EXCEPTION 'Invalid model' USING ERRCODE='22023'; END IF;
   END IF;
   -- Existing CVEs can only be reused when already owned by this slice.
   IF EXISTS(SELECT 1 FROM evidence.vulnerabilities v WHERE v.cve_id=item->>'cve') AND NOT EXISTS(
    SELECT 1 FROM evidence.epss_observations e JOIN evidence.observation_receipts r ON r.id=e.receipt_id
    JOIN evidence.collection_attempts t ON t.id=r.collection_attempt_id WHERE t.connection_id=connection AND e.cve_id=item->>'cve') THEN
    RAISE EXCEPTION 'CVE belongs to another scope' USING ERRCODE='22023';
   END IF;
  END LOOP;
  INSERT INTO evidence.collection_attempts(id,connection_id,started_at,outcome,complete,revision,input_fingerprint)
   VALUES(execution,connection,started,'running',false,1,digest);
  FOR item IN SELECT value FROM jsonb_array_elements(doc->'data') LOOP
   cve:=item->>'cve'; stamp:=item->>'date'; model:=item->>'model_version';
   prob:=epss_import.score(item->'epss'); pct:=NULL;
   IF item->'percentile' IS NOT NULL AND item->'percentile'<>'null'::jsonb THEN pct:=epss_import.score(item->'percentile'); END IF;
   content:=epss_import.record_hash(fixture,cve,stamp,prob,pct,model); record_key:=cve||'/'||stamp;
   revision_id:=epss_import.identity('revision',record_key||'/'||content);
   receipt:=epss_import.identity('receipt',execution::text||'/'||revision_id::text);
   INSERT INTO evidence.vulnerabilities(cve_id) VALUES(cve) ON CONFLICT DO NOTHING;
   INSERT INTO evidence.source_revisions(id,connection_id,source_record_id,collected_at,content_hash,origin,licence_or_provenance)
    VALUES(revision_id,connection,record_key,started,content,'synthetic','TriageMate invented fixture: '||fixture)
    ON CONFLICT(connection_id,source_record_id,content_hash) DO NOTHING;
   IF NOT EXISTS(SELECT 1 FROM evidence.source_revisions WHERE id=revision_id AND connection_id=connection AND source_record_id=record_key AND content_hash=content AND origin='synthetic' AND licence_or_provenance='TriageMate invented fixture: '||fixture) THEN
    RAISE EXCEPTION 'Revision identity conflict'; END IF;
   INSERT INTO evidence.observation_receipts(id,source_revision_id,collection_attempt_id) VALUES(receipt,revision_id,execution);
   INSERT INTO evidence.epss_observations(id,cve_id,receipt_id,probability,percentile,score_date,model_version)
    VALUES(epss_import.identity('observation',receipt::text),cve,receipt,prob,pct,stamp::date,model);
  END LOOP;
  UPDATE evidence.collection_attempts SET outcome='success',complete=true,finished_at=clock_timestamp() WHERE id=execution;
  SET CONSTRAINTS ALL IMMEDIATE;
 EXCEPTION WHEN OTHERS THEN
  failure:=CASE WHEN SQLSTATE LIKE '22%' THEN 'invalid_input' ELSE 'persistence_failure' END;
  INSERT INTO evidence.collection_attempts(id,connection_id,started_at,finished_at,outcome,complete,error_code,safe_error_detail,revision,input_fingerprint)
   VALUES(execution,connection,started,clock_timestamp(),'failure',false,failure,'Offline synthetic EPSS import failed; no evidence from this execution was retained.',1,digest);
  SET CONSTRAINTS ALL IMMEDIATE;
 END;
 SELECT * INTO a FROM evidence.collection_attempts WHERE id=execution;
 RETURN epss_import.result(a);
END $_$;


ALTER FUNCTION epss_import.submit(execution uuid, raw bytea) OWNER TO tm_epss_function;

--
-- Name: unique_keys(json); Type: FUNCTION; Schema: epss_import; Owner: tm_epss_function
--

CREATE FUNCTION epss_import.unique_keys(doc json) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE child json;
BEGIN
 IF json_typeof(doc)='object' THEN
  IF EXISTS(SELECT key FROM json_each(doc) GROUP BY key HAVING count(*)>1) THEN RETURN false; END IF;
  FOR child IN SELECT value FROM json_each(doc) LOOP
   IF NOT epss_import.unique_keys(child) THEN RETURN false; END IF;
  END LOOP;
 ELSIF json_typeof(doc)='array' THEN
  FOR child IN SELECT value FROM json_array_elements(doc) LOOP
   IF NOT epss_import.unique_keys(child) THEN RETURN false; END IF;
  END LOOP;
 END IF;
 RETURN true;
END $$;


ALTER FUNCTION epss_import.unique_keys(doc json) OWNER TO tm_epss_function;

--
-- Name: check_device_receipts(); Type: FUNCTION; Schema: evidence; Owner: tm_mock_owner
--

CREATE FUNCTION evidence.check_device_receipts() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE t text; invalid boolean;
BEGIN
 -- A new finding can affect only its own device/receipt binding and duplicate
 -- identity. All parent edits and finding UPDATE/DELETE retain the full scan.
 IF TG_OP='INSERT' AND TG_TABLE_SCHEMA='evidence'
    AND TG_TABLE_NAME='vulnerability_findings' THEN
  IF EXISTS (
   SELECT 1 FROM evidence.vulnerability_findings f
   JOIN evidence.provider_devices p ON p.id=f.provider_device_id
   JOIN evidence.observation_receipts r ON r.id=f.receipt_id
   JOIN evidence.collection_attempts a ON a.id=r.collection_attempt_id
   JOIN evidence.source_connections c ON c.id=a.connection_id
   LEFT JOIN evidence_pipeline.exposure_snapshots s ON s.collection_attempt_id=a.id
   LEFT JOIN evidence_pipeline.input_device_scopes b ON b.input_connection_id=s.input_connection_id
   WHERE f.id=NEW.id AND (
    (p.connection_id<>a.connection_id AND s.collection_attempt_id IS NULL)
    OR ((c.collector_reference LIKE 'evidence-pipeline-v1:%' OR s.collection_attempt_id IS NOT NULL)
     AND (s.collection_attempt_id IS NULL OR c.input_kind<>'findings'
      OR p.connection_id<>b.device_connection_id
      OR NOT EXISTS (
       SELECT 1 FROM evidence.device_observations d
       JOIN evidence.observation_receipts dr ON dr.id=d.receipt_id
       WHERE d.provider_device_id=p.id AND dr.collection_attempt_id=s.device_attempt_id
      )))
   )
  ) THEN RAISE EXCEPTION 'Exposure device is absent from the pinned source snapshot'; END IF;
  IF EXISTS (
   SELECT 1 FROM evidence.vulnerability_findings f
   JOIN evidence.observation_receipts r ON r.id=f.receipt_id
   JOIN evidence_pipeline.exposure_snapshots s ON s.collection_attempt_id=r.collection_attempt_id
   JOIN evidence.observation_receipts other_r ON other_r.collection_attempt_id=s.collection_attempt_id
   JOIN evidence.vulnerability_findings other ON other.receipt_id=other_r.id
    AND other.source_finding_id=f.source_finding_id AND other.id<>f.id
   WHERE f.id=NEW.id
  ) THEN RAISE EXCEPTION 'Duplicate source finding in exposure snapshot'; END IF;
  RETURN NULL;
 END IF;
 -- Child observation inserts perform the complete check at constraint time.
 -- Parent updates still require the full check below.
 IF TG_OP='INSERT' AND TG_TABLE_NAME IN
   ('observation_receipts','collection_attempts','provider_devices') THEN
   RETURN NULL;
 END IF;
    FOREACH t IN ARRAY ARRAY['device_observations','software_observations',
        'classification_observations','vulnerability_findings','vulnerability_events',
        'device_missing_patches','update_policy_observations','antivirus_observations'] LOOP
        EXECUTE format(
            'SELECT EXISTS(SELECT 1 FROM evidence.%I e
             JOIN evidence.provider_devices p ON p.id=e.provider_device_id
             JOIN evidence.observation_receipts r ON r.id=e.receipt_id
             JOIN evidence.collection_attempts a ON a.id=r.collection_attempt_id
             WHERE p.connection_id<>a.connection_id
             AND NOT ($1 IN (''software_observations'',''vulnerability_findings'',''device_missing_patches'',''update_policy_observations'',''antivirus_observations'')
                 AND EXISTS(SELECT 1 FROM evidence_pipeline.exposure_snapshots s
                            WHERE s.collection_attempt_id=a.id)))', t)
            INTO invalid USING t;
        IF invalid THEN RAISE EXCEPTION 'Device and receipt connections differ in %',t; END IF;
    END LOOP;
    PERFORM evidence_pipeline.validate_exposure();
    RETURN NULL;
END $_$;


ALTER FUNCTION evidence.check_device_receipts() OWNER TO tm_mock_owner;

--
-- Name: check_patch_graph(); Type: FUNCTION; Schema: evidence; Owner: tm_mock_owner
--

CREATE FUNCTION evidence.check_patch_graph() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE record_id uuid; match_finding uuid; match_patch uuid;
BEGIN
 IF TG_TABLE_SCHEMA='evidence' AND TG_TABLE_NAME='patch_replacements' THEN
  IF EXISTS(WITH RECURSIVE reach(id) AS (
   SELECT p.superseded_patch_id FROM evidence.patch_replacements p WHERE p.id=NEW.id
   UNION SELECT p.superseded_patch_id FROM reach r
    JOIN evidence.patch_replacements p ON p.patch_id=r.id
  ) SELECT 1 FROM reach r JOIN evidence.patch_replacements p ON p.id=NEW.id
    WHERE r.id=p.patch_id) THEN RAISE EXCEPTION 'Patch supersedence cycle'; END IF;
  RETURN NULL;
 END IF;
 -- These records do not change replacement edges. Validate only synthetic
 -- matches depending on the changed record, against the final transaction state.
 IF TG_TABLE_NAME='mock_fix_matches' THEN
  match_finding := NEW.finding_id; match_patch := NEW.patch_id;
 ELSE
  record_id := NEW.id;
 END IF;
 IF EXISTS(SELECT 1 FROM mock_support.mock_fix_matches m
 JOIN evidence.patch_applicability a ON a.id=m.applicability_id
 JOIN evidence.vulnerability_findings f ON f.id=m.finding_id
 JOIN evidence.software s ON s.id=f.software_id
 WHERE ((TG_TABLE_NAME='mock_fix_matches' AND m.finding_id=match_finding AND m.patch_id=match_patch)
 OR (TG_TABLE_NAME='patch_applicability' AND a.id=record_id)
 OR (TG_TABLE_NAME='vulnerability_findings' AND f.id=record_id)
 OR (TG_TABLE_NAME='software' AND s.id=record_id))
 AND (a.patch_id<>m.patch_id OR a.software_product<>s.product_name
 OR a.publisher IS DISTINCT FROM s.publisher OR a.platform IS DISTINCT FROM s.platform
 OR a.version_expression IS DISTINCT FROM '='||s.version)) THEN
 RAISE EXCEPTION 'Synthetic fix match must agree with exact product/version applicability'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION evidence.check_patch_graph() OWNER TO tm_mock_owner;

--
-- Name: check_provenance(); Type: FUNCTION; Schema: evidence; Owner: tm_mock_owner
--

CREATE FUNCTION evidence.check_provenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 -- Inserts of parents cannot invalidate existing children. Deferred child
 -- triggers validate references even when the child was inserted first.
 IF TG_OP='INSERT' AND TG_TABLE_NAME IN ('source_revisions','collection_attempts') THEN
   RETURN NULL;
 END IF;
 IF TG_OP='INSERT' AND TG_TABLE_NAME='observation_receipts' THEN
   IF EXISTS (SELECT 1 FROM evidence.observation_receipts r
     JOIN evidence.source_revisions v ON v.id=r.source_revision_id
     JOIN evidence.collection_attempts a ON a.id=r.collection_attempt_id
     WHERE r.id=NEW.id AND v.connection_id<>a.connection_id) THEN
     RAISE EXCEPTION 'Receipt revision and attempt connections differ';
   END IF;
   RETURN NULL;
 END IF;
 IF EXISTS (SELECT 1 FROM evidence.observation_receipts r
 JOIN evidence.source_revisions v ON v.id=r.source_revision_id
 JOIN evidence.collection_attempts a ON a.id=r.collection_attempt_id WHERE v.connection_id<>a.connection_id) THEN
 RAISE EXCEPTION 'Receipt revision and attempt connections differ'; END IF;
 IF EXISTS (SELECT 1 FROM mock_support.mock_snapshot_selections s
 JOIN evidence.collection_attempts a ON a.id=s.collection_attempt_id
 WHERE s.connection_id<>a.connection_id OR NOT a.complete OR a.outcome<>'success') THEN
 RAISE EXCEPTION 'Snapshot must select a complete successful attempt on its connection'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION evidence.check_provenance() OWNER TO tm_mock_owner;

--
-- Name: evaluate_completeness(uuid, text, evidence.completeness_cell_input[]); Type: FUNCTION; Schema: evidence; Owner: tm_mock_owner
--

CREATE FUNCTION evidence.evaluate_completeness(definition_id uuid, applicability_state text, cells evidence.completeness_cell_input[]) RETURNS TABLE(completeness integer, completeness_total integer, evaluated_cells evidence.completeness_cell_result[])
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE field record; cell evidence.completeness_cell_input; populated boolean;
BEGIN
 evaluated_cells := ARRAY[]::evidence.completeness_cell_result[];
 IF applicability_state='unresolved' AND definition_id IS NULL THEN
   completeness:=NULL; completeness_total:=NULL; RETURN NEXT; RETURN;
 END IF;
 IF applicability_state IS DISTINCT FROM 'resolved' OR NOT EXISTS (
  SELECT 1 FROM mock_support.completeness_definitions d WHERE d.id=definition_id
 ) THEN RAISE EXCEPTION 'Unknown completeness definition or applicability'; END IF;
 IF cells IS NULL THEN RAISE EXCEPTION 'Cells must be a typed array'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(cells) c GROUP BY c.field_key HAVING count(*)>1) THEN
  RAISE EXCEPTION 'Duplicate completeness field'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(cells) c LEFT JOIN mock_support.completeness_fields f
  ON f.definition_id=evaluate_completeness.definition_id AND f.field_key=c.field_key
  WHERE f.field_key IS NULL OR c.value_kind IS DISTINCT FROM f.value_kind
  OR num_nonnulls(c.boolean_value,c.numeric_value,c.text_value)>1
  OR (c.value_kind<>'boolean' AND c.boolean_value IS NOT NULL)
  OR (c.value_kind<>'number' AND c.numeric_value IS NOT NULL)
  OR (c.value_kind<>'text' AND c.text_value IS NOT NULL)) THEN
  RAISE EXCEPTION 'Invalid completeness cell or type'; END IF;
 completeness:=0; completeness_total:=0;
 FOR field IN SELECT f.field_key,f.value_kind FROM mock_support.completeness_fields f
  WHERE f.definition_id=evaluate_completeness.definition_id ORDER BY f.field_key LOOP
  SELECT c.* INTO cell FROM unnest(cells) c WHERE c.field_key=field.field_key;
  populated := CASE field.value_kind WHEN 'boolean' THEN cell.boolean_value IS NOT NULL
   WHEN 'number' THEN cell.numeric_value IS NOT NULL
   ELSE cell.text_value IS NOT NULL AND cell.text_value !~ '^\s*$' END;
  completeness_total:=completeness_total+1;
  IF populated THEN completeness:=completeness+1; END IF;
  evaluated_cells:=array_append(evaluated_cells,ROW(field.field_key,field.value_kind,
   cell.boolean_value,cell.numeric_value,cell.text_value,cell.source_receipt_id,populated)::evidence.completeness_cell_result);
 END LOOP;
 RETURN NEXT;
END $_$;


ALTER FUNCTION evidence.evaluate_completeness(definition_id uuid, applicability_state text, cells evidence.completeness_cell_input[]) OWNER TO tm_mock_owner;

--
-- Name: application_cpe_criterion(jsonb, jsonb, text, text); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.application_cpe_criterion(criterion jsonb, facts jsonb, product text, cpe_product text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE identity_check jsonb; parts text[]; part text; architecture text; candidate bigint[];
 lower_key bigint[]; upper_key bigint[]; exact_key bigint[]; bound_key bigint[]; bound_name text;
 lower_exclusive boolean := false; upper_exclusive boolean := false; inside boolean := true;
 has_bounds boolean := false; ordering integer; i integer; reason text; state text := 'unknown';
BEGIN
 candidate := evidence_pipeline.windows_app_version_key(facts->>'version');
 IF candidate IS NULL OR cardinality(candidate)<>4 OR jsonb_typeof(facts->'version') IS DISTINCT FROM 'string' THEN RETURN jsonb_build_object('state','unknown','reason','missing_or_invalid_application_version'); END IF;
 IF facts->>'product' IS DISTINCT FROM product OR facts->>'platform' IS DISTINCT FROM 'windows' THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_application_cpe_identity'); END IF;
 IF jsonb_typeof(criterion) IS DISTINCT FROM 'object' THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_criterion_fields'); END IF;
 IF criterion-ARRAY['criteria','vulnerable','matchCriteriaId','versionStartIncluding','versionStartExcluding','versionEndIncluding','versionEndExcluding']<>'{}'::jsonb OR jsonb_typeof(criterion->'vulnerable') IS DISTINCT FROM 'boolean' THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_criterion_fields'); END IF;
 parts := CASE WHEN jsonb_typeof(criterion->'criteria')='string' AND length(criterion->>'criteria')<=4096 THEN string_to_array(criterion->>'criteria',':') ELSE ARRAY[]::text[] END;
 IF cardinality(parts)<>13 OR parts[1:5] IS DISTINCT FROM ARRAY['cpe','2.3','a','microsoft',cpe_product] THEN RETURN jsonb_build_object('state','unknown','reason','other_product_or_environment_requires_evidence'); END IF;
 IF parts[11] IN ('android','iphone_os') THEN RETURN jsonb_build_object('state','excluded','reason','explicit_non_windows_target_platform'); END IF;
 IF parts[11] NOT IN ('*','windows') THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_cpe_environment_selector'); END IF;
 FOR i IN 7..13 LOOP
 IF i<>11 AND parts[i]<>'*' THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_cpe_environment_selector'); END IF;
 END LOOP;
 FOREACH bound_name IN ARRAY ARRAY['versionStartIncluding','versionStartExcluding','versionEndIncluding','versionEndExcluding'] LOOP
  IF criterion ? bound_name THEN
   has_bounds := true;
   bound_key := evidence_pipeline.windows_app_version_key(criterion->>bound_name);
   IF bound_key IS NULL OR jsonb_typeof(criterion->bound_name) IS DISTINCT FROM 'string' THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_version_ordering'); END IF;
   IF bound_name IN ('versionStartIncluding','versionStartExcluding') THEN lower_key := bound_key; lower_exclusive := bound_name='versionStartExcluding';
   ELSE upper_key := bound_key; upper_exclusive := bound_name='versionEndExcluding'; END IF;
  END IF;
 END LOOP;
 IF (criterion ? 'versionStartIncluding' AND criterion ? 'versionStartExcluding') OR (criterion ? 'versionEndIncluding' AND criterion ? 'versionEndExcluding') THEN RETURN jsonb_build_object('state','unknown','reason','conflicting_version_bounds'); END IF;
 IF lower_key IS NOT NULL AND upper_key IS NOT NULL THEN
 ordering := evidence_pipeline.windows_app_version_compare(lower_key,upper_key);
 IF ordering IS NULL THEN RETURN jsonb_build_object('state','unknown','reason','ambiguous_version_components'); END IF;
 IF ordering>0 OR (ordering=0 AND (lower_exclusive OR upper_exclusive)) THEN RETURN jsonb_build_object('state','unknown','reason','empty_or_reversed_version_bounds'); END IF;
 END IF;
 IF parts[6]<>'*' THEN
  exact_key := evidence_pipeline.windows_app_version_key(parts[6]);
  IF exact_key IS NULL OR has_bounds THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_exact_version_and_range_combination'); END IF;
  ordering := evidence_pipeline.windows_app_version_compare(candidate,exact_key);
 IF ordering IS NULL THEN RETURN jsonb_build_object('state','unknown','reason','ambiguous_version_components'); END IF;
 inside := ordering=0; reason := 'explicit_exact_application_version';
 ELSIF NOT has_bounds THEN inside := true; reason := 'explicit_application_version_bounds';
 ELSE
  FOREACH bound_name IN ARRAY ARRAY['versionStartIncluding','versionStartExcluding','versionEndIncluding','versionEndExcluding'] LOOP
   IF criterion ? bound_name THEN
    ordering := evidence_pipeline.windows_app_version_compare(candidate,evidence_pipeline.windows_app_version_key(criterion->>bound_name));
    IF ordering IS NULL THEN RETURN jsonb_build_object('state','unknown','reason','ambiguous_version_components'); END IF;
    inside := inside AND CASE bound_name WHEN 'versionStartIncluding' THEN ordering>=0 WHEN 'versionStartExcluding' THEN ordering>0 WHEN 'versionEndIncluding' THEN ordering<=0 ELSE ordering<0 END;
   END IF;
  END LOOP;
  reason := 'explicit_application_version_bounds';
 END IF;
 state := CASE WHEN inside THEN 'matched' ELSE 'excluded' END;
 RETURN jsonb_build_object('state',state,'reason',reason);
END $$;


ALTER FUNCTION evidence_pipeline.application_cpe_criterion(criterion jsonb, facts jsonb, product text, cpe_product text) OWNER TO tm_mock_owner;

--
-- Name: application_cpe_group(jsonb, jsonb, boolean, text, text); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.application_cpe_group(item jsonb, facts jsonb, is_root boolean, product text, cpe_product text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE key text := CASE WHEN is_root THEN 'nodes' ELSE 'cpeMatch' END;
 children jsonb; evaluated jsonb := '[]'; child jsonb; result jsonb; op text; truth boolean;
BEGIN
 IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item-ARRAY[key,'operator','negate']<>'{}'::jsonb THEN RETURN evidence_pipeline.windows_cpe_unknown('unsupported_configuration_fields'); END IF;
 children := item->key;
 IF jsonb_typeof(children) IS DISTINCT FROM 'array' THEN RETURN evidence_pipeline.windows_cpe_unknown('empty_or_invalid_configuration'); END IF;
 IF jsonb_array_length(children)=0 THEN RETURN evidence_pipeline.windows_cpe_unknown('empty_or_invalid_configuration'); END IF;
 op := item->>'operator';
 IF op IS NULL AND is_root AND jsonb_array_length(children)=1 THEN op := 'OR'; END IF;
 IF op IS NULL OR op NOT IN ('AND','OR') OR (item ? 'negate' AND jsonb_typeof(item->'negate') IS DISTINCT FROM 'boolean') THEN RETURN evidence_pipeline.windows_cpe_unknown('unsupported_configuration_operator'); END IF;
 FOR child IN SELECT value FROM jsonb_array_elements(children) LOOP
  IF is_root THEN result := evidence_pipeline.application_cpe_group(child,facts,false,product,cpe_product);
  ELSE
   result := evidence_pipeline.application_cpe_criterion(child,facts,product,cpe_product);
   truth := CASE result->>'state' WHEN 'matched' THEN true WHEN 'excluded' THEN false ELSE NULL END;
   result := jsonb_build_object('truth',truth,'witness',CASE WHEN child->'vulnerable'='true'::jsonb THEN truth ELSE false END,'negative_witness',false,'reason',result->>'reason');
  END IF;
  evaluated := evaluated || jsonb_build_array(result);
 END LOOP;
 RETURN evidence_pipeline.windows_cpe_combine(evaluated,op,COALESCE((item->>'negate')::boolean,false));
END $$;


ALTER FUNCTION evidence_pipeline.application_cpe_group(item jsonb, facts jsonb, is_root boolean, product text, cpe_product text) OWNER TO tm_mock_owner;

--
-- Name: application_cpe_status(jsonb, jsonb, text, text); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.application_cpe_status(configurations jsonb, facts jsonb, product text, cpe_product text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE item jsonb; evaluated jsonb := '[]'; result jsonb; state text;
BEGIN
 IF jsonb_typeof(configurations) IS DISTINCT FROM 'array' THEN result := evidence_pipeline.windows_cpe_unknown('empty_or_invalid_configurations');
 ELSIF jsonb_array_length(configurations)=0 THEN result := evidence_pipeline.windows_cpe_unknown('empty_or_invalid_configurations');
 ELSE
  FOR item IN SELECT value FROM jsonb_array_elements(configurations) LOOP
   evaluated := evaluated || jsonb_build_array(evidence_pipeline.application_cpe_group(item,facts,true,product,cpe_product));
  END LOOP;
  result := evidence_pipeline.windows_cpe_combine(evaluated,'OR');
 END IF;
 state := CASE WHEN result->'truth'='false'::jsonb THEN 'excluded' WHEN result->'witness'='true'::jsonb THEN 'matched' ELSE 'unknown' END;
 RETURN jsonb_build_object('state',state,'reason','evaluated_application_cpe_conditions','conditions',result);
END $$;


ALTER FUNCTION evidence_pipeline.application_cpe_status(configurations jsonb, facts jsonb, product text, cpe_product text) OWNER TO tm_mock_owner;

--
-- Name: check_assessment_projection(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_assessment_projection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source_kind text; revision_record text;
BEGIN
 SELECT c.input_kind,rev.source_record_id INTO source_kind,revision_record
 FROM evidence.observation_receipts r
 JOIN evidence.collection_attempts a ON a.id=r.collection_attempt_id
 JOIN evidence.source_connections c ON c.id=a.connection_id
 JOIN evidence.source_revisions rev ON rev.id=r.source_revision_id AND rev.connection_id=c.id
 WHERE r.id=NEW.receipt_id AND c.source_name='Defender';
 IF source_kind IS NULL OR source_kind NOT IN ('vulnerability_baseline','vulnerability_events')
 OR NEW.cve_id IS DISTINCT FROM NEW.claim->>'cve_id'
 OR NEW.event_kind IS DISTINCT FROM NEW.claim->>'event_kind'
 OR NEW.event_time_text IS DISTINCT FROM NEW.claim->>'event_time_raw'
 OR NEW.event_time_utc IS DISTINCT FROM (NEW.claim->>'event_time_utc')::timestamptz
 OR NEW.event_fingerprint IS DISTINCT FROM NEW.claim->>'fingerprint'
 OR NEW.event_fingerprint IS DISTINCT FROM revision_record
 OR jsonb_typeof(NEW.instance_key::jsonb) IS DISTINCT FROM 'array'
 OR jsonb_array_length(NEW.instance_key::jsonb)<>3
 OR NEW.instance_key::jsonb->>0 IS DISTINCT FROM NEW.claim->>'native_device_id'
 OR NEW.instance_key::jsonb->>1 IS DISTINCT FROM NEW.claim->'product'->>'id'
 OR NEW.instance_key::jsonb->>2 IS DISTINCT FROM NEW.cve_id
 OR (source_kind='vulnerability_baseline' AND (NEW.event_kind IS NOT NULL OR NEW.event_time_text IS NOT NULL OR NEW.event_time_utc IS NOT NULL))
 OR (source_kind='vulnerability_events' AND (NEW.event_kind IS NULL OR NEW.event_time_text IS NULL))
 THEN RAISE EXCEPTION 'Assessment projection differs from retained source'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION evidence_pipeline.check_assessment_projection() OWNER TO tm_mock_owner;

--
-- Name: check_assessment_run(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_assessment_run() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source_kind text; source_id uuid; baseline_id uuid; expected_id uuid; expected_since timestamptz; started timestamptz;
BEGIN
 PERFORM pg_advisory_xact_lock(731904217);
 SELECT c.input_kind,c.id,b.baseline_connection_id,a.started_at
 INTO source_kind,source_id,baseline_id,started
 FROM evidence.collection_attempts a JOIN evidence.source_connections c ON c.id=a.connection_id
 JOIN evidence_pipeline.assessment_bindings b ON b.connection_id=c.id WHERE a.id=NEW.attempt_id;
 IF source_kind='vulnerability_baseline' THEN
  IF NEW.predecessor_attempt_id IS NOT NULL OR NEW.since_time IS NOT NULL OR baseline_id IS NOT NULL
  THEN RAISE EXCEPTION 'Baseline cannot use delta checkpoint'; END IF;
 ELSIF source_kind='vulnerability_events' THEN
  SELECT r.attempt_id,r.next_since_time INTO expected_id,expected_since
  FROM evidence_pipeline.assessment_runs r JOIN evidence.collection_attempts a ON a.id=r.attempt_id
  WHERE a.connection_id IN (source_id,baseline_id) AND a.complete AND a.outcome='success'
   AND r.attempt_id<>NEW.attempt_id
  ORDER BY a.finished_at DESC,a.id DESC LIMIT 1;
  IF expected_id IS NULL OR NEW.predecessor_attempt_id IS DISTINCT FROM expected_id
   OR NEW.since_time IS DISTINCT FROM expected_since
  THEN RAISE EXCEPTION 'Assessment checkpoint differs from committed predecessor'; END IF;
 ELSE RAISE EXCEPTION 'Invalid assessment input kind'; END IF;
 IF NEW.next_since_time IS DISTINCT FROM GREATEST(NEW.since_time,started-interval '6 hours')
 THEN RAISE EXCEPTION 'Assessment checkpoint skips source overlap'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION evidence_pipeline.check_assessment_run() OWNER TO tm_mock_owner;

--
-- Name: check_assessment_window(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_assessment_window() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE started timestamptz;
BEGIN
 SELECT a.started_at INTO started FROM evidence.collection_attempts a WHERE a.id=NEW.attempt_id;
 IF NEW.since_time IS NOT NULL AND (NEW.since_time < started - interval '14 days' OR NEW.since_time > started)
 THEN RAISE EXCEPTION 'Assessment request exceeds provider history window'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION evidence_pipeline.check_assessment_window() OWNER TO tm_mock_owner;

--
-- Name: check_catalogue(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_catalogue() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT EXISTS (
  SELECT 1 FROM evidence.observation_receipts r
  JOIN evidence.collection_attempts a ON a.id=r.collection_attempt_id
  JOIN evidence.source_connections c ON c.id=a.connection_id
  JOIN evidence.source_revisions rev ON rev.id=r.source_revision_id AND rev.connection_id=c.id
  JOIN evidence_pipeline.authorized_connections auth ON auth.connection_id=c.id AND auth.origin=rev.origin
  WHERE r.id=NEW.receipt_id AND a.complete AND a.outcome='success'
   AND c.source_name='Defender' AND c.input_kind='vulnerability_catalogue'
   AND rev.source_record_id=('[' || '"catalogue","' || NEW.cve_id || '"]')
 ) THEN RAISE EXCEPTION 'Catalogue receipt/source identity mismatch'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION evidence_pipeline.check_catalogue() OWNER TO tm_mock_owner;

--
-- Name: check_component_assessment_results(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_component_assessment_results() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF EXISTS (
  SELECT 1 FROM new_component_results r
  JOIN evidence_pipeline.component_check_runs c ON c.id=r.check_id
  JOIN evidence_pipeline.windows_inventory_observations o ON o.receipt_id=r.receipt_id
  WHERE o.attempt_id<>c.inventory_attempt_id
   OR r.result->>'kind' IS DISTINCT FROM o.kind
   OR r.result->>'native_id' IS DISTINCT FROM o.native_id
   OR r.result->>'version' IS DISTINCT FROM o.facts->>'version'
 ) THEN RAISE EXCEPTION 'Component result differs from exact inventory observation'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION evidence_pipeline.check_component_assessment_results() OWNER TO tm_mock_owner;

--
-- Name: check_component_assessment_run(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_component_assessment_run() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM evidence_pipeline.component_check_seals WHERE check_id=NEW.id)
 THEN RAISE EXCEPTION 'Component assessment is not sealed'; END IF;
 IF NOT EXISTS (
  SELECT 1 FROM evidence.collection_attempts a
  JOIN evidence_pipeline.windows_inventory_runs w ON w.attempt_id=a.id
  JOIN evidence_pipeline.windows_inventory_bindings b ON b.connection_id=a.connection_id
  JOIN evidence_pipeline.authorized_connections auth ON auth.connection_id=a.connection_id
  JOIN evidence.source_connections c ON c.id=a.connection_id
  JOIN evidence.microsoft_tenants t ON t.id=c.tenant_id
  WHERE a.id=NEW.inventory_attempt_id AND a.complete AND a.outcome='success'
   AND NEW.metadata->>'inventory_sha256'=a.input_fingerprint
   AND NEW.metadata->>'origin'=auth.origin
   AND NEW.metadata->'binding'->>'machine_guid'=b.machine_guid::text
   AND NEW.metadata->'binding'->>'device_id'=b.entra_device_id::text
   AND NEW.metadata->'binding'->>'tenant_id'=t.external_tenant_id
   AND (NEW.metadata->>'observed_at')::timestamptz BETWEEN a.started_at AND a.finished_at
   AND NEW.metadata->'result_count'=to_jsonb(w.record_count)
 ) THEN RAISE EXCEPTION 'Component assessment must match exact inventory device, source and time'; END IF;
 IF NEW.metadata->'result_count' IS DISTINCT FROM
    (SELECT to_jsonb(count(*)) FROM evidence_pipeline.component_check_results r WHERE r.check_id=NEW.id)
 THEN RAISE EXCEPTION 'Component assessment result set is incomplete'; END IF;
 IF EXISTS (
   SELECT 1 FROM jsonb_array_elements(NEW.metadata->'sources') anchor
   WHERE NOT EXISTS (SELECT 1 FROM evidence_pipeline.component_check_source_chunks s
     WHERE s.check_id=NEW.id AND s.source_sha256=anchor->>'sha256')
 ) OR NOT EXISTS (
   SELECT 1 FROM evidence_pipeline.component_check_source_chunks s
   WHERE s.check_id=NEW.id AND s.source_sha256=NEW.metadata->>'inventory_sha256'
 ) THEN RAISE EXCEPTION 'Component assessment source evidence is incomplete'; END IF;
 IF EXISTS (
   SELECT source_sha256 FROM evidence_pipeline.component_check_source_chunks
   WHERE check_id=NEW.id GROUP BY source_sha256
   HAVING min(chunk_number)<>0 OR max(chunk_number)<>count(*)-1
 ) THEN RAISE EXCEPTION 'Component assessment source chunks are incomplete'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION evidence_pipeline.check_component_assessment_run() OWNER TO tm_mock_owner;

--
-- Name: check_cve_projection(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_cve_projection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE claim jsonb; total integer;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM evidence.collection_attempts a
 JOIN evidence.source_connections c ON c.id=a.connection_id
 WHERE a.id=NEW.collection_attempt_id
 AND (c.source_name,c.input_kind) IN (('CVE','records'),('CISA','vulnrichment')))
 THEN RETURN NULL; END IF;
 claim := evidence_pipeline.cve_receipt_claim(NEW.id);
 IF claim IS NULL OR jsonb_typeof(claim->'projection') IS DISTINCT FROM 'array'
 THEN RAISE EXCEPTION 'CVE receipt requires complete authorized claim'; END IF;
 SELECT count(*) INTO total FROM evidence.cve_record_observations WHERE receipt_id=NEW.id;
 IF total <> 1 THEN RAISE EXCEPTION 'CVE record projection missing'; END IF;
 SELECT count(*)+1 INTO total FROM evidence.cve_contributions WHERE receipt_id=NEW.id;
 IF total <> jsonb_array_length(claim->'projection')
 THEN RAISE EXCEPTION 'CVE contributor projection incomplete'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION evidence_pipeline.check_cve_projection() OWNER TO tm_mock_owner;

--
-- Name: check_cvrf_projection(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_cvrf_projection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE target uuid; claim jsonb; recipe jsonb; field jsonb; expected jsonb; actual jsonb;
 identities jsonb; observed_rows jsonb; mapped jsonb;
 entity uuid; linked uuid; row_number integer := 0; table_name text; total integer; source_record text;
BEGIN
 target := NEW.id;
 IF NOT EXISTS(SELECT 1 FROM evidence.observation_receipts r
 JOIN evidence.collection_attempts a ON a.id=r.collection_attempt_id
 JOIN evidence.source_connections c ON c.id=a.connection_id
 WHERE r.id=target AND c.source_name='MSRC' AND c.input_kind='security_updates')
 THEN RETURN NULL; END IF;
 IF NOT evidence_pipeline.is_cvrf_receipt(target) THEN
 RAISE EXCEPTION 'CVRF receipt requires a complete authorized source claim'; END IF;
 SELECT p.claim::jsonb,rev.source_record_id INTO claim,source_record
 FROM evidence.observation_receipts r
 JOIN evidence.source_revisions rev ON rev.id=r.source_revision_id
 JOIN evidence_pipeline.public_claims p ON p.source_revision_id=r.source_revision_id WHERE r.id=target;
 IF NOT (
   (claim->>'adapter'='msrc-cvrf-updates-v1'
    AND claim->'record'->>'cve_id'=source_record
    AND source_record ~ '^CVE-[0-9]{4}-[0-9]{4,}$')
   OR (claim->>'adapter'='msrc-cvrf-advisory-v1'
    AND claim->'record'->>'native_id'=source_record
    AND source_record ~ '^(ADV[0-9]{6}|CVE-[0-9]{4}-[0-9]{4,}(-M| - M| mariner - do not use this one))$'
    AND NOT (claim->'record' ? 'cve_id')
    AND claim->'source_vulnerability'->>'CVE'=source_record)
 ) IS TRUE OR jsonb_typeof(claim->'projection') IS DISTINCT FROM 'array'
 THEN RAISE EXCEPTION 'Invalid CVRF source claim'; END IF;
 SELECT count(*) INTO total FROM evidence_pipeline.cvrf_projection WHERE receipt_id=target;
 IF total <> jsonb_array_length(claim->'projection')
 OR NOT EXISTS(SELECT 1 FROM evidence_pipeline.cvrf_batches b WHERE b.receipt_id=target AND b.row_count=total)
 THEN RAISE EXCEPTION 'Incomplete CVRF projection map'; END IF;
 -- These receipt-local lookup objects replace repeated per-field SQL reads.
 -- The existing claim, recipe, row-value and unclaimed-row checks remain below.
 SELECT jsonb_object_agg(m.row_index::text,jsonb_build_object('entity_id',m.entity_id,'table_name',m.table_name))
 INTO identities FROM evidence_pipeline.cvrf_projection m WHERE m.receipt_id=target;
 SELECT jsonb_object_agg(kind||'/'||id::text,value) INTO observed_rows FROM (
  SELECT 'patches'::text AS kind,id,to_jsonb(p) AS value FROM evidence.patches p WHERE receipt_id=target
  UNION ALL SELECT 'patch_vulnerabilities',id,to_jsonb(v) FROM evidence.patch_vulnerabilities v WHERE receipt_id=target
  UNION ALL SELECT 'patch_applicability',id,to_jsonb(a) FROM evidence.patch_applicability a WHERE receipt_id=target
  UNION ALL SELECT 'patch_replacements',id,to_jsonb(r) FROM evidence.patch_replacements r WHERE receipt_id=target
 ) rows;
 FOR recipe IN SELECT value FROM jsonb_array_elements(claim->'projection') LOOP
  table_name := recipe->>0;
  IF claim->>'adapter'='msrc-cvrf-advisory-v1' AND table_name='patch_vulnerabilities'
  THEN RAISE EXCEPTION 'Native advisory cannot assert a CVE relationship'; END IF;
  IF table_name NOT IN ('patches','patch_vulnerabilities','patch_applicability','patch_replacements')
  OR jsonb_typeof(recipe->1) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid CVRF recipe'; END IF;
  mapped := identities->row_number::text;
  entity := CASE WHEN mapped->>'table_name'=recipe->>0 THEN (mapped->>'entity_id')::uuid ELSE NULL END;
  IF entity IS NULL THEN RAISE EXCEPTION 'Missing CVRF projection identity'; END IF;
  expected := jsonb_build_object('id',entity,'receipt_id',target);
  FOR field IN SELECT value FROM jsonb_array_elements(recipe->1) LOOP
   IF jsonb_typeof(field->1)='object' THEN
    IF field->>0 NOT IN ('patch_id','superseded_patch_id') OR NOT (field->1 ? 'row_reference')
    OR (field->1->>'row_reference')::integer >= row_number
    OR claim->'projection'->((field->1->>'row_reference')::integer)->>0 IS DISTINCT FROM 'patches'
    THEN RAISE EXCEPTION 'Invalid CVRF relationship reference'; END IF;
    linked := (identities->((field->1->>'row_reference')::integer)::text->>'entity_id')::uuid;
    IF linked IS NULL THEN RAISE EXCEPTION 'Missing CVRF relationship target'; END IF;
    expected := expected || jsonb_build_object(field->>0,linked);
   ELSE
    expected := expected || jsonb_build_object(field->>0,field->1);
   END IF;
  END LOOP;
  actual := observed_rows->(table_name||'/'||entity::text);
  IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'CVRF projection differs from retained claim'; END IF;
  row_number := row_number + 1;
 END LOOP;
 FOREACH table_name IN ARRAY ARRAY['patches','patch_vulnerabilities','patch_applicability','patch_replacements'] LOOP
  EXECUTE format('SELECT count(*) FROM evidence.%I t WHERE receipt_id=$1 AND NOT EXISTS (SELECT 1 FROM evidence_pipeline.cvrf_projection m WHERE m.receipt_id=t.receipt_id AND m.entity_id=t.id)',table_name) INTO total USING target;
  IF total <> 0 THEN RAISE EXCEPTION 'Unclaimed CVRF projection'; END IF;
 END LOOP;
 RETURN NULL;
END $_$;


ALTER FUNCTION evidence_pipeline.check_cvrf_projection() OWNER TO tm_mock_owner;

--
-- Name: check_defender_recommendation(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_defender_recommendation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source_claim jsonb; recommendation evidence.recommendations%ROWTYPE;
BEGIN
 SELECT c.claim INTO source_claim FROM evidence_pipeline.recommendation_claims c WHERE c.receipt_id=NEW.receipt_id;
 IF source_claim IS NULL THEN RETURN NULL; END IF;
 IF (SELECT count(*) FROM evidence.recommendations r WHERE r.receipt_id=NEW.receipt_id)<>1
 THEN RAISE EXCEPTION 'Defender recommendation projection must be unique and complete'; END IF;
 SELECT * INTO recommendation FROM evidence.recommendations r WHERE r.receipt_id=NEW.receipt_id;
 IF recommendation.source_recommendation_id IS DISTINCT FROM source_claim->>'source_id'
 OR recommendation.advisory_id IS NOT NULL OR recommendation.recommendation_text IS NOT NULL
 OR recommendation.title IS DISTINCT FROM source_claim->'fields'->>'title'
 OR recommendation.vendor IS DISTINCT FROM source_claim->'fields'->>'vendor'
 OR recommendation.product_name IS DISTINCT FROM source_claim->'fields'->>'product_name'
 OR recommendation.recommended_version IS DISTINCT FROM source_claim->'fields'->>'recommended_version'
 OR recommendation.recommended_program IS DISTINCT FROM source_claim->'fields'->>'recommended_program'
 OR recommendation.recommended_vendor IS DISTINCT FROM source_claim->'fields'->>'recommended_vendor'
 OR recommendation.category IS DISTINCT FROM source_claim->'fields'->>'category'
 OR recommendation.subcategory IS DISTINCT FROM source_claim->'fields'->>'subcategory'
 OR recommendation.remediation_type IS DISTINCT FROM source_claim->'fields'->>'remediation_type'
 OR recommendation.source_status IS DISTINCT FROM source_claim->'fields'->>'source_status'
 THEN RAISE EXCEPTION 'Defender recommendation fields differ from retained source'; END IF;
 IF EXISTS (SELECT 1 FROM evidence_pipeline.recommendation_device_references refs
 WHERE refs.receipt_id=NEW.receipt_id AND refs.provider_device_id IS NOT NULL
 AND NOT EXISTS(SELECT 1 FROM evidence.recommendation_devices d
 WHERE d.recommendation_id=refs.recommendation_id AND d.provider_device_id=refs.provider_device_id AND d.receipt_id=refs.receipt_id))
 THEN RAISE EXCEPTION 'Defender recommendation device projection incomplete'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION evidence_pipeline.check_defender_recommendation() OWNER TO tm_mock_owner;

--
-- Name: check_exposure(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_exposure() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='INSERT' AND TG_TABLE_SCHEMA='evidence'
    AND TG_TABLE_NAME='observation_receipts' THEN
  RETURN NULL;
 END IF;
 -- These child INSERTs already execute check_device_receipts(), whose complete
 -- exposure validation runs at the same deferred-constraint boundary. Keep its
 -- check and avoid this second copy. UPDATE/DELETE paths remain unchanged.
 IF TG_OP='INSERT' AND TG_TABLE_SCHEMA='evidence' AND TG_TABLE_NAME IN
   ('device_observations','software_observations','vulnerability_findings',
    'device_missing_patches','update_policy_observations','antivirus_observations') THEN
  RETURN NULL;
 END IF;
 IF TG_OP='INSERT' AND TG_TABLE_SCHEMA='evidence' AND TG_TABLE_NAME='patches' THEN
  IF NOT EXISTS (SELECT 1 FROM evidence.device_missing_patches p
                 WHERE p.patch_id=NEW.id) THEN
   RETURN NULL;
  END IF;
 END IF;
 PERFORM evidence_pipeline.validate_exposure();
 RETURN NULL;
END $$;


ALTER FUNCTION evidence_pipeline.check_exposure() OWNER TO tm_mock_owner;

--
-- Name: check_lab_connections(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_lab_connections() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM evidence_pipeline.authorized_connections a
        JOIN evidence.source_connections c ON c.id=a.connection_id
        LEFT JOIN evidence.microsoft_tenants t ON t.id=c.tenant_id
        WHERE (a.origin='lab' AND (t.evidence_origin IS DISTINCT FROM 'lab'
            OR c.source_name NOT IN ('Entra','Intune','Defender','Windows inventory')))
           OR (t.evidence_origin='lab' AND a.origin<>'lab')
    ) THEN RAISE EXCEPTION 'Lab connection origin and tenant must agree'; END IF;
    IF EXISTS (
        SELECT 1 FROM evidence.source_revisions r
        JOIN evidence.source_connections c ON c.id=r.connection_id
        LEFT JOIN evidence_pipeline.authorized_connections a ON a.connection_id=c.id
        LEFT JOIN evidence.microsoft_tenants t ON t.id=c.tenant_id
        WHERE r.origin='lab' AND (a.origin IS DISTINCT FROM 'lab'
            OR t.evidence_origin IS DISTINCT FROM 'lab'
            OR c.source_name NOT IN ('Entra','Intune','Defender','Windows inventory'))
    ) THEN RAISE EXCEPTION 'Existing lab revisions require registered lab authority'; END IF;
    RETURN NULL;
END $$;


ALTER FUNCTION evidence_pipeline.check_lab_connections() OWNER TO tm_mock_owner;

--
-- Name: check_lab_revision(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_lab_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NEW.origin='lab' AND NOT EXISTS (
        SELECT 1 FROM evidence.source_connections c
        JOIN evidence_pipeline.authorized_connections a ON a.connection_id=c.id
        JOIN evidence.microsoft_tenants t ON t.id=c.tenant_id
        WHERE c.id=NEW.connection_id AND a.origin='lab' AND t.evidence_origin='lab'
          AND c.source_name IN ('Entra','Intune','Defender','Windows inventory')
    ) THEN RAISE EXCEPTION 'Lab revision requires a registered Microsoft lab connection'; END IF;
    RETURN NULL;
END $$;


ALTER FUNCTION evidence_pipeline.check_lab_revision() OWNER TO tm_mock_owner;

--
-- Name: check_osv_projection(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_osv_projection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE claim jsonb; total integer; expected integer; target_table text;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM evidence.collection_attempts a
 JOIN evidence.source_connections c ON c.id=a.connection_id
 WHERE a.id=NEW.collection_attempt_id AND c.source_name IN ('OSV','GitHub','Ubuntu') AND c.input_kind='advisories')
 THEN RETURN NULL; END IF;
 claim := evidence_pipeline.osv_receipt_claim(NEW.id);
 IF claim IS NULL OR jsonb_typeof(claim->'projection') IS DISTINCT FROM 'array'
 THEN RAISE EXCEPTION 'OSV receipt requires complete authorized claim'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(claim->'projection') p
 WHERE p.value->>0 IS NULL OR p.value->>0 NOT IN ('osv_advisory_observations','osv_aliases','osv_affected_packages'))
 THEN RAISE EXCEPTION 'Unexpected OSV projection table'; END IF;
 SELECT count(*) INTO total FROM evidence.osv_advisory_observations WHERE receipt_id=NEW.id;
 IF total <> 1 THEN RAISE EXCEPTION 'OSV advisory projection missing'; END IF;
 FOREACH target_table IN ARRAY ARRAY['osv_advisory_observations','osv_aliases','osv_affected_packages'] LOOP
  SELECT count(*) INTO expected FROM jsonb_array_elements(claim->'projection') p WHERE p.value->>0=target_table;
  EXECUTE format('SELECT count(*) FROM evidence.%I WHERE receipt_id=$1',target_table) INTO total USING NEW.id;
  IF total <> expected THEN RAISE EXCEPTION 'OSV projection incomplete'; END IF;
 END LOOP;
 RETURN NULL;
END $_$;


ALTER FUNCTION evidence_pipeline.check_osv_projection() OWNER TO tm_mock_owner;

--
-- Name: check_osv_query(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_osv_query() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE target uuid; m jsonb; page record; body jsonb; token text;
 tokens text[]:=ARRAY[]::text[]; count_pages integer;
 count_links integer; count_records integer:=0; finished timestamptz;
 previous_finish timestamptz; page_start timestamptz; page_finish timestamptz;
 successful boolean;
BEGIN
 IF TG_TABLE_NAME='collection_attempts' THEN target:=NEW.id; ELSE target:=NEW.attempt_id; END IF;
 IF NOT EXISTS(SELECT 1 FROM evidence.collection_attempts a JOIN evidence.source_connections c ON c.id=a.connection_id
 WHERE a.id=target AND c.source_name='OSV' AND c.input_kind='advisories'
 AND c.scope_reference='https://api.osv.dev/v1/query') THEN RETURN NULL; END IF;
 SELECT b.manifest::jsonb->0,a.complete,a.started_at,a.finished_at INTO m,successful,previous_finish,finished
 FROM evidence_pipeline.osv_query_batches b JOIN evidence.collection_attempts a ON a.id=b.attempt_id
 WHERE b.attempt_id=target;
 IF m IS NULL THEN RAISE EXCEPTION 'OSV query attempt requires its manifest'; END IF;
 SELECT count(*) INTO count_pages
 FROM evidence_pipeline.osv_query_pages WHERE attempt_id=target;
 IF count_pages<>jsonb_array_length(m->'pages')
 OR (successful AND count_pages=0) THEN RAISE EXCEPTION 'OSV query pages incomplete'; END IF;
 FOR page IN SELECT page_index,wire FROM evidence_pipeline.osv_query_pages WHERE attempt_id=target ORDER BY page_index LOOP
  IF page.page_index>=count_pages THEN RAISE EXCEPTION 'OSV query page gap'; END IF;
  page_start:=(m->'pages'->page.page_index->>'started_at')::timestamptz;
  page_finish:=(m->'pages'->page.page_index->>'finished_at')::timestamptz;
  IF page_start IS NULL OR page_finish IS NULL OR page_start<previous_finish
  OR page_finish<page_start OR page_finish>finished THEN RAISE EXCEPTION 'OSV query page times invalid'; END IF;
  previous_finish:=page_finish;
  IF NOT successful THEN CONTINUE; END IF;
  body:=ltrim(convert_from(page.wire,'UTF8'),chr(65279))::jsonb;
  IF jsonb_typeof(body)<>'object' OR (body ? 'vulns' AND jsonb_typeof(body->'vulns')<>'array')
  THEN RAISE EXCEPTION 'OSV query page shape invalid'; END IF;
  -- Expand each page once instead of decoding the entire wire for every link.
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(body->'vulns','[]'::jsonb)) WITH ORDINALITY src(value,position)
   LEFT JOIN evidence_pipeline.osv_query_advisory_links l ON l.attempt_id=target
    AND l.page_index=page.page_index AND l.record_index=src.position-1
   LEFT JOIN evidence.observation_receipts r ON r.id=l.receipt_id
   LEFT JOIN evidence_pipeline.public_claims p ON p.source_revision_id=r.source_revision_id
   WHERE (p.claim::jsonb->>'source_document')::jsonb IS DISTINCT FROM src.value)
  THEN RAISE EXCEPTION 'OSV query source links incomplete or changed'; END IF;
  token:=nullif(body->>'next_page_token','');
  IF (token IS NULL) IS DISTINCT FROM (page.page_index=count_pages-1)
  OR token=ANY(tokens) THEN RAISE EXCEPTION 'OSV query continuation invalid'; END IF;
  IF token IS NOT NULL THEN
   IF jsonb_typeof(body->'next_page_token')<>'string' OR length(token)>4096
   THEN RAISE EXCEPTION 'OSV query token invalid'; END IF;
   tokens:=array_append(tokens,token);
  END IF;
  count_records:=count_records+coalesce(jsonb_array_length(body->'vulns'),0);
 END LOOP;
 SELECT count(*) INTO count_links FROM evidence_pipeline.osv_query_advisory_links WHERE attempt_id=target;
 IF count_links<>count_records THEN RAISE EXCEPTION 'OSV query advisory links incomplete'; END IF;
 IF EXISTS(SELECT 1 FROM evidence.observation_receipts r WHERE r.collection_attempt_id=target
 AND NOT EXISTS(SELECT 1 FROM evidence_pipeline.osv_query_advisory_links l WHERE l.attempt_id=target AND l.receipt_id=r.id))
 THEN RAISE EXCEPTION 'OSV query receipt has no source page'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION evidence_pipeline.check_osv_query() OWNER TO tm_mock_owner;

--
-- Name: check_patch_product_scope(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_patch_product_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW.source_product_id IS NOT NULL AND NOT evidence_pipeline.is_cvrf_receipt(NEW.receipt_id)
 THEN RAISE EXCEPTION 'Product-scoped patch identity requires a CVRF source'; END IF;
