END $$;


ALTER FUNCTION evidence_pipeline.check_patch_product_scope() OWNER TO tm_mock_owner;

--
-- Name: check_reference_projection(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_reference_projection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE total integer;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM evidence.collection_attempts a JOIN evidence.source_connections c ON c.id=a.connection_id
 WHERE a.id=NEW.collection_attempt_id AND evidence_pipeline.reference_source_allowed(c.source_name,c.input_kind,c.scope_reference))
 THEN RETURN NULL; END IF;
 SELECT count(*) INTO total FROM evidence.public_reference_observations WHERE receipt_id=NEW.id;
 IF total<>1 OR evidence_pipeline.reference_claim(NEW.id) IS NULL THEN
 RAISE EXCEPTION 'Reference receipt requires one complete authorized projection'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION evidence_pipeline.check_reference_projection() OWNER TO tm_mock_owner;

--
-- Name: check_selected_component_binding(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_selected_component_binding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT EXISTS (
  SELECT 1 FROM evidence.collection_attempts a
  JOIN evidence_pipeline.windows_inventory_bindings b ON b.connection_id=a.connection_id
  JOIN evidence.source_connections c ON c.id=a.connection_id
  JOIN evidence.microsoft_tenants t ON t.id=c.tenant_id
  JOIN evidence_pipeline.authorized_connections auth ON auth.connection_id=c.id
  WHERE a.id=NEW.inventory_attempt_id AND a.complete AND a.outcome='success'
   AND NEW.report->>'origin'=auth.origin
   AND NEW.report->'binding'->>'machine_guid'=b.machine_guid::text
   AND NEW.report->'binding'->>'device_id'=b.entra_device_id::text
   AND NEW.report->'binding'->>'tenant_id'=t.external_tenant_id
 ) THEN RAISE EXCEPTION 'Selected component capture requires exact registered inventory device'; END IF;
 IF EXISTS (
  SELECT 1 FROM jsonb_array_elements(NEW.report->'rows') r
  WHERE r->>'inventory_receipt_id' IS NOT NULL AND NOT EXISTS (
   SELECT 1 FROM evidence_pipeline.windows_inventory_observations o
   WHERE o.attempt_id=NEW.inventory_attempt_id AND o.receipt_id::text=r->>'inventory_receipt_id'
    AND o.kind='appx' AND o.native_id=r->>'native_id'
    AND o.facts->>'version' IS NOT DISTINCT FROM r->>'version'
    AND o.facts->>'name' IS NOT DISTINCT FROM r->'observed_identity'->>'name'
    AND o.facts->>'family_name' IS NOT DISTINCT FROM r->'observed_identity'->>'family_name'
    AND o.facts->>'publisher' IS NOT DISTINCT FROM r->'observed_identity'->>'publisher'
    AND o.facts->>'architecture' IS NOT DISTINCT FROM r->'observed_identity'->>'architecture'
  )
 ) THEN RAISE EXCEPTION 'Selected component association differs from inventory identity or version'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION evidence_pipeline.check_selected_component_binding() OWNER TO tm_mock_owner;

--
-- Name: check_windows_bundle_members(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_windows_bundle_members() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
 IF EXISTS (
  SELECT 1 FROM evidence_pipeline.windows_inventory_observations m
  LEFT JOIN evidence_pipeline.windows_inventory_observations p
   ON p.attempt_id=m.attempt_id AND p.kind='appx' AND p.native_id=m.facts->>'bundle_native_id'
  WHERE m.attempt_id IN (SELECT attempt_id FROM new_bundle_rows) AND m.kind='appx_bundle_member' AND (
   p.receipt_id IS NULL OR p.facts->'is_bundle' IS DISTINCT FROM 'true'::jsonb
   OR p.facts->'bundle_manifest'->>'state' IS DISTINCT FROM 'read'
   OR p.facts->'bundle_manifest'->>'sha256' IS DISTINCT FROM m.facts->>'manifest_sha256'
   OR p.facts->>'name' IS DISTINCT FROM m.facts->>'name'
   OR p.facts->>'publisher' IS DISTINCT FROM m.facts->>'publisher'
   OR p.facts->>'family_name' IS DISTINCT FROM m.facts->>'family_name'
   OR p.facts->>'version' IS DISTINCT FROM m.facts->>'bundle_version'
   OR (m.facts->>'member_index')::numeric>(p.facts->'bundle_manifest'->>'member_count')::numeric
  )
 ) THEN RAISE EXCEPTION 'Bundle member must pin its exact collection parent'; END IF;
 IF EXISTS (
  SELECT 1 FROM evidence_pipeline.windows_inventory_observations p
  WHERE p.attempt_id IN (SELECT attempt_id FROM new_bundle_rows) AND p.kind='appx' AND p.facts ? 'bundle_manifest' AND (
   jsonb_typeof(p.facts->'bundle_manifest'->'member_count') IS DISTINCT FROM 'number'
   OR p.facts->'bundle_manifest'->>'member_count' !~ '^(0|[1-9][0-9]*)$'
   OR (p.facts->'bundle_manifest'->>'member_count')::numeric <>
    (SELECT count(*) FROM evidence_pipeline.windows_inventory_observations m
     WHERE m.attempt_id=p.attempt_id AND m.kind='appx_bundle_member' AND m.facts->>'bundle_native_id'=p.native_id)
  )
 ) THEN RAISE EXCEPTION 'Bundle declaration count differs from complete source'; END IF;
 RETURN NULL;
END $_$;


ALTER FUNCTION evidence_pipeline.check_windows_bundle_members() OWNER TO tm_mock_owner;

--
-- Name: check_windows_inventory_bindings(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_windows_inventory_bindings() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF EXISTS (
  SELECT 1 FROM evidence_pipeline.windows_inventory_bindings b
  WHERE NOT evidence_pipeline.valid_windows_inventory_binding(b.connection_id)
 ) OR EXISTS (
  SELECT 1 FROM evidence_pipeline.authorized_connections a
  JOIN evidence.source_connections c ON c.id=a.connection_id
  WHERE c.source_name='Windows inventory'
   AND NOT evidence_pipeline.valid_windows_inventory_binding(c.id)
 ) THEN RAISE EXCEPTION 'Windows inventory requires an exact registered device binding'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION evidence_pipeline.check_windows_inventory_bindings() OWNER TO tm_mock_owner;

--
-- Name: check_windows_inventory_records(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_windows_inventory_records() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF EXISTS (
  SELECT 1 FROM new_inventory_rows n
  JOIN evidence.observation_receipts r ON r.id=n.receipt_id
  JOIN evidence.source_revisions v ON v.id=r.source_revision_id
  JOIN evidence.collection_attempts a ON a.id=n.attempt_id
  WHERE r.collection_attempt_id<>n.attempt_id OR v.connection_id<>a.connection_id
   OR NOT evidence_pipeline.valid_windows_inventory_binding(a.connection_id)
 ) THEN RAISE EXCEPTION 'Windows inventory receipt differs from its source run'; END IF;
 IF EXISTS (
  SELECT 1 FROM (SELECT DISTINCT attempt_id FROM new_inventory_rows) affected
  JOIN evidence_pipeline.windows_inventory_runs s ON s.attempt_id=affected.attempt_id
  WHERE s.record_count<>(SELECT count(*) FROM evidence_pipeline.windows_inventory_observations o WHERE o.attempt_id=s.attempt_id)
 ) THEN RAISE EXCEPTION 'Windows inventory observation count differs from complete source'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION evidence_pipeline.check_windows_inventory_records() OWNER TO tm_mock_owner;

--
-- Name: check_windows_inventory_run(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_windows_inventory_run() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT EXISTS (
  SELECT 1 FROM evidence.collection_attempts a
  JOIN evidence_pipeline.windows_inventory_bindings b ON b.connection_id=a.connection_id
  JOIN evidence.collection_attempts d ON d.id=NEW.device_attempt_id AND d.connection_id=b.device_connection_id
  JOIN evidence.provider_devices p ON p.id=NEW.provider_device_id AND p.connection_id=b.device_connection_id
  WHERE a.id=NEW.attempt_id AND a.complete AND a.outcome='success'
   AND d.complete AND d.outcome='success'
   AND p.native_device_id=b.native_device_id AND p.microsoft_registration_id=b.entra_device_id::text
   AND evidence_pipeline.valid_windows_inventory_binding(a.connection_id)
   AND EXISTS (SELECT 1 FROM evidence.device_observations o
    JOIN evidence.observation_receipts r ON r.id=o.receipt_id
    WHERE o.provider_device_id=p.id AND r.collection_attempt_id=d.id)
 ) THEN RAISE EXCEPTION 'Windows inventory must pin its exact complete device evidence'; END IF;
 IF NEW.record_count<>(SELECT count(*) FROM evidence_pipeline.windows_inventory_observations o WHERE o.attempt_id=NEW.attempt_id)
 THEN RAISE EXCEPTION 'Windows inventory observation count differs from complete source'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION evidence_pipeline.check_windows_inventory_run() OWNER TO tm_mock_owner;

--
-- Name: check_windows_os_native_facts(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_windows_os_native_facts() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE bundle jsonb; native jsonb; installed jsonb; identity jsonb; queries jsonb;
 native_time timestamptz; install_time timestamptz; expected_version text;
 requests jsonb; receipt jsonb; page jsonb; label text;
 first_time timestamptz; last_time timestamptz; earliest timestamptz; latest timestamptz;
BEGIN
 bundle:=convert_from(NEW.original_bytes,'UTF8')::jsonb;
 native:=(bundle->'sources'->'native'->>'text')::jsonb;
 installed:=(bundle->'sources'->'installed'->>'text')::jsonb;
 identity:=installed->'identity';
 IF native->>'architecture' IS DISTINCT FROM 'AMD64'
  OR ((native->>'release'='24H2' AND native->>'build'='26100')
   OR (native->>'release'='25H2' AND native->>'build'='26200')) IS NOT TRUE
  OR jsonb_typeof(native->'ubr') IS DISTINCT FROM 'number'
  OR (native->>'ubr' ~ '^[0-9]+$') IS NOT TRUE
  OR jsonb_typeof(identity->'ubr') IS DISTINCT FROM 'number'
  OR identity->'ubr' IS DISTINCT FROM native->'ubr'
  OR identity->>'release' IS DISTINCT FROM native->>'release'
  OR identity->>'architecture' IS DISTINCT FROM 'AMD64'
  OR identity->>'build' IS DISTINCT FROM native->>'build'
 THEN RAISE EXCEPTION 'OS native facts require complete compatible Windows revisions'; END IF;
 expected_version:='10.0.'||(native->>'build')||'.'||(native->>'ubr');
 IF expected_version IS NULL OR NEW.report->>'windows_version' IS DISTINCT FROM expected_version
 THEN RAISE EXCEPTION 'OS native facts require a complete Windows version'; END IF;
 native_time:=(native->>'observed_at')::timestamptz;
 install_time:=(installed->>'observed_at')::timestamptz;
 IF native_time IS NULL OR install_time IS NULL OR (identity->>'observed_at')::timestamptz IS NULL
  OR install_time NOT BETWEEN native_time-interval '24 hours' AND native_time+interval '24 hours'
 THEN RAISE EXCEPTION 'OS native facts require compatible installation observation times'; END IF;
 -- Every review participates in recency ordering, including unresolved identity.
 -- Bind that ordering to the retained receipts before accepting either state.
 requests:=(bundle->'sources'->'requests'->>'text')::jsonb;
 IF jsonb_typeof(requests) IS DISTINCT FROM 'array'
 THEN RAISE EXCEPTION 'OS observation times require retained request receipts'; END IF;
 FOREACH label IN ARRAY ARRAY['devices','software-inventory','vulnerabilities','current-missing-kbs'] LOOP
  IF (SELECT count(*) FROM jsonb_array_elements(requests) r WHERE r->>'label'=label)<>1
  THEN RAISE EXCEPTION 'OS observation times require one receipt per export'; END IF;
  SELECT r INTO receipt FROM jsonb_array_elements(requests) r WHERE r->>'label'=label;
  IF receipt->'complete' IS DISTINCT FROM 'true'::jsonb
   OR jsonb_typeof(receipt->'pages') IS DISTINCT FROM 'array'
   OR jsonb_array_length(receipt->'pages') IS DISTINCT FROM 1
  THEN RAISE EXCEPTION 'OS observation times require complete single-page receipts'; END IF;
  page:=receipt->'pages'->0;
  first_time:=(page->>'started_at')::timestamptz;
  last_time:=(page->>'finished_at')::timestamptz;
  IF first_time IS NULL OR last_time IS NULL OR first_time IN ('infinity'::timestamptz,'-infinity'::timestamptz) OR last_time IN ('infinity'::timestamptz,'-infinity'::timestamptz)
   OR last_time<first_time OR last_time-first_time>interval '1 hour'
   OR last_time NOT BETWEEN native_time-interval '24 hours' AND native_time+interval '24 hours'
   OR (NEW.report->'sources'->(label||'-0')->>'started_at')::timestamptz IS DISTINCT FROM first_time
   OR (NEW.report->'sources'->(label||'-0')->>'finished_at')::timestamptz IS DISTINCT FROM last_time
  THEN RAISE EXCEPTION 'OS observation times require compatible source-backed timestamps'; END IF;
  earliest:=LEAST(earliest,first_time); latest:=GREATEST(latest,last_time);
 END LOOP;
 IF latest-earliest>interval '1 hour'
  OR (NEW.report->>'provider_observed_at')::timestamptz IS DISTINCT FROM latest
 THEN RAISE EXCEPTION 'OS observation times require source-backed review recency'; END IF;
 queries:=bundle->'queried_kbs';
 IF jsonb_typeof(queries) IS DISTINCT FROM 'array' OR jsonb_array_length(queries)=0
  OR (SELECT count(DISTINCT q) FROM jsonb_array_elements(queries) q)<>jsonb_array_length(queries)
  OR EXISTS (SELECT 1 FROM jsonb_array_elements(queries) q WHERE jsonb_typeof(q)<>'string' OR (q#>>'{}') !~ '^KB[0-9]{6,8}$')
  OR NEW.report->'queried_kbs' IS DISTINCT FROM queries
  OR jsonb_typeof(installed->'rows') IS DISTINCT FROM 'array'
  OR EXISTS (SELECT 1 FROM jsonb_array_elements(installed->'rows') h WHERE (queries ? (h->>'HotFixID')) IS NOT TRUE)
 THEN RAISE EXCEPTION 'OS native facts require an explicit bounded installed-update query'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION evidence_pipeline.check_windows_os_native_facts() OWNER TO tm_mock_owner;

--
-- Name: check_windows_os_review(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_windows_os_review() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE bundle jsonb; native jsonb; installed jsonb; item record; findings jsonb; missing jsonb; selected text;
BEGIN
 bundle:=convert_from(NEW.original_bytes,'UTF8')::jsonb;
 native:=(bundle->'sources'->'native'->>'text')::jsonb;
 installed:=(bundle->'sources'->'installed'->>'text')::jsonb;
 IF NOT EXISTS (
  SELECT 1 FROM evidence.collection_attempts a
  JOIN evidence_pipeline.windows_inventory_bindings b ON b.connection_id=a.connection_id
  JOIN evidence.source_connections c ON c.id=a.connection_id
  JOIN evidence.microsoft_tenants t ON t.id=c.tenant_id
  JOIN evidence_pipeline.authorized_connections auth ON auth.connection_id=c.id
  WHERE a.id=NEW.inventory_attempt_id AND a.complete AND a.outcome='success'
   AND NEW.report->>'origin'=auth.origin AND bundle->>'origin'=auth.origin
   AND bundle->>'collection_tenant_id'=t.external_tenant_id
   AND native->>'tenant_id'=t.external_tenant_id
   AND native->>'device_id'=b.entra_device_id::text
   AND native->>'machine_guid'=b.machine_guid::text
   AND NEW.report->'binding'->>'machine_guid'=b.machine_guid::text
   AND NEW.report->'binding'->>'device_id'=b.entra_device_id::text
   AND NEW.report->'binding'->>'tenant_id'=t.external_tenant_id
 ) THEN RAISE EXCEPTION 'OS review requires exact registered inventory device and origin'; END IF;
 IF bundle->>'contract' IS DISTINCT FROM NEW.report->>'contract'
  OR NEW.report->>'windows_version' IS DISTINCT FROM '10.0.'||(native->>'build')||'.'||(native->>'ubr')
  OR NEW.report->>'release' IS DISTINCT FROM native->>'release'
  OR native->>'architecture' IS DISTINCT FROM 'AMD64'
  OR installed->'identity'->>'device_id' IS DISTINCT FROM native->>'device_id'
  OR installed->'identity'->>'machine_guid' IS DISTINCT FROM native->>'machine_guid'
  OR installed->'identity'->>'tenant_id' IS DISTINCT FROM native->>'tenant_id'
  OR installed->'identity'->>'build' IS DISTINCT FROM native->>'build'
  OR installed->'identity'->>'ubr' IS DISTINCT FROM native->>'ubr'
  OR (NEW.report->>'native_observed_at')::timestamptz IS DISTINCT FROM (native->>'observed_at')::timestamptz
  OR NEW.report->>'product_label' IS DISTINCT FROM 'Windows 11 Version '||(native->>'release')||' for x64-based Systems'
 THEN RAISE EXCEPTION 'OS review interpretation differs from native evidence'; END IF;
 FOR item IN SELECT key,value FROM jsonb_each(bundle->'sources') LOOP
  IF encode(sha256(convert_to(item.value->>'text','UTF8')),'hex') IS DISTINCT FROM item.value->>'sha256'
   OR NEW.report->'sources'->item.key->>'sha256' IS DISTINCT FROM item.value->>'sha256'
  THEN RAISE EXCEPTION 'OS review source hash differs'; END IF;
 END LOOP;
 selected:=NEW.report->>'selected_native_device_id';
 IF selected IS NOT NULL THEN
  SELECT COALESCE(jsonb_agg(f),'[]'::jsonb) INTO findings
  FROM jsonb_array_elements(((bundle->'sources'->'vulnerabilities-0'->>'text')::jsonb)->'value') f
  WHERE f->>'deviceId'=selected;
  missing:=((bundle->'sources'->'current-missing-kbs-0'->>'text')::jsonb)->'value';
  IF NEW.report->'device_findings' IS DISTINCT FROM findings
   OR NEW.report->'missing_updates' IS DISTINCT FROM missing
   OR NEW.report->>'missing_state' IS DISTINCT FROM (CASE WHEN jsonb_array_length(missing)=0 THEN 'none_reported' ELSE 'reported_missing' END)
  THEN RAISE EXCEPTION 'OS review source results differ'; END IF;
 END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.report->'installed_updates') k
  WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(installed->'rows') h WHERE h->>'HotFixID'=k->>'kb')
   OR (k->>'observed_at')::timestamptz IS DISTINCT FROM (installed->>'observed_at')::timestamptz)
 THEN RAISE EXCEPTION 'OS review installation assertion lacks native evidence'; END IF;
 IF NEW.report->>'selected_native_device_id' IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM evidence.provider_devices p
  JOIN evidence.source_connections c ON c.id=p.connection_id
  JOIN evidence.microsoft_tenants t ON t.id=c.tenant_id
  JOIN evidence_pipeline.authorized_connections auth ON auth.connection_id=c.id
  WHERE p.native_device_id=NEW.report->>'selected_native_device_id'
   AND p.microsoft_registration_id=NEW.report->'binding'->>'device_id'
   AND t.external_tenant_id=NEW.report->'binding'->>'tenant_id'
   AND auth.origin=NEW.report->>'origin' AND c.source_name='Defender'
 ) THEN RAISE EXCEPTION 'Selected OS identity requires retained Defender registration'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION evidence_pipeline.check_windows_os_review() OWNER TO tm_mock_owner;

--
-- Name: check_windows_os_review_authority(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.check_windows_os_review_authority() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE bundle jsonb; native jsonb; requests jsonb; devices jsonb; software jsonb;
 chosen jsonb; candidate jsonb; receipt jsonb; page jsonb; payload jsonb; reported jsonb;
 selected text; label text; route text; expected_version text; native_time timestamptz;
 first_time timestamptz; last_time timestamptz; earliest timestamptz; latest timestamptz;
 matching_count integer; versions jsonb;
BEGIN
 bundle:=convert_from(NEW.original_bytes,'UTF8')::jsonb;
 selected:=NEW.report->>'selected_native_device_id';
 IF selected IS NULL THEN
  IF NEW.report->>'identity_state' IS DISTINCT FROM 'unresolved'
   OR NEW.report->>'missing_state' IS DISTINCT FROM 'identity_unresolved'
   OR NEW.report->'missing_updates' IS DISTINCT FROM 'null'::jsonb
   OR NEW.report->'device_findings' IS DISTINCT FROM 'null'::jsonb
   OR NEW.report->'windows_findings' IS DISTINCT FROM 'null'::jsonb
   OR EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.report->'providers') p WHERE p->>'state' IS DISTINCT FROM 'unresolved')
  THEN RAISE EXCEPTION 'OS identity authority requires unresolved source results without selection'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.report->>'identity_state' IS DISTINCT FROM 'selected_from_compatible_retained_evidence'
  OR selected !~ '^[a-f0-9]{40}$'
 THEN RAISE EXCEPTION 'OS identity authority requires a resolved provider identifier'; END IF;
 native:=(bundle->'sources'->'native'->>'text')::jsonb;
 native_time:=(native->>'observed_at')::timestamptz;
 expected_version:='10.0.'||(native->>'build')||'.'||(native->>'ubr');
 IF native_time IS NULL OR (((native->>'release'='24H2' AND native->>'build'='26100')
  OR (native->>'release'='25H2' AND native->>'build'='26200'))) IS NOT TRUE
 THEN RAISE EXCEPTION 'OS identity authority requires supported native release facts'; END IF;
 requests:=(bundle->'sources'->'requests'->>'text')::jsonb;
 FOR label,route IN SELECT * FROM (VALUES
  ('devices','https://api.security.microsoft.com/api/machines'),
  ('software-inventory','https://api.security.microsoft.com/api/machines/SoftwareInventoryByMachine'),
  ('vulnerabilities','https://api.security.microsoft.com/api/machines/SoftwareVulnerabilitiesByMachine'),
  ('current-missing-kbs','https://api.security.microsoft.com/api/machines/'||selected||'/getmissingkbs')) x(label,route)
 LOOP
  IF (SELECT count(*) FROM jsonb_array_elements(requests) r WHERE r->>'label'=label)<>1
  THEN RAISE EXCEPTION 'OS identity authority requires one complete export per source'; END IF;
  SELECT r INTO receipt FROM jsonb_array_elements(requests) r WHERE r->>'label'=label;
  payload:=(bundle->'sources'->(label||'-0')->>'text')::jsonb;
  page:=receipt->'pages'->0;
  IF receipt->'complete' IS DISTINCT FROM 'true'::jsonb
   OR jsonb_array_length(receipt->'pages') IS DISTINCT FROM 1
   OR page->>'url' IS DISTINCT FROM route OR page->'status' IS DISTINCT FROM '200'::jsonb
   OR page->>'sha256' IS DISTINCT FROM bundle->'sources'->(label||'-0')->>'sha256'
   OR jsonb_typeof(payload->'value') IS DISTINCT FROM 'array'
   OR receipt->'count' IS DISTINCT FROM to_jsonb(jsonb_array_length(payload->'value'))
   OR COALESCE(payload->>'@odata.nextLink','')<>'' OR COALESCE(payload->>'nextLink','')<>''
  THEN RAISE EXCEPTION 'OS identity authority requires complete exact-endpoint source receipts'; END IF;
  first_time:=(page->>'started_at')::timestamptz; last_time:=(page->>'finished_at')::timestamptz;
  IF first_time IS NULL OR last_time IS NULL OR last_time<first_time
   OR last_time-first_time>interval '1 hour'
   OR last_time NOT BETWEEN native_time-interval '24 hours' AND native_time+interval '24 hours'
   OR (NEW.report->'sources'->(label||'-0')->>'started_at')::timestamptz IS DISTINCT FROM first_time
   OR (NEW.report->'sources'->(label||'-0')->>'finished_at')::timestamptz IS DISTINCT FROM last_time
   OR NEW.report->'sources'->(label||'-0')->>'url' IS DISTINCT FROM route
  THEN RAISE EXCEPTION 'OS identity authority requires compatible source observation times'; END IF;
  earliest:=LEAST(earliest,first_time); latest:=GREATEST(latest,last_time);
 END LOOP;
 IF latest-earliest>interval '1 hour' OR (NEW.report->>'provider_observed_at')::timestamptz IS DISTINCT FROM latest
 THEN RAISE EXCEPTION 'OS identity authority requires a bounded export window'; END IF;
 devices:=((bundle->'sources'->'devices-0'->>'text')::jsonb)->'value';
 software:=((bundle->'sources'->'software-inventory-0'->>'text')::jsonb)->'value';
 IF (SELECT count(DISTINCT d->>'id') FROM jsonb_array_elements(devices) d)<>jsonb_array_length(devices)
  OR EXISTS (SELECT 1 FROM jsonb_array_elements(devices) d
   WHERE d->>'aadDeviceId' IS DISTINCT FROM native->>'device_id' OR (d->>'id' ~ '^[a-f0-9]{40}$') IS NOT TRUE)
  OR (SELECT count(*) FROM jsonb_array_elements(devices) d WHERE d->>'id'=selected)<>1
 THEN RAISE EXCEPTION 'OS identity authority requires unique same-registration devices'; END IF;
 SELECT d INTO chosen FROM jsonb_array_elements(devices) d WHERE d->>'id'=selected;
 IF chosen->>'osPlatform' IS DISTINCT FROM 'Windows11'
  OR chosen->>'osBuild' IS DISTINCT FROM native->>'build'
  OR chosen->>'version' IS DISTINCT FROM native->>'release'
  OR chosen->>'osProcessor' IS DISTINCT FROM 'x64'
  OR (chosen->>'osArchitecture' IN ('64-bit','x64')) IS NOT TRUE
  OR COALESCE(chosen->>'mergedIntoMachineId','')<>''
  OR chosen->'isPotentialDuplication'='true'::jsonb OR chosen->'isExcluded'='true'::jsonb
  OR ((chosen->>'lastSeen')::timestamptz BETWEEN native_time-interval '24 hours' AND native_time+interval '24 hours') IS NOT TRUE
 THEN RAISE EXCEPTION 'OS identity authority rejects incompatible selected provider'; END IF;
 FOR candidate IN SELECT d FROM jsonb_array_elements(devices) d LOOP
  first_time:=(candidate->>'firstSeen')::timestamptz; last_time:=(candidate->>'lastSeen')::timestamptz;
  SELECT count(*),COALESCE(jsonb_agg(DISTINCT s->>'softwareVersion' ORDER BY s->>'softwareVersion'),'[]'::jsonb)
   INTO matching_count,versions FROM jsonb_array_elements(software) s
   WHERE s->>'deviceId'=candidate->>'id' AND s->>'softwareName'='windows_11' AND s->>'softwareVendor'='microsoft';
  IF first_time IS NULL OR last_time IS NULL OR first_time>last_time OR last_time>latest+interval '2 minutes'
   OR (candidate->>'id'=selected AND (matching_count<>1 OR versions IS DISTINCT FROM jsonb_build_array(expected_version)))
   OR (candidate->>'id'<>selected AND (matching_count=0 OR versions ? expected_version OR last_time>=(chosen->>'firstSeen')::timestamptz))
  THEN RAISE EXCEPTION 'OS identity authority rejects ambiguous or incompatible provider observations'; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(NEW.report->'providers') p WHERE p->>'native_device_id'=candidate->>'id')<>1
  THEN RAISE EXCEPTION 'OS identity authority requires retained provider alternatives'; END IF;
  SELECT p INTO reported FROM jsonb_array_elements(NEW.report->'providers') p WHERE p->>'native_device_id'=candidate->>'id';
  IF reported->>'state' IS DISTINCT FROM (CASE WHEN candidate->>'id'=selected THEN 'selected' ELSE 'historical_incompatible_os' END)
   OR reported->'windows_versions' IS DISTINCT FROM versions
   OR (reported->>'first_seen')::timestamptz IS DISTINCT FROM first_time
   OR (reported->>'last_seen')::timestamptz IS DISTINCT FROM last_time
  THEN RAISE EXCEPTION 'OS identity authority requires source-backed provider interpretations'; END IF;
 END LOOP;
 IF jsonb_array_length(NEW.report->'providers')<>jsonb_array_length(devices)
  OR EXISTS (SELECT 1 FROM jsonb_array_elements(((bundle->'sources'->'current-missing-kbs-0'->>'text')::jsonb)->'value') m
   WHERE COALESCE(m->>'machineId',selected)<>selected)
 THEN RAISE EXCEPTION 'OS identity authority rejects different source device'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION evidence_pipeline.check_windows_os_review_authority() OWNER TO tm_mock_owner;

--
-- Name: completeness_summary(uuid[]); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.completeness_summary(selected_connections uuid[]) RETURNS TABLE(domain text, populated bigint, applicable bigint, unknown_applicability bigint, percentage numeric, assessment text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
 -- Plan this fixed query for the selected scope, rather than a generic UUID array.
 -- The array is a bound parameter; caller input is never SQL text.
 RETURN QUERY EXECUTE $statement$
 WITH selected AS (
 SELECT * FROM evidence_pipeline.selected_product_completeness_cells($1)
 ), domains AS (
 SELECT domain,count(*) FILTER(WHERE populated AND applicability='applicable') AS populated,
 count(*) FILTER(WHERE applicability='applicable') AS applicable,
 count(*) FILTER(WHERE applicability='unknown') AS unknown_applicability
 FROM selected GROUP BY domain
 ), totals AS (
 SELECT * FROM domains UNION ALL
 SELECT 'whole-product',coalesce(sum(populated),0)::bigint,
 coalesce(sum(applicable),0)::bigint,coalesce(sum(unknown_applicability),0)::bigint FROM domains
 )
 SELECT domain,populated,applicable,unknown_applicability,
 100.0*populated/nullif(applicable,0),
 CASE WHEN applicable=0 THEN 'Not assessable' ELSE 'Provisional eligible evidence cells' END
 FROM totals ORDER BY domain
$statement$ USING selected_connections;
END
$_$;


ALTER FUNCTION evidence_pipeline.completeness_summary(selected_connections uuid[]) OWNER TO tm_mock_owner;

--
-- Name: FUNCTION completeness_summary(selected_connections uuid[]); Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON FUNCTION evidence_pipeline.completeness_summary(selected_connections uuid[]) IS 'Equal-weight eligible cells in explicitly selected connections. Unknown applicability and collection coverage remain separate. Empty denominator yields NULL percentage and Not assessable. Unsupported domain definitions remain visible in product_collection_coverage, never silently complete.';


--
-- Name: component_assessment_unsealed(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.component_assessment_unsealed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF EXISTS (SELECT 1 FROM evidence_pipeline.component_check_seals WHERE check_id=NEW.check_id)
 THEN RAISE EXCEPTION 'Completed component assessment evidence is immutable'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION evidence_pipeline.component_assessment_unsealed() OWNER TO tm_mock_owner;

--
-- Name: cve_projection_matches(uuid, text, text, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.cve_projection_matches(target uuid, target_table text, target_cve text, fields jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE claim jsonb; recipe jsonb; expected jsonb;
BEGIN
 claim := evidence_pipeline.cve_receipt_claim(target);
 IF claim IS NULL OR claim->>'cve_id' IS DISTINCT FROM target_cve
 OR jsonb_typeof(claim->'projection') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
 FOR recipe IN SELECT value FROM jsonb_array_elements(claim->'projection') LOOP
  IF recipe->>0 IS DISTINCT FROM target_table THEN CONTINUE; END IF;
  expected := recipe->1;
  IF target_table='cve_record_observations' THEN
   expected := expected || jsonb_build_object('source_metadata',(expected->>'source_metadata')::jsonb);
  ELSIF target_table='cve_contributions' THEN
   expected := expected || jsonb_build_object('source_fields',(expected->>'source_fields')::jsonb);
  ELSE RETURN false; END IF;
  IF expected=fields THEN RETURN true; END IF;
 END LOOP;
 RETURN false;
END $$;


ALTER FUNCTION evidence_pipeline.cve_projection_matches(target uuid, target_table text, target_cve text, fields jsonb) OWNER TO tm_mock_owner;

--
-- Name: cve_receipt_claim(uuid); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.cve_receipt_claim(target uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT p.claim::jsonb FROM evidence.observation_receipts r
 JOIN evidence.collection_attempts a ON a.id=r.collection_attempt_id
 JOIN evidence.source_revisions rev ON rev.id=r.source_revision_id AND rev.connection_id=a.connection_id
 JOIN evidence.source_connections c ON c.id=a.connection_id
 JOIN evidence_pipeline.authorized_connections auth ON auth.connection_id=c.id AND auth.origin=rev.origin
 JOIN evidence_pipeline.public_claims p ON p.source_revision_id=rev.id
 WHERE r.id=target AND a.complete AND a.outcome='success' AND c.tenant_id IS NULL
 AND (c.source_name,c.input_kind) IN (('CVE','records'),('CISA','vulnrichment'))
 AND p.claim::jsonb->>'adapter'='cve-record-v1'
 AND p.claim::jsonb->>'cve_id'=rev.source_record_id
$$;


ALTER FUNCTION evidence_pipeline.cve_receipt_claim(target uuid) OWNER TO tm_mock_owner;

--
-- Name: cve_snapshot_matches(text, text, text, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.cve_snapshot_matches(provider text, source_origin text, commit_id text, members jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT provider IN ('CVE','CISA') AND jsonb_typeof(members)='array'
 AND (SELECT count(*)=count(DISTINCT member->>'path') FROM jsonb_array_elements(members) member)
 AND NOT EXISTS (
  SELECT 1 FROM jsonb_array_elements(members) member
  LEFT JOIN evidence.observation_receipts r ON r.id=(member->>'receipt_id')::uuid
  LEFT JOIN evidence.collection_attempts a ON a.id=r.collection_attempt_id
  LEFT JOIN evidence.source_connections c ON c.id=a.connection_id
  LEFT JOIN evidence.source_revisions rev ON rev.id=r.source_revision_id
  LEFT JOIN evidence.cve_record_observations o ON o.receipt_id=r.id
  WHERE NOT coalesce(
   jsonb_typeof(member)='object' AND member ? 'path' AND member ? 'receipt_id'
   AND (member-'path'-'receipt_id')='{}'::jsonb
   AND o.cve_id ~ '^CVE-[0-9]{4}-[0-9]{4,19}$'
   AND member->>'path'=CASE provider WHEN 'CVE' THEN 'cves/' ELSE '' END
    ||split_part(o.cve_id,'-',2)||'/'
    ||left(split_part(o.cve_id,'-',3),length(split_part(o.cve_id,'-',3))-3)||'xxx/'||o.cve_id||'.json'
   AND c.source_name=provider
   AND c.input_kind=CASE provider WHEN 'CVE' THEN 'records' ELSE 'vulnrichment' END
   AND c.tenant_id IS NULL
   AND a.complete AND a.outcome='success'
   AND rev.origin=source_origin
   AND rev.source_url='https://raw.githubusercontent.com/'
    ||CASE provider WHEN 'CVE' THEN 'CVEProject/cvelistV5/' ELSE 'cisagov/vulnrichment/' END
    ||commit_id||'/'||(member->>'path'),false)
 );
$_$;


ALTER FUNCTION evidence_pipeline.cve_snapshot_matches(provider text, source_origin text, commit_id text, members jsonb) OWNER TO tm_mock_owner;

--
-- Name: edge_cpe_criterion(jsonb, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.edge_cpe_criterion(criterion jsonb, facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE identity_check jsonb; parts text[]; part text; architecture text; candidate bigint[];
 lower_key bigint[]; upper_key bigint[]; exact_key bigint[]; bound_key bigint[]; bound_name text;
 lower_exclusive boolean := false; upper_exclusive boolean := false; inside boolean := true;
 has_bounds boolean := false; reason text; state text := 'unknown';
BEGIN
 candidate := evidence_pipeline.windows_build_key(facts->>'version');
 IF candidate IS NULL THEN RETURN jsonb_build_object('state','unknown','reason','missing_or_invalid_edge_version'); END IF;
 IF jsonb_typeof(criterion) IS DISTINCT FROM 'object' THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_criterion_fields'); END IF;
 IF criterion-ARRAY['criteria','vulnerable','matchCriteriaId','versionStartIncluding','versionStartExcluding','versionEndIncluding','versionEndExcluding']<>'{}'::jsonb OR jsonb_typeof(criterion->'vulnerable') IS DISTINCT FROM 'boolean' THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_criterion_fields'); END IF;
 parts := CASE WHEN jsonb_typeof(criterion->'criteria')='string' AND length(criterion->>'criteria')<=4096 THEN string_to_array(criterion->>'criteria',':') ELSE ARRAY[]::text[] END;
 IF cardinality(parts)<>13 OR parts[1:5] IS DISTINCT FROM ARRAY['cpe','2.3','a','microsoft','edge_chromium'] THEN RETURN jsonb_build_object('state','unknown','reason','other_product_or_environment_requires_evidence'); END IF;
 FOREACH part IN ARRAY parts[7:13] LOOP
 IF part<>'*' THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_cpe_environment_selector'); END IF;
 END LOOP;
 FOREACH bound_name IN ARRAY ARRAY['versionStartIncluding','versionStartExcluding','versionEndIncluding','versionEndExcluding'] LOOP
  IF criterion ? bound_name THEN
   has_bounds := true;
   bound_key := evidence_pipeline.windows_build_key(criterion->>bound_name);
   IF bound_key IS NULL THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_version_ordering'); END IF;
   IF bound_name IN ('versionStartIncluding','versionStartExcluding') THEN lower_key := bound_key; lower_exclusive := bound_name='versionStartExcluding';
   ELSE upper_key := bound_key; upper_exclusive := bound_name='versionEndExcluding'; END IF;
  END IF;
 END LOOP;
 IF (criterion ? 'versionStartIncluding' AND criterion ? 'versionStartExcluding') OR (criterion ? 'versionEndIncluding' AND criterion ? 'versionEndExcluding') THEN RETURN jsonb_build_object('state','unknown','reason','conflicting_version_bounds'); END IF;
 IF lower_key>upper_key OR (lower_key=upper_key AND (lower_exclusive OR upper_exclusive)) THEN RETURN jsonb_build_object('state','unknown','reason','empty_or_reversed_version_bounds'); END IF;
 IF parts[6]<>'*' THEN
  exact_key := evidence_pipeline.windows_build_key(parts[6]);
  IF exact_key IS NULL OR has_bounds THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_exact_version_and_range_combination'); END IF;
  inside := candidate=exact_key; reason := 'explicit_exact_edge_version';
 ELSIF NOT has_bounds THEN inside := true; reason := 'explicit_edge_version_bounds';
 ELSE
  IF lower_key IS NOT NULL THEN inside := inside AND (candidate>lower_key OR (NOT lower_exclusive AND candidate=lower_key)); END IF;
  IF upper_key IS NOT NULL THEN inside := inside AND (candidate<upper_key OR (NOT upper_exclusive AND candidate=upper_key)); END IF;
  reason := 'explicit_edge_version_bounds';
 END IF;
 state := CASE WHEN inside THEN 'matched' ELSE 'excluded' END;
 RETURN jsonb_build_object('state',state,'reason',reason);
END $$;


ALTER FUNCTION evidence_pipeline.edge_cpe_criterion(criterion jsonb, facts jsonb) OWNER TO tm_mock_owner;

--
-- Name: edge_cpe_group(jsonb, jsonb, boolean); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.edge_cpe_group(item jsonb, facts jsonb, is_root boolean) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE key text := CASE WHEN is_root THEN 'nodes' ELSE 'cpeMatch' END;
 children jsonb; evaluated jsonb := '[]'; child jsonb; result jsonb; op text; truth boolean;
BEGIN
 IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item-ARRAY[key,'operator','negate']<>'{}'::jsonb THEN RETURN evidence_pipeline.windows_cpe_unknown('unsupported_configuration_fields'); END IF;
 children := item->key;
 IF jsonb_typeof(children) IS DISTINCT FROM 'array' THEN RETURN evidence_pipeline.windows_cpe_unknown('empty_or_invalid_configuration'); END IF;
 IF jsonb_array_length(children)=0 THEN RETURN evidence_pipeline.windows_cpe_unknown('empty_or_invalid_configuration'); END IF;
 op := item->>'operator';
 IF op IS NULL AND is_root AND jsonb_array_length(children)=1 THEN op := 'OR'; END IF;
 IF op IS NULL OR op NOT IN ('AND','OR') OR (item ? 'negate' AND jsonb_typeof(item->'negate') IS DISTINCT FROM 'boolean') THEN RETURN evidence_pipeline.windows_cpe_unknown('unsupported_configuration_operator'); END IF;
 FOR child IN SELECT value FROM jsonb_array_elements(children) LOOP
  IF is_root THEN result := evidence_pipeline.edge_cpe_group(child,facts,false);
  ELSE
   result := evidence_pipeline.edge_cpe_criterion(child,facts);
   truth := CASE result->>'state' WHEN 'matched' THEN true WHEN 'excluded' THEN false ELSE NULL END;
   result := jsonb_build_object('truth',truth,'witness',CASE WHEN child->'vulnerable'='true'::jsonb THEN truth ELSE false END,'negative_witness',false,'reason',result->>'reason');
  END IF;
  evaluated := evaluated || jsonb_build_array(result);
 END LOOP;
 RETURN evidence_pipeline.windows_cpe_combine(evaluated,op,COALESCE((item->>'negate')::boolean,false));
END $$;


ALTER FUNCTION evidence_pipeline.edge_cpe_group(item jsonb, facts jsonb, is_root boolean) OWNER TO tm_mock_owner;

--
-- Name: edge_cpe_status(jsonb, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.edge_cpe_status(configurations jsonb, facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE item jsonb; evaluated jsonb := '[]'; result jsonb; state text;
BEGIN
 IF jsonb_typeof(configurations) IS DISTINCT FROM 'array' THEN result := evidence_pipeline.windows_cpe_unknown('empty_or_invalid_configurations');
 ELSIF jsonb_array_length(configurations)=0 THEN result := evidence_pipeline.windows_cpe_unknown('empty_or_invalid_configurations');
 ELSE
  FOR item IN SELECT value FROM jsonb_array_elements(configurations) LOOP
   evaluated := evaluated || jsonb_build_array(evidence_pipeline.edge_cpe_group(item,facts,true));
  END LOOP;
  result := evidence_pipeline.windows_cpe_combine(evaluated,'OR');
 END IF;
 state := CASE WHEN result->'truth'='false'::jsonb THEN 'excluded' WHEN result->'witness'='true'::jsonb THEN 'matched' ELSE 'unknown' END;
 RETURN jsonb_build_object('state',state,'reason','evaluated_edge_cpe_conditions','conditions',result);
END $$;


ALTER FUNCTION evidence_pipeline.edge_cpe_status(configurations jsonb, facts jsonb) OWNER TO tm_mock_owner;

--
-- Name: edge_inventory_products(jsonb, text, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.edge_inventory_products(source_fields jsonb, provider text, facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE candidate bigint[]; entry jsonb; rule jsonb; rec record; vr record; profile text;
 result jsonb; evaluated jsonb := '[]'; matches jsonb; default_state text;
 matched boolean; state text; combined text; reason text; conflict boolean;
BEGIN
 <<evaluate>> BEGIN
 IF NOT evidence_pipeline.inventory_source_supported(facts,'desktop_application') OR facts->>'product' IS DISTINCT FROM 'Microsoft Edge'
 OR facts->>'publisher' IS DISTINCT FROM 'Microsoft Corporation' THEN
 reason := 'unsupported_inventory_product_identity'; EXIT evaluate; END IF;
 candidate := evidence_pipeline.windows_build_key(facts->>'version');
 IF candidate IS NULL OR candidate[1]<77 THEN reason := 'unsupported_or_missing_edge_chromium_version'; EXIT evaluate; END IF;
 profile := CASE WHEN facts->>'source'='Windows inventory' THEN 'native-windows-microsoft-edge-chromium-v1' ELSE 'intune-windows-microsoft-edge-chromium-v1' END;
 IF facts->>'platform' IS DISTINCT FROM 'windows' OR facts->>'operating_system' IS NULL OR facts->>'operating_system' NOT IN
 ('Windows','Windows10','Windows11','WindowsServer2012','WindowsServer2012R2','WindowsServer2016','WindowsServer2019','WindowsServer2022','WindowsServer2025') THEN
 reason := 'missing_or_conflicting_inventory_platform'; EXIT evaluate; END IF;
 IF provider IS DISTINCT FROM 'microsoft' OR jsonb_typeof(source_fields) IS DISTINCT FROM 'object' THEN
 reason := 'missing_published_microsoft_cna_evidence'; EXIT evaluate; END IF;
 IF source_fields ? 'configurations' THEN reason := 'additional_cna_configuration_requires_evaluation'; EXIT evaluate; END IF;
 IF jsonb_typeof(source_fields->'affected') IS DISTINCT FROM 'array' THEN reason := 'missing_affected_entries'; EXIT evaluate; END IF;
 IF jsonb_array_length(source_fields->'affected')=0 THEN reason := 'missing_affected_entries'; EXIT evaluate; END IF;
 FOR rec IN SELECT value,ordinality FROM jsonb_array_elements(source_fields->'affected') WITH ORDINALITY LOOP
 entry := rec.value;
 IF jsonb_typeof(entry) IS DISTINCT FROM 'object' THEN reason := 'invalid_affected_entry'; EXIT evaluate; END IF;
 IF entry->>'vendor' IS DISTINCT FROM 'Microsoft' OR entry->>'product' IS DISTINCT FROM 'Microsoft Edge (Chromium-based)' THEN CONTINUE; END IF;
 IF entry-ARRAY['vendor','product','versions','defaultStatus','platforms']<>'{}'::jsonb THEN reason := 'unsupported_product_selectors'; EXIT evaluate; END IF;
 IF entry ? 'platforms' AND entry->'platforms' IS DISTINCT FROM '["Windows"]'::jsonb THEN reason := 'missing_or_unsupported_platform_evidence'; EXIT evaluate; END IF;
 default_state := CASE WHEN entry ? 'defaultStatus' THEN entry->>'defaultStatus' ELSE 'unknown' END;
 IF default_state IS NULL OR default_state NOT IN ('affected','unaffected','unknown') OR jsonb_typeof(entry->'versions') IS DISTINCT FROM 'array' THEN reason := 'missing_version_status'; EXIT evaluate; END IF;
 IF jsonb_array_length(entry->'versions')=0 THEN reason := 'missing_version_status'; EXIT evaluate; END IF;
 matches := '[]'; state := NULL; conflict := false;
 FOR vr IN SELECT value,ordinality FROM jsonb_array_elements(entry->'versions') WITH ORDINALITY LOOP
 rule := vr.value;
 IF jsonb_typeof(rule) IS DISTINCT FROM 'object' THEN reason := 'unsupported_or_conflicting_version_rules'; EXIT evaluate; END IF;
 IF evidence_pipeline.windows_build_key(rule->>'version') IS NULL
 OR (rule ? 'versionType' AND rule->>'versionType' IS DISTINCT FROM 'custom')
 OR (rule ? 'lessThan' AND evidence_pipeline.windows_build_key(rule->>'lessThan') IS NULL)
 OR (rule ? 'lessThanOrEqual' AND evidence_pipeline.windows_build_key(rule->>'lessThanOrEqual') IS NULL) THEN
 reason := 'unsupported_or_conflicting_version_rules'; EXIT evaluate; END IF;
 matched := evidence_pipeline.vmware_tools_version_match(rule,candidate);
 IF matched IS NULL THEN reason := 'unsupported_or_conflicting_version_rules'; EXIT evaluate; END IF;
 IF matched THEN
 IF state IS NOT NULL AND state<>rule->>'status' THEN conflict := true; END IF;
 state := rule->>'status'; matches := matches || jsonb_build_array(jsonb_build_object('index',vr.ordinality-1,'status',state));
 END IF;
 END LOOP;
 IF conflict THEN reason := 'conflicting_version_statuses'; EXIT evaluate; END IF;
 state := COALESCE(state,default_state);
 evaluated := evaluated || jsonb_build_array(jsonb_build_object('index',rec.ordinality-1,'state',state,'matches',matches));
 END LOOP;
 IF jsonb_array_length(evaluated)=0 THEN reason := 'no_supported_edge_entry'; EXIT evaluate; END IF;
 SELECT count(DISTINCT value->>'state')>1,min(value->>'state') INTO conflict,combined FROM jsonb_array_elements(evaluated);
 IF conflict THEN reason := 'conflicting_product_entries'; combined := NULL; ELSE reason := 'explicit_edge_product_version_statement'; END IF;
 END evaluate;
 IF reason NOT IN ('conflicting_product_entries','explicit_edge_product_version_statement') THEN evaluated := '[]'; END IF;
 RETURN evidence_pipeline.vmware_tools_result(COALESCE(combined,'unknown'),reason,evaluated)
 || jsonb_build_object('inventory',facts,'mapping_profile',profile);
END $$;


ALTER FUNCTION evidence_pipeline.edge_inventory_products(source_fields jsonb, provider text, facts jsonb) OWNER TO tm_mock_owner;

--
-- Name: edge_inventory_status(jsonb, text, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.edge_inventory_status(source_fields jsonb, provider text, facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE product jsonb; cpe jsonb; state text := 'unknown'; reason text := 'incomplete_product_or_cpe_evidence';
BEGIN
 product := evidence_pipeline.edge_inventory_products(source_fields,provider,facts);
 IF jsonb_typeof(source_fields) IS DISTINCT FROM 'object' OR NOT source_fields ? 'cpeApplicability' OR source_fields ? 'configurations' OR product->>'mapping_profile' IS NULL THEN RETURN product; END IF;
 cpe := evidence_pipeline.edge_cpe_status(source_fields->'cpeApplicability',facts);
 IF product->>'state' IN ('affected','unaffected') AND cpe->>'state'<>'unknown' THEN
 IF (product->>'state'='affected')=(cpe->>'state'='matched') THEN state := product->>'state'; reason := 'consistent_product_and_cpe_evidence'; ELSE reason := 'conflicting_product_and_cpe_evidence'; END IF;
 END IF;
 RETURN product || jsonb_build_object('state',state,'reason',reason,'product',product,'cpe',cpe);
END $$;


ALTER FUNCTION evidence_pipeline.edge_inventory_status(source_fields jsonb, provider text, facts jsonb) OWNER TO tm_mock_owner;

--
-- Name: github_snapshot_matches(text, text, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.github_snapshot_matches(source_origin text, commit_id text, members jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT jsonb_typeof(members)='array'
 AND (SELECT count(*)=count(DISTINCT member->>'path') FROM jsonb_array_elements(members) member)
 AND NOT EXISTS (
  SELECT 1 FROM jsonb_array_elements(members) member
  LEFT JOIN evidence.observation_receipts r ON r.id=(member->>'receipt_id')::uuid
  LEFT JOIN evidence.collection_attempts a ON a.id=r.collection_attempt_id
  LEFT JOIN evidence.source_connections c ON c.id=a.connection_id
  LEFT JOIN evidence.source_revisions rev ON rev.id=r.source_revision_id
  LEFT JOIN evidence.osv_advisory_observations o ON o.receipt_id=r.id
  WHERE NOT coalesce(
   jsonb_typeof(member)='object' AND member ? 'path' AND member ? 'receipt_id'
   AND (member-'path'-'receipt_id')='{}'::jsonb
   AND member->>'path' ~ '^advisories/(github-reviewed|unreviewed)/[0-9]{4}/(0[1-9]|1[0-2])/GHSA(-[23456789cfghjmpqrvwx]{4}){3}/GHSA(-[23456789cfghjmpqrvwx]{4}){3}\.json$'
   AND split_part(member->>'path','/',5)||'.json'=split_part(member->>'path','/',6)
   AND split_part(member->>'path','/',5)=o.advisory_id
   AND c.source_name='GitHub' AND c.input_kind='advisories'
   AND a.complete AND a.outcome='success'
   AND rev.origin=source_origin
   AND rev.source_url='https://raw.githubusercontent.com/github/advisory-database/'||commit_id||'/'||(member->>'path'),false)
 );
$_$;


ALTER FUNCTION evidence_pipeline.github_snapshot_matches(source_origin text, commit_id text, members jsonb) OWNER TO tm_mock_owner;

--
-- Name: historical_event_completeness_summary(uuid[]); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.historical_event_completeness_summary(selected_connections uuid[]) RETURNS TABLE(populated bigint, applicable bigint, unknown_applicability bigint, distinct_events bigint, percentage numeric, assessment text)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 WITH selected AS (
  SELECT * FROM evidence_pipeline.historical_event_completeness_cells
  WHERE connection_id=ANY(selected_connections)
 ), totals AS (
  SELECT count(*) FILTER(WHERE populated AND applicability='applicable') AS populated,
   count(*) FILTER(WHERE applicability='applicable') AS applicable,
   count(*) FILTER(WHERE applicability='unknown') AS unknown_applicability,
   count(DISTINCT (connection_id,event_fingerprint)) AS distinct_events
  FROM selected
 )
 SELECT populated,applicable,unknown_applicability,distinct_events,
  100.0*populated/nullif(applicable,0),
  CASE WHEN applicable=0 THEN 'Not assessable' ELSE 'Provisional historical event cells' END
 FROM totals
$$;


ALTER FUNCTION evidence_pipeline.historical_event_completeness_summary(selected_connections uuid[]) OWNER TO tm_mock_owner;

--
-- Name: inventory_product_status(jsonb, text, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.inventory_product_status(source_fields jsonb, provider text, facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE profile text; evaluation jsonb; affected jsonb; entry jsonb;
 validated jsonb := '[]'::jsonb;
BEGIN
 <<evaluate>>
 BEGIN
  IF NOT evidence_pipeline.inventory_source_supported(facts,'desktop_application')
   OR facts->>'product' IS DISTINCT FROM 'VMware Tools'
   OR facts->>'publisher' IS NULL OR facts->>'publisher' NOT IN ('VMware, Inc.','Broadcom Inc.') THEN
   evaluation := evidence_pipeline.vmware_tools_result('unknown','unsupported_inventory_product_identity'); EXIT evaluate;
  END IF;
  profile := CASE WHEN facts->>'source'='Windows inventory' THEN 'native-windows-vmware-tools-v1' ELSE 'intune-windows-vmware-tools-v1' END;
  IF facts->>'platform' IS DISTINCT FROM 'windows' OR facts->>'operating_system' IS NULL
   OR facts->>'operating_system' NOT IN ('Windows','Windows10','Windows11','WindowsServer2012',
    'WindowsServer2012R2','WindowsServer2016','WindowsServer2019','WindowsServer2022','WindowsServer2025') THEN
   evaluation := evidence_pipeline.vmware_tools_result('unknown','missing_or_conflicting_inventory_platform'); EXIT evaluate;
  END IF;
  IF jsonb_typeof(source_fields) IS DISTINCT FROM 'object' THEN
   evaluation := evidence_pipeline.vmware_tools_result('unknown','missing_published_cna_evidence'); EXIT evaluate;
  END IF;
  IF source_fields ? 'cpeApplicability' OR source_fields ? 'configurations' THEN
   evaluation := evidence_pipeline.vmware_tools_result('unknown','additional_cna_configuration_requires_evaluation'); EXIT evaluate;
  END IF;
  affected := source_fields->'affected';
  IF jsonb_typeof(affected) IS DISTINCT FROM 'array' THEN
   evaluation := evidence_pipeline.vmware_tools_result('unknown','missing_affected_entries'); EXIT evaluate;
  END IF;
  IF jsonb_array_length(affected)=0 THEN
   evaluation := evidence_pipeline.vmware_tools_result('unknown','missing_affected_entries'); EXIT evaluate;
  END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(affected) LOOP
   IF entry->>'vendor'='VMware' AND entry->>'product' IN ('Tools','VMware tools','VMware Tools') AND entry ? 'platforms' THEN
    IF entry->'platforms' IS DISTINCT FROM '["Windows"]'::jsonb THEN
     evaluation := evidence_pipeline.vmware_tools_result('unknown','missing_or_unsupported_platform_evidence'); EXIT evaluate;
    END IF;
    -- Only this selector has been established by the original inventory and
    -- pinned operating-system facts. Keep every other selector for evaluation.
    entry := entry-'platforms';
   END IF;
   validated := validated || jsonb_build_array(entry);
  END LOOP;
  evaluation := evidence_pipeline.vmware_tools_status(validated,provider,
   jsonb_build_object('product','tools','publisher','vmware','version',facts->'version',
    'operating_system',facts->'operating_system'));
 END;
 RETURN evaluation || jsonb_build_object('inventory',facts,'mapping_profile',profile);
END $$;


ALTER FUNCTION evidence_pipeline.inventory_product_status(source_fields jsonb, provider text, facts jsonb) OWNER TO tm_mock_owner;

--
-- Name: inventory_source_supported(jsonb, text); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.inventory_source_supported(facts jsonb, distribution text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT coalesce(jsonb_typeof(facts)='object' AND (
  facts->>'source'='Intune' OR
  (facts->>'source'='Windows inventory' AND jsonb_typeof(facts->'native_id')='string'
   AND length(btrim(facts->>'native_id'))>0 AND (
    (distribution='desktop_application' AND facts->>'kind'='registry') OR
    (distribution='windows_package' AND facts->>'kind'='appx'
     AND facts->'is_resource_package'='false'::jsonb
     AND EXISTS (SELECT 1 FROM jsonb_array_elements(CASE
      WHEN jsonb_typeof(facts->'user_states')='array' THEN facts->'user_states' ELSE '[]'::jsonb END) u
      WHERE u->>'install_state'='Installed'))))),false);
$$;


ALTER FUNCTION evidence_pipeline.inventory_source_supported(facts jsonb, distribution text) OWNER TO tm_mock_owner;

--
-- Name: is_cvrf_receipt(uuid); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.is_cvrf_receipt(target uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS (
 SELECT 1 FROM evidence.observation_receipts r
 JOIN evidence.collection_attempts a ON a.id=r.collection_attempt_id
 JOIN evidence.source_revisions rev ON rev.id=r.source_revision_id AND rev.connection_id=a.connection_id
 JOIN evidence.source_connections c ON c.id=a.connection_id
 JOIN evidence_pipeline.authorized_connections auth ON auth.connection_id=c.id AND auth.origin=rev.origin
 JOIN evidence_pipeline.public_claims claim ON claim.source_revision_id=rev.id
 WHERE r.id=target AND a.complete AND a.outcome='success'
 AND c.source_name='MSRC' AND c.input_kind='security_updates' AND c.tenant_id IS NULL)
$$;


ALTER FUNCTION evidence_pipeline.is_cvrf_receipt(target uuid) OWNER TO tm_mock_owner;

--
-- Name: media_cpe_status(jsonb, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.media_cpe_status(configurations jsonb, facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE identity_check jsonb;
BEGIN
 identity_check := evidence_pipeline.media_inventory_status(NULL,'microsoft',facts);
 IF identity_check->>'reason' IS DISTINCT FROM 'missing_published_microsoft_cna_evidence' THEN
  RETURN jsonb_build_object('state','unknown','reason','missing_supported_media_identity');
 END IF;
 RETURN evidence_pipeline.application_cpe_status(configurations,facts,facts->>'product',CASE facts->>'product' WHEN 'Microsoft.AV1VideoExtension' THEN 'av1_video_extension' WHEN 'Microsoft.HEIFImageExtension' THEN 'heif_image_extension' WHEN 'Microsoft.RawImageExtension' THEN 'raw_image_extension' WHEN 'Microsoft.WebMediaExtensions' THEN 'web_media_extensions' WHEN 'Microsoft.WebpImageExtension' THEN 'webp_image_extension' WHEN 'Microsoft.MPEG2VideoExtension' THEN 'mpeg-2_video_extension' END)
 || jsonb_build_object('reason','evaluated_media_cpe_conditions');
END $$;


ALTER FUNCTION evidence_pipeline.media_cpe_status(configurations jsonb, facts jsonb) OWNER TO tm_mock_owner;

--
-- Name: media_inventory_status(jsonb, text, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.media_inventory_status(source_fields jsonb, provider text, facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE target text; candidate bigint[]; entry jsonb; rule jsonb; rec record; vr record; profile text;
 result jsonb; evaluated jsonb := '[]'; matches jsonb; default_state text;
 matched boolean; state text; combined text; reason text; conflict boolean; conditions_known boolean := true; product_status text := 'unknown'; manifest jsonb := facts->'manifest';
BEGIN
 target := CASE facts->>'product' WHEN 'Microsoft.AV1VideoExtension' THEN 'AV1 Video Extension' WHEN 'Microsoft.HEIFImageExtension' THEN 'HEIF Image Extension' WHEN 'Microsoft.RawImageExtension' THEN 'Raw Image Extension' WHEN 'Microsoft.WebMediaExtensions' THEN 'Web Media Extensions' WHEN 'Microsoft.WebpImageExtension' THEN 'WebP Image Extension' WHEN 'Microsoft.MPEG2VideoExtension' THEN 'MPEG-2 Video Extension' END;
 <<evaluate>> BEGIN
 IF facts->>'source' IS DISTINCT FROM 'Windows inventory'
 OR facts->>'kind' IS DISTINCT FROM 'appx'
 OR target IS NULL
 OR facts->>'name' IS DISTINCT FROM facts->>'product'
 OR facts->>'publisher' IS DISTINCT FROM 'CN=Microsoft Corporation, O=Microsoft Corporation, L=Redmond, S=Washington, C=US'
 OR facts->>'family_name' IS DISTINCT FROM (facts->>'product') || '_8wekyb3d8bbwe'
 OR facts->'is_bundle' IS DISTINCT FROM 'false'::jsonb
 OR facts->'is_resource_package' IS DISTINCT FROM 'false'::jsonb
 OR facts->'is_framework' IS DISTINCT FROM 'false'::jsonb
 OR jsonb_typeof(facts->'native_id') IS DISTINCT FROM 'string'
 OR length(btrim(facts->>'native_id'))=0 THEN reason := 'unsupported_inventory_product_identity'; EXIT evaluate; END IF;
 IF NOT evidence_pipeline.inventory_source_supported(facts,'windows_package') THEN
 reason := 'missing_installed_package_evidence'; EXIT evaluate; END IF;
 IF NOT evidence_pipeline.media_manifest_valid(facts) THEN
 reason := 'missing_or_conflicting_manifest_evidence'; EXIT evaluate; END IF;
 IF manifest->>'state' IS DISTINCT FROM 'read' OR manifest->>'display_name' IS DISTINCT FROM target THEN
 reason := 'missing_or_conflicting_manifest_product_name'; EXIT evaluate; END IF;
 profile := CASE WHEN facts->>'product'='Microsoft.AV1VideoExtension' THEN 'native-manifest-av1-cna-v1' ELSE 'native-manifest-store-media-cna-v1' END;
 IF facts->>'platform' IS DISTINCT FROM 'windows' OR facts->>'operating_system' IS NULL OR facts->>'operating_system' NOT IN
 ('Windows','Windows10','Windows11','WindowsServer2012','WindowsServer2012R2','WindowsServer2016','WindowsServer2019','WindowsServer2022','WindowsServer2025') THEN
 reason := 'missing_or_conflicting_inventory_platform'; EXIT evaluate; END IF;
 candidate := evidence_pipeline.windows_app_version_key(facts->>'version');
 IF candidate IS NULL OR cardinality(candidate)<>4 THEN reason := 'unsupported_or_missing_application_version'; EXIT evaluate; END IF;
 IF provider IS DISTINCT FROM 'microsoft' OR jsonb_typeof(source_fields) IS DISTINCT FROM 'object' THEN
 reason := 'missing_published_microsoft_cna_evidence'; EXIT evaluate; END IF;
 conditions_known := NOT (source_fields ? 'configurations' OR source_fields ? 'cpeApplicability');
 IF jsonb_typeof(source_fields->'affected') IS DISTINCT FROM 'array' THEN reason := 'missing_affected_entries'; EXIT evaluate; END IF;
 IF jsonb_array_length(source_fields->'affected')=0 THEN reason := 'missing_affected_entries'; EXIT evaluate; END IF;
 FOR rec IN SELECT value,ordinality FROM jsonb_array_elements(source_fields->'affected') WITH ORDINALITY LOOP
 entry := rec.value;
 IF jsonb_typeof(entry) IS DISTINCT FROM 'object' THEN reason := 'invalid_affected_entry'; EXIT evaluate; END IF;
 IF entry->>'vendor' IS DISTINCT FROM 'Microsoft' OR entry->>'product' IS DISTINCT FROM target THEN CONTINUE; END IF;
 IF entry-ARRAY['vendor','product','versions','defaultStatus','platforms']<>'{}'::jsonb THEN conditions_known := false; END IF;
 IF entry ? 'platforms' AND entry->'platforms' IS DISTINCT FROM '["Windows"]'::jsonb THEN conditions_known := false; END IF;
 default_state := CASE WHEN entry ? 'defaultStatus' THEN entry->>'defaultStatus' ELSE 'unknown' END;
 IF default_state IS NULL OR default_state NOT IN ('affected','unaffected','unknown') OR jsonb_typeof(entry->'versions') IS DISTINCT FROM 'array' THEN reason := 'missing_version_status'; EXIT evaluate; END IF;
 IF jsonb_array_length(entry->'versions')=0 THEN reason := 'missing_version_status'; EXIT evaluate; END IF;
 matches := '[]'; state := NULL; conflict := false;
 FOR vr IN SELECT value,ordinality FROM jsonb_array_elements(entry->'versions') WITH ORDINALITY LOOP
 rule := vr.value;
 IF jsonb_typeof(rule) IS DISTINCT FROM 'object' THEN reason := 'unsupported_or_conflicting_version_rules'; EXIT evaluate; END IF;
 IF evidence_pipeline.windows_app_version_key(rule->>'version') IS NULL
 OR (rule ? 'versionType' AND rule->>'versionType' IS DISTINCT FROM 'custom')
 OR (rule ? 'lessThan' AND evidence_pipeline.windows_app_version_key(rule->>'lessThan') IS NULL)
 OR (rule ? 'lessThanOrEqual' AND evidence_pipeline.windows_app_version_key(rule->>'lessThanOrEqual') IS NULL) THEN
 reason := 'unsupported_or_conflicting_version_rules'; EXIT evaluate; END IF;
 matched := evidence_pipeline.windows_app_version_match(rule,candidate);
 IF matched IS NULL THEN reason := 'unsupported_or_conflicting_version_rules'; EXIT evaluate; END IF;
 IF matched THEN
 IF state IS NOT NULL AND state<>rule->>'status' THEN conflict := true; END IF;
 state := rule->>'status'; matches := matches || jsonb_build_array(jsonb_build_object('index',vr.ordinality-1,'status',state));
 END IF;
 END LOOP;
 IF conflict THEN reason := 'conflicting_version_statuses'; EXIT evaluate; END IF;
 state := COALESCE(state,default_state);
 evaluated := evaluated || jsonb_build_array(jsonb_build_object('index',rec.ordinality-1,'state',state,'matches',matches));
 END LOOP;
 IF jsonb_array_length(evaluated)=0 THEN reason := 'no_supported_application_entry'; EXIT evaluate; END IF;
 SELECT count(DISTINCT value->>'state')>1,min(value->>'state') INTO conflict,combined FROM jsonb_array_elements(evaluated);
 IF conflict THEN reason := 'conflicting_product_entries'; combined := NULL;
 ELSE product_status := combined;
 IF conditions_known THEN reason := 'explicit_application_product_version_statement';
 ELSE reason := 'additional_or_unknown_advisory_conditions'; combined := NULL; END IF; END IF;
 END evaluate;
 IF reason NOT IN ('conflicting_product_entries','explicit_application_product_version_statement','additional_or_unknown_advisory_conditions') THEN evaluated := '[]'; END IF;
 RETURN evidence_pipeline.vmware_tools_result(COALESCE(combined,'unknown'),reason,evaluated)
 || jsonb_build_object('inventory',facts,'mapping_profile',profile,'product_version_status',product_status,
 'condition_status',CASE WHEN reason='explicit_application_product_version_statement' THEN 'supported' ELSE 'unknown' END,'applicability','unknown');
END $$;


ALTER FUNCTION evidence_pipeline.media_inventory_status(source_fields jsonb, provider text, facts jsonb) OWNER TO tm_mock_owner;

--
-- Name: media_manifest_valid(jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.media_manifest_valid(facts jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE m jsonb := facts->'manifest'; field text; v jsonb; reference text; parts text[];
 fields constant text[] := ARRAY['state','reason','sha256','name','version','publisher',
 'display_name_reference','display_name','publisher_display_name','display_name_basis',
 'signature_kind','resource_lookup_hresult','resolution_culture'];
BEGIN
 IF jsonb_typeof(m) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
 IF NOT (m ?& fields) OR m-fields<>'{}'::jsonb THEN RETURN false; END IF;
 FOR field,v IN SELECT key,value FROM jsonb_each(m) LOOP
  IF field='resource_lookup_hresult' THEN
   IF v<>'null'::jsonb AND (jsonb_typeof(v)<>'number' OR v::text !~ '^-?[0-9]+$') THEN RETURN false; END IF;
   IF v<>'null'::jsonb AND (v::text::numeric < -2147483648 OR v::text::numeric > 2147483647) THEN RETURN false; END IF;
  ELSIF v<>'null'::jsonb AND (jsonb_typeof(v)<>'string' OR length(m->>field)>4096) THEN RETURN false;
  END IF;
 END LOOP;
 IF coalesce(m->>'signature_kind','')='' OR m->>'resolution_culture' IS NULL THEN RETURN false; END IF;
 IF m->>'state' IN ('unavailable','not_applicable') THEN
  IF m->>'display_name_basis' IS DISTINCT FROM 'unresolved' THEN RETURN false; END IF;
  FOREACH field IN ARRAY ARRAY['sha256','name','version','publisher','display_name_reference','display_name','publisher_display_name','resource_lookup_hresult'] LOOP
   IF m->field IS DISTINCT FROM 'null'::jsonb THEN RETURN false; END IF;
  END LOOP;
  RETURN CASE WHEN m->>'state'='unavailable' THEN coalesce(m->>'reason' IN ('manifest_read_failed','manifest_identity_conflict'),false)
   ELSE m->>'reason'='bundle_or_resource_package' AND (facts->'is_bundle'='true'::jsonb OR facts->'is_resource_package'='true'::jsonb) END;
 END IF;
 IF m->>'state' IS DISTINCT FROM 'read' OR m->>'reason' IS DISTINCT FROM 'exact_manifest_package_identity'
 OR facts->'is_bundle' IS DISTINCT FROM 'false'::jsonb OR facts->'is_resource_package' IS DISTINCT FROM 'false'::jsonb
 OR coalesce(m->>'sha256','') !~ '^[0-9a-f]{64}$' THEN RETURN false; END IF;
 FOREACH field IN ARRAY ARRAY['name','version','publisher'] LOOP
  IF coalesce(btrim(m->>field),'')='' OR m->field IS DISTINCT FROM facts->field THEN RETURN false; END IF;
 END LOOP;
 IF m->>'display_name_basis'='unresolved' THEN RETURN m->'display_name'='null'::jsonb; END IF;
 IF coalesce(m->>'display_name','')='' THEN RETURN false; END IF;
 reference := m->>'display_name_reference';
 IF m->>'display_name_basis'='literal_manifest_value' THEN
  RETURN coalesce(m->>'display_name'=reference AND reference !~* '^ms-resource:' AND reference NOT LIKE '@%'
   AND m->'resource_lookup_hresult'='null'::jsonb,false);
 END IF;
 IF m->>'display_name_basis'='package_resource_text' THEN
  IF m->'resource_lookup_hresult' IS DISTINCT FROM '0'::jsonb OR coalesce(reference,'') !~* '^ms-resource:(//[A-Za-z0-9._-]*/|/)?[A-Za-z0-9._-]+(/[A-Za-z0-9._-]+)*$' THEN RETURN false; END IF;
  parts := string_to_array(substr(reference,13),'/');
  IF parts[1]='' AND parts[2]='' THEN parts := parts[4:cardinality(parts)]; END IF;
  RETURN NOT (parts && ARRAY['.','..']);
 END IF;
 RETURN false;
END $_$;


ALTER FUNCTION evidence_pipeline.media_manifest_valid(facts jsonb) OWNER TO tm_mock_owner;

--
-- Name: native_inventory_accounting(jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.native_inventory_accounting(facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE missing jsonb := '[]'; field text; component text := 'unknown';
 installed_count bigint := 0; staged_count bigint := 0; other_count bigint := 0;
 installation text := 'unknown'; source_identity text := 'unknown';
BEGIN
 IF jsonb_typeof(facts) IS DISTINCT FROM 'object' OR facts->>'source' IS DISTINCT FROM 'Windows inventory'
 OR facts->>'kind' IS NULL OR facts->>'kind' NOT IN ('registry','appx') THEN
  RETURN jsonb_build_object('state','unknown','reason','unsupported_inventory_source','inventory',facts);
 END IF;
 FOREACH field IN ARRAY ARRAY['native_id','name','version','publisher'] LOOP
  IF jsonb_typeof(facts->field) IS DISTINCT FROM 'string' OR btrim(facts->>field)='' THEN
   missing := missing || jsonb_build_array(field);
  END IF;
 END LOOP;
 IF facts->>'kind'='appx' THEN
  FOREACH field IN ARRAY ARRAY['family_name','architecture'] LOOP
   IF jsonb_typeof(facts->field) IS DISTINCT FROM 'string' OR btrim(facts->>field)='' THEN
    missing := missing || jsonb_build_array(field);
   END IF;
  END LOOP;
  IF facts->'is_resource_package'='true'::jsonb THEN component := 'reported_resource_package';
  ELSIF facts->'is_framework'='true'::jsonb THEN component := 'reported_framework_package';
  ELSIF facts->'is_resource_package'='false'::jsonb AND facts->'is_framework'='false'::jsonb THEN
   component := 'reported_non_framework_non_resource_package'; END IF;
  SELECT count(*) FILTER (WHERE u->>'install_state'='Installed'),
   count(*) FILTER (WHERE u->>'install_state'='Staged'),
   count(*) FILTER (WHERE u->>'install_state' IS DISTINCT FROM 'Installed' AND u->>'install_state' IS DISTINCT FROM 'Staged')
   INTO installed_count,staged_count,other_count
   FROM jsonb_array_elements(CASE WHEN jsonb_typeof(facts->'user_states')='array' THEN facts->'user_states' ELSE '[]'::jsonb END) u;
  IF jsonb_typeof(facts->'user_states')='array' THEN
   installation := CASE WHEN installed_count>0 THEN 'reported_installed_for_some_users'
    WHEN staged_count+other_count>0 THEN 'no_reported_installed_user' ELSE 'empty_reported_user_states' END;
  END IF;
 ELSE
  installation := 'uninstall_registration_only';
  component := CASE facts->'system_component' WHEN '1'::jsonb THEN 'reported_registry_system_component'
   WHEN '0'::jsonb THEN 'reported_registry_non_system_component' ELSE 'unknown' END;
 END IF;
 IF jsonb_array_length(missing)=0 THEN source_identity := 'reported'; END IF;
 RETURN jsonb_build_object('state',source_identity,
  'reason',CASE WHEN source_identity='reported' THEN 'explicit_source_identity_fields' ELSE 'missing_source_identity_fields' END,
  'missing_fields',missing,'component_kind',component,'installation_evidence',installation,
  'installed_user_observations',installed_count,'staged_user_observations',staged_count,
  'other_user_observations',other_count,'inventory',facts,
  'interpretation','reported_identity_not_canonical_product_or_applicability');
END $$;


ALTER FUNCTION evidence_pipeline.native_inventory_accounting(facts jsonb) OWNER TO tm_mock_owner;

