--
-- Name: osv_projection_matches(uuid, text, text, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.osv_projection_matches(target uuid, target_table text, native_id text, fields jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE claim jsonb; recipe jsonb; expected jsonb;
BEGIN
 claim := evidence_pipeline.osv_receipt_claim(target);
 IF claim IS NULL OR claim->>'advisory_id' IS DISTINCT FROM native_id
 OR jsonb_typeof(claim->'projection') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
 FOR recipe IN SELECT value FROM jsonb_array_elements(claim->'projection') LOOP
  IF recipe->>0 IS DISTINCT FROM target_table THEN CONTINUE; END IF;
  expected := recipe->1;
  IF target_table IN ('osv_advisory_observations','osv_affected_packages') THEN
   expected := expected || jsonb_build_object('source_fields',(expected->>'source_fields')::jsonb);
  ELSIF target_table <> 'osv_aliases' THEN RETURN false; END IF;
  IF expected=fields THEN RETURN true; END IF;
 END LOOP;
 RETURN false;
END $$;


ALTER FUNCTION evidence_pipeline.osv_projection_matches(target uuid, target_table text, native_id text, fields jsonb) OWNER TO tm_mock_owner;

--
-- Name: osv_query_batch_matches(uuid, text); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.osv_query_batch_matches(target uuid, document text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM evidence.collection_attempts a
 JOIN evidence.source_connections c ON c.id=a.connection_id
 JOIN evidence_pipeline.authorized_connections auth ON auth.connection_id=c.id
 JOIN evidence_pipeline.osv_query_bindings b ON b.connection_id=c.id
 CROSS JOIN LATERAL (SELECT document::jsonb->0 AS m) j
 WHERE a.id=target AND c.source_name='OSV' AND c.input_kind='advisories'
 AND c.tenant_id IS NULL AND c.scope_reference='https://api.osv.dev/v1/query'
 AND j.m->>'format'='triagemate-osv-query-v1'
 AND j.m->>'execution_id'=a.id::text
 AND j.m->'query'=b.query_document::jsonb
 AND j.m->'scope'->>'connection_id'=c.id::text
 AND j.m->'scope'->>'source'=c.source_name AND j.m->'scope'->>'input_kind'=c.input_kind
 AND j.m->'scope'->>'scope_reference'=c.scope_reference
 AND j.m->'scope'->>'origin'=auth.origin AND j.m->'scope'->>'tenant_id' IS NULL
 AND c.collector_reference='evidence-pipeline-v1:'||auth.origin||':'||
   encode(sha256(convert_to(j.m->'scope'->>'provenance','UTF8')),'hex')
 AND (j.m->>'started_at')::timestamptz=a.started_at
 AND (j.m->>'finished_at')::timestamptz=a.finished_at
 AND j.m->>'error_code' IS NOT DISTINCT FROM a.error_code
 AND a.complete=(a.outcome='success')
 AND (a.complete=(j.m->>'error_code' IS NULL))
 AND jsonb_typeof(j.m->'pages')='array' AND jsonb_array_length(j.m->'pages')<=100
 AND a.input_fingerprint=encode(sha256(convert_to(document,'UTF8')),'hex'))
$$;


ALTER FUNCTION evidence_pipeline.osv_query_batch_matches(target uuid, document text) OWNER TO tm_mock_owner;

--
-- Name: osv_query_record_hashes(bytea); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.osv_query_record_hashes(wire bytea) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT coalesce(array_agg(encode(sha256(convert_to(value::text,'UTF8')),'hex') ORDER BY position),ARRAY[]::text[])
 FROM jsonb_array_elements(coalesce(ltrim(convert_from(wire,'UTF8'),chr(65279))::jsonb->'vulns','[]'::jsonb)) WITH ORDINALITY records(value,position)
$$;


ALTER FUNCTION evidence_pipeline.osv_query_record_hashes(wire bytea) OWNER TO tm_mock_owner;

--
-- Name: osv_receipt_claim(uuid); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.osv_receipt_claim(target uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT p.claim::jsonb FROM evidence.observation_receipts r
 JOIN evidence.collection_attempts a ON a.id=r.collection_attempt_id
 JOIN evidence.source_revisions rev ON rev.id=r.source_revision_id AND rev.connection_id=a.connection_id
 JOIN evidence.source_connections c ON c.id=a.connection_id
 JOIN evidence_pipeline.authorized_connections auth ON auth.connection_id=c.id AND auth.origin=rev.origin
 JOIN evidence_pipeline.public_claims p ON p.source_revision_id=rev.id
 WHERE r.id=target AND a.complete AND a.outcome='success' AND c.tenant_id IS NULL
 AND c.source_name IN ('OSV','GitHub','Ubuntu') AND c.input_kind='advisories'
 AND p.claim::jsonb->>'adapter'='osv-record-v1'
 AND p.claim::jsonb->>'advisory_id'=rev.source_record_id
$$;


ALTER FUNCTION evidence_pipeline.osv_receipt_claim(target uuid) OWNER TO tm_mock_owner;

