--
-- Name: recognize_windows_inventory(jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.recognize_windows_inventory(facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
 product text := facts->>'product'; publisher text := facts->>'publisher';
 family text; distribution text; architecture text; profile text;
 package_reference text; expected_family text; media_identity boolean := false;
 framework_mapping jsonb; system_mapping jsonb; store_mapping jsonb; cbs_mapping jsonb;
 version_parts jsonb; reason text := 'unsupported_inventory_product_identity';
 microsoft_package constant text := 'CN=Microsoft Corporation, O=Microsoft Corporation, L=Redmond, S=Washington, C=US';
BEGIN
 IF facts->>'source' IN ('Intune','Windows inventory') THEN
  IF publisher='Microsoft Corporation' THEN
   distribution := 'desktop_application';
   family := CASE product
    WHEN 'Microsoft Edge' THEN 'Microsoft Edge'
    WHEN 'Microsoft Edge WebView2 Runtime' THEN 'Microsoft Edge WebView2 Runtime'
    WHEN 'Microsoft Intune Management Extension' THEN 'Microsoft Intune Management Extension'
    WHEN 'Microsoft OneDrive' THEN 'Microsoft OneDrive'
    WHEN 'OpenSSH' THEN 'Microsoft OpenSSH for Windows'
    ELSE NULL END;
   IF product ~ '^Microsoft Visual C\+\+ 2015-2022 Redistributable \(x(64|86)\) - [0-9]{1,8}\.[0-9]{1,8}\.[0-9]{1,8}$' THEN
    family := 'Microsoft Visual C++ 2015-2022 Redistributable';
    architecture := CASE WHEN product LIKE '%(x64)%' THEN 'x64' ELSE 'x86' END;
   END IF;
   IF product ~ '^Microsoft Visual C\+\+ 2022 X(64|86) (Minimum|Additional) Runtime - [0-9]{1,8}\.[0-9]{1,8}\.[0-9]{1,8}$' THEN
    IF facts->>'version'=(string_to_array(product,' - '))[2] THEN
     family := CASE WHEN product LIKE '% Minimum Runtime - %' THEN 'Microsoft Visual C++ 2022 Minimum Runtime' ELSE 'Microsoft Visual C++ 2022 Additional Runtime' END;
     architecture := CASE WHEN product LIKE '% X64 %' THEN 'x64' ELSE 'x86' END;
    ELSE family := NULL; reason := 'conflicting_component_name_and_reported_version'; END IF;
   END IF;
  ELSIF publisher=microsoft_package THEN
   distribution := 'windows_package';
   family := CASE product
    WHEN 'MSTeams' THEN 'Microsoft Teams'
    WHEN 'Microsoft.MicrosoftEdge.Stable' THEN 'Microsoft Edge'
    WHEN 'Microsoft.OutlookForWindows' THEN 'Outlook for Windows'
    WHEN 'Microsoft.Windows.DevHome' THEN 'Windows Dev Home'
    WHEN 'Microsoft.WindowsAppRuntime.1.5' THEN 'Windows App Runtime 1.5'
    WHEN 'Microsoft.WindowsAppRuntime.1.6' THEN 'Windows App Runtime 1.6'
    WHEN 'MicrosoftCorporationII.QuickAssist' THEN 'Microsoft Quick Assist'
    ELSE NULL END;
   IF family IS NULL AND facts->>'source'='Windows inventory' THEN
    family := CASE product
    WHEN 'Microsoft.BingNews' THEN 'Microsoft News'
    WHEN 'Microsoft.BingWeather' THEN 'MSN Weather'
    WHEN 'Microsoft.DesktopAppInstaller' THEN 'App Installer'
    WHEN 'Microsoft.GamingApp' THEN 'Xbox'
    WHEN 'Microsoft.GetHelp' THEN 'Get Help'
    WHEN 'Microsoft.MicrosoftOfficeHub' THEN 'Microsoft Office Hub'
    WHEN 'Microsoft.MicrosoftSolitaireCollection' THEN 'Microsoft Solitaire Collection'
    WHEN 'Microsoft.MicrosoftStickyNotes' THEN 'Microsoft Sticky Notes'
    WHEN 'Microsoft.Paint' THEN 'Paint'
    WHEN 'Microsoft.PowerAutomateDesktop' THEN 'Power Automate Desktop'
    WHEN 'Microsoft.ScreenSketch' THEN 'Snipping Tool'
    WHEN 'Microsoft.StorePurchaseApp' THEN 'Store Purchase App'
    WHEN 'Microsoft.Todos' THEN 'Microsoft To Do'
    WHEN 'Microsoft.Windows.Photos' THEN 'Microsoft Photos'
    WHEN 'Microsoft.WindowsAlarms' THEN 'Windows Clock'
    WHEN 'Microsoft.WindowsCalculator' THEN 'Windows Calculator'
    WHEN 'Microsoft.WindowsCamera' THEN 'Windows Camera'
    WHEN 'Microsoft.WindowsFeedbackHub' THEN 'Feedback Hub'
    WHEN 'Microsoft.WindowsNotepad' THEN 'Windows Notepad'
    WHEN 'Microsoft.WindowsStore' THEN 'Microsoft Store'
    WHEN 'Microsoft.WindowsSoundRecorder' THEN 'Windows Sound Recorder'
    WHEN 'Microsoft.WindowsTerminal' THEN 'Windows Terminal'
    WHEN 'Microsoft.Xbox.TCUI' THEN 'Xbox Title Callable UI'
    WHEN 'Microsoft.XboxGamingOverlay' THEN 'Xbox Game Bar'
    WHEN 'Microsoft.XboxIdentityProvider' THEN 'Xbox Identity Provider'
    WHEN 'Microsoft.XboxSpeechToTextOverlay' THEN 'Xbox Speech To Text Overlay'
    WHEN 'Microsoft.YourPhone' THEN 'Phone Link'
    WHEN 'Microsoft.ZuneMusic' THEN 'Windows Media Player'
     ELSE NULL END;
    IF family IS NOT NULL THEN
     expected_family := product || '_8wekyb3d8bbwe';
     IF facts->>'family_name' IS DISTINCT FROM expected_family THEN
      family := NULL; reason := 'conflicting_published_package_family';
     ELSIF facts->'is_framework' IS DISTINCT FROM 'false'::jsonb THEN
      family := NULL; reason := 'conflicting_application_package_kind';
     ELSE
      package_reference := 'https://raw.githubusercontent.com/The-Virtual-Desktop-Team/Windows-Desktop-Optimization-Tool/2136d06113776f7df01ad168329e615f35e909cd/Configurations/Templates/AppxPackages.json';
     END IF;
    END IF;
   END IF;
  ELSIF publisher IN ('VMware, Inc.','Broadcom Inc.') AND product='VMware Tools' THEN
   family := 'VMware Tools'; distribution := 'desktop_application';
  END IF;
 END IF;
 IF family IS NULL AND facts->>'source'='Windows inventory' AND publisher=microsoft_package THEN
  family := CASE product
   WHEN 'Microsoft.AV1VideoExtension' THEN 'AV1 video codec package'
   WHEN 'Microsoft.HEVCVideoExtension' THEN 'HEVC video codec package'
   WHEN 'Microsoft.VP9VideoExtensions' THEN 'VP9 video codec package'
   ELSE NULL END;
  IF family IS NOT NULL THEN
   distribution := 'windows_package';
   IF facts->>'family_name' IS DISTINCT FROM product || '_8wekyb3d8bbwe' THEN
    family := NULL; reason := 'conflicting_published_package_family';
   ELSIF facts->'is_framework' IS DISTINCT FROM 'false'::jsonb THEN
    family := NULL; reason := 'conflicting_application_package_kind';
   ELSE
    media_identity := true;
    package_reference := 'https://chromium.googlesource.com/chromium/src/+/375869ebc88c041e6493d10543722631aee04df2/media/base/win/media_foundation_package_runtime_locator.cc?format=TEXT';
   END IF;
  END IF;
 END IF;
 IF family IS NULL AND facts->>'source'='Windows inventory' AND publisher=microsoft_package THEN
