--
-- Name: record_classification(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_classification_function
--

CREATE FUNCTION evidence_pipeline.record_classification(decision uuid, device uuid, chosen text, explanation text, expected_previous uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE prior evidence.classification_decisions%ROWTYPE;
DECLARE old evidence.classification_decisions%ROWTYPE;
BEGIN
 IF decision IS NULL OR device IS NULL OR decision='00000000-0000-0000-0000-000000000000'::uuid
 OR chosen IS NULL OR length(btrim(chosen))=0 OR length(chosen)>128
 OR explanation IS NULL OR length(btrim(explanation))=0 OR length(explanation)>4000 THEN
  RAISE EXCEPTION 'Classification requires a device, bounded type and reason' USING ERRCODE='22023';
 END IF;
 PERFORM pg_advisory_xact_lock(731904217);
 IF NOT EXISTS(SELECT 1 FROM evidence.provider_devices p
 JOIN evidence.source_connections c ON c.id=p.connection_id
 JOIN evidence_pipeline.authorized_connections a ON a.connection_id=c.id
 WHERE p.id=device AND c.source_name IN ('Entra','Intune','Defender') AND c.input_kind='devices') THEN
  RAISE EXCEPTION 'Classification target is not a registered Microsoft device' USING ERRCODE='22023';
 END IF;
 SELECT * INTO old FROM evidence.classification_decisions WHERE id=decision;
 IF FOUND THEN
  IF old.provider_device_id=device AND old.selected_type=chosen AND old.reason=explanation
   AND old.supersedes_decision_id IS NOT DISTINCT FROM expected_previous
   AND old.actor_kind='analyst' AND old.actor_reference='local operator' THEN
   RETURN decision;
  END IF;
  RAISE EXCEPTION 'Classification request identifier was reused with different input' USING ERRCODE='22023';
 END IF;
 SELECT * INTO prior FROM evidence.classification_decisions
 WHERE provider_device_id=device ORDER BY revision DESC,decided_at DESC,id DESC LIMIT 1;
 IF prior.id IS DISTINCT FROM expected_previous THEN
  RAISE EXCEPTION 'Classification changed; reload before saving' USING ERRCODE='40001';
 END IF;
 INSERT INTO evidence.classification_decisions(id,provider_device_id,selected_type,actor_kind,actor_reference,reason,decided_at,revision,supersedes_decision_id)
 VALUES(decision,device,chosen,'analyst','local operator',explanation,clock_timestamp(),coalesce(prior.revision,0)+1,prior.id);
 RETURN decision;
END $$;


ALTER FUNCTION evidence_pipeline.record_classification(decision uuid, device uuid, chosen text, explanation text, expected_previous uuid) OWNER TO tm_classification_function;

--
-- Name: reference_claim(uuid); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.reference_claim(target uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT p.claim::jsonb FROM evidence.observation_receipts receipt
 JOIN evidence.collection_attempts a ON a.id=receipt.collection_attempt_id
 JOIN evidence.source_revisions r ON r.id=receipt.source_revision_id AND r.connection_id=a.connection_id
 JOIN evidence.source_connections c ON c.id=a.connection_id
 JOIN evidence_pipeline.authorized_connections auth ON auth.connection_id=c.id AND auth.origin=r.origin
 JOIN evidence_pipeline.public_claims p ON p.source_revision_id=r.id
 WHERE (c.source_name<>'Cisco' OR r.origin='synthetic' OR
  c.scope_reference LIKE 'https://sec.cloudapps.cisco.com/security/center/content/CiscoSecurityAdvisory/%')
 AND (c.source_name<>'Cisco' OR c.scope_reference NOT LIKE
  'https://sec.cloudapps.cisco.com/security/center/content/CiscoSecurityAdvisory/%'
  OR r.source_record_id=split_part(c.scope_reference,'/',8)) AND (c.source_name<>'WA SOC' OR evidence_pipeline.wasoc_source_allowed(r.source_record_id,r.source_url)) AND receipt.id=target AND a.complete AND a.outcome='success' AND c.tenant_id IS NULL
 AND r.source_url=c.scope_reference AND evidence_pipeline.reference_source_allowed(c.source_name,c.input_kind,c.scope_reference)
 AND p.claim::jsonb->>'adapter'='public-reference-v1' AND p.claim::jsonb->>'native_id'=r.source_record_id
 AND p.claim::jsonb->>'reference_kind'=CASE c.source_name WHEN 'Exploit-DB' THEN 'exploit_metadata' WHEN 'CTID' THEN 'cve_attack_mapping' WHEN 'Red Hat' THEN 'vendor_csaf' WHEN 'Debian' THEN 'vendor_advisory_data' WHEN 'Apache HTTP Server' THEN 'vendor_advisory_data' WHEN 'Apache Tomcat' THEN 'vendor_advisory_data' WHEN 'Samba' THEN 'vendor_advisory_data' WHEN 'Cisco' THEN 'vendor_advisory_data' WHEN 'WA SOC' THEN 'vendor_advisory_data' WHEN 'Palo Alto Networks' THEN 'vendor_advisory_data' WHEN 'Microsoft Update Catalog' THEN 'vendor_advisory_data' ELSE 'attack_definition' END
$$;


ALTER FUNCTION evidence_pipeline.reference_claim(target uuid) OWNER TO tm_mock_owner;

--
-- Name: reference_projection_matches(uuid, text, text, text[], jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.reference_projection_matches(target uuid, native_id text, reference_kind text, cve_ids text[], source_fields jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 WITH checked AS MATERIALIZED (
  SELECT evidence_pipeline.reference_claim(target) AS claim
 )
 SELECT coalesce(claim->>'native_id'=native_id
  AND claim->>'reference_kind'=reference_kind
  AND claim->'cve_ids'=to_jsonb(cve_ids)
  AND (claim->>'source_fields')::jsonb=source_fields,false)
 FROM checked
$$;


ALTER FUNCTION evidence_pipeline.reference_projection_matches(target uuid, native_id text, reference_kind text, cve_ids text[], source_fields jsonb) OWNER TO tm_mock_owner;

--
-- Name: reference_source_allowed(text, text, text); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.reference_source_allowed(source_name text, input_kind text, scope_reference text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT (source_name,input_kind,scope_reference) IN (
 ('Exploit-DB','metadata','https://gitlab.com/exploit-database/exploitdb/-/raw/main/files_exploits.csv'),
 ('CTID','cve_mappings','https://raw.githubusercontent.com/center-for-threat-informed-defense/mappings-explorer/main/src/mapex_convert/mappings/Att&ckToCveMappings.csv'),
 ('MITRE ATT&CK','enterprise_definitions','https://raw.githubusercontent.com/mitre-attack/attack-stix-data/master/enterprise-attack/enterprise-attack.json')) OR (source_name='Red Hat' AND input_kind='advisories' AND scope_reference ~ '^https://security[.]access[.]redhat[.]com/data/csaf/v2/advisories/[0-9]{4}/(rhsa|rhba|rhea)-[0-9]{4}_[0-9]{3,10}[.]json$') OR (input_kind='tracker' AND source_name='Debian' AND scope_reference='https://security-tracker.debian.org/tracker/data/json')
 OR (input_kind='advisories' AND ((source_name='Apache HTTP Server' AND scope_reference ~ '^https://httpd[.]apache[.]org/security/json/CVE-[0-9]{4}-[0-9]{4,19}[.]json$')
 OR (source_name='Apache Tomcat' AND scope_reference ~ '^https://raw[.]githubusercontent[.]com/apache/tomcat-site/trunk/xdocs/security-(9|10|11)[.]xml$')
 OR (source_name='Samba' AND scope_reference ~ '^https://www[.]samba[.]org/samba/security/CVE-[0-9]{4}-[0-9]{4,19}[.]html$')))
 OR (source_name='Palo Alto Networks' AND input_kind='advisories' AND scope_reference ~ '^https://security[.]paloaltonetworks[.]com/json/CVE-[0-9]{4}-[0-9]{4,19}$')
 OR (source_name='Microsoft Update Catalog' AND input_kind='updates' AND scope_reference ~ '^https://www[.]catalog[.]update[.]microsoft[.]com/ScopedViewInline[.]aspx[?]updateid=[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
 OR (source_name='Cisco' AND input_kind='advisories' AND scope_reference ~ '^https://www[.]cisco[.]com/[.]well-known/csaf/[0-9]{4}/cisco-sa-[a-z0-9][a-z0-9_-]{0,240}[.]json$')
 OR (source_name='Cisco' AND input_kind='advisories' AND scope_reference ~ '^https://sec[.]cloudapps[.]cisco[.]com/security/center/content/CiscoSecurityAdvisory/(cisco-sa-[A-Za-z0-9][A-Za-z0-9_.-]{0,240})/csaf/\1[.]json$')
 OR (source_name='WA SOC' AND input_kind='advisories' AND evidence_pipeline.wasoc_source_allowed(
 substring(scope_reference FROM '/docs/advisories/([0-9]{9,14})-'),scope_reference))
$_$;


ALTER FUNCTION evidence_pipeline.reference_source_allowed(source_name text, input_kind text, scope_reference text) OWNER TO tm_mock_owner;

--
-- Name: refresh_notifications(uuid); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_notification_function
--

CREATE FUNCTION evidence_pipeline.refresh_notifications(p_connection uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    PERFORM pg_advisory_xact_lock(731904217);
    IF NOT EXISTS(SELECT 1 FROM evidence_pipeline.authorized_connections WHERE connection_id=p_connection) THEN
        RETURN;
    END IF;
    -- A late-arriving attempt can change episode boundaries. Remove only obsolete
    -- derived episodes; collection attempts/evidence and unrelated notices stay.
    DELETE FROM evidence.notification_attempts x USING evidence.notifications n
    WHERE x.notification_id=n.id AND n.connection_id=p_connection AND n.category='collection-failure'
      AND NOT EXISTS(SELECT 1 FROM evidence_pipeline.notification_episodes e WHERE e.id=n.id);
    DELETE FROM evidence.notifications n
    WHERE n.connection_id=p_connection AND n.category='collection-failure'
      AND NOT EXISTS(SELECT 1 FROM evidence_pipeline.notification_episodes e WHERE e.id=n.id);
    INSERT INTO evidence.notifications AS stored (
        id,connection_id,scope_reference,category,urgency,episode_started_at,
        first_failure_id,latest_failure_id,failure_count,status,resolved_at,
        recovery_attempt_id,revision,page_path)
    SELECT id,connection_id,scope_reference,category,urgency,episode_started_at,
        first_failure_id,latest_failure_id,failure_count,status,resolved_at,
        recovery_attempt_id,1,page_path
    FROM evidence_pipeline.notification_episodes WHERE connection_id=p_connection
    ON CONFLICT(id) DO UPDATE SET
        urgency=excluded.urgency,latest_failure_id=excluded.latest_failure_id,failure_count=excluded.failure_count,
        status=excluded.status,resolved_at=excluded.resolved_at,
        recovery_attempt_id=excluded.recovery_attempt_id,revision=stored.revision+1
    WHERE (stored.urgency,stored.latest_failure_id,stored.failure_count,stored.status,stored.resolved_at,stored.recovery_attempt_id)
        IS DISTINCT FROM (excluded.urgency,excluded.latest_failure_id,excluded.failure_count,excluded.status,excluded.resolved_at,excluded.recovery_attempt_id);
    DELETE FROM evidence.notification_attempts x USING evidence.notifications n
    WHERE x.notification_id=n.id AND n.connection_id=p_connection AND n.category='collection-failure'
      AND NOT EXISTS(SELECT 1 FROM evidence_pipeline.notification_episodes e
                     WHERE e.id=n.id AND x.collection_attempt_id=ANY(e.failure_ids));
    INSERT INTO evidence.notification_attempts(notification_id,collection_attempt_id)
    SELECT id,unnest(failure_ids) FROM evidence_pipeline.notification_episodes WHERE connection_id=p_connection
    ON CONFLICT DO NOTHING;
END $$;


ALTER FUNCTION evidence_pipeline.refresh_notifications(p_connection uuid) OWNER TO tm_notification_function;

--
-- Name: resource_package_pair(jsonb, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.resource_package_pair(resource jsonb, parent jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT coalesce(
 resource->>'source'='Windows inventory' AND parent->>'source'='Windows inventory'
 AND resource->>'kind'='appx' AND parent->>'kind'='appx'
 AND resource->'is_resource_package'='true'::jsonb
 AND resource->'is_bundle'='false'::jsonb AND resource->'is_framework'='false'::jsonb
 AND parent->'is_resource_package'='false'::jsonb
 AND parent->'is_bundle'='false'::jsonb AND parent->'is_framework'='false'::jsonb
 AND resource->>'native_id'<>parent->>'native_id'
 AND length(btrim(resource->>'native_id'))>0 AND length(btrim(parent->>'native_id'))>0
 AND length(btrim(resource->>'name'))>0 AND resource->>'name'=parent->>'name'
 AND length(btrim(resource->>'publisher'))>0 AND resource->>'publisher'=parent->>'publisher'
 AND length(btrim(resource->>'family_name'))>0 AND resource->>'family_name'=parent->>'family_name'
 AND resource->>'version' ~ '^[0-9]{1,5}(\.[0-9]{1,5}){3}$'
 AND resource->>'version'=parent->>'version'
 AND lower(parent->>'architecture') IN ('x86','x64','arm','arm64','neutral','x86a64')
 AND (lower(resource->>'architecture')='neutral' OR lower(resource->>'architecture')=lower(parent->>'architecture'))
 ,false);
$_$;


ALTER FUNCTION evidence_pipeline.resource_package_pair(resource jsonb, parent jsonb) OWNER TO tm_mock_owner;

--
-- Name: valid_bundle_member(jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.valid_bundle_member(f jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT coalesce(
 f->>'kind'='appx_bundle_member'
 AND jsonb_typeof(f->'member_index')='number'
 AND f->>'member_index' ~ '^[1-9][0-9]*$'
 AND f->>'manifest_sha256' ~ '^[0-9a-f]{64}$'
 AND f->>'member_type' IN ('application','resource')
 AND f->>'architecture' IN ('x86','x64','arm','arm64','neutral','x86a64')
 AND jsonb_typeof(f->'is_stub')='boolean'
 AND jsonb_typeof(f->'resource_id')='string'
 AND f->>'resource_id' ~ '^[A-Za-z0-9.-]{0,30}$'
 AND f->>'version' ~ '^[0-9]{1,5}(\.[0-9]{1,5}){3}$'
 AND f->>'bundle_version' ~ '^[0-9]{1,5}(\.[0-9]{1,5}){3}$'
 AND NOT EXISTS (SELECT 1 FROM unnest(string_to_array(f->>'version','.')) p
   WHERE CASE WHEN p ~ '^[0-9]{1,5}$' THEN p::integer>65535 ELSE true END)
 AND NOT EXISTS (SELECT 1 FROM unnest(string_to_array(f->>'bundle_version','.')) p
   WHERE CASE WHEN p ~ '^[0-9]{1,5}$' THEN p::integer>65535 ELSE true END)
 AND f->>'native_id'=encode(sha256(convert_to(
   '['||to_jsonb(f->>'bundle_native_id')::text||','||to_jsonb(f->>'manifest_sha256')::text||','||
   (f->>'member_index')||']','UTF8')),'hex')
 AND length(btrim(f->>'bundle_native_id')) BETWEEN 1 AND 4096
 AND length(btrim(f->>'name')) BETWEEN 1 AND 4096
 AND length(btrim(f->>'publisher')) BETWEEN 1 AND 4096
 AND length(btrim(f->>'family_name')) BETWEEN 1 AND 4096
 ,false);
$_$;


ALTER FUNCTION evidence_pipeline.valid_bundle_member(f jsonb) OWNER TO tm_mock_owner;

--
-- Name: valid_bundle_summary(jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.valid_bundle_summary(f jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT coalesce(f->>'kind'='appx' AND f->'is_bundle'='true'::jsonb
 AND jsonb_typeof(f->'bundle_manifest')='object'
 AND jsonb_typeof(f->'bundle_manifest'->'member_count')='number'
 AND f->'bundle_manifest'->>'member_count' ~ '^(0|[1-9][0-9]*)$'
 AND ((f->'bundle_manifest'->>'state'='read'
 AND f->'bundle_manifest'->>'reason'='exact_bundle_manifest_identity'
 AND f->'bundle_manifest'->>'sha256' ~ '^[0-9a-f]{64}$')
 OR (f->'bundle_manifest'->>'state'='unavailable'
 AND f->'bundle_manifest'->>'reason' IN ('bundle_manifest_read_failed','bundle_manifest_identity_conflict')
 AND f->'bundle_manifest'->'sha256'='null'::jsonb
 AND f->'bundle_manifest'->>'member_count'='0')),false);
$_$;


ALTER FUNCTION evidence_pipeline.valid_bundle_summary(f jsonb) OWNER TO tm_mock_owner;

