--
-- Name: collection_status; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.collection_status AS
 SELECT c.id AS connection_id,
    c.source_name,
    c.input_kind,
    c.tenant_id,
    c.scope_reference,
    selected.id AS selected_attempt_id,
    selected.finished_at AS selected_finished_at,
    latest.id AS latest_attempt_id,
    latest.outcome AS latest_outcome,
    latest.finished_at AS latest_finished_at,
    latest.error_code,
    latest.safe_error_detail
   FROM ((evidence.source_connections c
     LEFT JOIN LATERAL ( SELECT a.id,
            a.connection_id,
            a.started_at,
            a.finished_at,
            a.outcome,
            a.complete,
            a.error_code,
            a.safe_error_detail,
            a.revision,
            a.input_fingerprint
           FROM evidence.collection_attempts a
          WHERE ((a.connection_id = c.id) AND a.complete AND (a.outcome = 'success'::text))
          ORDER BY a.finished_at DESC, a.started_at DESC, a.id DESC
         LIMIT 1) selected ON (true))
     LEFT JOIN LATERAL ( SELECT a.id,
            a.connection_id,
            a.started_at,
            a.finished_at,
            a.outcome,
            a.complete,
            a.error_code,
            a.safe_error_detail,
            a.revision,
            a.input_fingerprint
           FROM evidence.collection_attempts a
          WHERE (a.connection_id = c.id)
          ORDER BY a.finished_at DESC, a.started_at DESC, a.id DESC
         LIMIT 1) latest ON (true))
  WHERE (c.collector_reference ~~ 'evidence-pipeline-v1:%'::text);


ALTER VIEW evidence_pipeline.collection_status OWNER TO tm_mock_owner;

--
-- Name: VIEW collection_status; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.collection_status IS 'Latest attempt and independently selected complete snapshot for each pipeline input. Failures retain prior usable evidence.';


--
-- Name: completeness_definition; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.completeness_definition AS
 SELECT 'computer-device-v2'::text AS definition_id,
    source_name,
    field_name,
    value_kind,
    ((lower(source_name) || '.'::text) || field_name) AS field_key
   FROM ( VALUES ('Entra'::text,'native_device_id'::text,'text'::text), ('Entra'::text,'display_name'::text,'text'::text), ('Entra'::text,'operating_system'::text,'text'::text), ('Entra'::text,'os_version'::text,'text'::text), ('Entra'::text,'join_type'::text,'text'::text), ('Entra'::text,'registered_at'::text,'timestamp'::text), ('Entra'::text,'approximate_last_sign_in'::text,'timestamp'::text), ('Entra'::text,'account_enabled'::text,'boolean'::text), ('Entra'::text,'managed_flag'::text,'boolean'::text), ('Entra'::text,'compliant_flag'::text,'boolean'::text), ('Intune'::text,'native_device_id'::text,'text'::text), ('Intune'::text,'display_name'::text,'text'::text), ('Intune'::text,'operating_system'::text,'text'::text), ('Intune'::text,'os_version'::text,'text'::text), ('Intune'::text,'management_state'::text,'text'::text), ('Intune'::text,'compliance_state'::text,'text'::text), ('Intune'::text,'owner_type'::text,'text'::text), ('Intune'::text,'manufacturer'::text,'text'::text), ('Intune'::text,'model'::text,'text'::text), ('Intune'::text,'serial_number'::text,'text'::text), ('Intune'::text,'enrolled_at'::text,'timestamp'::text), ('Intune'::text,'last_sync'::text,'timestamp'::text), ('Defender'::text,'native_device_id'::text,'text'::text), ('Defender'::text,'display_name'::text,'text'::text), ('Defender'::text,'operating_system'::text,'text'::text), ('Defender'::text,'release_label'::text,'text'::text), ('Defender'::text,'onboarding_status'::text,'text'::text), ('Defender'::text,'sensor_health'::text,'text'::text), ('Defender'::text,'first_seen'::text,'timestamp'::text), ('Defender'::text,'last_seen'::text,'timestamp'::text), ('Defender'::text,'os_build'::text,'number'::text), ('Defender'::text,'os_processor'::text,'text'::text), ('Microsoft'::text,'registration_id'::text,'text'::text), ('Microsoft'::text,'source_device_type'::text,'text'::text)) fields(source_name, field_name, value_kind);


ALTER VIEW evidence_pipeline.completeness_definition OWNER TO tm_mock_owner;

--
-- Name: VIEW completeness_definition; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.completeness_definition IS 'Provisional eligible source device facts, version 2. Defender os_processor counts the source architecture once. os_architecture bitness and derived architecture/OS class are inspectable but excluded as duplicate or derived representations; identifiers and provenance exclusions are unchanged.';


--
-- Name: exposure_snapshots; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.exposure_snapshots (
    collection_attempt_id uuid NOT NULL,
    input_connection_id uuid NOT NULL,
    device_attempt_id uuid NOT NULL,
    relationship_fingerprint text,
    CONSTRAINT exposure_snapshots_relationship_fingerprint_check CHECK ((relationship_fingerprint ~ '^[0-9a-f]{64}$'::text))
);


ALTER TABLE evidence_pipeline.exposure_snapshots OWNER TO tm_mock_owner;

--
-- Name: current_antivirus; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_antivirus AS
 SELECT c.connection_id,
    c.source_name,
    c.tenant_id,
    c.selected_attempt_id,
    c.selected_finished_at,
    c.latest_outcome,
    s.device_attempt_id,
    o.id,
    o.provider_device_id,
    o.receipt_id,
    o.source_record_id,
    o.device_name,
    o.os_kind,
    o.os_platform,
    o.os_version,
    o.mode,
    o.signature_version,
    o.engine_version,
    o.platform_version,
    o.signature_updated_at,
    o.engine_updated_at,
    o.platform_updated_at,
    o.signature_current,
    o.engine_current,
    o.platform_current,
    o.signature_published_at,
    o.refreshed_at,
    o.last_seen_at,
    o.quick_scan_result,
    o.quick_scan_error,
    o.quick_scan_at,
    o.full_scan_result,
    o.full_scan_error,
    o.full_scan_at,
    o.source_rbac_group_id,
    o.source_rbac_group_name,
    o.signature_status,
    o.engine_status,
    o.platform_status
   FROM (((evidence_pipeline.collection_status c
     JOIN evidence_pipeline.exposure_snapshots s ON ((s.collection_attempt_id = c.selected_attempt_id)))
     JOIN evidence.observation_receipts r ON ((r.collection_attempt_id = s.collection_attempt_id)))
     JOIN evidence.antivirus_observations o ON ((o.receipt_id = r.id)))
  WHERE ((c.source_name = 'Defender'::text) AND (c.input_kind = 'antivirus'::text));


ALTER VIEW evidence_pipeline.current_antivirus OWNER TO tm_mock_owner;

--
-- Name: VIEW current_antivirus; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_antivirus IS 'Source antivirus health; unknown text and report timestamps remain explicit. Multiple records can describe one device. No inference of vulnerability resolution or overall protection.';


--
-- Name: current_assessment_baseline; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_assessment_baseline AS
 WITH selected AS (
         SELECT DISTINCT ON (a.connection_id) a.id,
            a.connection_id,
            a.finished_at
           FROM (evidence.collection_attempts a
             JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
          WHERE (a.complete AND (a.outcome = 'success'::text) AND (c.source_name = 'Defender'::text) AND (c.input_kind = 'vulnerability_baseline'::text))
          ORDER BY a.connection_id, a.finished_at DESC, a.started_at DESC, a.id DESC
        )
 SELECT s.connection_id,
    s.id AS collection_attempt_id,
    s.finished_at AS collected_at,
    o.provider_device_id,
    o.cve_id,
    o.instance_key,
    o.claim,
    o.receipt_id
   FROM ((selected s
     JOIN evidence.observation_receipts r ON ((r.collection_attempt_id = s.id)))
     JOIN evidence_pipeline.assessment_observations o ON ((o.receipt_id = r.id)));


ALTER VIEW evidence_pipeline.current_assessment_baseline OWNER TO tm_mock_owner;

--
-- Name: wasoc_repository_snapshots; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.wasoc_repository_snapshots (
    source_name text NOT NULL,
    run_id uuid NOT NULL,
    origin text NOT NULL,
    repository_commit text NOT NULL,
    reference_observed_at timestamp with time zone NOT NULL,
    reference_payload jsonb NOT NULL,
    members jsonb NOT NULL,
    CONSTRAINT wasoc_repository_snapshots_check CHECK (COALESCE((((reference_payload ->> 'ref'::text) = 'refs/heads/main'::text) AND (((reference_payload -> 'object'::text) ->> 'type'::text) = 'commit'::text) AND (((reference_payload -> 'object'::text) ->> 'sha'::text) = repository_commit)), false)),
    CONSTRAINT wasoc_repository_snapshots_members_check CHECK (((jsonb_typeof(members) = 'array'::text) AND (jsonb_array_length(members) <= 1000000))),
    CONSTRAINT wasoc_repository_snapshots_origin_check CHECK ((origin = ANY (ARRAY['public'::text, 'synthetic'::text]))),
    CONSTRAINT wasoc_repository_snapshots_repository_commit_check CHECK (((repository_commit ~ '^[a-f0-9]{40}$'::text) AND (repository_commit <> '0000000000000000000000000000000000000000'::text))),
    CONSTRAINT wasoc_repository_snapshots_source_name_check CHECK ((source_name = 'WA SOC'::text))
);


ALTER TABLE evidence_pipeline.wasoc_repository_snapshots OWNER TO tm_mock_owner;

--
-- Name: current_wasoc_repository_snapshot; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_wasoc_repository_snapshot AS
 SELECT DISTINCT ON (origin) source_name,
    run_id,
    origin,
    repository_commit,
    reference_observed_at,
    reference_payload,
    members
   FROM evidence_pipeline.wasoc_repository_snapshots
  ORDER BY origin, reference_observed_at DESC, run_id DESC;


ALTER VIEW evidence_pipeline.current_wasoc_repository_snapshot OWNER TO tm_mock_owner;

--
-- Name: current_public_references; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_public_references AS
 WITH selected AS (
         SELECT DISTINCT ON (a.connection_id) a.connection_id,
            a.id,
            a.finished_at,
            c.source_name,
            c.input_kind
           FROM (evidence.collection_attempts a
             JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
          WHERE (evidence_pipeline.reference_source_allowed(c.source_name, c.input_kind, c.scope_reference) AND a.complete AND (a.outcome = 'success'::text))
          ORDER BY a.connection_id, a.finished_at DESC, a.started_at DESC, a.id DESC
        )
 SELECT s.connection_id,
    s.id AS collection_attempt_id,
    s.finished_at AS collected_at,
    s.source_name,
    s.input_kind,
    o.receipt_id,
    o.native_id,
    o.reference_kind,
    o.cve_ids,
    o.source_fields,
    r.origin,
    r.source_url,
    r.licence_or_provenance
   FROM (((selected s
     JOIN evidence.observation_receipts receipt ON ((receipt.collection_attempt_id = s.id)))
     JOIN evidence.source_revisions r ON ((r.id = receipt.source_revision_id)))
     JOIN evidence.public_reference_observations o ON ((o.receipt_id = receipt.id)))
  WHERE (s.source_name <> 'WA SOC'::text)
UNION ALL
 SELECT a.connection_id,
    a.id AS collection_attempt_id,
    a.finished_at AS collected_at,
    c.source_name,
    c.input_kind,
    o.receipt_id,
    o.native_id,
    o.reference_kind,
    o.cve_ids,
    o.source_fields,
    rev.origin,
    rev.source_url,
    rev.licence_or_provenance
   FROM ((((((evidence_pipeline.current_wasoc_repository_snapshot snap
     CROSS JOIN LATERAL jsonb_array_elements(snap.members) member(value))
     JOIN evidence.observation_receipts r ON ((r.id = ((member.value ->> 'receipt_id'::text))::uuid)))
     JOIN evidence.collection_attempts a ON ((a.id = r.collection_attempt_id)))
     JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
     JOIN evidence.source_revisions rev ON ((rev.id = r.source_revision_id)))
     JOIN evidence.public_reference_observations o ON ((o.receipt_id = r.id)));


ALTER VIEW evidence_pipeline.current_public_references OWNER TO tm_mock_owner;

--
-- Name: current_catalog_updates; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_catalog_updates AS
 SELECT connection_id,
    receipt_id,
    collected_at,
    origin,
    source_url,
    licence_or_provenance,
    native_id AS update_id,
    (source_fields -> 'notice'::text) AS metadata
   FROM evidence_pipeline.current_public_references r
  WHERE (source_name = 'Microsoft Update Catalog'::text);


ALTER VIEW evidence_pipeline.current_catalog_updates OWNER TO tm_mock_owner;

--
-- Name: current_device_status; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_device_status AS
 WITH selected AS (
         SELECT DISTINCT ON (a.connection_id) a.connection_id,
            a.id,
            a.finished_at
           FROM (evidence.collection_attempts a
             JOIN evidence.source_connections c_1 ON ((c_1.id = a.connection_id)))
          WHERE (a.complete AND (a.outcome = 'success'::text) AND (c_1.input_kind = 'devices'::text) AND (c_1.collector_reference ~~ 'evidence-pipeline-v1:%'::text))
          ORDER BY a.connection_id, a.finished_at DESC, a.started_at DESC, a.id DESC
        ), latest AS (
         SELECT DISTINCT ON (a.connection_id) a.connection_id,
            a.id,
            a.outcome,
            a.complete,
            a.finished_at
           FROM (evidence.collection_attempts a
             JOIN evidence.source_connections c_1 ON ((c_1.id = a.connection_id)))
          WHERE ((c_1.input_kind = 'devices'::text) AND (c_1.collector_reference ~~ 'evidence-pipeline-v1:%'::text))
          ORDER BY a.connection_id, a.finished_at DESC, a.started_at DESC, a.id DESC
        ), observations AS (
         SELECT o_1.id,
            o_1.provider_device_id,
            o_1.receipt_id,
            o_1.observed_at,
            o_1.display_name,
            o_1.operating_system,
            o_1.os_version,
            o_1.os_build,
            o_1.release_label,
            o_1.management_state,
            o_1.join_type,
            o_1.account_enabled,
            o_1.compliance_state,
            o_1.compliant_flag,
            o_1.managed_flag,
            o_1.enrolled_at,
            o_1.registered_at,
            o_1.first_seen,
            o_1.last_seen,
            o_1.last_sync,
            o_1.approximate_last_sign_in,
            o_1.onboarding_status,
            o_1.sensor_health,
            o_1.owner_type,
            o_1.manufacturer,
            o_1.model,
            o_1.serial_number,
            r.collection_attempt_id
           FROM ((evidence.device_observations o_1
             JOIN evidence.observation_receipts r ON ((r.id = o_1.receipt_id)))
             JOIN selected s_1 ON ((s_1.id = r.collection_attempt_id)))
        )
 SELECT p.id AS provider_device_id,
    p.connection_id,
    c.source_name,
    c.tenant_id,
    p.native_device_id,
    p.microsoft_registration_id,
    s.id AS selected_attempt_id,
    s.finished_at AS selected_collected_at,
    latest.id AS latest_attempt_id,
    latest.outcome AS latest_outcome,
    latest.complete AS latest_complete,
    (o.id IS NOT NULL) AS source_present,
    o.id AS observation_id,
    o.receipt_id,
    o.display_name,
    o.operating_system,
    o.os_version,
    o.os_build,
    o.release_label,
    o.account_enabled,
    o.managed_flag,
    o.compliant_flag,
    o.compliance_state,
    o.management_state,
    o.join_type,
    o.owner_type,
    o.manufacturer,
    o.model,
    o.serial_number,
    o.first_seen,
    o.last_seen,
    o.last_sync,
    o.approximate_last_sign_in,
        CASE c.source_name
            WHEN 'Defender'::text THEN o.last_seen
            WHEN 'Intune'::text THEN o.last_sync
            ELSE o.approximate_last_sign_in
        END AS reporting_at,
        CASE c.source_name
            WHEN 'Defender'::text THEN 'last_seen'::text
            WHEN 'Intune'::text THEN 'last_sync'::text
            ELSE 'approximate_last_sign_in'::text
        END AS reporting_timestamp_kind
   FROM ((((evidence.provider_devices p
     JOIN evidence.source_connections c ON ((c.id = p.connection_id)))
     LEFT JOIN selected s ON ((s.connection_id = p.connection_id)))
     LEFT JOIN latest ON ((latest.connection_id = p.connection_id)))
     LEFT JOIN observations o ON ((o.provider_device_id = p.id)))
  WHERE ((c.input_kind = 'devices'::text) AND (c.collector_reference ~~ 'evidence-pipeline-v1:%'::text));


ALTER VIEW evidence_pipeline.current_device_status OWNER TO tm_mock_owner;

--
-- Name: VIEW current_device_status; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_device_status IS 'Pipeline device evidence, source reporting times and latest/selected collection status. No agency assignment or completeness policy.';


--
-- Name: current_computer_links; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_computer_links AS
 WITH members AS (
         SELECT d.provider_device_id,
            d.connection_id,
            d.source_name,
            d.tenant_id,
            d.native_device_id,
            d.microsoft_registration_id,
            d.selected_attempt_id,
            d.selected_collected_at,
            d.latest_attempt_id,
            d.latest_outcome,
            d.latest_complete,
            d.source_present,
            d.observation_id,
            d.receipt_id,
            d.display_name,
            d.operating_system,
            d.os_version,
            d.os_build,
            d.release_label,
            d.account_enabled,
            d.managed_flag,
            d.compliant_flag,
            d.compliance_state,
            d.management_state,
            d.join_type,
            d.owner_type,
            d.manufacturer,
            d.model,
            d.serial_number,
            d.first_seen,
            d.last_seen,
            d.last_sync,
            d.approximate_last_sign_in,
            d.reporting_at,
            d.reporting_timestamp_kind,
            a.origin,
            t.external_tenant_id
           FROM ((evidence_pipeline.current_device_status d
             JOIN evidence_pipeline.authorized_connections a ON ((a.connection_id = d.connection_id)))
             JOIN evidence.microsoft_tenants t ON ((t.id = d.tenant_id)))
          WHERE d.source_present
        ), registrations AS (
         SELECT members.origin,
            members.external_tenant_id,
            members.microsoft_registration_id,
            members.source_name,
            count(DISTINCT members.native_device_id) AS source_duplicates
           FROM members
          GROUP BY members.origin, members.external_tenant_id, members.microsoft_registration_id, members.source_name
        ), native_ids AS (
         SELECT members.origin,
            members.external_tenant_id,
            members.source_name,
            members.native_device_id,
            count(DISTINCT members.microsoft_registration_id) AS registration_count
           FROM members
          GROUP BY members.origin, members.external_tenant_id, members.source_name, members.native_device_id
        ), checked AS (
         SELECT m.provider_device_id,
            m.connection_id,
            m.source_name,
            m.tenant_id,
            m.native_device_id,
            m.microsoft_registration_id,
            m.selected_attempt_id,
            m.selected_collected_at,
            m.latest_attempt_id,
            m.latest_outcome,
            m.latest_complete,
            m.source_present,
            m.observation_id,
            m.receipt_id,
            m.display_name,
            m.operating_system,
            m.os_version,
            m.os_build,
            m.release_label,
            m.account_enabled,
            m.managed_flag,
            m.compliant_flag,
            m.compliance_state,
            m.management_state,
            m.join_type,
            m.owner_type,
            m.manufacturer,
            m.model,
            m.serial_number,
            m.first_seen,
            m.last_seen,
            m.last_sync,
            m.approximate_last_sign_in,
            m.reporting_at,
            m.reporting_timestamp_kind,
            m.origin,
            m.external_tenant_id,
            n.registration_count AS native_registration_count,
            max(GREATEST(r.source_duplicates, n.registration_count)) OVER (PARTITION BY m.origin, m.external_tenant_id, m.microsoft_registration_id) AS largest_source_count
           FROM ((members m
             JOIN registrations r ON (((r.origin = m.origin) AND (r.external_tenant_id = m.external_tenant_id) AND (r.source_name = m.source_name) AND (NOT (r.microsoft_registration_id IS DISTINCT FROM m.microsoft_registration_id)))))
             JOIN native_ids n ON (((n.origin = m.origin) AND (n.external_tenant_id = m.external_tenant_id) AND (n.source_name = m.source_name) AND (n.native_device_id = m.native_device_id))))
        )
 SELECT
        CASE
            WHEN ((microsoft_registration_id IS NOT NULL) AND (largest_source_count = 1)) THEN ((((('registration/'::text || origin) || '/'::text) || external_tenant_id) || '/'::text) || microsoft_registration_id)
            WHEN (native_registration_count <= 1) THEN ((((((('native/'::text || origin) || '/'::text) || external_tenant_id) || '/'::text) || source_name) || '/'::text) || native_device_id)
            ELSE ('provider/'::text || (provider_device_id)::text)
        END AS computer_key,
        CASE
            WHEN (microsoft_registration_id IS NULL) THEN 'missing_or_invalid_registration_id'::text
            WHEN (largest_source_count > 1) THEN 'ambiguous_registration_id'::text
            ELSE 'microsoft_registration_id'::text
        END AS match_basis,
    provider_device_id,
    connection_id,
    source_name,
    tenant_id,
    origin,
    native_device_id,
    microsoft_registration_id,
    display_name,
    operating_system,
    os_version,
    selected_attempt_id,
    selected_collected_at,
    latest_attempt_id,
    latest_outcome,
    reporting_at,
    reporting_timestamp_kind
   FROM checked;


ALTER VIEW evidence_pipeline.current_computer_links OWNER TO tm_mock_owner;

--
-- Name: VIEW current_computer_links; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_computer_links IS 'Current source device to computer key mapping by tenant/origin and shared Microsoft registration ID; duplicate same-source registrations remain separate. No hostname match or agency assignment.';


--
-- Name: current_computers; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_computers AS
 SELECT computer_key,
        CASE
            WHEN bool_or((match_basis = 'ambiguous_registration_id'::text)) THEN 'ambiguous_registration_id'::text
            ELSE min(match_basis)
        END AS match_basis,
    tenant_id,
    origin,
    count(*) AS provider_record_count
   FROM evidence_pipeline.current_computer_links
  GROUP BY computer_key, tenant_id, origin;


ALTER VIEW evidence_pipeline.current_computers OWNER TO tm_mock_owner;

--
-- Name: VIEW current_computers; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_computers IS 'One row per current derived computer key. Current identity projection only; join current_computer_links for source fields and dates. Missing reporting is not remediation.';


--
-- Name: current_completeness_cells; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_completeness_cells AS
 WITH device_values AS (
         SELECT l.computer_key,
            l.source_name,
            l.provider_device_id,
            l.connection_id,
            d.receipt_id,
            (to_jsonb(o.*) || jsonb_build_object('native_device_id', l.native_device_id)) AS fields
           FROM ((evidence_pipeline.current_computer_links l
             JOIN evidence_pipeline.current_device_status d ON (((d.provider_device_id = l.provider_device_id) AND (d.selected_attempt_id = l.selected_attempt_id))))
             JOIN evidence.device_observations o ON (((o.provider_device_id = l.provider_device_id) AND (o.receipt_id = d.receipt_id))))
        ), registrations AS (
         SELECT current_computer_links.computer_key,
            max(current_computer_links.microsoft_registration_id) AS registration_id
           FROM evidence_pipeline.current_computer_links
          GROUP BY current_computer_links.computer_key
        ), cells AS (
         SELECT c.computer_key,
            c.tenant_id,
            c.origin,
            f.definition_id,
            f.field_key,
            f.source_name,
            f.value_kind,
            v.provider_device_id,
            v.connection_id,
            v.receipt_id,
                CASE
                    WHEN (v.provider_device_id IS NULL) THEN 'unknown'::text
                    ELSE 'applicable'::text
                END AS applicability,
                CASE
                    WHEN (v.provider_device_id IS NULL) THEN 'provider_link_not_established'::text
                    ELSE 'linked_provider_device'::text
                END AS applicability_reason,
            (v.fields -> f.field_name) AS value
           FROM ((evidence_pipeline.current_computers c
             CROSS JOIN evidence_pipeline.completeness_definition f)
             LEFT JOIN device_values v ON (((v.computer_key = c.computer_key) AND (v.source_name = f.source_name))))
          WHERE (f.source_name <> 'Microsoft'::text)
        UNION ALL
         SELECT c.computer_key,
            c.tenant_id,
            c.origin,
            f.definition_id,
            f.field_key,
            f.source_name,
            f.value_kind,
            NULL::uuid AS uuid,
            NULL::uuid AS uuid,
            NULL::uuid AS uuid,
            'applicable'::text,
                CASE
                    WHEN (f.field_name = 'registration_id'::text) THEN 'shared_microsoft_identity'::text
                    ELSE 'basic_inputs_do_not_establish_device_purpose'::text
                END AS "case",
                CASE
                    WHEN (f.field_name = 'registration_id'::text) THEN to_jsonb(r.registration_id)
                    ELSE NULL::jsonb
                END AS "case"
           FROM ((evidence_pipeline.current_computers c
             JOIN registrations r ON ((r.computer_key = c.computer_key)))
             CROSS JOIN evidence_pipeline.completeness_definition f)
          WHERE (f.source_name = 'Microsoft'::text)
        )
 SELECT computer_key,
    tenant_id,
    origin,
    definition_id,
    field_key,
    source_name,
    value_kind,
    provider_device_id,
    connection_id,
    receipt_id,
    applicability,
    applicability_reason,
    value,
    ((applicability = 'applicable'::text) AND (value IS NOT NULL) AND (value <> 'null'::jsonb)) AS populated,
        CASE
            WHEN (applicability = 'unknown'::text) THEN 'applicability_unknown'::text
            WHEN ((value IS NULL) OR (value = 'null'::jsonb)) THEN 'missing'::text
            ELSE 'present'::text
        END AS value_state
   FROM cells;


ALTER VIEW evidence_pipeline.current_completeness_cells OWNER TO tm_mock_owner;

--
-- Name: VIEW current_completeness_cells; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_completeness_cells IS 'Source-specific device facts, one shared registration identity and an unfilled source-purpose cell. Missing providers remain applicability unknown. Source receipt IDs are provenance, not counted cells.';


--
-- Name: current_cve_records; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_cve_records AS
 WITH selected AS (
         SELECT DISTINCT ON (a.connection_id) a.connection_id,
            a.id,
            a.finished_at
           FROM (evidence.collection_attempts a
             JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
          WHERE ((((c.source_name = 'CVE'::text) AND (c.input_kind = 'records'::text)) OR ((c.source_name = 'CISA'::text) AND (c.input_kind = 'vulnrichment'::text))) AND a.complete AND (a.outcome = 'success'::text))
          ORDER BY a.connection_id, a.finished_at DESC, a.started_at DESC, a.id DESC
        )
 SELECT s.connection_id,
    s.id AS collection_attempt_id,
    s.finished_at AS collected_at,
    o.receipt_id,
    o.cve_id,
    o.record_state,
    o.data_version,
    o.source_metadata,
    rev.origin,
    rev.source_url,
    rev.licence_or_provenance
   FROM (((selected s
     JOIN evidence.observation_receipts r ON ((r.collection_attempt_id = s.id)))
     JOIN evidence.source_revisions rev ON ((rev.id = r.source_revision_id)))
     JOIN evidence.cve_record_observations o ON ((o.receipt_id = r.id)));


ALTER VIEW evidence_pipeline.current_cve_records OWNER TO tm_mock_owner;

--
-- Name: current_cve_contributions; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_cve_contributions AS
 SELECT r.connection_id,
    r.collection_attempt_id,
    r.collected_at,
    r.receipt_id,
    r.cve_id,
    r.record_state,
    r.data_version,
    r.source_metadata,
    r.origin,
    r.source_url,
    r.licence_or_provenance,
    c.contributor_kind,
    c.contributor_index,
    c.organization_id,
    c.provider_name,
    c.source_fields
   FROM (evidence_pipeline.current_cve_records r
     JOIN evidence.cve_contributions c ON ((c.receipt_id = r.receipt_id)));


ALTER VIEW evidence_pipeline.current_cve_contributions OWNER TO tm_mock_owner;

--
-- Name: recommendation_claims; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.recommendation_claims (
    receipt_id uuid NOT NULL,
    claim jsonb NOT NULL,
    CONSTRAINT recommendation_claims_claim_check CHECK ((jsonb_typeof(claim) = 'object'::text))
);


ALTER TABLE evidence_pipeline.recommendation_claims OWNER TO tm_mock_owner;

--
-- Name: current_defender_recommendations; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_defender_recommendations AS
 WITH selected AS (
         SELECT DISTINCT ON (a.connection_id) a.connection_id,
            a.id,
            a.finished_at
           FROM (evidence.collection_attempts a
             JOIN evidence.source_connections c_1 ON ((c_1.id = a.connection_id)))
          WHERE ((c_1.source_name = 'Defender'::text) AND (c_1.input_kind = 'recommendations'::text) AND a.complete AND (a.outcome = 'success'::text))
          ORDER BY a.connection_id, a.finished_at DESC, a.started_at DESC, a.id DESC
        )
 SELECT s.connection_id,
    s.id AS collection_attempt_id,
    s.finished_at AS collected_at,
    rec.id,
    rec.source_recommendation_id,
    rec.advisory_id,
    rec.title,
    rec.recommendation_text,
    rec.vendor,
    rec.product_name,
    rec.recommended_version,
    rec.recommended_program,
    rec.recommended_vendor,
    rec.category,
    rec.subcategory,
    rec.remediation_type,
    rec.source_status,
    rec.receipt_id,
    c.claim,
    rev.origin,
    rev.licence_or_provenance
   FROM ((((selected s
     JOIN evidence.observation_receipts r ON ((r.collection_attempt_id = s.id)))
     JOIN evidence.recommendations rec ON ((rec.receipt_id = r.id)))
     JOIN evidence_pipeline.recommendation_claims c ON ((c.receipt_id = r.id)))
     JOIN evidence.source_revisions rev ON ((rev.id = r.source_revision_id)));


ALTER VIEW evidence_pipeline.current_defender_recommendations OWNER TO tm_mock_owner;

--
-- Name: current_findings; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_findings AS
 SELECT f.id AS finding_id,
    c.connection_id,
    c.source_name,
    c.tenant_id,
    c.selected_attempt_id,
    c.selected_finished_at,
    c.latest_outcome,
    x.device_attempt_id,
    f.provider_device_id,
    f.receipt_id,
    f.source_finding_id,
    f.cve_id,
    f.source_severity_label,
    f.fixing_patch_id,
    f.fixing_patch_reference,
    s.id AS software_id,
    s.product_name,
    s.publisher,
    s.version,
    s.platform
   FROM ((((evidence_pipeline.collection_status c
     JOIN evidence_pipeline.exposure_snapshots x ON ((x.collection_attempt_id = c.selected_attempt_id)))
     JOIN evidence.observation_receipts r ON ((r.collection_attempt_id = x.collection_attempt_id)))
     JOIN evidence.vulnerability_findings f ON ((f.receipt_id = r.id)))
     JOIN evidence.software s ON ((s.id = f.software_id)))
  WHERE (c.input_kind = 'findings'::text);


ALTER VIEW evidence_pipeline.current_findings OWNER TO tm_mock_owner;

--
-- Name: VIEW current_findings; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_findings IS 'Source-reported device/software/CVE findings. Raw patch references are not verified applicability or a remediation conclusion.';


--
-- Name: current_missing_patches; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_missing_patches AS
 SELECT o.id AS observation_id,
    c.connection_id,
    c.source_name,
    c.tenant_id,
    c.selected_attempt_id,
    c.selected_finished_at,
    c.latest_outcome,
    s.device_attempt_id,
    o.provider_device_id,
    o.receipt_id,
    o.observed_at,
    p.id AS patch_id,
    p.source_patch_id,
    p.title,
    p.url,
    p.product_names,
    o.reported_machine_count,
    o.reported_cve_count
   FROM ((((evidence_pipeline.collection_status c
     JOIN evidence_pipeline.exposure_snapshots s ON ((s.collection_attempt_id = c.selected_attempt_id)))
     JOIN evidence.observation_receipts r ON ((r.collection_attempt_id = s.collection_attempt_id)))
     JOIN evidence.device_missing_patches o ON ((o.receipt_id = r.id)))
     JOIN evidence.patches p ON (((p.id = o.patch_id) AND (p.receipt_id = o.receipt_id))))
  WHERE ((c.source_name = 'Defender'::text) AND (c.input_kind = 'missing_patches'::text));


ALTER VIEW evidence_pipeline.current_missing_patches OWNER TO tm_mock_owner;

--
-- Name: VIEW current_missing_patches; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_missing_patches IS 'Source-reported missing KBs on explicitly bound devices; counts do not identify CVEs or prove patch applicability.';


--
-- Name: public_claims; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.public_claims (
    source_revision_id uuid NOT NULL,
    claim text NOT NULL,
    CONSTRAINT public_claims_claim_check CHECK ((octet_length(claim) > 0))
);


ALTER TABLE evidence_pipeline.public_claims OWNER TO tm_mock_owner;

--
-- Name: current_msrc_advisory_claims; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_msrc_advisory_claims AS
 WITH selected AS (
         SELECT DISTINCT ON (a.connection_id) a.connection_id,
            a.id,
            a.finished_at
           FROM (evidence.collection_attempts a
             JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
          WHERE ((c.source_name = 'MSRC'::text) AND (c.input_kind = 'security_updates'::text) AND a.complete AND (a.outcome = 'success'::text))
          ORDER BY a.connection_id, a.finished_at DESC, a.started_at DESC, a.id DESC
        )
 SELECT s.connection_id,
    s.id AS collection_attempt_id,
    s.finished_at AS collected_at,
    r.id AS receipt_id,
    rev.source_record_id AS native_id,
    (p.claim)::jsonb AS claim,
    rev.origin,
    rev.source_url,
    rev.licence_or_provenance
   FROM (((selected s
     JOIN evidence.observation_receipts r ON ((r.collection_attempt_id = s.id)))
     JOIN evidence.source_revisions rev ON ((rev.id = r.source_revision_id)))
     JOIN evidence_pipeline.public_claims p ON ((p.source_revision_id = rev.id)))
  WHERE (rev.source_record_id !~ '^CVE-[0-9]{4}-[0-9]{4,}$'::text);


ALTER VIEW evidence_pipeline.current_msrc_advisory_claims OWNER TO tm_mock_owner;

--
-- Name: current_msrc_update_claims; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_msrc_update_claims AS
 WITH selected AS (
         SELECT DISTINCT ON (a.connection_id) a.connection_id,
            a.id,
            a.finished_at
           FROM (evidence.collection_attempts a
             JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
          WHERE ((c.source_name = 'MSRC'::text) AND (c.input_kind = 'security_updates'::text) AND a.complete AND (a.outcome = 'success'::text))
          ORDER BY a.connection_id, a.finished_at DESC, a.started_at DESC, a.id DESC
        )
 SELECT s.connection_id,
    s.id AS collection_attempt_id,
    s.finished_at AS collected_at,
    r.id AS receipt_id,
    rev.source_record_id AS cve_id,
    (p.claim)::jsonb AS claim,
    rev.origin,
    rev.source_url,
    rev.licence_or_provenance
   FROM (((selected s
     JOIN evidence.observation_receipts r ON ((r.collection_attempt_id = s.id)))
     JOIN evidence.source_revisions rev ON ((rev.id = r.source_revision_id)))
     JOIN evidence_pipeline.public_claims p ON ((p.source_revision_id = rev.id)))
  WHERE (rev.source_record_id ~ '^CVE-[0-9]{4}-[0-9]{4,}$'::text);


ALTER VIEW evidence_pipeline.current_msrc_update_claims OWNER TO tm_mock_owner;

--
-- Name: current_osv_advisories; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_osv_advisories AS
 WITH selected AS (
         SELECT DISTINCT ON (a.connection_id) a.connection_id,
            a.id,
            a.finished_at,
            c.source_name
           FROM (evidence.collection_attempts a
             JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
          WHERE ((c.source_name = ANY (ARRAY['OSV'::text, 'GitHub'::text, 'Ubuntu'::text])) AND (c.input_kind = 'advisories'::text) AND a.complete AND (a.outcome = 'success'::text))
          ORDER BY a.connection_id, a.finished_at DESC, a.started_at DESC, a.id DESC
        )
 SELECT s.connection_id,
    s.id AS collection_attempt_id,
    s.finished_at AS collected_at,
    o.receipt_id,
    o.advisory_id,
    o.modified_text,
    o.withdrawn_text,
    o.source_fields,
    rev.origin,
    rev.source_url,
    rev.licence_or_provenance,
    s.source_name
   FROM (((selected s
     JOIN evidence.observation_receipts r ON ((r.collection_attempt_id = s.id)))
     JOIN evidence.source_revisions rev ON ((rev.id = r.source_revision_id)))
     JOIN evidence.osv_advisory_observations o ON ((o.receipt_id = r.id)));


ALTER VIEW evidence_pipeline.current_osv_advisories OWNER TO tm_mock_owner;

--
-- Name: current_update_status; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_update_status AS
 SELECT c.connection_id,
    c.source_name,
    c.tenant_id,
    c.selected_attempt_id,
    c.selected_finished_at,
    c.latest_outcome,
    s.device_attempt_id,
    o.id,
    o.provider_device_id,
    o.receipt_id,
    o.source_device_id,
    o.source_registration_id,
    o.policy_id,
    o.device_name,
    o.owner_type,
    o.aggregate_state,
    o.aggregate_state_localized,
    o.current_status,
    o.current_status_localized,
    o.current_substatus,
    o.current_substatus_localized,
    o.event_time,
    o.last_wu_scan_at,
    o.alert_message,
    o.alert_message_localized
   FROM (((evidence_pipeline.collection_status c
     JOIN evidence_pipeline.exposure_snapshots s ON ((s.collection_attempt_id = c.selected_attempt_id)))
     JOIN evidence.observation_receipts r ON ((r.collection_attempt_id = s.collection_attempt_id)))
     JOIN evidence.update_policy_observations o ON ((o.receipt_id = r.id)))
  WHERE ((c.source_name = 'Intune'::text) AND (c.input_kind = 'update_status'::text));


ALTER VIEW evidence_pipeline.current_update_status OWNER TO tm_mock_owner;

--
-- Name: VIEW current_update_status; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_update_status IS 'Source-reported device/policy status; status labels do not establish installation of a named patch or resolution of a CVE.';


--
-- Name: current_vulnerability_catalogue; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_vulnerability_catalogue AS
 WITH selected AS (
         SELECT DISTINCT ON (a.connection_id) a.connection_id,
            a.id,
            a.finished_at
           FROM (evidence.collection_attempts a
             JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
          WHERE ((c.source_name = 'Defender'::text) AND (c.input_kind = 'vulnerability_catalogue'::text) AND a.complete AND (a.outcome = 'success'::text))
          ORDER BY a.connection_id, a.finished_at DESC, a.started_at DESC, a.id DESC
        )
 SELECT s.connection_id,
    s.id AS collection_attempt_id,
    s.finished_at AS collected_at,
    o.receipt_id,
    o.cve_id,
    o.claim,
    (o.claim ->> 'description'::text) AS description,
    (o.claim ->> 'severity'::text) AS source_severity,
    ((o.claim ->> 'cvssV3'::text))::numeric AS cvss_v3,
    (o.claim ->> 'cvssVector'::text) AS cvss_vector,
    ((o.claim ->> 'epss'::text))::numeric AS source_epss,
    ((o.claim ->> 'exposedMachines'::text))::bigint AS source_exposed_machines,
    rev.origin,
    rev.licence_or_provenance
   FROM (((selected s
     JOIN evidence.observation_receipts r ON ((r.collection_attempt_id = s.id)))
     JOIN evidence_pipeline.catalogue_observations o ON ((o.receipt_id = r.id)))
     JOIN evidence.source_revisions rev ON ((rev.id = r.source_revision_id)));


ALTER VIEW evidence_pipeline.current_vulnerability_catalogue OWNER TO tm_mock_owner;

--
-- Name: current_native_advisory_facts; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_native_advisory_facts AS
 SELECT r.connection_id,
    r.receipt_id,
    r.origin,
    'vendor-advisory'::text AS domain,
    (r.receipt_id)::text AS entity_key,
        CASE r.source_name
            WHEN 'Palo Alto Networks'::text THEN jsonb_build_object('advisory_id', r.native_id, 'title', (r.source_fields #> '{document,containers,cna,title}'::text[]), 'description', (r.source_fields #> '{document,containers,cna,descriptions}'::text[]), 'affected_products', (r.source_fields #> '{document,containers,cna,affected}'::text[]), 'published_at', (r.source_fields #> '{document,cveMetadata,datePublished}'::text[]), 'updated_at', (r.source_fields #> '{document,cveMetadata,dateUpdated}'::text[]))
            WHEN 'Apache HTTP Server'::text THEN jsonb_build_object('advisory_id', r.native_id, 'description', (r.source_fields #> '{document,description,description_data}'::text[]), 'affected_products', (r.source_fields #> '{document,affects,vendor,vendor_data}'::text[]))
            WHEN 'WA SOC'::text THEN jsonb_build_object('advisory_id', r.native_id, 'title', (r.source_fields #> '{notice,title}'::text[]), 'sections', (r.source_fields #> '{notice,sections}'::text[]), 'referenced_cves', (r.source_fields #> '{notice,referenced_cves}'::text[]))
            WHEN 'Samba'::text THEN jsonb_build_object('advisory_id', r.native_id, 'title', (r.source_fields #> '{notice,subject}'::text[]), 'description', (r.source_fields #> '{notice,summary}'::text[]), 'affected_versions', (r.source_fields #> '{notice,versions_text}'::text[]))
            ELSE jsonb_build_object('advisory_id', r.native_id, 'title', (r.source_fields #> '{document,document,title}'::text[]), 'published_at', (r.source_fields #> '{document,document,tracking,initial_release_date}'::text[]), 'updated_at', (r.source_fields #> '{document,document,tracking,current_release_date}'::text[]), 'publisher', (r.source_fields #> '{document,document,publisher,name}'::text[]), 'vulnerabilities', (r.source_fields #> '{document,vulnerabilities}'::text[]))
        END AS fields
   FROM evidence_pipeline.current_public_references r
  WHERE (r.source_name = ANY (ARRAY['Palo Alto Networks'::text, 'Apache HTTP Server'::text, 'Samba'::text, 'Red Hat'::text, 'Cisco'::text, 'WA SOC'::text]))
UNION ALL
 SELECT r.connection_id,
    r.receipt_id,
    r.origin,
    'vendor-advisory'::text AS domain,
    (((r.receipt_id)::text || '/'::text) || (n.ordinality)::text) AS entity_key,
    jsonb_build_object('cve_id', (n.value -> 'cve_id'::text), 'title', (n.value -> 'title'::text), 'description', (n.value -> 'paragraphs'::text), 'affected_versions', (n.value -> 'affected_text'::text), 'fixed_release', (n.value -> 'fixed_release'::text), 'published_at', (n.value -> 'section_date'::text)) AS fields
   FROM (evidence_pipeline.current_public_references r
     CROSS JOIN LATERAL jsonb_array_elements((r.source_fields -> 'notices'::text)) WITH ORDINALITY n(value, ordinality))
  WHERE (r.source_name = 'Apache Tomcat'::text)
UNION ALL
 SELECT r.connection_id,
    r.receipt_id,
    r.origin,
    'vendor-advisory'::text AS domain,
    (((r.receipt_id)::text || '/'::text) || issue.key) AS entity_key,
    jsonb_build_object('source_package', r.native_id, 'issue_id', issue.key, 'description', (issue.value -> 'description'::text), 'scope', (issue.value -> 'scope'::text), 'release_statuses', (issue.value -> 'releases'::text)) AS fields
   FROM (evidence_pipeline.current_public_references r
     CROSS JOIN LATERAL jsonb_each(((r.source_fields -> 'document'::text) -> r.native_id)) issue(key, value))
  WHERE (r.source_name = 'Debian'::text)
UNION ALL
 SELECT r.connection_id,
    r.receipt_id,
    r.origin,
    'osv-advisory'::text AS domain,
    (r.receipt_id)::text AS entity_key,
    jsonb_build_object('advisory_id', r.advisory_id, 'modified', r.modified_text, 'summary', (r.source_fields -> 'summary'::text), 'details', (r.source_fields -> 'details'::text), 'affected_packages', (r.source_fields -> 'affected'::text), 'references', (r.source_fields -> 'references'::text)) AS fields
   FROM evidence_pipeline.current_osv_advisories r
UNION ALL
 SELECT r.connection_id,
    r.receipt_id,
    r.origin,
    'cve-contribution'::text AS domain,
    (((((r.receipt_id)::text || '/'::text) || r.contributor_kind) || '/'::text) || (r.contributor_index)::text) AS entity_key,
        CASE
            WHEN (r.record_state = 'REJECTED'::text) THEN jsonb_build_object('cve_id', r.cve_id, 'state', r.record_state, 'provider', r.provider_name, 'rejection_reasons', (r.source_fields -> 'rejectedReasons'::text))
            ELSE jsonb_build_object('cve_id', r.cve_id, 'state', r.record_state, 'provider', r.provider_name, 'descriptions', (r.source_fields -> 'descriptions'::text), 'affected_products', (r.source_fields -> 'affected'::text), 'references', (r.source_fields -> 'references'::text))
        END AS fields
   FROM evidence_pipeline.current_cve_contributions r
UNION ALL
 SELECT r.connection_id,
    r.receipt_id,
    r.origin,
    'msrc-update'::text AS domain,
    (r.receipt_id)::text AS entity_key,
    jsonb_build_object('cve_id', r.cve_id, 'title', (r.claim #> '{source_vulnerability,Title}'::text[]), 'notes', (r.claim #> '{source_vulnerability,Notes}'::text[]), 'product_statuses', (r.claim #> '{source_vulnerability,ProductStatuses}'::text[]), 'remediations', (r.claim #> '{source_vulnerability,Remediations}'::text[])) AS fields
   FROM evidence_pipeline.current_msrc_update_claims r
UNION ALL
 SELECT r.connection_id,
    r.receipt_id,
    a.origin,
    'antivirus'::text AS domain,
    (r.receipt_id)::text AS entity_key,
    jsonb_build_object('source_record_id', (to_jsonb(r.*) -> 'source_record_id'::text), 'device_name', (to_jsonb(r.*) -> 'device_name'::text), 'os_kind', (to_jsonb(r.*) -> 'os_kind'::text), 'os_platform', (to_jsonb(r.*) -> 'os_platform'::text), 'os_version', (to_jsonb(r.*) -> 'os_version'::text), 'mode', (to_jsonb(r.*) -> 'mode'::text), 'signature_version', (to_jsonb(r.*) -> 'signature_version'::text), 'engine_version', (to_jsonb(r.*) -> 'engine_version'::text), 'platform_version', (to_jsonb(r.*) -> 'platform_version'::text), 'signature_updated_at', (to_jsonb(r.*) -> 'signature_updated_at'::text), 'engine_updated_at', (to_jsonb(r.*) -> 'engine_updated_at'::text), 'platform_updated_at', (to_jsonb(r.*) -> 'platform_updated_at'::text), 'signature_published_at', (to_jsonb(r.*) -> 'signature_published_at'::text), 'refreshed_at', (to_jsonb(r.*) -> 'refreshed_at'::text), 'last_seen_at', (to_jsonb(r.*) -> 'last_seen_at'::text), 'quick_scan_result', (to_jsonb(r.*) -> 'quick_scan_result'::text), 'quick_scan_error', (to_jsonb(r.*) -> 'quick_scan_error'::text), 'quick_scan_at', (to_jsonb(r.*) -> 'quick_scan_at'::text), 'full_scan_result', (to_jsonb(r.*) -> 'full_scan_result'::text), 'full_scan_error', (to_jsonb(r.*) -> 'full_scan_error'::text), 'full_scan_at', (to_jsonb(r.*) -> 'full_scan_at'::text), 'signature_status', (to_jsonb(r.*) -> 'signature_status'::text), 'engine_status', (to_jsonb(r.*) -> 'engine_status'::text), 'platform_status', (to_jsonb(r.*) -> 'platform_status'::text)) AS fields
   FROM (evidence_pipeline.current_antivirus r
     JOIN evidence_pipeline.authorized_connections a USING (connection_id))
UNION ALL
 SELECT r.connection_id,
    r.receipt_id,
    a.origin,
    'update-status'::text AS domain,
    (r.receipt_id)::text AS entity_key,
    jsonb_build_object('source_device_id', (to_jsonb(r.*) -> 'source_device_id'::text), 'source_registration_id', (to_jsonb(r.*) -> 'source_registration_id'::text), 'policy_id', (to_jsonb(r.*) -> 'policy_id'::text), 'device_name', (to_jsonb(r.*) -> 'device_name'::text), 'owner_type', (to_jsonb(r.*) -> 'owner_type'::text), 'aggregate_state', (to_jsonb(r.*) -> 'aggregate_state'::text), 'current_status', (to_jsonb(r.*) -> 'current_status'::text), 'current_substatus', (to_jsonb(r.*) -> 'current_substatus'::text), 'event_time', (to_jsonb(r.*) -> 'event_time'::text), 'last_wu_scan_at', (to_jsonb(r.*) -> 'last_wu_scan_at'::text), 'alert_message', (to_jsonb(r.*) -> 'alert_message'::text)) AS fields
   FROM (evidence_pipeline.current_update_status r
     JOIN evidence_pipeline.authorized_connections a USING (connection_id))
UNION ALL
 SELECT r.connection_id,
    r.receipt_id,
    a.origin,
    'missing-patch'::text AS domain,
    (r.receipt_id)::text AS entity_key,
    jsonb_build_object('source_patch_id', (to_jsonb(r.*) -> 'source_patch_id'::text), 'title', (to_jsonb(r.*) -> 'title'::text), 'url', (to_jsonb(r.*) -> 'url'::text), 'product_names', (to_jsonb(r.*) -> 'product_names'::text), 'reported_machine_count', (to_jsonb(r.*) -> 'reported_machine_count'::text), 'reported_cve_count', (to_jsonb(r.*) -> 'reported_cve_count'::text)) AS fields
   FROM (evidence_pipeline.current_missing_patches r
     JOIN evidence_pipeline.authorized_connections a USING (connection_id))
UNION ALL
 SELECT r.connection_id,
    r.receipt_id,
    r.origin,
    'device-recommendation'::text AS domain,
    (r.receipt_id)::text AS entity_key,
    jsonb_build_object('source_recommendation_id', (to_jsonb(r.*) -> 'source_recommendation_id'::text), 'title', (to_jsonb(r.*) -> 'title'::text), 'vendor', (to_jsonb(r.*) -> 'vendor'::text), 'product_name', (to_jsonb(r.*) -> 'product_name'::text), 'recommended_version', (to_jsonb(r.*) -> 'recommended_version'::text), 'recommended_program', (to_jsonb(r.*) -> 'recommended_program'::text), 'recommended_vendor', (to_jsonb(r.*) -> 'recommended_vendor'::text), 'category', (to_jsonb(r.*) -> 'category'::text), 'subcategory', (to_jsonb(r.*) -> 'subcategory'::text), 'remediation_type', (to_jsonb(r.*) -> 'remediation_type'::text), 'source_status', (to_jsonb(r.*) -> 'source_status'::text)) AS fields
   FROM evidence_pipeline.current_defender_recommendations r
UNION ALL
 SELECT r.connection_id,
    r.receipt_id,
    r.origin,
    'vulnerability-catalogue'::text AS domain,
    (r.receipt_id)::text AS entity_key,
    jsonb_build_object('id', r.cve_id, 'name', (r.claim -> 'name'::text), 'description', (r.claim -> 'description'::text), 'severity', (r.claim -> 'severity'::text), 'cvssV3', (r.claim -> 'cvssV3'::text), 'cvssVector', (r.claim -> 'cvssVector'::text), 'exposedMachines', (r.claim -> 'exposedMachines'::text), 'publishedOn', (r.claim -> 'publishedOn'::text), 'updatedOn', (r.claim -> 'updatedOn'::text), 'firstDetected', (r.claim -> 'firstDetected'::text), 'publicExploit', (r.claim -> 'publicExploit'::text), 'exploitVerified', (r.claim -> 'exploitVerified'::text), 'exploitInKit', (r.claim -> 'exploitInKit'::text), 'exploitTypes', (r.claim -> 'exploitTypes'::text), 'exploitUris', (r.claim -> 'exploitUris'::text), 'cveSupportability', (r.claim -> 'cveSupportability'::text), 'epss', (r.claim -> 'epss'::text), 'status', (r.claim -> 'status'::text), 'tags', (r.claim -> 'tags'::text)) AS fields
   FROM evidence_pipeline.current_vulnerability_catalogue r
UNION ALL
 SELECT r.connection_id,
    r.receipt_id,
    r.origin,
    'attack-definition'::text AS domain,
    (r.receipt_id)::text AS entity_key,
    jsonb_build_object('source_id', r.native_id, 'name', (r.source_fields #> '{object,name}'::text[]), 'description', (r.source_fields #> '{object,description}'::text[]), 'modified', (r.source_fields #> '{object,modified}'::text[]), 'revoked', (r.source_fields #> '{object,revoked}'::text[]), 'deprecated', (r.source_fields #> '{object,x_mitre_deprecated}'::text[]), 'platforms', (r.source_fields #> '{object,x_mitre_platforms}'::text[]), 'external_references', (r.source_fields #> '{object,external_references}'::text[])) AS fields
   FROM evidence_pipeline.current_public_references r
  WHERE (r.reference_kind = 'attack_definition'::text)
UNION ALL
 SELECT r.connection_id,
    r.receipt_id,
    r.origin,
    'exploit-metadata'::text AS domain,
    (((r.receipt_id)::text || '/'::text) || ("row".ordinality)::text) AS entity_key,
    jsonb_build_object('source_id', r.native_id, 'description', ("row".value -> 'description'::text), 'published_at', ("row".value -> 'date_published'::text), 'author', ("row".value -> 'author'::text), 'type', ("row".value -> 'type'::text), 'platform', ("row".value -> 'platform'::text), 'verified',
        CASE ("row".value ->> 'verified'::text)
            WHEN '0'::text THEN 'false'::jsonb
            WHEN '1'::text THEN 'true'::jsonb
            ELSE NULL::jsonb
        END, 'source_identifiers', ("row".value -> 'codes'::text)) AS fields
   FROM (evidence_pipeline.current_public_references r
     CROSS JOIN LATERAL jsonb_array_elements((r.source_fields -> 'raw_rows'::text)) WITH ORDINALITY "row"(value, ordinality))
  WHERE (r.reference_kind = 'exploit_metadata'::text)
UNION ALL
 SELECT r.connection_id,
    r.receipt_id,
    r.origin,
    'cve-attack-mapping'::text AS domain,
    (((r.receipt_id)::text || '/'::text) || ("row".ordinality)::text) AS entity_key,
    jsonb_build_object('cve_id', r.native_id, 'phase', ("row".value -> 'Phase'::text), 'primary_impact', ("row".value -> 'Primary Impact'::text), 'secondary_impact', ("row".value -> 'Secondary Impact'::text), 'exploitation_technique', ("row".value -> 'Exploitation Technique'::text), 'uncategorized', ("row".value -> 'Uncategorized'::text)) AS fields
   FROM (evidence_pipeline.current_public_references r
     CROSS JOIN LATERAL jsonb_array_elements((r.source_fields -> 'raw_rows'::text)) WITH ORDINALITY "row"(value, ordinality))
  WHERE (r.reference_kind = 'cve_attack_mapping'::text)
UNION ALL
 SELECT r.connection_id,
    r.receipt_id,
    r.origin,
    'catalog-update'::text AS domain,
    (r.receipt_id)::text AS entity_key,
    jsonb_build_object('update_id', r.update_id, 'title', (r.metadata -> 'title'::text), 'updated_at', (r.metadata -> 'updated_at'::text), 'description', (r.metadata -> 'description'::text), 'products', (r.metadata -> 'products'::text), 'classification', (r.metadata -> 'classification'::text), 'architecture', NULLIF((r.metadata ->> 'architecture'::text), 'n/a'::text), 'kb_articles', (r.metadata -> 'kb_articles'::text)) AS fields
   FROM evidence_pipeline.current_catalog_updates r
UNION ALL
 SELECT r.connection_id,
    r.receipt_id,
    r.origin,
    'vendor-advisory'::text AS domain,
    (r.receipt_id)::text AS entity_key,
    jsonb_build_object('advisory_id', r.native_id, 'title', (r.claim #> '{source_vulnerability,Title}'::text[]), 'notes', (r.claim #> '{source_vulnerability,Notes}'::text[]), 'product_statuses', (r.claim #> '{source_vulnerability,ProductStatuses}'::text[]), 'remediations', (r.claim #> '{source_vulnerability,Remediations}'::text[])) AS fields
   FROM evidence_pipeline.current_msrc_advisory_claims r;


ALTER VIEW evidence_pipeline.current_native_advisory_facts OWNER TO tm_mock_owner;

--
-- Name: current_native_advisory_completeness_cells; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_native_advisory_completeness_cells AS
 SELECT r.domain,
    r.entity_key,
    r.connection_id,
    r.origin,
    r.receipt_id,
    (r.domain || '-v1'::text) AS definition_id,
    f.key AS field_name,
    'applicable'::text AS applicability,
    'explicit_native_source_definition'::text AS applicability_reason,
    f.value,
    ((f.value IS NOT NULL) AND (f.value <> ALL (ARRAY['null'::jsonb, '""'::jsonb, '[]'::jsonb, '{}'::jsonb]))) AS populated
   FROM (evidence_pipeline.current_native_advisory_facts r
     CROSS JOIN LATERAL jsonb_each(r.fields) f(key, value));


ALTER VIEW evidence_pipeline.current_native_advisory_completeness_cells OWNER TO tm_mock_owner;

--
-- Name: current_public_advisories; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_public_advisories AS
 SELECT e.id,
    e.source_advisory_id,
    e.title,
    e.publisher,
    e.url,
    e.published_at,
    e.updated_at,
    e.content_or_reference,
    e.receipt_id,
    c.connection_id,
    c.source_name,
    c.input_kind,
    c.scope_reference,
    c.selected_attempt_id,
    c.selected_finished_at,
    c.latest_outcome,
    c.latest_finished_at,
    revision.origin,
    revision.source_url,
    revision.licence_or_provenance,
    revision.content_hash
   FROM ((((evidence_pipeline.collection_status c
     JOIN evidence.observation_receipts receipt ON ((receipt.collection_attempt_id = c.selected_attempt_id)))
     JOIN evidence.source_revisions revision ON ((revision.id = receipt.source_revision_id)))
     JOIN evidence_pipeline.public_claims claim ON ((claim.source_revision_id = revision.id)))
     JOIN evidence.advisories e ON ((e.receipt_id = receipt.id)))
  WHERE ((c.tenant_id IS NULL) AND (c.source_name = 'MSRC'::text) AND (c.input_kind = 'advisories'::text));


ALTER VIEW evidence_pipeline.current_public_advisories OWNER TO tm_mock_owner;

--
-- Name: VIEW current_public_advisories; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_public_advisories IS 'Latest complete public input per source scope; failures retain previous evidence. Source-supported advisory/patch relationships; product labels are not device applicability or remediation evidence.';


--
-- Name: current_public_cvss_observations; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_public_cvss_observations AS
 SELECT e.id,
    e.cve_id,
    e.receipt_id,
    e.publisher,
    e.version,
    e.score,
    e.vector,
    e.published_at,
    c.connection_id,
    c.source_name,
    c.input_kind,
    c.scope_reference,
    c.selected_attempt_id,
    c.selected_finished_at,
    c.latest_outcome,
    c.latest_finished_at,
    revision.origin,
    revision.source_url,
    revision.licence_or_provenance,
    revision.content_hash
   FROM ((((evidence_pipeline.collection_status c
     JOIN evidence.observation_receipts receipt ON ((receipt.collection_attempt_id = c.selected_attempt_id)))
     JOIN evidence.source_revisions revision ON ((revision.id = receipt.source_revision_id)))
     JOIN evidence_pipeline.public_claims claim ON ((claim.source_revision_id = revision.id)))
     JOIN evidence.cvss_observations e ON ((e.receipt_id = receipt.id)))
  WHERE (c.tenant_id IS NULL);


