--
-- Name: current_public_epss_observations; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_public_epss_observations AS
 SELECT e.id,
    e.cve_id,
    e.receipt_id,
    e.probability,
    e.percentile,
    e.score_date,
    e.model_version,
    c.connection_id,
    c.source_name,
    c.input_kind,
    c.scope_reference,
    c.selected_attempt_id,
    c.selected_finished_at,
    c.latest_outcome,
    c.latest_finished_at,
    revision.origin,
    revision.source_url,
    revision.licence_or_provenance,
    revision.content_hash
   FROM ((((evidence_pipeline.collection_status c
     JOIN evidence.observation_receipts receipt ON ((receipt.collection_attempt_id = c.selected_attempt_id)))
     JOIN evidence.source_revisions revision ON ((revision.id = receipt.source_revision_id)))
     JOIN evidence_pipeline.public_claims claim ON ((claim.source_revision_id = revision.id)))
     JOIN evidence.epss_observations e ON ((e.receipt_id = receipt.id)))
  WHERE ((c.tenant_id IS NULL) AND (c.source_name = 'FIRST'::text) AND (c.input_kind = 'epss'::text));


