--
-- Name: product_completeness_definition; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.product_completeness_definition AS
 SELECT domain,
    (domain || '-v1'::text) AS definition_id,
    field_name
   FROM ( VALUES ('public-advisory'::text,'source_advisory_id'::text), ('public-advisory'::text,'title'::text), ('public-advisory'::text,'publisher'::text), ('public-advisory'::text,'url'::text), ('public-advisory'::text,'published_at'::text), ('public-advisory'::text,'updated_at'::text), ('public-advisory'::text,'content_or_reference'::text), ('public-vulnerability'::text,'cve_id'::text), ('public-vulnerability'::text,'title'::text), ('public-vulnerability'::text,'description'::text), ('public-vulnerability'::text,'source_severity_label'::text), ('public-vulnerability'::text,'published_at'::text), ('public-vulnerability'::text,'updated_at'::text), ('public-vulnerability'::text,'supportability'::text), ('public-cvss'::text,'cve_id'::text), ('public-cvss'::text,'publisher'::text), ('public-cvss'::text,'version'::text), ('public-cvss'::text,'score'::text), ('public-cvss'::text,'vector'::text), ('public-cvss'::text,'published_at'::text), ('public-epss'::text,'cve_id'::text), ('public-epss'::text,'probability'::text), ('public-epss'::text,'percentile'::text), ('public-epss'::text,'score_date'::text), ('public-epss'::text,'model_version'::text), ('public-kev'::text,'cve_id'::text), ('public-kev'::text,'membership'::text), ('public-kev'::text,'date_added'::text), ('public-kev'::text,'required_action'::text), ('public-kev'::text,'source_due_date'::text), ('public-patch'::text,'source_patch_id'::text), ('public-patch'::text,'title'::text), ('public-patch'::text,'url'::text), ('public-patch'::text,'published_at'::text), ('public-patch'::text,'product_names'::text), ('public-recommendation'::text,'source_recommendation_id'::text), ('public-recommendation'::text,'title'::text), ('public-recommendation'::text,'recommendation_text'::text), ('public-recommendation'::text,'vendor'::text), ('public-recommendation'::text,'product_name'::text), ('public-recommendation'::text,'recommended_version'::text), ('public-recommendation'::text,'recommended_program'::text), ('public-recommendation'::text,'recommended_vendor'::text), ('public-recommendation'::text,'category'::text), ('public-recommendation'::text,'subcategory'::text), ('public-recommendation'::text,'remediation_type'::text), ('public-recommendation'::text,'source_status'::text)) fields(domain, field_name);


ALTER VIEW evidence_pipeline.product_completeness_definition OWNER TO tm_mock_owner;

--
-- Name: current_public_completeness_cells; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_public_completeness_cells AS
 WITH records AS (
         SELECT 'public-advisory'::text AS domain,
            (v.id)::text AS entity_key,
            v.connection_id,
            v.origin,
            v.receipt_id,
            to_jsonb(v.*) AS fields
           FROM evidence_pipeline.current_public_advisories v
        UNION ALL
         SELECT 'public-vulnerability'::text AS domain,
            (v.id)::text AS entity_key,
            v.connection_id,
            v.origin,
            v.receipt_id,
            to_jsonb(v.*) AS fields
           FROM evidence_pipeline.current_public_vulnerability_details v
        UNION ALL
         SELECT 'public-cvss'::text AS domain,
            (v.id)::text AS entity_key,
            v.connection_id,
            v.origin,
            v.receipt_id,
            to_jsonb(v.*) AS fields
           FROM evidence_pipeline.current_public_cvss_observations v
        UNION ALL
         SELECT 'public-epss'::text AS domain,
            (v.id)::text AS entity_key,
            v.connection_id,
            v.origin,
            v.receipt_id,
            to_jsonb(v.*) AS fields
           FROM evidence_pipeline.current_public_epss_observations v
        UNION ALL
         SELECT 'public-kev'::text AS domain,
            (v.id)::text AS entity_key,
            v.connection_id,
            v.origin,
            v.receipt_id,
            to_jsonb(v.*) AS fields
           FROM evidence_pipeline.current_public_kev_observations v
        UNION ALL
         SELECT 'public-patch'::text AS domain,
            (v.id)::text AS entity_key,
            v.connection_id,
            v.origin,
            v.receipt_id,
            f.fields
           FROM (evidence_pipeline.current_public_patches v
             CROSS JOIN LATERAL ( SELECT jsonb_build_object('source_patch_id', v.source_patch_id, 'title', v.title, 'url', v.url, 'published_at', v.published_at, 'product_names', v.product_names) AS fields
                 OFFSET 0) f)
        UNION ALL
         SELECT 'public-recommendation'::text AS domain,
            (v.id)::text AS entity_key,
            v.connection_id,
            v.origin,
            v.receipt_id,
            to_jsonb(v.*) AS fields
           FROM evidence_pipeline.current_public_recommendations v
        )
 SELECT r.domain,
    r.entity_key,
    r.connection_id,
    r.origin,
    r.receipt_id,
    d.definition_id,
    d.field_name,
    'applicable'::text AS applicability,
    'explicit_source_record_definition'::text AS applicability_reason,
    (r.fields -> d.field_name) AS value,
    (((r.fields -> d.field_name) IS NOT NULL) AND ((r.fields -> d.field_name) <> ALL (ARRAY['null'::jsonb, '""'::jsonb, '[]'::jsonb, '{}'::jsonb]))) AS populated
   FROM (records r
     JOIN evidence_pipeline.product_completeness_definition d USING (domain));


ALTER VIEW evidence_pipeline.current_public_completeness_cells OWNER TO tm_mock_owner;

--
-- Name: software_inventory; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
