CREATE TABLE evidence_pipeline.software_inventory (
    id uuid NOT NULL,
    collection_attempt_id uuid NOT NULL,
    receipt_id uuid NOT NULL,
    software_id uuid NOT NULL,
    source_application_id text NOT NULL,
    reported_device_count integer,
    CONSTRAINT software_inventory_reported_device_count_check CHECK ((reported_device_count >= 0)),
    CONSTRAINT software_inventory_source_application_id_check CHECK ((length(btrim(source_application_id)) > 0))
);


ALTER TABLE evidence_pipeline.software_inventory OWNER TO tm_mock_owner;

--
-- Name: current_software_inventory; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_software_inventory AS
 SELECT i.id AS inventory_id,
    c.connection_id,
    c.source_name,
    c.tenant_id,
    c.selected_attempt_id,
    c.selected_finished_at,
    c.latest_outcome,
    x.device_attempt_id,
    i.receipt_id,
    i.source_application_id,
    s.id AS software_id,
    s.product_name,
    s.publisher,
    s.version,
    s.platform,
    i.reported_device_count,
    ( SELECT count(*) AS count
           FROM evidence.software_observations o
          WHERE (o.inventory_id = i.id)) AS observed_device_count
   FROM (((evidence_pipeline.collection_status c
     JOIN evidence_pipeline.exposure_snapshots x ON ((x.collection_attempt_id = c.selected_attempt_id)))
     JOIN evidence_pipeline.software_inventory i ON ((i.collection_attempt_id = x.collection_attempt_id)))
     JOIN evidence.software s ON ((s.id = i.software_id)))
  WHERE (c.input_kind = 'software'::text);


ALTER VIEW evidence_pipeline.current_software_inventory OWNER TO tm_mock_owner;

--
-- Name: VIEW current_software_inventory; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_software_inventory IS 'Current app inventory, including apps with no device associations or reported CVEs. Source-native counts stay separate from observed links.';


--
-- Name: software_completeness_definition; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.software_completeness_definition AS
 SELECT 'software-inventory-v1'::text AS definition_id,
    field_name,
    value_kind
   FROM ( VALUES ('source_application_id'::text,'text'::text), ('product_name'::text,'text'::text), ('publisher'::text,'text'::text), ('version'::text,'text'::text), ('platform'::text,'text'::text), ('reported_device_count'::text,'number'::text)) fields(field_name, value_kind);


ALTER VIEW evidence_pipeline.software_completeness_definition OWNER TO tm_mock_owner;

--
-- Name: current_software_completeness_cells; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_software_completeness_cells AS
 SELECT i.inventory_id,
    i.connection_id,
    i.source_name,
    i.tenant_id,
    ac.origin,
    i.selected_attempt_id,
    i.device_attempt_id,
    i.receipt_id,
    f.definition_id,
    f.field_name,
    f.value_kind,
    'applicable'::text AS applicability,
    (to_jsonb(i.*) -> f.field_name) AS value,
    (((to_jsonb(i.*) -> f.field_name) IS NOT NULL) AND ((to_jsonb(i.*) -> f.field_name) <> 'null'::jsonb)) AS populated
   FROM ((evidence_pipeline.current_software_inventory i
     JOIN evidence_pipeline.authorized_connections ac ON ((ac.connection_id = i.connection_id)))
     CROSS JOIN evidence_pipeline.software_completeness_definition f);


ALTER VIEW evidence_pipeline.current_software_completeness_cells OWNER TO tm_mock_owner;

--
-- Name: vulnerability_completeness_definition; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.vulnerability_completeness_definition AS
 SELECT 'vulnerability-evidence-v1'::text AS definition_id,
    input_kind,
    field_name
   FROM ( VALUES ('findings'::text,'source_record_id'::text), ('findings'::text,'native_device_id'::text), ('findings'::text,'cve_id'::text), ('findings'::text,'product_name'::text), ('findings'::text,'publisher'::text), ('findings'::text,'version'::text), ('findings'::text,'severity'::text), ('vulnerability_baseline'::text,'source_record_id'::text), ('vulnerability_baseline'::text,'native_device_id'::text), ('vulnerability_baseline'::text,'cve_id'::text), ('vulnerability_baseline'::text,'product_name'::text), ('vulnerability_baseline'::text,'publisher'::text), ('vulnerability_baseline'::text,'version'::text), ('vulnerability_baseline'::text,'severity'::text), ('vulnerability_baseline'::text,'cvss'::text), ('vulnerability_baseline'::text,'security_update_available'::text)) fields(input_kind, field_name);


ALTER VIEW evidence_pipeline.vulnerability_completeness_definition OWNER TO tm_mock_owner;

--
-- Name: current_vulnerability_completeness_cells; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_vulnerability_completeness_cells AS
 WITH records AS (
         SELECT f.connection_id,
            f.selected_attempt_id,
            f.receipt_id,
            f.device_attempt_id,
            f.provider_device_id,
            'findings'::text AS input_kind,
            jsonb_build_object('source_record_id', f.source_finding_id, 'native_device_id', p.native_device_id, 'cve_id', f.cve_id, 'product_name', f.product_name, 'publisher', f.publisher, 'version', f.version, 'severity', f.source_severity_label) AS fields
           FROM (evidence_pipeline.current_findings f
             JOIN evidence.provider_devices p ON ((p.id = f.provider_device_id)))
        UNION ALL
         SELECT a.connection_id,
            a.collection_attempt_id,
            a.receipt_id,
            r.device_attempt_id,
            a.provider_device_id,
            'vulnerability_baseline'::text,
            jsonb_build_object('source_record_id', (a.claim -> 'source_record_id'::text), 'native_device_id', (a.claim -> 'native_device_id'::text), 'cve_id', a.cve_id, 'product_name', ((a.claim -> 'product'::text) -> 'product_name'::text), 'publisher', ((a.claim -> 'product'::text) -> 'publisher'::text), 'version', ((a.claim -> 'product'::text) -> 'version'::text), 'severity', ( SELECT (v.value -> 1)
                   FROM jsonb_array_elements((a.claim -> 'fields'::text)) v(value)
                  WHERE ((v.value ->> 0) = 'vulnerabilitySeverityLevel'::text)), 'cvss', ( SELECT (v.value -> 1)
                   FROM jsonb_array_elements((a.claim -> 'fields'::text)) v(value)
                  WHERE ((v.value ->> 0) = 'cvssScore'::text)), 'security_update_available', ( SELECT (v.value -> 1)
                   FROM jsonb_array_elements((a.claim -> 'fields'::text)) v(value)
                  WHERE ((v.value ->> 0) = 'securityUpdateAvailable'::text))) AS jsonb_build_object
           FROM (evidence_pipeline.current_assessment_baseline a
             JOIN evidence_pipeline.assessment_runs r ON ((r.attempt_id = a.collection_attempt_id)))
        ), cells AS (
         SELECT r.connection_id,
            r.selected_attempt_id,
            r.receipt_id,
            r.device_attempt_id,
            r.provider_device_id,
            r.input_kind,
            d.definition_id,
            d.field_name,
            (r.fields -> d.field_name) AS value,
                CASE
                    WHEN ((r.input_kind = 'vulnerability_baseline'::text) AND (d.field_name = ANY (ARRAY['cve_id'::text, 'severity'::text, 'cvss'::text])) AND (((r.fields -> 'cve_id'::text) IS NULL) OR ((r.fields -> 'cve_id'::text) = 'null'::jsonb))) THEN 'unknown'::text
                    ELSE 'applicable'::text
                END AS applicability
           FROM (records r
             JOIN evidence_pipeline.vulnerability_completeness_definition d USING (input_kind))
        )
 SELECT cells.connection_id,
    cells.selected_attempt_id,
    cells.receipt_id,
    cells.device_attempt_id,
    cells.provider_device_id,
    cells.input_kind,
    cells.definition_id,
    cells.field_name,
    cells.value,
    cells.applicability,
    ac.origin,
    ((cells.applicability = 'applicable'::text) AND (cells.value IS NOT NULL) AND (cells.value <> 'null'::jsonb)) AS populated
   FROM (cells
     JOIN evidence_pipeline.authorized_connections ac USING (connection_id));


ALTER VIEW evidence_pipeline.current_vulnerability_completeness_cells OWNER TO tm_mock_owner;

--
-- Name: windows_inventory_bindings; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.windows_inventory_bindings (
    connection_id uuid NOT NULL,
    device_connection_id uuid NOT NULL,
    native_device_id text NOT NULL,
    machine_guid uuid NOT NULL,
    entra_device_id uuid NOT NULL,
    CONSTRAINT windows_inventory_bindings_check CHECK ((connection_id <> device_connection_id)),
    CONSTRAINT windows_inventory_bindings_entra_device_id_check CHECK ((entra_device_id <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT windows_inventory_bindings_machine_guid_check CHECK ((machine_guid <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT windows_inventory_bindings_native_device_id_check CHECK (((length(btrim(native_device_id)) >= 1) AND (length(btrim(native_device_id)) <= 4096)))
);


ALTER TABLE evidence_pipeline.windows_inventory_bindings OWNER TO tm_mock_owner;

--
-- Name: windows_inventory_observations; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.windows_inventory_observations (
    receipt_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    kind text NOT NULL,
    native_id text NOT NULL,
    facts jsonb NOT NULL,
    CONSTRAINT windows_bundle_member_fields CHECK (((kind <> 'appx_bundle_member'::text) OR evidence_pipeline.valid_bundle_member(facts))),
    CONSTRAINT windows_bundle_summary_fields CHECK (((NOT (facts ? 'bundle_manifest'::text)) OR evidence_pipeline.valid_bundle_summary(facts))),
    CONSTRAINT windows_inventory_observations_check CHECK (((jsonb_typeof(facts) = 'object'::text) AND (NOT ((facts ->> 'kind'::text) IS DISTINCT FROM kind)) AND (NOT ((facts ->> 'native_id'::text) IS DISTINCT FROM native_id)))),
    CONSTRAINT windows_inventory_observations_kind_check CHECK ((kind = ANY (ARRAY['registry'::text, 'appx'::text, 'appx_bundle_member'::text]))),
    CONSTRAINT windows_inventory_observations_native_id_check CHECK (((length(btrim(native_id)) >= 1) AND (length(btrim(native_id)) <= 4096)))
);


ALTER TABLE evidence_pipeline.windows_inventory_observations OWNER TO tm_mock_owner;

--
-- Name: windows_inventory_runs; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.windows_inventory_runs (
    attempt_id uuid NOT NULL,
    device_attempt_id uuid NOT NULL,
    provider_device_id uuid NOT NULL,
    coverage jsonb NOT NULL,
    record_count bigint NOT NULL,
    CONSTRAINT windows_inventory_runs_coverage_check CHECK ((jsonb_typeof(coverage) = 'object'::text)),
    CONSTRAINT windows_inventory_runs_record_count_check CHECK ((record_count >= 0))
);


ALTER TABLE evidence_pipeline.windows_inventory_runs OWNER TO tm_mock_owner;

--
-- Name: current_windows_inventory_evidence; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_windows_inventory_evidence AS
 WITH selected AS (
         SELECT DISTINCT ON (a_1.connection_id) a_1.id,
            a_1.connection_id,
            a_1.started_at,
            a_1.finished_at
           FROM (evidence.collection_attempts a_1
             JOIN evidence_pipeline.windows_inventory_runs s_1 ON ((s_1.attempt_id = a_1.id)))
          WHERE (a_1.complete AND (a_1.outcome = 'success'::text))
          ORDER BY a_1.connection_id, a_1.started_at DESC, a_1.finished_at DESC, a_1.id DESC
        )
 SELECT a.connection_id,
    a.id AS collection_attempt_id,
    a.started_at,
    a.finished_at,
    c.source_name,
    c.scope_reference,
    t.external_tenant_id AS tenant_id,
    v.origin,
    s.device_attempt_id,
    s.provider_device_id,
    b.machine_guid,
    b.entra_device_id,
    o.receipt_id,
    o.kind,
    o.native_id,
    (o.facts ->> 'name'::text) AS product_name,
    (o.facts ->> 'version'::text) AS version,
    (o.facts ->> 'publisher'::text) AS publisher,
    o.facts,
    s.coverage,
    v.licence_or_provenance,
    v.content_hash
   FROM (((((((selected a
     JOIN evidence_pipeline.windows_inventory_runs s ON ((s.attempt_id = a.id)))
     JOIN evidence_pipeline.windows_inventory_bindings b ON ((b.connection_id = a.connection_id)))
     JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
     JOIN evidence.microsoft_tenants t ON ((t.id = c.tenant_id)))
     JOIN evidence_pipeline.windows_inventory_observations o ON ((o.attempt_id = a.id)))
     JOIN evidence.observation_receipts r ON ((r.id = o.receipt_id)))
     JOIN evidence.source_revisions v ON ((v.id = r.source_revision_id)));


ALTER VIEW evidence_pipeline.current_windows_inventory_evidence OWNER TO tm_mock_owner;

--
-- Name: current_windows_inventory; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_windows_inventory AS
 SELECT connection_id,
    collection_attempt_id,
    started_at,
    finished_at,
    source_name,
    scope_reference,
    tenant_id,
    origin,
    device_attempt_id,
    provider_device_id,
    machine_guid,
    entra_device_id,
    receipt_id,
    kind,
    native_id,
    product_name,
    version,
    publisher,
    facts,
    coverage,
    licence_or_provenance,
    content_hash
   FROM evidence_pipeline.current_windows_inventory_evidence
  WHERE (kind = ANY (ARRAY['registry'::text, 'appx'::text]));


ALTER VIEW evidence_pipeline.current_windows_inventory OWNER TO tm_mock_owner;

--
-- Name: VIEW current_windows_inventory; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_windows_inventory IS 'Distinct read-only Windows registry/Appx observations. Package observations are not unique products or independent applicability. Pinned device/source/tenant provenance and coverage remain inspectable.';


--
-- Name: windows_inventory_completeness_definition; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.windows_inventory_completeness_definition AS
 SELECT kind,
    (('windows-inventory-'::text || kind) || '-v1'::text) AS definition_id,
    field_name
   FROM ( VALUES ('registry'::text,'native_id'::text), ('registry'::text,'name'::text), ('registry'::text,'version'::text), ('registry'::text,'publisher'::text), ('registry'::text,'install_date'::text), ('registry'::text,'system_component'::text), ('registry'::text,'release_type'::text), ('registry'::text,'parent_key_name'::text), ('appx'::text,'native_id'::text), ('appx'::text,'name'::text), ('appx'::text,'version'::text), ('appx'::text,'publisher'::text), ('appx'::text,'architecture'::text), ('appx'::text,'is_framework'::text), ('appx'::text,'is_resource_package'::text), ('appx'::text,'non_removable'::text), ('appx'::text,'status'::text), ('appx'::text,'user_states'::text)) fields(kind, field_name);


ALTER VIEW evidence_pipeline.windows_inventory_completeness_definition OWNER TO tm_mock_owner;

--
-- Name: current_windows_inventory_completeness_cells; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_windows_inventory_completeness_cells AS
 SELECT 'windows-inventory'::text AS domain,
    (i.receipt_id)::text AS entity_key,
    i.connection_id,
    i.tenant_id,
    i.origin,
    i.receipt_id,
    i.kind,
    i.native_id,
    d.definition_id,
    d.field_name,
    'applicable'::text AS applicability,
    'explicit_source_kind_definition'::text AS applicability_reason,
    (i.facts -> d.field_name) AS value,
    (((i.facts -> d.field_name) IS NOT NULL) AND ((i.facts -> d.field_name) <> ALL (ARRAY['null'::jsonb, '""'::jsonb])) AND ((jsonb_typeof((i.facts -> d.field_name)) <> 'string'::text) OR (btrim((i.facts ->> d.field_name)) <> ''::text))) AS populated
   FROM (evidence_pipeline.current_windows_inventory i
     JOIN evidence_pipeline.windows_inventory_completeness_definition d USING (kind));


ALTER VIEW evidence_pipeline.current_windows_inventory_completeness_cells OWNER TO tm_mock_owner;

--
-- Name: VIEW current_windows_inventory_completeness_cells; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_windows_inventory_completeness_cells IS 'Provisional source-observation completeness. Registry and Appx have separate eligible fields; false, zero and an explicitly empty user-state array are populated. Missing optional facts remain missing, not silently inapplicable. Family-name duplicates, kind selectors, internal identity, collection times, derived installation or recognition and provenance mechanics are excluded. Package user states occupy one source field per package, not additional products. Selected source scopes remain separate observations; this does not establish unique installed-product coverage or applicability.';


--
-- Name: current_product_completeness_cells; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_product_completeness_cells AS
 SELECT 'device'::text AS domain,
    c.computer_key AS entity_key,
    c.origin,
    c.definition_id,
    c.field_key AS field_name,
    c.applicability,
    c.applicability_reason,
    c.value,
    c.populated,
    c.receipt_id,
        CASE
            WHEN (c.connection_id IS NOT NULL) THEN ARRAY[c.connection_id]
            ELSE ARRAY( SELECT DISTINCT l.connection_id
               FROM evidence_pipeline.current_computer_links l
              WHERE (l.computer_key = c.computer_key)
              ORDER BY l.connection_id)
        END AS scope_connections
   FROM evidence_pipeline.current_completeness_cells c
UNION ALL
 SELECT 'software'::text AS domain,
    (current_software_completeness_cells.inventory_id)::text AS entity_key,
    current_software_completeness_cells.origin,
    current_software_completeness_cells.definition_id,
    current_software_completeness_cells.field_name,
    current_software_completeness_cells.applicability,
    'explicit_source_inventory_definition'::text AS applicability_reason,
    current_software_completeness_cells.value,
    current_software_completeness_cells.populated,
    current_software_completeness_cells.receipt_id,
    ARRAY[current_software_completeness_cells.connection_id] AS scope_connections
   FROM evidence_pipeline.current_software_completeness_cells
UNION ALL
 SELECT 'vulnerability'::text AS domain,
    (current_vulnerability_completeness_cells.receipt_id)::text AS entity_key,
    current_vulnerability_completeness_cells.origin,
    current_vulnerability_completeness_cells.definition_id,
    current_vulnerability_completeness_cells.field_name,
    current_vulnerability_completeness_cells.applicability,
        CASE
            WHEN (current_vulnerability_completeness_cells.applicability = 'unknown'::text) THEN 'source_cve_applicability_unknown'::text
            ELSE 'explicit_source_finding_definition'::text
        END AS applicability_reason,
    current_vulnerability_completeness_cells.value,
    current_vulnerability_completeness_cells.populated,
    current_vulnerability_completeness_cells.receipt_id,
    ARRAY[current_vulnerability_completeness_cells.connection_id] AS scope_connections
   FROM evidence_pipeline.current_vulnerability_completeness_cells
UNION ALL
 SELECT current_public_completeness_cells.domain,
    current_public_completeness_cells.entity_key,
    current_public_completeness_cells.origin,
    current_public_completeness_cells.definition_id,
    current_public_completeness_cells.field_name,
    current_public_completeness_cells.applicability,
    current_public_completeness_cells.applicability_reason,
    current_public_completeness_cells.value,
    current_public_completeness_cells.populated,
    current_public_completeness_cells.receipt_id,
    ARRAY[current_public_completeness_cells.connection_id] AS scope_connections
   FROM evidence_pipeline.current_public_completeness_cells
UNION ALL
 SELECT current_native_advisory_completeness_cells.domain,
    current_native_advisory_completeness_cells.entity_key,
    current_native_advisory_completeness_cells.origin,
    current_native_advisory_completeness_cells.definition_id,
    current_native_advisory_completeness_cells.field_name,
    current_native_advisory_completeness_cells.applicability,
    current_native_advisory_completeness_cells.applicability_reason,
    current_native_advisory_completeness_cells.value,
    current_native_advisory_completeness_cells.populated,
    current_native_advisory_completeness_cells.receipt_id,
    ARRAY[current_native_advisory_completeness_cells.connection_id] AS scope_connections
   FROM evidence_pipeline.current_native_advisory_completeness_cells
UNION ALL
 SELECT current_windows_inventory_completeness_cells.domain,
    current_windows_inventory_completeness_cells.entity_key,
    current_windows_inventory_completeness_cells.origin,
    current_windows_inventory_completeness_cells.definition_id,
    current_windows_inventory_completeness_cells.field_name,
    current_windows_inventory_completeness_cells.applicability,
    current_windows_inventory_completeness_cells.applicability_reason,
    current_windows_inventory_completeness_cells.value,
    current_windows_inventory_completeness_cells.populated,
    current_windows_inventory_completeness_cells.receipt_id,
    ARRAY[current_windows_inventory_completeness_cells.connection_id] AS scope_connections
   FROM evidence_pipeline.current_windows_inventory_completeness_cells;


ALTER VIEW evidence_pipeline.current_product_completeness_cells OWNER TO tm_mock_owner;

--
-- Name: selected_product_completeness_cells(uuid[]); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.selected_product_completeness_cells(selected_connections uuid[]) RETURNS SETOF evidence_pipeline.current_product_completeness_cells
    LANGUAGE sql STABLE
    AS $$
 SELECT * FROM evidence_pipeline.current_product_completeness_cells
 WHERE domain='device' AND scope_connections && selected_connections
 UNION ALL
 SELECT 'software',inventory_id::text,origin,definition_id,field_name,applicability,
 'explicit_source_inventory_definition',value,populated,receipt_id,ARRAY[connection_id]
 FROM evidence_pipeline.current_software_completeness_cells
 WHERE connection_id=ANY(selected_connections)
 UNION ALL
 SELECT 'vulnerability',receipt_id::text,origin,definition_id,field_name,applicability,
 CASE WHEN applicability='unknown' THEN 'source_cve_applicability_unknown' ELSE 'explicit_source_finding_definition' END,
 value,populated,receipt_id,ARRAY[connection_id]
 FROM evidence_pipeline.current_vulnerability_completeness_cells
 WHERE connection_id=ANY(selected_connections)
 UNION ALL
 SELECT domain,entity_key,origin,definition_id,field_name,applicability,
 applicability_reason,value,populated,receipt_id,ARRAY[connection_id]
 FROM evidence_pipeline.current_public_completeness_cells
 WHERE connection_id=ANY(selected_connections)
 UNION ALL
 SELECT domain,entity_key,origin,definition_id,field_name,applicability,
 applicability_reason,value,populated,receipt_id,ARRAY[connection_id]
 FROM evidence_pipeline.current_native_advisory_completeness_cells
 WHERE connection_id=ANY(selected_connections)
 UNION ALL
 SELECT domain,entity_key,origin,definition_id,field_name,applicability,
 applicability_reason,value,populated,receipt_id,ARRAY[connection_id]
 FROM evidence_pipeline.current_windows_inventory_completeness_cells
 WHERE connection_id=ANY(selected_connections)
$$;


ALTER FUNCTION evidence_pipeline.selected_product_completeness_cells(selected_connections uuid[]) OWNER TO tm_mock_owner;

--
-- Name: FUNCTION selected_product_completeness_cells(selected_connections uuid[]); Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON FUNCTION evidence_pipeline.selected_product_completeness_cells(selected_connections uuid[]) IS 'The same eligible cells as current_product_completeness_cells, filtered by selected connections before single-source domain expansion. Device shared-scope cells retain existing overlap semantics. Invoker authority; no security definer or cached evidence.';


--
-- Name: ubuntu_snapshot_matches(text, text, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.ubuntu_snapshot_matches(source_origin text, commit_id text, members jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_typeof(members)='array'
 AND (SELECT count(*)=count(DISTINCT member->>'path') FROM jsonb_array_elements(members) member)
 AND NOT EXISTS (
  SELECT 1 FROM jsonb_array_elements(members) member
  LEFT JOIN evidence.observation_receipts r ON r.id=(member->>'receipt_id')::uuid
  LEFT JOIN evidence.collection_attempts a ON a.id=r.collection_attempt_id
  LEFT JOIN evidence.source_connections c ON c.id=a.connection_id
  LEFT JOIN evidence.source_revisions rev ON rev.id=r.source_revision_id
  LEFT JOIN evidence.osv_advisory_observations o ON o.receipt_id=r.id
  WHERE NOT coalesce(
   jsonb_typeof(member)='object' AND member ? 'path' AND member ? 'receipt_id'
   AND (member-'path'-'receipt_id')='{}'::jsonb
   AND c.source_name='Ubuntu' AND c.input_kind='advisories' AND c.tenant_id IS NULL
   AND rev.connection_id=c.id AND c.scope_reference=rev.source_url
   AND a.complete AND a.outcome='success' AND rev.origin=source_origin
   AND evidence_pipeline.ubuntu_source_allowed(o.advisory_id,rev.source_url)
   AND rev.source_url='https://raw.githubusercontent.com/canonical/ubuntu-security-notices/'
     ||commit_id||'/'||(member->>'path'),false)
 );
$$;


ALTER FUNCTION evidence_pipeline.ubuntu_snapshot_matches(source_origin text, commit_id text, members jsonb) OWNER TO tm_mock_owner;

--
-- Name: ubuntu_source_allowed(text, text); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.ubuntu_source_allowed(native_id text, source_url text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 WITH revision AS (SELECT split_part(source_url,'/',6) AS ref)
 SELECT COALESCE((ref='main' OR (ref ~ '^[0-9a-f]{40}$' AND ref <> '0000000000000000000000000000000000000000'))
 AND CASE
 WHEN native_id ~ '^UBUNTU-CVE-[0-9]{4}-[0-9]{4,19}$' THEN
 source_url='https://raw.githubusercontent.com/canonical/ubuntu-security-notices/'||ref||'/osv/cve/'||split_part(native_id,'-',3)||'/'||native_id||'.json'
 WHEN native_id ~ '^(USN|LSN)-[0-9]{1,10}-[0-9]{1,5}$' THEN
 source_url='https://raw.githubusercontent.com/canonical/ubuntu-security-notices/'||ref||'/osv/'||lower(split_part(native_id,'-',1))||'/'||native_id||'.json'
 ELSE false END,false) FROM revision
$_$;


ALTER FUNCTION evidence_pipeline.ubuntu_source_allowed(native_id text, source_url text) OWNER TO tm_mock_owner;

--
-- Name: valid_windows_inventory_binding(uuid); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.valid_windows_inventory_binding(target uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS (
  SELECT 1 FROM evidence_pipeline.windows_inventory_bindings b
  JOIN evidence.source_connections c ON c.id=b.connection_id
  JOIN evidence.source_connections d ON d.id=b.device_connection_id
  JOIN evidence_pipeline.authorized_connections a ON a.connection_id=c.id
  JOIN evidence_pipeline.authorized_connections ad ON ad.connection_id=d.id
  WHERE b.connection_id=target AND c.source_name='Windows inventory'
   AND c.input_kind='software_inventory'
   AND c.scope_reference='entra-device:'||b.entra_device_id::text
   AND c.tenant_id IS NOT NULL AND c.tenant_id=d.tenant_id
   AND d.source_name IN ('Entra','Intune','Defender') AND d.input_kind='devices'
   AND a.origin IN ('synthetic','lab') AND a.origin=ad.origin
 )
$$;


ALTER FUNCTION evidence_pipeline.valid_windows_inventory_binding(target uuid) OWNER TO tm_mock_owner;

--
-- Name: validate_exposure(); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.validate_exposure() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
    IF EXISTS (
        SELECT 1 FROM evidence_pipeline.input_device_scopes b
        JOIN evidence.source_connections i ON i.id=b.input_connection_id
        JOIN evidence.source_connections d ON d.id=b.device_connection_id
        LEFT JOIN evidence_pipeline.authorized_connections ai ON ai.connection_id=i.id
        LEFT JOIN evidence_pipeline.authorized_connections ad ON ad.connection_id=d.id
        WHERE ai.connection_id IS NULL OR ad.connection_id IS NULL
        OR ai.origin IS DISTINCT FROM ad.origin
        OR i.tenant_id IS NULL OR i.tenant_id IS DISTINCT FROM d.tenant_id
        OR i.source_name IS DISTINCT FROM d.source_name
        OR d.input_kind <> 'devices'
        OR NOT ((i.source_name='Intune' AND i.input_kind IN ('software','update_status'))
             OR (i.source_name='Defender' AND i.input_kind IN ('findings','missing_patches','antivirus')))
    ) THEN RAISE EXCEPTION 'Exposure source binding is invalid'; END IF;

    IF EXISTS (
        SELECT 1 FROM evidence_pipeline.exposure_snapshots s
        JOIN evidence_pipeline.input_device_scopes b ON b.input_connection_id=s.input_connection_id
        JOIN evidence.collection_attempts a ON a.id=s.collection_attempt_id
        JOIN evidence.collection_attempts d ON d.id=s.device_attempt_id
        WHERE a.connection_id<>s.input_connection_id
        OR d.connection_id<>b.device_connection_id
        OR NOT a.complete OR a.outcome<>'success'
        OR NOT d.complete OR d.outcome<>'success'
    ) THEN RAISE EXCEPTION 'Exposure snapshot must pin complete scoped device evidence'; END IF;

    IF EXISTS (
        SELECT 1 FROM evidence_pipeline.software_inventory i
        JOIN evidence_pipeline.exposure_snapshots s ON s.collection_attempt_id=i.collection_attempt_id
        JOIN evidence.source_connections c ON c.id=s.input_connection_id
        JOIN evidence.observation_receipts r ON r.id=i.receipt_id
        WHERE r.collection_attempt_id<>i.collection_attempt_id
        OR c.source_name<>'Intune' OR c.input_kind<>'software'
        OR (c.scope_reference NOT LIKE 'managed-device-apps:%' AND i.reported_device_count IS NOT NULL AND i.reported_device_count <>
            (SELECT count(*) FROM evidence.software_observations o WHERE o.inventory_id=i.id))
    ) THEN RAISE EXCEPTION 'Software inventory receipt or association count is invalid'; END IF;

    IF EXISTS (
        SELECT 1 FROM evidence_pipeline.software_inventory i
        JOIN evidence_pipeline.exposure_snapshots s ON s.collection_attempt_id=i.collection_attempt_id
        JOIN evidence.source_connections c ON c.id=s.input_connection_id
        WHERE c.scope_reference LIKE 'managed-device-apps:%' AND (
          c.scope_reference !~ '^managed-device-apps:[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
          OR (SELECT count(*) FROM evidence.software_observations o WHERE o.inventory_id=i.id)<>1
          OR EXISTS (
            SELECT 1 FROM evidence.software_observations o JOIN evidence.provider_devices p ON p.id=o.provider_device_id
            WHERE o.inventory_id=i.id AND c.scope_reference<>('managed-device-apps:' || p.native_device_id)
          )
        )
    ) THEN RAISE EXCEPTION 'Scoped software must retain its exact device relationship'; END IF;

    IF EXISTS (
        SELECT 1 FROM evidence.software_observations o
        JOIN evidence.observation_receipts r ON r.id=o.receipt_id
        JOIN evidence.collection_attempts a ON a.id=r.collection_attempt_id
        JOIN evidence.source_connections c ON c.id=a.connection_id
        LEFT JOIN evidence_pipeline.software_inventory i ON i.id=o.inventory_id
        WHERE (c.collector_reference LIKE 'evidence-pipeline-v1:%' OR o.inventory_id IS NOT NULL)
        AND (i.id IS NULL OR i.collection_attempt_id<>a.id
             OR i.receipt_id<>o.receipt_id OR i.software_id<>o.software_id
             OR i.source_application_id<>o.source_application_id)
    ) THEN RAISE EXCEPTION 'Software device link does not match its inventory record'; END IF;

    IF EXISTS (
        SELECT 1 FROM (
            SELECT provider_device_id,receipt_id,'software'::text AS input_kind
            FROM evidence.software_observations
            UNION ALL
            SELECT provider_device_id,receipt_id,'findings'::text
            FROM evidence.vulnerability_findings
            UNION ALL
            SELECT provider_device_id,receipt_id,'missing_patches'::text
            FROM evidence.device_missing_patches
            UNION ALL
            SELECT provider_device_id,receipt_id,'update_status'::text
            FROM evidence.update_policy_observations
            UNION ALL
            SELECT provider_device_id,receipt_id,'antivirus'::text
            FROM evidence.antivirus_observations
        ) o
        JOIN evidence.observation_receipts r ON r.id=o.receipt_id
        JOIN evidence.collection_attempts a ON a.id=r.collection_attempt_id
        JOIN evidence.source_connections c ON c.id=a.connection_id
        LEFT JOIN evidence_pipeline.exposure_snapshots s ON s.collection_attempt_id=a.id
        LEFT JOIN evidence_pipeline.input_device_scopes b ON b.input_connection_id=s.input_connection_id
        JOIN evidence.provider_devices p ON p.id=o.provider_device_id
        WHERE (c.collector_reference LIKE 'evidence-pipeline-v1:%' OR s.collection_attempt_id IS NOT NULL)
        AND (s.collection_attempt_id IS NULL OR c.input_kind<>o.input_kind
             OR p.connection_id<>b.device_connection_id
             OR NOT EXISTS (
                 SELECT 1 FROM evidence.device_observations d
                 JOIN evidence.observation_receipts dr ON dr.id=d.receipt_id
                 WHERE d.provider_device_id=p.id AND dr.collection_attempt_id=s.device_attempt_id
             ))
    ) THEN RAISE EXCEPTION 'Exposure device is absent from the pinned source snapshot'; END IF;

    IF EXISTS (
        SELECT 1 FROM evidence.vulnerability_findings f
        JOIN evidence.observation_receipts r ON r.id=f.receipt_id
        JOIN evidence_pipeline.exposure_snapshots s ON s.collection_attempt_id=r.collection_attempt_id
        GROUP BY s.collection_attempt_id,f.source_finding_id HAVING count(*)>1
    ) THEN RAISE EXCEPTION 'Duplicate source finding in exposure snapshot'; END IF;

    IF EXISTS (
        SELECT 1 FROM evidence.device_missing_patches o
        JOIN evidence.observation_receipts r ON r.id=o.receipt_id
        JOIN evidence_pipeline.exposure_snapshots s ON s.collection_attempt_id=r.collection_attempt_id
        JOIN evidence.patches p ON p.id=o.patch_id
        WHERE p.receipt_id<>o.receipt_id
    ) THEN RAISE EXCEPTION 'Missing patch must retain its source receipt'; END IF;
    IF EXISTS (
        SELECT 1 FROM evidence.update_policy_observations o
        JOIN evidence.observation_receipts r ON r.id=o.receipt_id
        JOIN evidence_pipeline.exposure_snapshots s ON s.collection_attempt_id=r.collection_attempt_id
        JOIN evidence.provider_devices p ON p.id=o.provider_device_id
        WHERE o.source_device_id<>p.native_device_id
    ) THEN RAISE EXCEPTION 'Update status source device differs from bound device'; END IF;
    IF EXISTS (
        SELECT 1 FROM evidence.device_missing_patches o
        JOIN evidence.observation_receipts r ON r.id=o.receipt_id
        JOIN evidence_pipeline.exposure_snapshots s ON s.collection_attempt_id=r.collection_attempt_id
        JOIN evidence.patches p ON p.id=o.patch_id
        GROUP BY s.collection_attempt_id,o.provider_device_id,p.source_patch_id HAVING count(*)>1
    ) THEN RAISE EXCEPTION 'Duplicate device patch observation'; END IF;
    IF EXISTS (
        SELECT 1 FROM evidence.update_policy_observations o
        JOIN evidence.observation_receipts r ON r.id=o.receipt_id
        JOIN evidence_pipeline.exposure_snapshots s ON s.collection_attempt_id=r.collection_attempt_id
        GROUP BY s.collection_attempt_id,o.provider_device_id,o.policy_id HAVING count(*)>1
    ) THEN RAISE EXCEPTION 'Duplicate device policy observation'; END IF;
    IF EXISTS (
        SELECT 1 FROM evidence.antivirus_observations o
        JOIN evidence.observation_receipts r ON r.id=o.receipt_id
        JOIN evidence_pipeline.exposure_snapshots s ON s.collection_attempt_id=r.collection_attempt_id
        WHERE o.source_record_id IS NULL OR btrim(o.source_record_id)=''
        OR o.signature_current IS DISTINCT FROM CASE o.signature_status WHEN 'True' THEN true WHEN 'False' THEN false ELSE NULL END
        OR o.engine_current IS DISTINCT FROM CASE o.engine_status WHEN 'True' THEN true WHEN 'False' THEN false ELSE NULL END
        OR o.platform_current IS DISTINCT FROM CASE o.platform_status WHEN 'True' THEN true WHEN 'False' THEN false ELSE NULL END
    ) THEN RAISE EXCEPTION 'Antivirus source identity or freshness semantics differ'; END IF;
    IF EXISTS (
        SELECT 1 FROM evidence.antivirus_observations o
        JOIN evidence.observation_receipts r ON r.id=o.receipt_id
        JOIN evidence_pipeline.exposure_snapshots s ON s.collection_attempt_id=r.collection_attempt_id
        GROUP BY s.collection_attempt_id,o.source_record_id HAVING count(*)>1
    ) THEN RAISE EXCEPTION 'Duplicate antivirus source record'; END IF;
END $_$;


ALTER FUNCTION evidence_pipeline.validate_exposure() OWNER TO tm_mock_owner;

--
-- Name: vmware_tools_result(text, text, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.vmware_tools_result(state text, reason text, entries jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('state',state,'reason',reason,'entries',entries,
 'interpretation','publisher_product_version_statement_not_full_applicability');
$$;


ALTER FUNCTION evidence_pipeline.vmware_tools_result(state text, reason text, entries jsonb) OWNER TO tm_mock_owner;

--
-- Name: vmware_tools_status(jsonb, text, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.vmware_tools_status(affected jsonb, provider text, facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE candidate bigint[]; rec record; version_rec record; entry jsonb;
 versions jsonb; default_state text; matched boolean; matches jsonb; evaluations jsonb := '[]';
 version_state text; entry_state text; combined_state text; conflict boolean := false; version_conflict boolean;
BEGIN
 candidate := evidence_pipeline.vmware_tools_version(facts->>'version');
 IF provider IS DISTINCT FROM 'vmware' OR facts->>'publisher' IS DISTINCT FROM 'vmware'
 OR facts->>'product' IS DISTINCT FROM 'tools' OR candidate IS NULL THEN
  RETURN evidence_pipeline.vmware_tools_result('unknown','unsupported_or_missing_pinned_tools_identity');
 END IF;
 IF jsonb_typeof(affected) IS DISTINCT FROM 'array' THEN
  RETURN evidence_pipeline.vmware_tools_result('unknown','missing_affected_entries');
 END IF;
 IF jsonb_array_length(affected)=0 THEN
  RETURN evidence_pipeline.vmware_tools_result('unknown','missing_affected_entries');
 END IF;
 FOR rec IN SELECT value,ordinality FROM jsonb_array_elements(affected) WITH ORDINALITY LOOP
  entry := rec.value;
  IF jsonb_typeof(entry) IS DISTINCT FROM 'object' THEN
   RETURN evidence_pipeline.vmware_tools_result('unknown','invalid_affected_entry');
  END IF;
  IF entry->>'vendor' IS DISTINCT FROM 'VMware' OR entry->>'product' IS NULL
  OR entry->>'product' NOT IN ('Tools','VMware tools','VMware Tools') THEN CONTINUE; END IF;
  IF entry-ARRAY['vendor','product','versions','defaultStatus','platforms']<>'{}'::jsonb THEN
   RETURN evidence_pipeline.vmware_tools_result('unknown','unsupported_product_selectors');
  END IF;
  IF entry ? 'platforms' AND (entry->'platforms' IS DISTINCT FROM '["Windows"]'::jsonb
  OR facts->>'operating_system' IS NULL OR facts->>'operating_system' NOT IN
  ('Windows10','Windows11','WindowsServer2012','WindowsServer2012R2','WindowsServer2016','WindowsServer2019','WindowsServer2022','WindowsServer2025')) THEN
   RETURN evidence_pipeline.vmware_tools_result('unknown','missing_or_unsupported_platform_evidence');
  END IF;
  default_state := CASE WHEN entry ? 'defaultStatus' THEN entry->>'defaultStatus' ELSE 'unknown' END;
  versions := entry->'versions';
  IF default_state IS NULL OR default_state NOT IN ('affected','unaffected','unknown')
  OR jsonb_typeof(versions) IS DISTINCT FROM 'array' THEN
   RETURN evidence_pipeline.vmware_tools_result('unknown','missing_version_status');
  END IF;
  IF jsonb_array_length(versions)=0 THEN
   RETURN evidence_pipeline.vmware_tools_result('unknown','missing_version_status');
  END IF;
  matches := '[]'; entry_state := NULL; version_conflict := false;
  FOR version_rec IN SELECT value,ordinality FROM jsonb_array_elements(versions) WITH ORDINALITY LOOP
   matched := evidence_pipeline.vmware_tools_version_match(version_rec.value,candidate);
   IF matched IS NULL THEN
    RETURN evidence_pipeline.vmware_tools_result('unknown','unsupported_or_conflicting_version_rules');
   END IF;
   IF matched THEN
    version_state := version_rec.value->>'status';
    IF entry_state IS NOT NULL AND entry_state<>version_state THEN
     version_conflict := true;
    END IF;
    entry_state := version_state;
    matches := matches || jsonb_build_array(jsonb_build_object('index',version_rec.ordinality-1,'status',version_state));
   END IF;
  END LOOP;
  IF version_conflict THEN RETURN evidence_pipeline.vmware_tools_result('unknown','conflicting_version_statuses'); END IF;
  entry_state := COALESCE(entry_state,default_state);
  evaluations := evaluations || jsonb_build_array(jsonb_build_object('index',rec.ordinality-1,'state',entry_state,'matches',matches));
  IF combined_state IS NOT NULL AND combined_state<>entry_state THEN conflict := true; END IF;
  combined_state := entry_state;
 END LOOP;
 IF combined_state IS NULL THEN RETURN evidence_pipeline.vmware_tools_result('unknown','no_supported_tools_entry'); END IF;
 IF conflict THEN RETURN evidence_pipeline.vmware_tools_result('unknown','conflicting_product_entries',evaluations); END IF;
 RETURN evidence_pipeline.vmware_tools_result(combined_state,'explicit_tools_product_version_statement',evaluations);
END $$;


ALTER FUNCTION evidence_pipeline.vmware_tools_status(affected jsonb, provider text, facts jsonb) OWNER TO tm_mock_owner;

--
-- Name: vmware_tools_version(text); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.vmware_tools_version(value text) RETURNS bigint[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE parts bigint[];
BEGIN
 IF value IS NULL OR value !~ '^(0|[1-9][0-9]{0,8})([.](0|[1-9][0-9]{0,8})){2,3}$' THEN RETURN NULL; END IF;
 parts := string_to_array(value,'.')::bigint[];
 IF cardinality(parts)=3 THEN parts := parts || 0::bigint; END IF;
 RETURN parts;
END $_$;


ALTER FUNCTION evidence_pipeline.vmware_tools_version(value text) OWNER TO tm_mock_owner;

--
-- Name: vmware_tools_version_match(jsonb, bigint[]); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.vmware_tools_version_match(item jsonb, candidate bigint[]) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE raw text; parts text[]; prefix bigint[] := ARRAY[]::bigint[];
 start_key bigint[]; end_key bigint[]; part text; wildcard boolean := false;
 exclusive boolean; bounded boolean;
BEGIN
 IF candidate IS NULL OR cardinality(candidate)<>4 OR candidate[1] IS NULL OR candidate[2] IS NULL OR candidate[3] IS NULL OR candidate[4] IS NULL THEN RETURN NULL; END IF;
 IF jsonb_typeof(item) IS DISTINCT FROM 'object' THEN RETURN NULL; END IF;
 IF item-ARRAY['version','status','versionType','lessThan','lessThanOrEqual']<>'{}'::jsonb
 OR item->>'status' IS NULL OR item->>'status' NOT IN ('affected','unaffected','unknown')
 OR (item ? 'versionType' AND (item->>'versionType' IS NULL OR item->>'versionType' NOT IN ('custom','commercial'))) THEN RETURN NULL; END IF;
 raw := item->>'version'; start_key := evidence_pipeline.vmware_tools_version(raw);
 IF start_key IS NULL THEN
  IF raw IS NULL THEN RETURN NULL; END IF;
  parts := string_to_array(raw,'.');
  IF cardinality(parts) NOT IN (3,4) THEN RETURN NULL; END IF;
  FOREACH part IN ARRAY parts LOOP
   IF part='x' THEN wildcard := true;
   ELSIF wildcard OR part !~ '^(0|[1-9][0-9]{0,8})$' THEN RETURN NULL;
   ELSE prefix := prefix || part::bigint;
   END IF;
  END LOOP;
  IF NOT wildcard OR cardinality(prefix)=0 THEN RETURN NULL; END IF;
  start_key := prefix;
  WHILE cardinality(start_key)<4 LOOP start_key := start_key || 0::bigint; END LOOP;
 END IF;
 IF item ? 'lessThan' AND item ? 'lessThanOrEqual' THEN RETURN NULL; END IF;
 bounded := item ? 'lessThan' OR item ? 'lessThanOrEqual';
 exclusive := item ? 'lessThan';
 IF NOT bounded THEN
  IF wildcard THEN RETURN candidate[1:cardinality(prefix)]=prefix; END IF;
  RETURN candidate=start_key;
 END IF;
 end_key := evidence_pipeline.vmware_tools_version(CASE WHEN exclusive THEN item->>'lessThan' ELSE item->>'lessThanOrEqual' END);
 IF end_key IS NULL OR end_key<start_key OR (end_key=start_key AND exclusive) THEN RETURN NULL; END IF;
 RETURN candidate>=start_key AND (NOT wildcard OR candidate[1:cardinality(prefix)]=prefix)
 AND (candidate<end_key OR (NOT exclusive AND candidate=end_key));
END $_$;


ALTER FUNCTION evidence_pipeline.vmware_tools_version_match(item jsonb, candidate bigint[]) OWNER TO tm_mock_owner;

--
-- Name: wasoc_snapshot_matches(text, text, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.wasoc_snapshot_matches(source_origin text, commit_id text, members jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_typeof(members)='array'
 AND (SELECT count(*)=count(DISTINCT member->>'path') FROM jsonb_array_elements(members) member)
 AND NOT EXISTS (
  SELECT 1 FROM jsonb_array_elements(members) member
  LEFT JOIN evidence.observation_receipts r ON r.id=(member->>'receipt_id')::uuid
  LEFT JOIN evidence.collection_attempts a ON a.id=r.collection_attempt_id
  LEFT JOIN evidence.source_connections c ON c.id=a.connection_id
  LEFT JOIN evidence.source_revisions rev ON rev.id=r.source_revision_id
  LEFT JOIN evidence.public_reference_observations o ON o.receipt_id=r.id
  WHERE NOT coalesce(
   jsonb_typeof(member)='object' AND member ? 'path' AND member ? 'receipt_id'
   AND (member-'path'-'receipt_id')='{}'::jsonb
   AND c.source_name='WA SOC' AND c.input_kind='advisories' AND c.tenant_id IS NULL
   AND rev.connection_id=c.id AND c.scope_reference=rev.source_url
   AND a.complete AND a.outcome='success' AND rev.origin=source_origin
   AND evidence_pipeline.wasoc_source_allowed(o.native_id,rev.source_url)
   AND rev.source_url=evidence_pipeline.wasoc_source_url(commit_id,member->>'path'),false)
 );
$$;


ALTER FUNCTION evidence_pipeline.wasoc_snapshot_matches(source_origin text, commit_id text, members jsonb) OWNER TO tm_mock_owner;

--
-- Name: wasoc_source_allowed(text, text); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.wasoc_source_allowed(native_id text, url text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE prefix text := 'https://raw.githubusercontent.com/wagov/wasocshared/';
 relative text; commit_id text; encoded text; path text; wire bytea := ''::bytea;
 index integer := 1; token text;
BEGIN
 IF left(url,length(prefix))<>prefix THEN RETURN false; END IF;
 relative := substr(url,length(prefix)+1); commit_id := split_part(relative,'/',1);
 encoded := substr(relative,42);
 WHILE index<=length(encoded) LOOP
  token := substr(encoded,index,1);
  IF token='%' THEN
   token := substr(encoded,index+1,2);
   IF token !~ '^[0-9A-F]{2}$' THEN RETURN false; END IF;
   wire := wire || decode(token,'hex'); index := index+3;
  ELSE
   wire := wire || convert_to(token,'UTF8'); index := index+1;
  END IF;
 END LOOP;
 BEGIN path := convert_from(wire,'UTF8'); EXCEPTION WHEN character_not_in_repertoire THEN RETURN false; END;
 RETURN coalesce(evidence_pipeline.wasoc_source_url(commit_id,path)=url
  AND substring(path FROM '^docs/advisories/([0-9]{9,14})-')=native_id,false);
END $_$;


ALTER FUNCTION evidence_pipeline.wasoc_source_allowed(native_id text, url text) OWNER TO tm_mock_owner;

--
-- Name: wasoc_source_url(text, text); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.wasoc_source_url(commit_id text, path text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE wire bytea; encoded text := ''; value integer; index integer;
BEGIN
 IF commit_id !~ '^[a-f0-9]{40}$' OR commit_id=repeat('0',40)
 OR path !~ '^docs/advisories/[0-9]{9,14}-[^/\\[:cntrl:]?#%]{1,240}[.]md$'
 THEN RETURN NULL; END IF;
 wire := convert_to(path,'UTF8');
 FOR index IN 0..length(wire)-1 LOOP
  value := get_byte(wire,index);
  IF (value BETWEEN 65 AND 90) OR (value BETWEEN 97 AND 122)
   OR (value BETWEEN 48 AND 57) OR value IN (45,46,47,95,126)
  THEN encoded := encoded || chr(value);
  ELSE encoded := encoded || '%' || upper(lpad(to_hex(value),2,'0')); END IF;
 END LOOP;
 RETURN 'https://raw.githubusercontent.com/wagov/wasocshared/'||commit_id||'/'||encoded;
END $_$;


ALTER FUNCTION evidence_pipeline.wasoc_source_url(commit_id text, path text) OWNER TO tm_mock_owner;

