--
-- Name: windows_app_inventory_products(jsonb, text, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.windows_app_inventory_products(source_fields jsonb, provider text, facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE target text; candidate bigint[]; entry jsonb; rule jsonb; rec record; vr record; profile text;
 result jsonb; evaluated jsonb := '[]'; matches jsonb; default_state text;
 matched boolean; state text; combined text; reason text; conflict boolean;
BEGIN
 <<evaluate>> BEGIN
 IF NOT evidence_pipeline.inventory_source_supported(facts,CASE WHEN facts->>'product'='MSTeams' THEN 'windows_package' ELSE 'desktop_application' END) THEN reason := 'unsupported_inventory_product_identity'; EXIT evaluate; END IF;
 IF facts->>'product'='Microsoft OneDrive' AND facts->>'publisher'='Microsoft Corporation' THEN
 target := 'OneDrive for Windows'; profile := CASE WHEN facts->>'source'='Windows inventory' THEN 'native-windows-onedrive-v1' ELSE 'intune-windows-onedrive-v1' END;
 ELSIF facts->>'product'='MSTeams' AND facts->>'publisher'='CN=Microsoft Corporation, O=Microsoft Corporation, L=Redmond, S=Washington, C=US' THEN
 target := 'Microsoft Teams for Desktop'; profile := CASE WHEN facts->>'source'='Windows inventory' THEN 'native-windows-msteams-v1' ELSE 'intune-windows-msteams-v1' END;
 ELSE reason := 'unsupported_inventory_product_identity'; EXIT evaluate; END IF;
 IF facts->>'platform' IS DISTINCT FROM 'windows' OR facts->>'operating_system' IS NULL OR facts->>'operating_system' NOT IN
 ('Windows','Windows10','Windows11','WindowsServer2012','WindowsServer2012R2','WindowsServer2016','WindowsServer2019','WindowsServer2022','WindowsServer2025') THEN
 reason := 'missing_or_conflicting_inventory_platform'; EXIT evaluate; END IF;
 candidate := evidence_pipeline.windows_app_version_key(facts->>'version');
 IF candidate IS NULL OR cardinality(candidate)<>4 THEN reason := 'unsupported_or_missing_application_version'; EXIT evaluate; END IF;
 IF provider IS DISTINCT FROM 'microsoft' OR jsonb_typeof(source_fields) IS DISTINCT FROM 'object' THEN
 reason := 'missing_published_microsoft_cna_evidence'; EXIT evaluate; END IF;
 IF source_fields ? 'configurations' THEN reason := 'additional_cna_configuration_requires_evaluation'; EXIT evaluate; END IF;
 IF jsonb_typeof(source_fields->'affected') IS DISTINCT FROM 'array' THEN reason := 'missing_affected_entries'; EXIT evaluate; END IF;
 IF jsonb_array_length(source_fields->'affected')=0 THEN reason := 'missing_affected_entries'; EXIT evaluate; END IF;
 FOR rec IN SELECT value,ordinality FROM jsonb_array_elements(source_fields->'affected') WITH ORDINALITY LOOP
 entry := rec.value;
 IF jsonb_typeof(entry) IS DISTINCT FROM 'object' THEN reason := 'invalid_affected_entry'; EXIT evaluate; END IF;
 IF entry->>'vendor' IS DISTINCT FROM 'Microsoft' OR entry->>'product' IS DISTINCT FROM target THEN CONTINUE; END IF;
 IF entry-ARRAY['vendor','product','versions','defaultStatus','platforms']<>'{}'::jsonb THEN reason := 'unsupported_product_selectors'; EXIT evaluate; END IF;
 IF entry ? 'platforms' AND entry->'platforms' IS DISTINCT FROM '["Windows"]'::jsonb THEN reason := 'missing_or_unsupported_platform_evidence'; EXIT evaluate; END IF;
 default_state := CASE WHEN entry ? 'defaultStatus' THEN entry->>'defaultStatus' ELSE 'unknown' END;
 IF default_state IS NULL OR default_state NOT IN ('affected','unaffected','unknown') OR jsonb_typeof(entry->'versions') IS DISTINCT FROM 'array' THEN reason := 'missing_version_status'; EXIT evaluate; END IF;
 IF jsonb_array_length(entry->'versions')=0 THEN reason := 'missing_version_status'; EXIT evaluate; END IF;
 matches := '[]'; state := NULL; conflict := false;
 FOR vr IN SELECT value,ordinality FROM jsonb_array_elements(entry->'versions') WITH ORDINALITY LOOP
 rule := vr.value;
 IF jsonb_typeof(rule) IS DISTINCT FROM 'object' THEN reason := 'unsupported_or_conflicting_version_rules'; EXIT evaluate; END IF;
 IF evidence_pipeline.windows_app_version_key(rule->>'version') IS NULL
 OR (rule ? 'versionType' AND rule->>'versionType' IS DISTINCT FROM 'custom')
 OR (rule ? 'lessThan' AND evidence_pipeline.windows_app_version_key(rule->>'lessThan') IS NULL)
 OR (rule ? 'lessThanOrEqual' AND evidence_pipeline.windows_app_version_key(rule->>'lessThanOrEqual') IS NULL) THEN
 reason := 'unsupported_or_conflicting_version_rules'; EXIT evaluate; END IF;
 matched := evidence_pipeline.windows_app_version_match(rule,candidate);
 IF matched IS NULL THEN reason := 'unsupported_or_conflicting_version_rules'; EXIT evaluate; END IF;
 IF matched THEN
 IF state IS NOT NULL AND state<>rule->>'status' THEN conflict := true; END IF;
 state := rule->>'status'; matches := matches || jsonb_build_array(jsonb_build_object('index',vr.ordinality-1,'status',state));
 END IF;
 END LOOP;
 IF conflict THEN reason := 'conflicting_version_statuses'; EXIT evaluate; END IF;
 state := COALESCE(state,default_state);
 evaluated := evaluated || jsonb_build_array(jsonb_build_object('index',rec.ordinality-1,'state',state,'matches',matches));
 END LOOP;
 IF jsonb_array_length(evaluated)=0 THEN reason := 'no_supported_application_entry'; EXIT evaluate; END IF;
 SELECT count(DISTINCT value->>'state')>1,min(value->>'state') INTO conflict,combined FROM jsonb_array_elements(evaluated);
 IF conflict THEN reason := 'conflicting_product_entries'; combined := NULL; ELSE reason := 'explicit_application_product_version_statement'; END IF;
 END evaluate;
 IF reason NOT IN ('conflicting_product_entries','explicit_application_product_version_statement') THEN evaluated := '[]'; END IF;
 RETURN evidence_pipeline.vmware_tools_result(COALESCE(combined,'unknown'),reason,evaluated)
 || jsonb_build_object('inventory',facts,'mapping_profile',profile);
END $$;


ALTER FUNCTION evidence_pipeline.windows_app_inventory_products(source_fields jsonb, provider text, facts jsonb) OWNER TO tm_mock_owner;

--
-- Name: windows_app_inventory_status(jsonb, text, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.windows_app_inventory_status(source_fields jsonb, provider text, facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE product jsonb; cpe jsonb; state text := 'unknown'; reason text := 'incomplete_product_or_cpe_evidence';
BEGIN
 product := evidence_pipeline.windows_app_inventory_products(source_fields,provider,facts);
 IF jsonb_typeof(source_fields) IS DISTINCT FROM 'object' OR NOT source_fields ? 'cpeApplicability' OR source_fields ? 'configurations' OR product->>'mapping_profile' IS NULL THEN RETURN product; END IF;
 cpe := evidence_pipeline.windows_app_cpe_status(source_fields->'cpeApplicability',facts);
 IF product->>'state' IN ('affected','unaffected') AND cpe->>'state'<>'unknown' THEN
 IF (product->>'state'='affected')=(cpe->>'state'='matched') THEN state := product->>'state'; reason := 'consistent_product_and_cpe_evidence'; ELSE reason := 'conflicting_product_and_cpe_evidence'; END IF;
 END IF;
 RETURN product || jsonb_build_object('state',state,'reason',reason,'product',product,'cpe',cpe);
END $$;


ALTER FUNCTION evidence_pipeline.windows_app_inventory_status(source_fields jsonb, provider text, facts jsonb) OWNER TO tm_mock_owner;

--
-- Name: windows_app_version_compare(bigint[], bigint[]); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.windows_app_version_compare(a bigint[], b bigint[]) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN a[1:least(cardinality(a),cardinality(b))]<b[1:least(cardinality(a),cardinality(b))] THEN -1
 WHEN a[1:least(cardinality(a),cardinality(b))]>b[1:least(cardinality(a),cardinality(b))] THEN 1
 WHEN cardinality(a)=cardinality(b) THEN 0 END;
$$;


ALTER FUNCTION evidence_pipeline.windows_app_version_compare(a bigint[], b bigint[]) OWNER TO tm_mock_owner;

--
-- Name: windows_app_version_key(text); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.windows_app_version_key(value text) RETURNS bigint[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT CASE WHEN value ~ '^[0-9]{1,8}(\.[0-9]{1,8}){1,3}$' THEN string_to_array(value,'.')::bigint[] END;
$_$;


ALTER FUNCTION evidence_pipeline.windows_app_version_key(value text) OWNER TO tm_mock_owner;

--
-- Name: windows_app_version_match(jsonb, bigint[]); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.windows_app_version_match(rule jsonb, candidate bigint[]) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE lower_key bigint[]; upper_key bigint[]; low_cmp integer; high_cmp integer; ordering integer; bound text;
BEGIN
 IF jsonb_typeof(rule) IS DISTINCT FROM 'object' THEN RETURN NULL; END IF;
 IF rule-ARRAY['version','status','versionType','lessThan','lessThanOrEqual']<>'{}'::jsonb
 OR rule->>'status' IS NULL OR rule->>'status' NOT IN ('affected','unaffected','unknown')
 OR (rule ? 'versionType' AND rule->>'versionType' IS DISTINCT FROM 'custom')
 OR jsonb_typeof(rule->'version') IS DISTINCT FROM 'string' THEN RETURN NULL; END IF;
 lower_key := evidence_pipeline.windows_app_version_key(rule->>'version');
 IF lower_key IS NULL OR (rule ? 'lessThan' AND rule ? 'lessThanOrEqual') THEN RETURN NULL; END IF;
 low_cmp := evidence_pipeline.windows_app_version_compare(candidate,lower_key);
 IF NOT rule ? 'lessThan' AND NOT rule ? 'lessThanOrEqual' THEN RETURN low_cmp=0; END IF;
 bound := CASE WHEN rule ? 'lessThan' THEN 'lessThan' ELSE 'lessThanOrEqual' END;
 IF jsonb_typeof(rule->bound) IS DISTINCT FROM 'string' THEN RETURN NULL; END IF;
 upper_key := evidence_pipeline.windows_app_version_key(rule->>bound);
 IF upper_key IS NULL THEN RETURN NULL; END IF;
 ordering := evidence_pipeline.windows_app_version_compare(lower_key,upper_key);
 IF ordering IS NULL OR ordering>0 OR (ordering=0 AND bound='lessThan') THEN RETURN NULL; END IF;
 high_cmp := evidence_pipeline.windows_app_version_compare(candidate,upper_key);
 IF low_cmp IS NULL OR high_cmp IS NULL THEN RETURN NULL; END IF;
 RETURN low_cmp>=0 AND CASE WHEN bound='lessThan' THEN high_cmp<0 ELSE high_cmp<=0 END;
END $$;


ALTER FUNCTION evidence_pipeline.windows_app_version_match(rule jsonb, candidate bigint[]) OWNER TO tm_mock_owner;

--
-- Name: windows_build_key(text); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.windows_build_key(value text) RETURNS bigint[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
 IF value IS NULL OR value !~ '^(0|[1-9][0-9]{0,8})([.](0|[1-9][0-9]{0,8})){3}$' THEN RETURN NULL; END IF;
 RETURN string_to_array(value,'.')::bigint[];
END $_$;


ALTER FUNCTION evidence_pipeline.windows_build_key(value text) OWNER TO tm_mock_owner;

--
-- Name: windows_cna_record_status(jsonb, text, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.windows_cna_record_status(source_fields jsonb, provider text, facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE product jsonb; cpe jsonb; state text := 'unknown'; reason text := 'incomplete_product_or_cpe_evidence';
BEGIN
 IF jsonb_typeof(source_fields) IS DISTINCT FROM 'object' THEN RETURN jsonb_build_object('state','unknown','reason','invalid_cna_record','entries','[]'::jsonb); END IF;
 product := evidence_pipeline.windows_cna_status(source_fields->'affected',provider,facts);
 IF source_fields ? 'configurations' THEN RETURN jsonb_build_object('state','unknown','reason','textual_configuration_requires_evidence','product',product); END IF;
 IF NOT source_fields ? 'cpeApplicability' THEN RETURN product; END IF;
 cpe := evidence_pipeline.windows_cpe_status(source_fields->'cpeApplicability',facts);
 IF product->>'state' IN ('affected','unaffected') AND cpe->>'state'<>'unknown' THEN
  IF (product->>'state'='affected')=(cpe->>'state'='matched') THEN state := product->>'state'; reason := 'consistent_product_and_cpe_evidence';
  ELSE reason := 'conflicting_product_and_cpe_evidence'; END IF;
 END IF;
 RETURN jsonb_build_object('state',state,'reason',reason,'product',product,'cpe',cpe);
END $$;


ALTER FUNCTION evidence_pipeline.windows_cna_record_status(source_fields jsonb, provider text, facts jsonb) OWNER TO tm_mock_owner;

--
-- Name: windows_cna_status(jsonb, text, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.windows_cna_status(affected jsonb, provider text, facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE build bigint[]; architecture text; expected_product text; expected_platform text;
 rec record; entry jsonb; evaluation jsonb; evaluations jsonb := '[]'; status text; matched_state text;
BEGIN
 IF provider IS NULL OR lower(provider)<>'microsoft' THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_publisher','entries','[]'::jsonb); END IF;
 IF jsonb_typeof(affected) IS DISTINCT FROM 'array' OR jsonb_typeof(facts) IS DISTINCT FROM 'object' THEN RETURN jsonb_build_object('state','unknown','reason','invalid_product_evidence','entries','[]'::jsonb); END IF;
 IF facts-ARRAY['product','publisher','version','operating_system','release','os_build','os_architecture','os_processor']<>'{}'::jsonb OR NOT facts ?& ARRAY['product','publisher','version','operating_system','release','os_build','os_architecture','os_processor'] THEN RETURN jsonb_build_object('state','unknown','reason','incomplete_pinned_facts','entries','[]'::jsonb); END IF;
 build := evidence_pipeline.windows_build_key(facts->>'version');
 IF facts->>'publisher' IS DISTINCT FROM 'microsoft' OR facts->>'product' IS NULL OR facts->>'product' NOT IN ('windows_10','windows_11')
 OR facts->>'operating_system' IS DISTINCT FROM (CASE facts->>'product' WHEN 'windows_10' THEN 'Windows10' WHEN 'windows_11' THEN 'Windows11' END)
 OR facts->>'release' IS NULL OR facts->>'release' !~ '^[0-9]{2}H[12]$' OR build IS NULL OR build[1:2]<>ARRAY[10,0]::bigint[]
 OR facts->>'os_build' IS DISTINCT FROM build[3]::text THEN RETURN jsonb_build_object('state','unknown','reason','missing_or_conflicting_pinned_windows_identity','entries','[]'::jsonb); END IF;
 architecture := CASE WHEN facts->>'os_architecture'='64-bit' AND facts->>'os_processor'='x64' THEN 'x64'
 WHEN facts->>'os_architecture'='64-bit' AND facts->>'os_processor' IN ('ARM64','arm64') THEN 'arm64'
 WHEN facts->>'os_architecture'='32-bit' AND facts->>'os_processor'='x86' THEN 'x86' END;
 IF architecture IS NULL THEN RETURN jsonb_build_object('state','unknown','reason','missing_or_conflicting_pinned_architecture','entries','[]'::jsonb); END IF;
 expected_product := CASE facts->>'product' WHEN 'windows_10' THEN 'Windows 10 Version ' ELSE 'Windows 11 Version ' END || (facts->>'release');
 expected_platform := CASE architecture WHEN 'x64' THEN 'x64-based Systems' WHEN 'arm64' THEN 'ARM64-based Systems' ELSE '32-bit Systems' END;
 FOR rec IN SELECT value,ordinality FROM jsonb_array_elements(affected) WITH ORDINALITY LOOP
  entry := rec.value;
  IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR jsonb_typeof(entry->'vendor') IS DISTINCT FROM 'string' OR jsonb_typeof(entry->'product') IS DISTINCT FROM 'string' THEN RETURN jsonb_build_object('state','unknown','reason','invalid_product_identity','entries',evaluations); END IF;
  IF entry->>'vendor'<>'Microsoft' OR lower(entry->>'product')<>lower(expected_product) THEN CONTINUE; END IF;
  IF entry-ARRAY['vendor','product','platforms','versions','defaultStatus']<>'{}'::jsonb THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_product_constraints','entries',evaluations); END IF;
  IF jsonb_typeof(entry->'platforms') IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('state','unknown','reason','missing_or_unsupported_platforms','entries',evaluations); END IF;
  IF jsonb_array_length(entry->'platforms')=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(entry->'platforms') p WHERE jsonb_typeof(p.value)<>'string' OR p.value#>>'{}' NOT IN ('x64-based Systems','ARM64-based Systems','32-bit Systems')) THEN RETURN jsonb_build_object('state','unknown','reason','missing_or_unsupported_platforms','entries',evaluations); END IF;
  IF NOT (entry->'platforms') ? expected_platform THEN CONTINUE; END IF;
  evaluation := evidence_pipeline.windows_cna_versions(entry,build);
  IF NOT evaluation ? 'version_indexes' THEN RETURN evaluation || jsonb_build_object('entries',evaluations); END IF;
  status := evaluation->>'state';
  evaluations := evaluations || jsonb_build_array(evaluation || jsonb_build_object('product_index',rec.ordinality-1));
  IF matched_state IS NOT NULL AND matched_state<>status THEN RETURN jsonb_build_object('state','unknown','reason','conflicting_product_statuses','entries',evaluations); END IF;
  matched_state := status;
 END LOOP;
 IF matched_state IS NULL THEN RETURN jsonb_build_object('state','unknown','reason','no_supported_product_platform_entry','entries',evaluations); END IF;
 RETURN jsonb_build_object('state',matched_state,'reason','evaluated_microsoft_windows_cna','entries',evaluations);
END $_$;


ALTER FUNCTION evidence_pipeline.windows_cna_status(affected jsonb, provider text, facts jsonb) OWNER TO tm_mock_owner;

--
-- Name: windows_cna_versions(jsonb, bigint[]); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.windows_cna_versions(entry jsonb, candidate bigint[]) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE versions jsonb; item jsonb; change jsonb; rec record; change_rec record;
 start_key bigint[]; end_key bigint[]; change_key bigint[]; last_key bigint[];
 state text; previous_state text; matched_state text; default_state text;
 exclusive boolean; bounded boolean; inside boolean; indexes jsonb := '[]'; changes jsonb;
BEGIN
 IF entry ? 'defaultStatus' AND jsonb_typeof(entry->'defaultStatus') IS DISTINCT FROM 'string' THEN RETURN jsonb_build_object('state','unknown','reason','invalid_default_status'); END IF;
 default_state := COALESCE(entry->>'defaultStatus','unknown');
 IF default_state NOT IN ('affected','unaffected','unknown') THEN RETURN jsonb_build_object('state','unknown','reason','invalid_default_status'); END IF;
 versions := COALESCE(entry->'versions','[]');
 IF jsonb_typeof(versions) IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('state','unknown','reason','missing_version_status'); END IF;
 IF jsonb_array_length(versions)=0 AND (entry ? 'versions' OR NOT entry ? 'defaultStatus') THEN RETURN jsonb_build_object('state','unknown','reason','missing_version_status'); END IF;
 FOR rec IN SELECT value,ordinality FROM jsonb_array_elements(versions) WITH ORDINALITY LOOP
  item := rec.value;
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item-ARRAY['version','status','versionType','lessThan','lessThanOrEqual','changes'] <> '{}'::jsonb THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_version_fields'); END IF;
  state := item->>'status'; start_key := evidence_pipeline.windows_build_key(item->>'version');
  IF state IS NULL OR state NOT IN ('affected','unaffected','unknown') OR start_key IS NULL OR (item ? 'versionType' AND item->>'versionType' IS DISTINCT FROM 'custom') THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_windows_version_or_status'); END IF;
  IF item ? 'lessThan' AND item ? 'lessThanOrEqual' THEN RETURN jsonb_build_object('state','unknown','reason','conflicting_version_bounds'); END IF;
  bounded := item ? 'lessThan' OR item ? 'lessThanOrEqual';
  exclusive := item ? 'lessThan';
  IF NOT bounded THEN
   IF item ? 'changes' THEN RETURN jsonb_build_object('state','unknown','reason','changes_require_range'); END IF;
   inside := candidate=start_key;
  ELSE
   IF item->>'versionType' IS DISTINCT FROM 'custom' THEN RETURN jsonb_build_object('state','unknown','reason','range_requires_windows_version_type'); END IF;
   end_key := evidence_pipeline.windows_build_key(COALESCE(item->>'lessThan',item->>'lessThanOrEqual'));
   IF (end_key IS NULL AND COALESCE(item->>'lessThan',item->>'lessThanOrEqual') IS DISTINCT FROM '*') OR end_key<start_key OR (end_key=start_key AND exclusive) THEN RETURN jsonb_build_object('state','unknown','reason','invalid_version_range'); END IF;
   changes := COALESCE(item->'changes','[]');
   IF jsonb_typeof(changes) IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('state','unknown','reason','invalid_status_changes'); END IF;
   -- Validate every change before sorting; malformed entries cannot disappear.
   FOR change IN SELECT value FROM jsonb_array_elements(changes) LOOP
    IF jsonb_typeof(change) IS DISTINCT FROM 'object' OR change-ARRAY['at','status']<>'{}'::jsonb OR NOT change ? 'at' OR NOT change ? 'status' THEN RETURN jsonb_build_object('state','unknown','reason','invalid_status_change'); END IF;
    change_key := evidence_pipeline.windows_build_key(change->>'at');
    IF change_key IS NULL OR change->>'status' IS NULL OR change->>'status' NOT IN ('affected','unaffected','unknown') OR change_key<start_key OR change_key>end_key OR (exclusive AND change_key=end_key) THEN RETURN jsonb_build_object('state','unknown','reason','status_change_outside_range'); END IF;
   END LOOP;
   last_key := NULL; previous_state := NULL;
   FOR change_rec IN SELECT evidence_pipeline.windows_build_key(value->>'at') AS key,value->>'status' AS status FROM jsonb_array_elements(changes) ORDER BY 1 LOOP
    IF change_rec.key=last_key AND change_rec.status<>previous_state THEN RETURN jsonb_build_object('state','unknown','reason','conflicting_status_changes'); END IF;
    last_key := change_rec.key; previous_state := change_rec.status;
    IF change_rec.key<=candidate THEN state := change_rec.status; END IF;
   END LOOP;
   inside := candidate>=start_key AND (end_key IS NULL OR candidate<end_key OR (NOT exclusive AND candidate=end_key));
  END IF;
  IF inside THEN
   IF matched_state IS NOT NULL AND matched_state<>state THEN RETURN jsonb_build_object('state','unknown','reason','conflicting_matching_version_statuses'); END IF;
   matched_state := state; indexes := indexes || jsonb_build_array(rec.ordinality-1);
  END IF;
 END LOOP;
 IF matched_state IS NOT NULL THEN RETURN jsonb_build_object('state',matched_state,'reason','explicit_version_status','version_indexes',indexes); END IF;
 RETURN jsonb_build_object('state',default_state,'reason',CASE WHEN entry ? 'defaultStatus' THEN 'publisher_default_status' ELSE 'outside_ranges_default_unknown' END,'version_indexes','[]'::jsonb);
END $$;


ALTER FUNCTION evidence_pipeline.windows_cna_versions(entry jsonb, candidate bigint[]) OWNER TO tm_mock_owner;

--
-- Name: windows_cpe_combine(jsonb, text, boolean); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.windows_cpe_combine(children jsonb, op text, negated boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE child jsonb; truth boolean; positive boolean := false; negative boolean := false;
 witness boolean; negative_witness boolean; swap boolean;
BEGIN
 IF jsonb_typeof(children) IS DISTINCT FROM 'array' OR op IS NULL OR op NOT IN ('AND','OR') OR negated IS NULL THEN RETURN evidence_pipeline.windows_cpe_unknown('invalid_combination'); END IF;
 truth := op='AND';
 FOR child IN SELECT value FROM jsonb_array_elements(children) LOOP
  IF op='AND' THEN truth := truth AND (child->>'truth')::boolean;
  ELSE truth := truth OR (child->>'truth')::boolean; END IF;
  positive := positive OR (child->>'witness')::boolean;
  negative := negative OR (child->>'negative_witness')::boolean;
 END LOOP;
 witness := CASE WHEN op='AND' THEN truth AND positive ELSE positive END;
 negative_witness := CASE WHEN op='OR' THEN NOT truth AND negative ELSE negative END;
 IF negated THEN truth := NOT truth; swap := witness; witness := negative_witness; negative_witness := swap; END IF;
 RETURN jsonb_build_object('truth',truth,'witness',witness,'negative_witness',negative_witness,'operator',op,'negate',negated,'children',children);
END $$;


ALTER FUNCTION evidence_pipeline.windows_cpe_combine(children jsonb, op text, negated boolean) OWNER TO tm_mock_owner;

--
-- Name: windows_cpe_criterion(jsonb, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.windows_cpe_criterion(criterion jsonb, facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE identity_check jsonb; parts text[]; part text; architecture text; candidate bigint[];
 lower_key bigint[]; upper_key bigint[]; exact_key bigint[]; bound_key bigint[]; bound_name text;
 lower_exclusive boolean := false; upper_exclusive boolean := false; inside boolean := true;
 has_bounds boolean := false; reason text; state text := 'unknown';
BEGIN
 IF jsonb_typeof(facts) IS DISTINCT FROM 'object' OR facts-ARRAY['product','publisher','version','operating_system','release','os_build','os_architecture','os_processor']<>'{}'::jsonb OR NOT facts ?& ARRAY['product','publisher','version','operating_system','release','os_build','os_architecture','os_processor'] THEN
  RETURN jsonb_build_object('state','unknown','reason','incomplete_pinned_facts');
 END IF;
 identity_check := evidence_pipeline.windows_cna_status('[]','Microsoft',facts);
 IF identity_check->>'reason'<>'no_supported_product_platform_entry' THEN
  RETURN jsonb_build_object('state','unknown','reason',identity_check->>'reason');
 END IF;
 candidate := evidence_pipeline.windows_build_key(facts->>'version');
 architecture := CASE facts->>'os_processor' WHEN 'ARM64' THEN 'arm64' ELSE facts->>'os_processor' END;
 IF jsonb_typeof(criterion) IS DISTINCT FROM 'object' THEN RETURN jsonb_build_object('state','unknown','reason','invalid_criterion'); END IF;
 IF criterion-ARRAY['criteria','vulnerable','matchCriteriaId','versionStartIncluding','versionStartExcluding','versionEndIncluding','versionEndExcluding']<>'{}'::jsonb OR jsonb_typeof(criterion->'vulnerable') IS DISTINCT FROM 'boolean' THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_criterion_fields'); END IF;
 IF jsonb_typeof(criterion->'criteria') IS DISTINCT FROM 'string' OR length(criterion->>'criteria')>4096 THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_cpe_encoding'); END IF;
 parts := string_to_array(criterion->>'criteria',':');
 IF parts[13] IS NULL OR parts[14] IS NOT NULL OR parts[1]<>'cpe' OR parts[2]<>'2.3' THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_cpe_encoding'); END IF;
 FOREACH part IN ARRAY parts[3:13] LOOP
  IF part !~ '^([A-Za-z0-9_.-]+|\*)$' THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_cpe_encoding'); END IF;
 END LOOP;
 IF parts[3]<>'o' OR parts[4]<>'microsoft' THEN RETURN jsonb_build_object('state','unknown','reason','other_product_or_environment_requires_evidence'); END IF;
 IF lower(parts[5])<>lower((facts->>'product')||'_'||(facts->>'release')) THEN
  IF criterion->'vulnerable'='true'::jsonb AND lower(parts[5]) IN ('windows_10_1607','windows_10_1809','windows_10_21h2','windows_10_22h2','windows_11_23h2','windows_11_24h2','windows_11_25h2','windows_11_26h1','windows_server_2012','windows_server_2012_r2','windows_server_2016','windows_server_2019','windows_server_2022','windows_server_2025') THEN RETURN jsonb_build_object('state','excluded','reason','different_explicit_windows_os_target'); END IF;
  RETURN jsonb_build_object('state','unknown','reason','other_windows_product_requires_mapping');
 END IF;
 IF parts[7]<>'*' OR parts[8]<>'*' OR parts[9]<>'*' OR parts[10]<>'*' OR parts[11]<>'*' OR parts[13]<>'*' THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_cpe_environment_selector'); END IF;
 IF parts[12] NOT IN ('*','x64','x86','arm64') THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_cpe_architecture'); END IF;
 IF parts[12]<>'*' AND parts[12]<>architecture THEN RETURN jsonb_build_object('state','excluded','reason','explicit_architecture_mismatch'); END IF;
 FOREACH bound_name IN ARRAY ARRAY['versionStartIncluding','versionStartExcluding','versionEndIncluding','versionEndExcluding'] LOOP
  IF criterion ? bound_name THEN
   has_bounds := true;
   bound_key := evidence_pipeline.windows_build_key(criterion->>bound_name);
   IF bound_key IS NULL THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_version_ordering'); END IF;
   IF bound_name IN ('versionStartIncluding','versionStartExcluding') THEN lower_key := bound_key; lower_exclusive := bound_name='versionStartExcluding';
   ELSE upper_key := bound_key; upper_exclusive := bound_name='versionEndExcluding'; END IF;
  END IF;
 END LOOP;
 IF (criterion ? 'versionStartIncluding' AND criterion ? 'versionStartExcluding') OR (criterion ? 'versionEndIncluding' AND criterion ? 'versionEndExcluding') THEN RETURN jsonb_build_object('state','unknown','reason','conflicting_version_bounds'); END IF;
 IF lower_key>upper_key OR (lower_key=upper_key AND (lower_exclusive OR upper_exclusive)) THEN RETURN jsonb_build_object('state','unknown','reason','empty_or_reversed_version_bounds'); END IF;
 IF parts[6]<>'*' THEN
  exact_key := evidence_pipeline.windows_build_key(parts[6]);
  IF exact_key IS NULL OR has_bounds THEN RETURN jsonb_build_object('state','unknown','reason','unsupported_exact_version_and_range_combination'); END IF;
  inside := candidate=exact_key; reason := 'explicit_exact_windows_build';
 ELSIF NOT has_bounds THEN inside := true; reason := 'explicit_any_version_for_matched_windows_product';
 ELSE
  IF lower_key IS NOT NULL THEN inside := inside AND (candidate>lower_key OR (NOT lower_exclusive AND candidate=lower_key)); END IF;
  IF upper_key IS NOT NULL THEN inside := inside AND (candidate<upper_key OR (NOT upper_exclusive AND candidate=upper_key)); END IF;
  reason := 'explicit_windows_build_bounds';
 END IF;
 state := CASE WHEN inside THEN 'matched' ELSE 'excluded' END;
 RETURN jsonb_build_object('state',state,'reason',reason);
END $_$;


ALTER FUNCTION evidence_pipeline.windows_cpe_criterion(criterion jsonb, facts jsonb) OWNER TO tm_mock_owner;

--
-- Name: windows_cpe_group(jsonb, jsonb, boolean); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.windows_cpe_group(item jsonb, facts jsonb, is_root boolean) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE key text := CASE WHEN is_root THEN 'nodes' ELSE 'cpeMatch' END;
 children jsonb; evaluated jsonb := '[]'; child jsonb; result jsonb; op text; truth boolean;
BEGIN
 IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item-ARRAY[key,'operator','negate']<>'{}'::jsonb THEN RETURN evidence_pipeline.windows_cpe_unknown('unsupported_configuration_fields'); END IF;
 children := item->key;
 IF jsonb_typeof(children) IS DISTINCT FROM 'array' THEN RETURN evidence_pipeline.windows_cpe_unknown('empty_or_invalid_configuration'); END IF;
 IF jsonb_array_length(children)=0 THEN RETURN evidence_pipeline.windows_cpe_unknown('empty_or_invalid_configuration'); END IF;
 op := item->>'operator';
 IF op IS NULL AND is_root AND jsonb_array_length(children)=1 THEN op := 'OR'; END IF;
 IF op IS NULL OR op NOT IN ('AND','OR') OR (item ? 'negate' AND jsonb_typeof(item->'negate') IS DISTINCT FROM 'boolean') THEN RETURN evidence_pipeline.windows_cpe_unknown('unsupported_configuration_operator'); END IF;
 FOR child IN SELECT value FROM jsonb_array_elements(children) LOOP
  IF is_root THEN result := evidence_pipeline.windows_cpe_group(child,facts,false);
  ELSE
   result := evidence_pipeline.windows_cpe_criterion(child,facts);
   truth := CASE result->>'state' WHEN 'matched' THEN true WHEN 'excluded' THEN false ELSE NULL END;
   result := jsonb_build_object('truth',truth,'witness',CASE WHEN child->'vulnerable'='true'::jsonb THEN truth ELSE false END,'negative_witness',false,'reason',result->>'reason');
  END IF;
  evaluated := evaluated || jsonb_build_array(result);
 END LOOP;
 RETURN evidence_pipeline.windows_cpe_combine(evaluated,op,COALESCE((item->>'negate')::boolean,false));
END $$;


ALTER FUNCTION evidence_pipeline.windows_cpe_group(item jsonb, facts jsonb, is_root boolean) OWNER TO tm_mock_owner;

--
-- Name: windows_cpe_status(jsonb, jsonb); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE FUNCTION evidence_pipeline.windows_cpe_status(configurations jsonb, facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE item jsonb; evaluated jsonb := '[]'; result jsonb; state text;
BEGIN
 IF jsonb_typeof(configurations) IS DISTINCT FROM 'array' THEN result := evidence_pipeline.windows_cpe_unknown('empty_or_invalid_configurations');
 ELSIF jsonb_array_length(configurations)=0 THEN result := evidence_pipeline.windows_cpe_unknown('empty_or_invalid_configurations');
 ELSE
  FOR item IN SELECT value FROM jsonb_array_elements(configurations) LOOP
   evaluated := evaluated || jsonb_build_array(evidence_pipeline.windows_cpe_group(item,facts,true));
  END LOOP;
  result := evidence_pipeline.windows_cpe_combine(evaluated,'OR');
 END IF;
 state := CASE WHEN result->'truth'='false'::jsonb THEN 'excluded' WHEN result->'witness'='true'::jsonb THEN 'matched' ELSE 'unknown' END;
 RETURN jsonb_build_object('state',state,'reason','evaluated_windows_cpe_conditions','conditions',result);
END $$;


ALTER FUNCTION evidence_pipeline.windows_cpe_status(configurations jsonb, facts jsonb) OWNER TO tm_mock_owner;

--
-- Name: windows_cpe_unknown(text); Type: FUNCTION; Schema: evidence_pipeline; Owner: tm_mock_owner
