CREATE FUNCTION evidence_pipeline.windows_cpe_unknown(reason text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('truth',NULL,'witness',NULL,'negative_witness',NULL,'reason',reason)
$$;


