--
-- Name: computer_inputs(); Type: FUNCTION; Schema: mock_support; Owner: tm_mock_owner
--

CREATE FUNCTION mock_support.computer_inputs() RETURNS TABLE(case_id uuid, computer_id uuid, definition_id uuid, applicability_state text, source_name text, os_version text, microsoft_registration_id text, defender_last_seen timestamp with time zone, intune_last_sync timestamp with time zone, cells evidence.completeness_cell_input[])
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
WITH bindings(case_id,computer_id,definition_id,applicability_state) AS (VALUES
('b795c0e7-3146-5e5d-91a5-c16a308caf7a'::uuid,'71edc1f5-a14e-53e2-af9b-ba4f5a42012f'::uuid,'a78e1a8f-69c2-5517-92ca-575298133653'::uuid,'resolved'::text),
('50a2f81c-24b7-5678-9f85-cdfbbffe9a03'::uuid,'ba064b7d-43f7-5409-a379-c6b9c796846f'::uuid,'a78e1a8f-69c2-5517-92ca-575298133653'::uuid,'resolved'::text),
('133dc3ee-ae2f-533f-8265-c8e805889ccc'::uuid,'40ee5a0a-02da-5d46-9b14-74e12efbd911'::uuid,'1112cdaf-9e52-543e-bf2f-5275a0bc39e9'::uuid,'resolved'::text),
('475cf98a-3764-5e65-9fb4-58a82464c865'::uuid,'7fa21054-386d-55d0-bd53-bb40369d8887'::uuid,NULL::uuid,'unresolved'::text)), inputs AS (
 SELECT b.*,d.source_name,d.os_version,d.microsoft_registration_id,d.last_seen,i.last_sync,d.receipt_id AS dr,i.receipt_id AS ir,
 (SELECT count(*) FROM evidence.computer_source_status st WHERE st.computer_id=b.computer_id AND st.source_name='Defender') AS dc,
 (SELECT count(*) FROM evidence.computer_source_status st WHERE st.computer_id=b.computer_id AND st.source_name='Intune') AS ic
 FROM bindings b JOIN evidence.computers c ON c.id=b.computer_id
 LEFT JOIN LATERAL (SELECT st.source_name,p.microsoft_registration_id,o.os_version,o.last_seen,o.receipt_id
  FROM evidence.computer_source_status st JOIN evidence.provider_devices p ON p.id=st.provider_device_id
  JOIN evidence.device_observations o ON o.id=st.observation_id
  WHERE st.computer_id=b.computer_id AND st.source_name='Defender'
  AND (SELECT count(*) FROM evidence.computer_source_status x WHERE x.computer_id=b.computer_id AND x.source_name='Defender')=1) d ON true
 LEFT JOIN LATERAL (SELECT o.last_sync,o.receipt_id FROM evidence.computer_source_status st
  JOIN evidence.device_observations o ON o.id=st.observation_id
  WHERE st.computer_id=b.computer_id AND st.source_name='Intune'
  AND (SELECT count(*) FROM evidence.computer_source_status x WHERE x.computer_id=b.computer_id AND x.source_name='Intune')=1) i ON true
)
SELECT x.case_id,x.computer_id,CASE WHEN dc>1 OR ic>1 THEN NULL ELSE x.definition_id END,
 CASE WHEN dc>1 OR ic>1 THEN 'unresolved' ELSE x.applicability_state END,
 x.source_name,x.os_version,x.microsoft_registration_id,x.last_seen,x.last_sync,
 ARRAY(SELECT ROW(f.field_key,'text',NULL::boolean,NULL::numeric,
 CASE f.field_key WHEN 'source_name' THEN x.source_name WHEN 'os_version' THEN x.os_version
 WHEN 'microsoft_registration_id' THEN x.microsoft_registration_id WHEN 'defender_last_seen' THEN x.last_seen::text
 WHEN 'intune_last_sync' THEN x.last_sync::text END,
 CASE WHEN f.field_key='intune_last_sync' THEN x.ir ELSE x.dr END)::evidence.completeness_cell_input
 FROM mock_support.completeness_fields f WHERE f.definition_id=x.definition_id ORDER BY f.field_key)
FROM inputs x;
$$;


ALTER FUNCTION mock_support.computer_inputs() OWNER TO tm_mock_owner;

--
-- Name: selected_receipt(uuid); Type: FUNCTION; Schema: mock_support; Owner: tm_mock_owner
--

CREATE FUNCTION mock_support.selected_receipt(receipt uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM evidence.observation_receipts r
 JOIN evidence.collection_attempts a ON a.id=r.collection_attempt_id
 JOIN mock_support.mock_snapshot_selections s ON s.connection_id=a.connection_id AND s.collection_attempt_id=a.id
 WHERE r.id=receipt AND a.complete AND a.outcome='success')
$$;


