CREATE VIEW evidence.completeness_case_counts AS
 SELECT x.case_id,
    x.computer_id,
    x.definition_id,
    d.revision AS definition_revision,
    x.applicability_state,
    c.completeness,
    c.completeness_total
   FROM ((mock_support.computer_inputs() x(case_id, computer_id, definition_id, applicability_state, source_name, os_version, microsoft_registration_id, defender_last_seen, intune_last_sync, cells)
     LEFT JOIN mock_support.completeness_definitions d ON ((d.id = x.definition_id)))
     CROSS JOIN LATERAL evidence.evaluate_completeness(x.definition_id, x.applicability_state, x.cells) c(completeness, completeness_total, evaluated_cells));


