    connection_id uuid NOT NULL,
    collection_attempt_id uuid NOT NULL
);


ALTER TABLE mock_support.mock_snapshot_selections OWNER TO tm_mock_owner;

--
-- Name: TABLE mock_snapshot_selections; Type: COMMENT; Schema: mock_support; Owner: tm_mock_owner
