COMMENT ON TABLE mock_support.mock_snapshot_selections IS 'Mock-only support; not product policy.';


--
-- Name: computer_source_status; Type: VIEW; Schema: evidence; Owner: tm_mock_owner
--

CREATE VIEW evidence.computer_source_status AS
 SELECT l.computer_id,
    p.id AS provider_device_id,
    p.connection_id,
    c.source_name,
    d.id AS observation_id,
    (d.id IS NOT NULL) AS source_present,
        CASE c.source_name
            WHEN 'Defender'::text THEN 'last_seen'::text
            WHEN 'Intune'::text THEN 'last_sync'::text
            ELSE 'approximate_last_sign_in'::text
        END AS reporting_timestamp_kind,
        CASE c.source_name
            WHEN 'Defender'::text THEN d.last_seen
            WHEN 'Intune'::text THEN d.last_sync
            ELSE d.approximate_last_sign_in
        END AS reporting_at,
    snap.collection_attempt_id AS selected_attempt_id,
    a.finished_at AS selected_collected_at,
    latest.id AS latest_attempt_id,
    latest.outcome AS latest_outcome,
    latest.started_at AS latest_attempt_at
   FROM ((((((evidence.computer_source_links l
     JOIN evidence.provider_devices p ON ((p.id = l.provider_device_id)))
     JOIN evidence.source_connections c ON ((c.id = p.connection_id)))
     LEFT JOIN mock_support.mock_snapshot_selections snap ON ((snap.connection_id = c.id)))
     LEFT JOIN evidence.collection_attempts a ON ((a.id = snap.collection_attempt_id)))
     LEFT JOIN evidence.device_observations d ON (((d.provider_device_id = p.id) AND mock_support.selected_receipt(d.receipt_id))))
     LEFT JOIN LATERAL ( SELECT x.id,
            x.outcome,
            x.started_at
           FROM evidence.collection_attempts x
          WHERE (x.connection_id = c.id)
          ORDER BY x.started_at DESC, x.id DESC
         LIMIT 1) latest ON (true));


ALTER VIEW evidence.computer_source_status OWNER TO tm_mock_owner;

--
-- Name: VIEW computer_source_status; Type: COMMENT; Schema: evidence; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence.computer_source_status IS 'Synthetic evidence view; current receipts depend on predetermined mock snapshot selections, not operational collection selection.';


