    o.id AS software_observation_id,
    o.receipt_id,
    o.source_application_id,
    s.publisher,
    s.product_name,
    s.version,
    s.platform,
    o.observed_at
   FROM ((evidence.software_observations o
     JOIN evidence.software s ON ((s.id = o.software_id)))
     JOIN evidence.computer_source_links l ON ((l.provider_device_id = o.provider_device_id)))
  WHERE mock_support.selected_receipt(o.receipt_id);


