--
-- Name: known_fix_candidates; Type: VIEW; Schema: evidence; Owner: tm_mock_owner
--

CREATE VIEW evidence.known_fix_candidates AS
 SELECT f.computer_id,
    f.provider_device_id,
    f.finding_id,
    f.software_id,
    f.cve_id,
    m.patch_id,
    m.applicability_id,
    pv.receipt_id AS relationship_receipt_id,
    s.product_name,
    s.version,
    p.source_patch_id
   FROM (((((evidence.current_vulnerabilities f
     JOIN mock_support.mock_fix_matches m ON ((m.finding_id = f.finding_id)))
     JOIN evidence.patch_applicability a ON (((a.id = m.applicability_id) AND (a.patch_id = m.patch_id))))
     JOIN evidence.patch_vulnerabilities pv ON (((pv.patch_id = m.patch_id) AND (pv.cve_id = f.cve_id))))
     JOIN evidence.software s ON ((s.id = f.software_id)))
     JOIN evidence.patches p ON ((p.id = m.patch_id)))
  WHERE (mock_support.selected_receipt(pv.receipt_id) AND mock_support.selected_receipt(a.receipt_id) AND (s.product_name = a.software_product) AND (NOT (s.publisher IS DISTINCT FROM a.publisher)) AND (NOT (s.platform IS DISTINCT FROM a.platform)) AND (a.version_expression = ('='::text || s.version)));


ALTER VIEW evidence.known_fix_candidates OWNER TO tm_mock_owner;

--
-- Name: VIEW known_fix_candidates; Type: COMMENT; Schema: evidence; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence.known_fix_candidates IS 'Synthetic evidence view; predetermined mock fix matches checked against exact product/version relationships, not a general patch resolver. Rows are finding/patch candidates.';


