    software_id,
    cve_id,
    finding_id,
    receipt_id
   FROM evidence.current_vulnerabilities f
  WHERE (NOT (EXISTS ( SELECT 1
           FROM evidence.known_fix_candidates k
          WHERE (k.finding_id = f.finding_id))));


