--
-- Name: notifications; Type: TABLE; Schema: evidence; Owner: tm_mock_owner
--

CREATE TABLE evidence.notifications (
    id uuid NOT NULL,
    connection_id uuid NOT NULL,
    scope_reference text NOT NULL,
    category text NOT NULL,
    urgency text NOT NULL,
    episode_started_at timestamp with time zone NOT NULL,
    first_failure_id uuid NOT NULL,
    latest_failure_id uuid NOT NULL,
    failure_count integer NOT NULL,
    status text NOT NULL,
    resolved_at timestamp with time zone,
    recovery_attempt_id uuid,
    revision integer NOT NULL,
    page_path text NOT NULL,
    CONSTRAINT notifications_check CHECK ((((status = 'unresolved'::text) AND (resolved_at IS NULL) AND (recovery_attempt_id IS NULL)) OR ((status = 'resolved'::text) AND (resolved_at IS NOT NULL) AND (recovery_attempt_id IS NOT NULL)))),
    CONSTRAINT notifications_failure_count_check CHECK ((failure_count > 0)),
    CONSTRAINT notifications_revision_check CHECK ((revision > 0)),
    CONSTRAINT notifications_status_check CHECK ((status = ANY (ARRAY['unresolved'::text, 'resolved'::text]))),
    CONSTRAINT notifications_urgency_check CHECK ((urgency = ANY (ARRAY['low'::text, 'moderate'::text, 'high'::text, 'critical'::text])))
);


ALTER TABLE evidence.notifications OWNER TO tm_mock_owner;

--
-- Name: TABLE notifications; Type: COMMENT; Schema: evidence; Owner: tm_mock_owner
--

COMMENT ON TABLE evidence.notifications IS 'Derived collection failure episodes. Original failed attempts remain retained after recovery. Single-user workflow.';


--
-- Name: notification_details; Type: VIEW; Schema: evidence; Owner: tm_mock_owner
--

CREATE VIEW evidence.notification_details AS
 SELECT n.id AS notification_id,
    n.connection_id,
    n.scope_reference,
    n.category,
    n.urgency,
    n.status,
    n.failure_count,
    n.page_path,
    n.episode_started_at,
    n.resolved_at,
    n.recovery_attempt_id,
    a.id AS attempt_id,
    a.outcome AS attempt_outcome,
    a.started_at AS attempt_started_at,
    a.finished_at AS attempt_finished_at
   FROM ((evidence.notifications n
     LEFT JOIN evidence.notification_attempts na ON ((na.notification_id = n.id)))
     LEFT JOIN evidence.collection_attempts a ON ((a.id = na.collection_attempt_id)));


ALTER VIEW evidence.notification_details OWNER TO tm_mock_owner;

