--
-- Name: assessment_checkpoints; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.assessment_checkpoints AS
 SELECT DISTINCT ON (a.connection_id) a.connection_id,
    r.attempt_id,
    r.next_since_time,
    a.finished_at
   FROM (evidence_pipeline.assessment_runs r
     JOIN evidence.collection_attempts a ON ((a.id = r.attempt_id)))
  WHERE (a.complete AND (a.outcome = 'success'::text))
  ORDER BY a.connection_id, a.finished_at DESC, a.started_at DESC, a.id DESC;


ALTER VIEW evidence_pipeline.assessment_checkpoints OWNER TO tm_mock_owner;

--
-- Name: assessment_device_references; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.assessment_device_references AS
 SELECT a.connection_id,
    r.collection_attempt_id,
    o.receipt_id,
    (o.claim ->> 'native_device_id'::text) AS source_native_device_id,
    o.provider_device_id,
        CASE
            WHEN (o.provider_device_id IS NULL) THEN 'unbound'::text
            ELSE 'bound'::text
        END AS link_state
   FROM ((evidence_pipeline.assessment_observations o
     JOIN evidence.observation_receipts r ON ((r.id = o.receipt_id)))
     JOIN evidence.collection_attempts a ON ((a.id = r.collection_attempt_id)));


ALTER VIEW evidence_pipeline.assessment_device_references OWNER TO tm_mock_owner;

