-- Name: component_check_results; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.component_check_results (
    check_id uuid NOT NULL,
    receipt_id uuid NOT NULL,
    result jsonb NOT NULL,
    CONSTRAINT component_check_results_result_check CHECK (((jsonb_typeof(result) = 'object'::text) AND (NOT ((result ->> 'state'::text) IS DISTINCT FROM 'unknown'::text)) AND (NOT (jsonb_typeof((result -> 'evaluations'::text)) IS DISTINCT FROM 'array'::text)) AND ((result ->> 'facts_sha256'::text) ~ '^[0-9a-f]{64}$'::text)))
);


ALTER TABLE evidence_pipeline.component_check_results OWNER TO tm_mock_owner;

--
-- Name: component_check_runs; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.component_check_runs (
    id uuid NOT NULL,
    inventory_attempt_id uuid NOT NULL,
    evidence_fingerprint text NOT NULL,
    engine_fingerprint text NOT NULL,
    metadata jsonb NOT NULL,
    stored_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT component_check_runs_engine_fingerprint_check CHECK ((engine_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT component_check_runs_evidence_fingerprint_check CHECK ((evidence_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT component_check_runs_metadata_check CHECK (((jsonb_typeof(metadata) = 'object'::text) AND (NOT ((metadata ->> 'contract'::text) IS DISTINCT FROM 'triagemate-component-assessment-v1'::text)) AND (NOT ((metadata ->> 'defender_coverage'::text) IS DISTINCT FROM 'unverified'::text)) AND (NOT (jsonb_typeof((metadata -> 'rules'::text)) IS DISTINCT FROM 'array'::text)) AND (NOT (jsonb_typeof((metadata -> 'sources'::text)) IS DISTINCT FROM 'array'::text))))
);


ALTER TABLE evidence_pipeline.component_check_runs OWNER TO tm_mock_owner;

--
-- Name: component_assessment_history; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.component_assessment_history AS
 SELECT c.id AS check_id,
    c.inventory_attempt_id,
    c.evidence_fingerprint,
    c.engine_fingerprint,
    c.stored_at,
    c.metadata,
    a.connection_id,
    a.started_at,
    a.finished_at,
    s.scope_reference,
    t.external_tenant_id AS tenant_id,
    auth.origin,
    w.device_attempt_id,
    w.provider_device_id,
    b.machine_guid,
    b.entra_device_id,
    o.receipt_id,
    o.kind,
    o.native_id,
    (o.facts ->> 'name'::text) AS product_name,
    (o.facts ->> 'version'::text) AS version,
    r.result
   FROM ((((((((evidence_pipeline.component_check_runs c
     JOIN evidence.collection_attempts a ON ((a.id = c.inventory_attempt_id)))
     JOIN evidence.source_connections s ON ((s.id = a.connection_id)))
     JOIN evidence.microsoft_tenants t ON ((t.id = s.tenant_id)))
     JOIN evidence_pipeline.authorized_connections auth ON ((auth.connection_id = s.id)))
     JOIN evidence_pipeline.windows_inventory_runs w ON ((w.attempt_id = a.id)))
     JOIN evidence_pipeline.windows_inventory_bindings b ON ((b.connection_id = a.connection_id)))
     JOIN evidence_pipeline.component_check_results r ON ((r.check_id = c.id)))
     JOIN evidence_pipeline.windows_inventory_observations o ON ((o.receipt_id = r.receipt_id)));


ALTER VIEW evidence_pipeline.component_assessment_history OWNER TO tm_mock_owner;

--
-- Name: component_check_seals; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.component_check_seals (
    check_id uuid NOT NULL
);


ALTER TABLE evidence_pipeline.component_check_seals OWNER TO tm_mock_owner;

--
-- Name: component_check_source_chunks; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.component_check_source_chunks (
    check_id uuid NOT NULL,
    source_sha256 text NOT NULL,
    chunk_number bigint NOT NULL,
    payload bytea NOT NULL,
    CONSTRAINT component_check_source_chunks_chunk_number_check CHECK ((chunk_number >= 0)),
    CONSTRAINT component_check_source_chunks_payload_check CHECK ((octet_length(payload) <= 65536)),
    CONSTRAINT component_check_source_chunks_source_sha256_check CHECK ((source_sha256 ~ '^[0-9a-f]{64}$'::text))
);


ALTER TABLE evidence_pipeline.component_check_source_chunks OWNER TO tm_mock_owner;

--
-- Name: current_attack_definitions; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_attack_definitions AS
 SELECT connection_id,
    collection_attempt_id,
    collected_at,
    source_name,
    input_kind,
    receipt_id,
    native_id,
    reference_kind,
    cve_ids,
    source_fields,
    origin,
    source_url,
    licence_or_provenance,
    ((source_fields -> 'object'::text) ->> 'name'::text) AS technique_name,
    ((source_fields -> 'object'::text) ->> 'modified'::text) AS modified_text,
    (((source_fields -> 'object'::text) ->> 'revoked'::text))::boolean AS revoked,
    (((source_fields -> 'object'::text) ->> 'x_mitre_deprecated'::text))::boolean AS deprecated
   FROM evidence_pipeline.current_public_references r
  WHERE (reference_kind = 'attack_definition'::text);


ALTER VIEW evidence_pipeline.current_attack_definitions OWNER TO tm_mock_owner;

--
-- Name: current_catalog_replacement_claims; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_catalog_replacement_claims AS
 SELECT r.connection_id,
    r.receipt_id,
    r.origin,
    r.source_url,
    r.licence_or_provenance,
    r.update_id AS source_update_id,
    section.direction,
    (item.value ->> 'update_id'::text) AS target_update_id,
    (item.value ->> 'title'::text) AS target_title,
        CASE
            WHEN ((item.value ->> 'update_id'::text) IS NULL) THEN 'source_title_only_identity_unresolved'::text
            ELSE 'explicit_source_catalog_identity'::text
        END AS identity_basis
   FROM ((evidence_pipeline.current_catalog_updates r
     CROSS JOIN ( VALUES ('replaces'::text), ('replaced_by'::text)) section(direction))
     CROSS JOIN LATERAL jsonb_array_elements((r.metadata -> section.direction)) item(value));


ALTER VIEW evidence_pipeline.current_catalog_replacement_claims OWNER TO tm_mock_owner;

--
-- Name: VIEW current_catalog_replacement_claims; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_catalog_replacement_claims IS 'Source-scoped Catalog relationships only. Title-only targets preserve unknown UUID. No device applicability, installation or execution is inferred.';


--
-- Name: current_classifications; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_classifications AS
 SELECT d.provider_device_id,
    d.connection_id,
    d.source_name,
    d.tenant_id,
    d.native_device_id,
    d.display_name,
    d.operating_system,
    d.source_present,
    d.selected_attempt_id,
    o.id AS source_classification_id,
    o.category AS source_category,
    o.device_type AS source_device_type,
    o.subtype AS source_subtype,
    o.observed_at AS source_observed_at,
    chosen.id AS decision_id,
    chosen.selected_type,
    chosen.reason,
    chosen.actor_reference,
    chosen.decided_at,
    chosen.revision AS decision_revision
   FROM ((evidence_pipeline.current_device_status d
     LEFT JOIN evidence.classification_observations o ON (((o.provider_device_id = d.provider_device_id) AND (o.receipt_id = d.receipt_id))))
     LEFT JOIN LATERAL ( SELECT x.id,
            x.provider_device_id,
            x.selected_type,
            x.actor_kind,
            x.actor_reference,
            x.reason,
            x.decided_at,
            x.revision,
            x.supersedes_decision_id
           FROM evidence.classification_decisions x
          WHERE (x.provider_device_id = d.provider_device_id)
          ORDER BY x.revision DESC, x.decided_at DESC, x.id DESC
         LIMIT 1) chosen ON (true));


ALTER VIEW evidence_pipeline.current_classifications OWNER TO tm_mock_owner;

--
-- Name: VIEW current_classifications; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_classifications IS 'Microsoft classifications and latest local decision shown separately; missing source classifications remain unknown. No precedence or computer identity merge.';


--
-- Name: current_completeness; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_completeness AS
 SELECT computer_key,
    tenant_id,
    origin,
    definition_id,
    count(*) FILTER (WHERE populated) AS completeness,
    count(*) FILTER (WHERE (applicability = 'applicable'::text)) AS completeness_total,
    count(*) FILTER (WHERE (applicability = 'unknown'::text)) AS applicability_unknown_total
   FROM evidence_pipeline.current_completeness_cells
  GROUP BY computer_key, tenant_id, origin, definition_id;


ALTER VIEW evidence_pipeline.current_completeness OWNER TO tm_mock_owner;

--
-- Name: VIEW current_completeness; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_completeness IS 'Provisional device evidence cells only. Unknown provider applicability is separate. No risk score, percentage, agency assignment or claim of software/vulnerability coverage.';


--
-- Name: current_windows_inventory_runs; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_windows_inventory_runs AS
 SELECT DISTINCT ON (a.connection_id) a.connection_id,
    a.id AS collection_attempt_id,
    a.started_at,
    a.finished_at,
    a.input_fingerprint,
    c.source_name,
    c.scope_reference,
    t.external_tenant_id AS tenant_id,
    auth.origin,
    s.device_attempt_id,
    s.provider_device_id,
    b.machine_guid,
    b.entra_device_id,
    s.coverage,
    s.record_count
   FROM (((((evidence.collection_attempts a
     JOIN evidence_pipeline.windows_inventory_runs s ON ((s.attempt_id = a.id)))
     JOIN evidence_pipeline.windows_inventory_bindings b ON ((b.connection_id = a.connection_id)))
     JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
     JOIN evidence.microsoft_tenants t ON ((t.id = c.tenant_id)))
     JOIN evidence_pipeline.authorized_connections auth ON ((auth.connection_id = c.id)))
  WHERE (a.complete AND (a.outcome = 'success'::text))
  ORDER BY a.connection_id, a.started_at DESC, a.finished_at DESC, a.id DESC;


ALTER VIEW evidence_pipeline.current_windows_inventory_runs OWNER TO tm_mock_owner;

--
-- Name: current_component_assessments; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_component_assessments AS
 SELECT h.check_id,
    h.inventory_attempt_id,
    h.evidence_fingerprint,
    h.engine_fingerprint,
    h.stored_at,
    h.metadata,
    h.connection_id,
    h.started_at,
    h.finished_at,
    h.scope_reference,
    h.tenant_id,
    h.origin,
    h.device_attempt_id,
    h.provider_device_id,
    h.machine_guid,
    h.entra_device_id,
    h.receipt_id,
    h.kind,
    h.native_id,
    h.product_name,
    h.version,
    h.result
   FROM ((evidence_pipeline.component_assessment_history h
     JOIN evidence_pipeline.current_windows_inventory_runs i ON ((i.collection_attempt_id = h.inventory_attempt_id)))
     JOIN ( SELECT DISTINCT ON (component_check_runs.inventory_attempt_id) component_check_runs.id
           FROM evidence_pipeline.component_check_runs
          ORDER BY component_check_runs.inventory_attempt_id, component_check_runs.stored_at DESC, component_check_runs.id DESC) selected ON ((selected.id = h.check_id)));


ALTER VIEW evidence_pipeline.current_component_assessments OWNER TO tm_mock_owner;

--
-- Name: VIEW current_component_assessments; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_component_assessments IS 'Pinned component checks for the selected complete inventory snapshot. Per-CVE results do not establish Defender coverage, exhaustive vulnerability assessment or completeness credit.';


--
-- Name: current_ctid_mappings; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_ctid_mappings AS
 SELECT r.connection_id,
    r.collection_attempt_id,
    r.receipt_id,
    r.native_id AS cve_id,
    (m.value ->> 0) AS mapping_category,
    (m.value ->> 1) AS technique_id,
    r.origin,
    r.source_url,
    r.licence_or_provenance
   FROM (evidence_pipeline.current_public_references r
     CROSS JOIN LATERAL jsonb_array_elements((r.source_fields -> 'mappings'::text)) m(value))
  WHERE (r.reference_kind = 'cve_attack_mapping'::text);


ALTER VIEW evidence_pipeline.current_ctid_mappings OWNER TO tm_mock_owner;

--
-- Name: cve_repository_snapshots; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.cve_repository_snapshots (
    source_name text NOT NULL,
    run_id uuid NOT NULL,
    origin text NOT NULL,
    repository_commit text NOT NULL,
    reference_observed_at timestamp with time zone NOT NULL,
    reference_payload jsonb NOT NULL,
    members jsonb NOT NULL,
    CONSTRAINT cve_repository_snapshots_check CHECK (COALESCE((((reference_payload ->> 'ref'::text) =
CASE source_name
    WHEN 'CVE'::text THEN 'refs/heads/main'::text
    ELSE 'refs/heads/develop'::text
END) AND (((reference_payload -> 'object'::text) ->> 'type'::text) = 'commit'::text) AND (((reference_payload -> 'object'::text) ->> 'sha'::text) = repository_commit)), false)),
    CONSTRAINT cve_repository_snapshots_members_check CHECK (((jsonb_typeof(members) = 'array'::text) AND (jsonb_array_length(members) <= 1000000))),
    CONSTRAINT cve_repository_snapshots_origin_check CHECK ((origin = ANY (ARRAY['public'::text, 'synthetic'::text]))),
    CONSTRAINT cve_repository_snapshots_repository_commit_check CHECK (((repository_commit ~ '^[a-f0-9]{40}$'::text) AND (repository_commit <> '0000000000000000000000000000000000000000'::text))),
    CONSTRAINT cve_repository_snapshots_source_name_check CHECK ((source_name = ANY (ARRAY['CVE'::text, 'CISA'::text])))
);


ALTER TABLE evidence_pipeline.cve_repository_snapshots OWNER TO tm_mock_owner;

--
-- Name: current_cve_repository_snapshot; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_cve_repository_snapshot AS
 SELECT DISTINCT ON (source_name, origin) source_name,
    run_id,
    origin,
    repository_commit,
    reference_observed_at,
    reference_payload,
    members
   FROM evidence_pipeline.cve_repository_snapshots
  ORDER BY source_name, origin, reference_observed_at DESC, run_id DESC;


ALTER VIEW evidence_pipeline.current_cve_repository_snapshot OWNER TO tm_mock_owner;

--
-- Name: current_cve_repository_records; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_cve_repository_records AS
 SELECT s.source_name,
    s.run_id,
    s.repository_commit,
    s.reference_observed_at,
    (m.member ->> 'path'::text) AS repository_path,
    o.receipt_id,
    o.cve_id,
    o.record_state,
    o.data_version,
    o.source_metadata,
    s.origin,
    rev.source_url,
    rev.licence_or_provenance
   FROM ((((evidence_pipeline.current_cve_repository_snapshot s
     CROSS JOIN LATERAL jsonb_array_elements(s.members) m(member))
     JOIN evidence.cve_record_observations o ON ((o.receipt_id = ((m.member ->> 'receipt_id'::text))::uuid)))
     JOIN evidence.observation_receipts r ON ((r.id = o.receipt_id)))
     JOIN evidence.source_revisions rev ON ((rev.id = r.source_revision_id)));


ALTER VIEW evidence_pipeline.current_cve_repository_records OWNER TO tm_mock_owner;

--
-- Name: current_cve_repository_contributions; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_cve_repository_contributions AS
 SELECT r.source_name,
    r.run_id,
    r.repository_commit,
    r.reference_observed_at,
    r.repository_path,
    r.receipt_id,
    r.cve_id,
    r.record_state,
    r.data_version,
    r.source_metadata,
    r.origin,
    r.source_url,
    r.licence_or_provenance,
    c.contributor_kind,
    c.contributor_index,
    c.organization_id,
    c.provider_name,
    c.source_fields
   FROM (evidence_pipeline.current_cve_repository_records r
     JOIN evidence.cve_contributions c ON ((c.receipt_id = r.receipt_id)));


ALTER VIEW evidence_pipeline.current_cve_repository_contributions OWNER TO tm_mock_owner;

--
-- Name: current_defender_missing_updates; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_defender_missing_updates AS
 WITH selected AS (
         SELECT DISTINCT ON (a.connection_id) a.id,
            a.connection_id,
            a.finished_at
           FROM (evidence.collection_attempts a
             JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
          WHERE (a.complete AND (a.outcome = 'success'::text) AND (c.source_name = 'Defender'::text) AND (c.input_kind = 'missing_patches'::text))
          ORDER BY a.connection_id, a.finished_at DESC, a.started_at DESC, a.id DESC
        )
 SELECT s.connection_id,
    s.id AS collection_attempt_id,
    s.finished_at AS collected_at,
    m.receipt_id,
    m.provider_device_id,
    d.native_device_id,
    p.source_patch_id,
    p.title,
    p.product_names,
    p.url,
    m.observed_at,
    m.reported_machine_count,
    m.reported_cve_count,
    rev.origin,
    rev.source_url,
    rev.licence_or_provenance
   FROM (((((selected s
     JOIN evidence.observation_receipts r ON ((r.collection_attempt_id = s.id)))
     JOIN evidence.device_missing_patches m ON ((m.receipt_id = r.id)))
     JOIN evidence.patches p ON (((p.id = m.patch_id) AND (p.receipt_id = m.receipt_id))))
     JOIN evidence.provider_devices d ON ((d.id = m.provider_device_id)))
     JOIN evidence.source_revisions rev ON ((rev.id = r.source_revision_id)));


ALTER VIEW evidence_pipeline.current_defender_missing_updates OWNER TO tm_mock_owner;

--
-- Name: defender_update_advice_history; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.defender_update_advice_history AS
 SELECT a.connection_id,
    a.id AS collection_attempt_id,
    a.finished_at AS collected_at,
    o.receipt_id,
    o.provider_device_id,
    o.cve_id,
    o.instance_key,
    o.event_kind,
    o.event_time_text,
    o.event_time_utc,
    (o.claim ->> 'native_device_id'::text) AS native_device_id,
    ((o.claim -> 'product'::text) ->> 'publisher'::text) AS software_vendor,
    ((o.claim -> 'product'::text) ->> 'product_name'::text) AS software_name,
    ((o.claim -> 'product'::text) ->> 'version'::text) AS software_version,
    (f.fields ->> 'osPlatform'::text) AS os_platform,
    (f.fields ->> 'recommendedSecurityUpdate'::text) AS recommended_update,
    (f.fields ->> 'recommendedSecurityUpdateId'::text) AS recommended_update_reference,
    (f.fields ->> 'recommendationReference'::text) AS recommendation_reference,
    ((f.fields ->> 'securityUpdateAvailable'::text))::boolean AS security_update_available,
    rev.origin,
    rev.source_url,
    rev.licence_or_provenance
   FROM (((((evidence_pipeline.assessment_observations o
     JOIN evidence.observation_receipts r ON ((r.id = o.receipt_id)))
     JOIN evidence.collection_attempts a ON ((a.id = r.collection_attempt_id)))
     JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
     JOIN evidence.source_revisions rev ON ((rev.id = r.source_revision_id)))
     CROSS JOIN LATERAL ( SELECT jsonb_object_agg((entry.value ->> 0), (entry.value -> 1)) AS fields
           FROM jsonb_array_elements((o.claim -> 'fields'::text)) entry(value)) f)
  WHERE (a.complete AND (a.outcome = 'success'::text) AND (c.source_name = 'Defender'::text) AND (c.input_kind = ANY (ARRAY['vulnerability_baseline'::text, 'vulnerability_events'::text])));


ALTER VIEW evidence_pipeline.defender_update_advice_history OWNER TO tm_mock_owner;

--
-- Name: current_defender_update_advice; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_defender_update_advice AS
 SELECT h.connection_id,
    h.collection_attempt_id,
    h.collected_at,
    h.receipt_id,
    h.provider_device_id,
    h.cve_id,
    h.instance_key,
    h.event_kind,
    h.event_time_text,
    h.event_time_utc,
    h.native_device_id,
    h.software_vendor,
    h.software_name,
    h.software_version,
    h.os_platform,
    h.recommended_update,
    h.recommended_update_reference,
    h.recommendation_reference,
    h.security_update_available,
    h.origin,
    h.source_url,
    h.licence_or_provenance
   FROM (evidence_pipeline.current_assessment_baseline b
     JOIN evidence_pipeline.defender_update_advice_history h ON ((h.receipt_id = b.receipt_id)));


ALTER VIEW evidence_pipeline.current_defender_update_advice OWNER TO tm_mock_owner;

--
-- Name: current_msrc_patch_fixes; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_msrc_patch_fixes AS
 SELECT c.connection_id,
    c.collection_attempt_id,
    c.collected_at,
    c.cve_id,
    c.receipt_id,
    p.id AS patch_id,
    p.source_patch_id,
    p.source_product_id,
    p.product_names,
    a.software_product,
    a.version_expression,
    a.architecture,
    c.origin,
    c.source_url,
    c.licence_or_provenance
   FROM (((evidence_pipeline.current_msrc_update_claims c
     JOIN evidence.patch_vulnerabilities v ON (((v.receipt_id = c.receipt_id) AND (v.cve_id = c.cve_id))))
     JOIN evidence.patches p ON (((p.id = v.patch_id) AND (p.receipt_id = c.receipt_id))))
     LEFT JOIN evidence.patch_applicability a ON (((a.patch_id = p.id) AND (a.receipt_id = c.receipt_id))));


ALTER VIEW evidence_pipeline.current_msrc_patch_fixes OWNER TO tm_mock_owner;

--
-- Name: current_device_patch_candidates; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_device_patch_candidates AS
 WITH patch_fixes AS MATERIALIZED (
         SELECT current_msrc_patch_fixes.connection_id,
            current_msrc_patch_fixes.collection_attempt_id,
            current_msrc_patch_fixes.collected_at,
            current_msrc_patch_fixes.cve_id,
            current_msrc_patch_fixes.receipt_id,
            current_msrc_patch_fixes.patch_id,
            current_msrc_patch_fixes.source_patch_id,
            current_msrc_patch_fixes.source_product_id,
            current_msrc_patch_fixes.product_names,
            current_msrc_patch_fixes.software_product,
            current_msrc_patch_fixes.version_expression,
            current_msrc_patch_fixes.architecture,
            current_msrc_patch_fixes.origin,
            current_msrc_patch_fixes.source_url,
            current_msrc_patch_fixes.licence_or_provenance
           FROM evidence_pipeline.current_msrc_patch_fixes
        ), findings AS (
         SELECT f_1.finding_id,
            f_1.connection_id,
            f_1.source_name,
            f_1.tenant_id,
            f_1.selected_attempt_id,
            f_1.selected_finished_at,
            f_1.latest_outcome,
            f_1.device_attempt_id,
            f_1.provider_device_id,
            f_1.receipt_id,
            f_1.source_finding_id,
            f_1.cve_id,
            f_1.source_severity_label,
            f_1.fixing_patch_id,
            f_1.fixing_patch_reference,
            f_1.software_id,
            f_1.product_name,
            f_1.publisher,
            f_1.version,
            f_1.platform,
                CASE
                    WHEN ((f_1.source_name = 'Defender'::text) AND (f_1.fixing_patch_reference ~ '^[0-9]{6,8}$'::text)) THEN ('KB'::text || f_1.fixing_patch_reference)
                    ELSE f_1.fixing_patch_reference
                END AS fix_selector
           FROM evidence_pipeline.current_findings f_1
        )
 SELECT f.connection_id,
    f.provider_device_id,
    l.computer_key,
    f.receipt_id AS finding_receipt_id,
    f.source_finding_id,
    f.cve_id,
    f.product_name,
    f.publisher,
    f.version,
    f.fixing_patch_reference,
    p.connection_id AS advisory_connection_id,
    p.receipt_id AS advisory_receipt_id,
    p.source_patch_id,
    p.source_product_id,
    p.software_product AS source_product_label,
    p.origin AS advisory_origin,
    l.origin AS device_origin,
        CASE
            WHEN (p.patch_id IS NULL) THEN 'unknown'::text
            WHEN ((f.fix_selector = p.source_patch_id) AND (f.product_name = p.software_product)) THEN 'source_reported_applicable'::text
            ELSE 'unknown'::text
        END AS applicability,
        CASE
            WHEN (p.patch_id IS NULL) THEN 'no_collected_patch_for_cve'::text
            WHEN ((f.fix_selector = p.source_patch_id) AND (f.product_name = p.software_product)) THEN 'defender_fix_reference_and_exact_msrc_product_label'::text
            WHEN (f.product_name IS DISTINCT FROM p.software_product) THEN 'product_identity_unresolved'::text
            ELSE 'device_fix_reference_missing_or_different'::text
        END AS applicability_reason,
    p.source_url,
    p.licence_or_provenance
   FROM ((findings f
     JOIN evidence_pipeline.current_computer_links l USING (provider_device_id))
     LEFT JOIN patch_fixes p ON (((p.cve_id = f.cve_id) AND ((p.origin = 'public'::text) OR (p.origin = l.origin)))));


ALTER VIEW evidence_pipeline.current_device_patch_candidates OWNER TO tm_mock_owner;

--
-- Name: VIEW current_device_patch_candidates; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_device_patch_candidates IS 'Source fix reference (numeric Defender KBs compared with a KB prefix) and exact full MSRC product label are required for source-reported applicability. All other CVE joins remain unresolved candidates. No fuzzy display-name/package match, architecture inference, patch execution or installation assertion.';


--
-- Name: current_msrc_patch_replacements; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_msrc_patch_replacements AS
 SELECT c.connection_id,
    c.collection_attempt_id,
    c.collected_at,
    c.receipt_id,
    p.id AS patch_id,
    p.source_patch_id,
    p.source_product_id,
    p.product_names,
    old.id AS superseded_patch_id,
    old.source_patch_id AS superseded_kb,
    c.origin,
    c.source_url,
    c.licence_or_provenance
   FROM (((evidence_pipeline.current_msrc_update_claims c
     JOIN evidence.patch_replacements r ON ((r.receipt_id = c.receipt_id)))
     JOIN LATERAL ( SELECT p_1.id,
            p_1.source_patch_id,
            p_1.source_product_id,
            p_1.product_names
           FROM evidence.patches p_1
          WHERE ((p_1.id = r.patch_id) AND (p_1.receipt_id = c.receipt_id))
         OFFSET 0) p ON (true))
     JOIN LATERAL ( SELECT old_1.id,
            old_1.source_patch_id
           FROM evidence.patches old_1
          WHERE ((old_1.id = r.superseded_patch_id) AND (old_1.receipt_id = c.receipt_id))
         OFFSET 0) old ON (true));


ALTER VIEW evidence_pipeline.current_msrc_patch_replacements OWNER TO tm_mock_owner;

--
-- Name: current_device_patch_replacements; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_device_patch_replacements AS
 SELECT c.connection_id,
    c.provider_device_id,
    c.computer_key,
    c.finding_receipt_id,
    c.source_finding_id,
    c.cve_id,
    c.product_name,
    c.publisher,
    c.version,
    c.fixing_patch_reference,
    c.advisory_connection_id,
    c.advisory_receipt_id,
    c.source_patch_id,
    c.source_product_id,
    c.source_product_label,
    c.advisory_origin,
    c.device_origin,
    c.applicability,
    c.applicability_reason,
    c.source_url,
    c.licence_or_provenance,
    r.source_patch_id AS replacing_patch,
    r.superseded_kb AS replaced_patch,
    r.receipt_id AS replacement_receipt_id,
    'source_scoped_replacement_not_installation'::text AS replacement_meaning
   FROM (evidence_pipeline.current_device_patch_candidates c
     JOIN evidence_pipeline.current_msrc_patch_replacements r ON (((r.receipt_id = c.advisory_receipt_id) AND (r.source_product_id = c.source_product_id) AND (r.source_patch_id = c.source_patch_id))))
  WHERE (c.applicability = 'source_reported_applicable'::text);


ALTER VIEW evidence_pipeline.current_device_patch_replacements OWNER TO tm_mock_owner;

--
-- Name: current_device_product_candidates; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_device_product_candidates AS
 WITH finding_context AS MATERIALIZED (
         SELECT f.id AS finding_id,
            f.receipt_id AS finding_receipt_id,
            f.provider_device_id,
            f.source_finding_id,
            a.connection_id,
            fc.source_name AS finding_source,
            x.device_attempt_id,
            d_1.receipt_id AS device_receipt_id,
            d_1.operating_system AS pinned_operating_system,
            d_1.release_label AS pinned_release_label
           FROM ((((((evidence.vulnerability_findings f
             JOIN evidence.observation_receipts fr ON ((fr.id = f.receipt_id)))
             JOIN evidence.collection_attempts a ON ((a.id = fr.collection_attempt_id)))
             JOIN evidence_pipeline.exposure_snapshots x ON ((x.collection_attempt_id = fr.collection_attempt_id)))
             JOIN evidence.source_connections fc ON ((fc.id = a.connection_id)))
             JOIN evidence.observation_receipts dr ON ((dr.collection_attempt_id = x.device_attempt_id)))
             JOIN evidence.device_observations d_1 ON (((d_1.receipt_id = dr.id) AND (d_1.provider_device_id = f.provider_device_id))))
        ), product_definitions AS NOT MATERIALIZED (
         SELECT claim.receipt_id,
            claim.collected_at,
            (definition.value ->> 'ProductID'::text) AS product_id,
            (definition.value ->> 'CPE'::text) AS source_cpe
           FROM (evidence_pipeline.current_msrc_update_claims claim
             CROSS JOIN LATERAL jsonb_array_elements((claim.claim #> '{source_document,ProductTree,FullProductName}'::text[])) definition(value))
        ), candidates AS (
         SELECT p.connection_id,
            p.provider_device_id,
            p.computer_key,
            p.finding_receipt_id,
            p.source_finding_id,
            p.cve_id,
            p.product_name,
            p.publisher,
            p.version,
            p.fixing_patch_reference,
            p.advisory_connection_id,
            p.advisory_receipt_id,
            p.source_patch_id,
            p.source_product_id,
            p.source_product_label,
            p.advisory_origin,
            p.device_origin,
            p.applicability,
            p.applicability_reason,
            p.source_url,
            p.licence_or_provenance,
            f.finding_id,
            f.finding_source,
            f.device_attempt_id,
            f.device_receipt_id,
            f.pinned_operating_system,
            f.pinned_release_label,
            definition.source_cpe,
            definition.collected_at AS advisory_collected_at
           FROM ((evidence_pipeline.current_device_patch_candidates p
             JOIN finding_context f ON (((f.finding_receipt_id = p.finding_receipt_id) AND (f.provider_device_id = p.provider_device_id) AND (f.source_finding_id = p.source_finding_id) AND (f.connection_id = p.connection_id))))
             LEFT JOIN product_definitions definition ON (((definition.receipt_id = p.advisory_receipt_id) AND (definition.product_id = p.source_product_id))))
        ), checked AS (
         SELECT candidates.connection_id,
            candidates.provider_device_id,
            candidates.computer_key,
            candidates.finding_receipt_id,
            candidates.source_finding_id,
            candidates.cve_id,
            candidates.product_name,
            candidates.publisher,
            candidates.version,
            candidates.fixing_patch_reference,
            candidates.advisory_connection_id,
            candidates.advisory_receipt_id,
            candidates.source_patch_id,
            candidates.source_product_id,
            candidates.source_product_label,
            candidates.advisory_origin,
            candidates.device_origin,
            candidates.applicability,
            candidates.applicability_reason,
            candidates.source_url,
            candidates.licence_or_provenance,
            candidates.finding_id,
            candidates.finding_source,
            candidates.device_attempt_id,
            candidates.device_receipt_id,
            candidates.pinned_operating_system,
            candidates.pinned_release_label,
            candidates.source_cpe,
            candidates.advisory_collected_at,
            COALESCE(((candidates.finding_source = 'Defender'::text) AND (candidates.publisher = 'microsoft'::text) AND (candidates.product_name = ANY (ARRAY['windows_10'::text, 'windows_11'::text])) AND (candidates.pinned_operating_system =
                CASE candidates.product_name
                    WHEN 'windows_10'::text THEN 'Windows10'::text
                    WHEN 'windows_11'::text THEN 'Windows11'::text
                    ELSE NULL::text
                END) AND (candidates.pinned_release_label ~ '^[0-9]{2}H[12]$'::text) AND (candidates.source_cpe ~*
                CASE
                    WHEN ((candidates.product_name = ANY (ARRAY['windows_10'::text, 'windows_11'::text])) AND (candidates.pinned_release_label ~ '^[0-9]{2}H[12]$'::text)) THEN (((('^cpe:2[.]3:o:microsoft:'::text || candidates.product_name) || '_'::text) || candidates.pinned_release_label) || ':[A-Za-z0-9_.-]+:([A-Za-z0-9_.*-]+:){6}[A-Za-z0-9_.*-]+$'::text)
                    ELSE NULL::text
                END)), false) AS family_release_correlated
           FROM candidates
        )
 SELECT checked.connection_id,
    checked.provider_device_id,
    checked.computer_key,
    checked.finding_receipt_id,
    checked.source_finding_id,
    checked.cve_id,
    checked.product_name,
    checked.publisher,
    checked.version,
    checked.fixing_patch_reference,
    checked.advisory_connection_id,
    checked.advisory_receipt_id,
    checked.source_patch_id,
    checked.source_product_id,
    checked.source_product_label,
    checked.advisory_origin,
    checked.device_origin,
    checked.applicability,
    checked.applicability_reason,
    checked.source_url,
    checked.licence_or_provenance,
    checked.finding_id,
    checked.finding_source,
    checked.device_attempt_id,
    checked.device_receipt_id,
    checked.pinned_operating_system,
    checked.pinned_release_label,
    checked.source_cpe,
    checked.advisory_collected_at,
    checked.family_release_correlated,
        CASE
            WHEN checked.family_release_correlated THEN 'pinned_windows_family_release'::text
            ELSE 'unsupported_or_conflicting_product_evidence'::text
        END AS product_correlation_reason,
    'unknown'::text AS independent_applicability,
        CASE
            WHEN (checked.family_release_correlated AND (architecture.value IS NOT NULL) AND (split_part(checked.source_cpe, ':'::text, 12) = architecture.value)) THEN 'affected_version_semantics_unresolved'::text
            WHEN checked.family_release_correlated THEN 'architecture_and_version_applicability_unresolved'::text
            ELSE 'product_identity_unresolved'::text
        END AS independent_applicability_reason,
    d.os_architecture AS pinned_os_architecture,
    d.os_processor AS pinned_os_processor,
    architecture.value AS derived_architecture,
        CASE
            WHEN (architecture.value IS NULL) THEN 'missing_ambiguous_or_conflicting_architecture'::text
            ELSE 'explicit_consistent_defender_architecture_and_processor'::text
        END AS architecture_reason,
        CASE
            WHEN ((NOT checked.family_release_correlated) OR (architecture.value IS NULL)) THEN NULL::boolean
            WHEN (split_part(checked.source_cpe, ':'::text, 12) = ANY (ARRAY['x64'::text, 'x86'::text, 'arm64'::text])) THEN (split_part(checked.source_cpe, ':'::text, 12) = architecture.value)
            ELSE NULL::boolean
        END AS architecture_correlated
   FROM ((checked
     JOIN evidence.device_observations d ON (((d.receipt_id = checked.device_receipt_id) AND (d.provider_device_id = checked.provider_device_id))))
     CROSS JOIN LATERAL ( SELECT
                CASE
                    WHEN ((d.os_architecture = '64-bit'::text) AND (d.os_processor = 'x64'::text)) THEN 'x64'::text
                    WHEN ((d.os_architecture = '32-bit'::text) AND (d.os_processor = 'x86'::text)) THEN 'x86'::text
                    WHEN ((d.os_architecture = '64-bit'::text) AND (d.os_processor = ANY (ARRAY['ARM64'::text, 'arm64'::text]))) THEN 'arm64'::text
                    ELSE NULL::text
                END AS value) architecture);


ALTER VIEW evidence_pipeline.current_device_product_candidates OWNER TO tm_mock_owner;

--
-- Name: VIEW current_device_product_candidates; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_device_product_candidates IS 'Exact Defender Windows family and pinned release correlated with a restricted MSRC CPE selector. All candidates retain unknown independent applicability: explicit consistent architecture fields are compared while missing/conflicting values remain unknown; affected-version semantics and full product identity are not inferred. Source-reported applicability remains separately labelled; original evidence and receipt provenance are unchanged.';


--
-- Name: current_exploit_metadata; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_exploit_metadata AS
 SELECT connection_id,
    collection_attempt_id,
    collected_at,
    source_name,
    input_kind,
    receipt_id,
    native_id,
    reference_kind,
    cve_ids,
    source_fields,
    origin,
    source_url,
    licence_or_provenance,
    ((source_fields ->> 'verified'::text))::boolean AS publisher_verified,
    (source_fields ->> 'reference_url'::text) AS reference_url
   FROM evidence_pipeline.current_public_references r
  WHERE (reference_kind = 'exploit_metadata'::text);


ALTER VIEW evidence_pipeline.current_exploit_metadata OWNER TO tm_mock_owner;

--
-- Name: github_repository_snapshots; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.github_repository_snapshots (
    run_id uuid NOT NULL,
    origin text NOT NULL,
    repository_commit text NOT NULL,
    reference_observed_at timestamp with time zone NOT NULL,
    reference_payload jsonb NOT NULL,
    members jsonb NOT NULL,
    CONSTRAINT github_repository_snapshots_check CHECK (COALESCE((((reference_payload ->> 'ref'::text) = 'refs/heads/main'::text) AND (((reference_payload -> 'object'::text) ->> 'type'::text) = 'commit'::text) AND (((reference_payload -> 'object'::text) ->> 'sha'::text) = repository_commit)), false)),
    CONSTRAINT github_repository_snapshots_members_check CHECK (((jsonb_typeof(members) = 'array'::text) AND (jsonb_array_length(members) <= 100000))),
    CONSTRAINT github_repository_snapshots_origin_check CHECK ((origin = ANY (ARRAY['public'::text, 'synthetic'::text]))),
    CONSTRAINT github_repository_snapshots_repository_commit_check CHECK ((repository_commit ~ '^[a-f0-9]{40}$'::text))
);


ALTER TABLE evidence_pipeline.github_repository_snapshots OWNER TO tm_mock_owner;

--
-- Name: current_github_repository_snapshot; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_github_repository_snapshot AS
 SELECT DISTINCT ON (origin) run_id,
    origin,
    repository_commit,
    reference_observed_at,
    reference_payload,
    members
   FROM evidence_pipeline.github_repository_snapshots
  ORDER BY origin, reference_observed_at DESC, run_id DESC;


ALTER VIEW evidence_pipeline.current_github_repository_snapshot OWNER TO tm_mock_owner;

--
-- Name: current_github_advisories; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_github_advisories AS
 SELECT s.run_id,
    s.repository_commit,
    s.reference_observed_at,
    (m.member ->> 'path'::text) AS repository_path,
    o.receipt_id,
    o.advisory_id,
    o.modified_text,
    o.withdrawn_text,
    o.source_fields,
    s.origin,
    rev.source_url,
    rev.licence_or_provenance
   FROM ((((evidence_pipeline.current_github_repository_snapshot s
     CROSS JOIN LATERAL jsonb_array_elements(s.members) m(member))
     JOIN evidence.osv_advisory_observations o ON ((o.receipt_id = ((m.member ->> 'receipt_id'::text))::uuid)))
     JOIN evidence.observation_receipts r ON ((r.id = o.receipt_id)))
     JOIN evidence.source_revisions rev ON ((rev.id = r.source_revision_id)));


ALTER VIEW evidence_pipeline.current_github_advisories OWNER TO tm_mock_owner;

--
-- Name: current_software_devices; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_software_devices AS
 SELECT i.inventory_id,
    i.connection_id,
    i.source_name,
    i.tenant_id,
    i.selected_attempt_id,
    i.selected_finished_at,
    i.latest_outcome,
    i.device_attempt_id,
    i.receipt_id,
    i.source_application_id,
    i.software_id,
    i.product_name,
    i.publisher,
    i.version,
    i.platform,
    i.reported_device_count,
    i.observed_device_count,
    o.provider_device_id,
    o.id AS software_observation_id
   FROM (evidence_pipeline.current_software_inventory i
     JOIN evidence.software_observations o ON ((o.inventory_id = i.inventory_id)));


ALTER VIEW evidence_pipeline.current_software_devices OWNER TO tm_mock_owner;

--
-- Name: VIEW current_software_devices; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_software_devices IS 'Explicit software-to-provider-device links from the latest complete software snapshot and its pinned device inventory.';


--
-- Name: current_inventory_identities; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_inventory_identities AS
 SELECT i.inventory_id,
    i.connection_id,
    i.source_name,
    i.tenant_id,
    i.selected_attempt_id,
    i.selected_finished_at,
    i.latest_outcome,
    i.device_attempt_id,
    i.receipt_id,
    i.source_application_id,
    i.software_id,
    i.product_name,
    i.publisher,
    i.version,
    i.platform,
    i.reported_device_count,
    i.observed_device_count,
    i.provider_device_id,
    i.software_observation_id,
    s.origin AS inventory_origin,
    d.receipt_id AS device_receipt_id,
    d.operating_system,
    evidence_pipeline.recognize_windows_inventory(jsonb_build_object('source', i.source_name, 'product', i.product_name, 'publisher', i.publisher, 'version', i.version, 'platform', i.platform, 'operating_system', d.operating_system)) AS recognition
   FROM ((((evidence_pipeline.current_software_devices i
     JOIN evidence.observation_receipts ir ON ((ir.id = i.receipt_id)))
     JOIN evidence.source_revisions s ON ((s.id = ir.source_revision_id)))
     JOIN evidence.observation_receipts dr ON ((dr.collection_attempt_id = i.device_attempt_id)))
     JOIN evidence.device_observations d ON (((d.receipt_id = dr.id) AND (d.provider_device_id = i.provider_device_id))));


ALTER VIEW evidence_pipeline.current_inventory_identities OWNER TO tm_mock_owner;

--
-- Name: VIEW current_inventory_identities; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_inventory_identities IS 'Exact supported inventory names, publishers and pinned device platforms. Every inventory row remains separate, including aliases, scopes, tenants, origins and receipts. Package and desktop distributions are not merged. Reported version components do not establish upstream release equivalence, vulnerability applicability, software purpose or a fixing patch.';


--
-- Name: current_inventory_product_evaluations; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_inventory_product_evaluations AS
 WITH candidates AS MATERIALIZED (
         SELECT c.connection_id,
            c.collection_attempt_id,
            c.collected_at,
            c.receipt_id,
            c.cve_id,
            c.record_state,
            c.data_version,
            c.source_metadata,
            c.origin,
            c.source_url,
            c.licence_or_provenance,
            c.contributor_kind,
            c.contributor_index,
            c.organization_id,
            c.provider_name,
            c.source_fields
           FROM evidence_pipeline.current_cve_contributions c
          WHERE ((c.contributor_kind = 'cna'::text) AND (c.record_state = 'PUBLISHED'::text) AND (c.provider_name = ANY (ARRAY['vmware'::text, 'microsoft'::text])) AND (EXISTS ( SELECT 1
                   FROM jsonb_array_elements(
                        CASE
                            WHEN (jsonb_typeof((c.source_fields -> 'affected'::text)) = 'array'::text) THEN (c.source_fields -> 'affected'::text)
                            ELSE '[]'::jsonb
                        END) e(value)
                  WHERE (((c.provider_name = 'vmware'::text) AND ((e.value ->> 'vendor'::text) = 'VMware'::text) AND ((e.value ->> 'product'::text) = ANY (ARRAY['Tools'::text, 'VMware tools'::text, 'VMware Tools'::text]))) OR ((c.provider_name = 'microsoft'::text) AND ((e.value ->> 'vendor'::text) = 'Microsoft'::text) AND ((e.value ->> 'product'::text) = ANY (ARRAY['Microsoft Edge (Chromium-based)'::text, 'OneDrive for Windows'::text, 'Microsoft Teams for Desktop'::text])))))))
        ), inputs AS (
         SELECT i.inventory_id,
            i.software_observation_id,
            i.connection_id,
            i.tenant_id,
            s.origin AS inventory_origin,
            i.provider_device_id,
            i.receipt_id AS inventory_receipt_id,
            i.source_application_id,
            i.selected_attempt_id AS inventory_attempt_id,
            i.device_attempt_id,
            d.receipt_id AS device_receipt_id,
            i.selected_finished_at AS inventory_collected_at,
            da.finished_at AS device_collected_at,
            i.product_name,
            i.publisher,
            i.version,
            i.platform,
            d.operating_system,
            c.cve_id,
            c.connection_id AS public_connection_id,
            c.receipt_id AS public_receipt_id,
            c.collected_at AS public_collected_at,
            c.origin AS public_origin,
            c.source_url,
            c.licence_or_provenance,
            c.organization_id,
            c.provider_name,
            c.source_fields,
            jsonb_build_object('source', i.source_name, 'product', i.product_name, 'publisher', i.publisher, 'version', i.version, 'platform', i.platform, 'operating_system', d.operating_system) AS pinned_facts
           FROM ((((((evidence_pipeline.current_software_devices i
             JOIN evidence.observation_receipts ir ON ((ir.id = i.receipt_id)))
             JOIN evidence.source_revisions s ON ((s.id = ir.source_revision_id)))
             JOIN evidence.collection_attempts da ON ((da.id = i.device_attempt_id)))
             JOIN evidence.observation_receipts dr ON ((dr.collection_attempt_id = da.id)))
             JOIN evidence.device_observations d ON (((d.receipt_id = dr.id) AND (d.provider_device_id = i.provider_device_id))))
             LEFT JOIN candidates c ON (((i.source_name = 'Intune'::text) AND (((c.provider_name = 'vmware'::text) AND (i.product_name = 'VMware Tools'::text) AND (i.publisher = ANY (ARRAY['VMware, Inc.'::text, 'Broadcom Inc.'::text]))) OR ((c.provider_name = 'microsoft'::text) AND (((i.product_name = ANY (ARRAY['Microsoft Edge'::text, 'Microsoft OneDrive'::text])) AND (i.publisher = 'Microsoft Corporation'::text)) OR ((i.product_name = 'MSTeams'::text) AND (i.publisher = 'CN=Microsoft Corporation, O=Microsoft Corporation, L=Redmond, S=Washington, C=US'::text))) AND (EXISTS ( SELECT 1
                   FROM jsonb_array_elements((c.source_fields -> 'affected'::text)) app(value)
                  WHERE (((app.value ->> 'vendor'::text) = 'Microsoft'::text) AND ((app.value ->> 'product'::text) =
                        CASE i.product_name
                            WHEN 'Microsoft Edge'::text THEN 'Microsoft Edge (Chromium-based)'::text
                            WHEN 'Microsoft OneDrive'::text THEN 'OneDrive for Windows'::text
                            WHEN 'MSTeams'::text THEN 'Microsoft Teams for Desktop'::text
                            ELSE NULL::text
                        END)))))) AND ((c.origin = 'public'::text) OR (c.origin = s.origin)))))
        ), evaluated AS (
         SELECT inputs.inventory_id,
            inputs.software_observation_id,
            inputs.connection_id,
            inputs.tenant_id,
            inputs.inventory_origin,
            inputs.provider_device_id,
            inputs.inventory_receipt_id,
            inputs.source_application_id,
            inputs.inventory_attempt_id,
            inputs.device_attempt_id,
            inputs.device_receipt_id,
            inputs.inventory_collected_at,
            inputs.device_collected_at,
            inputs.product_name,
            inputs.publisher,
            inputs.version,
            inputs.platform,
            inputs.operating_system,
            inputs.cve_id,
            inputs.public_connection_id,
            inputs.public_receipt_id,
            inputs.public_collected_at,
            inputs.public_origin,
            inputs.source_url,
            inputs.licence_or_provenance,
            inputs.organization_id,
            inputs.provider_name,
            inputs.source_fields,
            inputs.pinned_facts,
                CASE
                    WHEN (inputs.product_name = ANY (ARRAY['Microsoft OneDrive'::text, 'MSTeams'::text])) THEN evidence_pipeline.windows_app_inventory_status(inputs.source_fields, inputs.provider_name, inputs.pinned_facts)
                    WHEN (inputs.product_name = 'Microsoft Edge'::text) THEN evidence_pipeline.edge_inventory_status(inputs.source_fields, inputs.provider_name, inputs.pinned_facts)
                    ELSE evidence_pipeline.inventory_product_status(inputs.source_fields, inputs.provider_name, inputs.pinned_facts)
                END AS evaluation
           FROM inputs
        )
 SELECT inventory_id,
    software_observation_id,
    connection_id,
    tenant_id,
    inventory_origin,
    provider_device_id,
    inventory_receipt_id,
    source_application_id,
    inventory_attempt_id,
    device_attempt_id,
    device_receipt_id,
    inventory_collected_at,
    device_collected_at,
    product_name,
    publisher,
    version,
    platform,
    operating_system,
    cve_id,
    public_connection_id,
    public_receipt_id,
    public_collected_at,
    public_origin,
    source_url,
    licence_or_provenance,
    organization_id,
    provider_name,
    source_fields,
    pinned_facts,
    evaluation,
    (evaluation ->> 'state'::text) AS source_product_version_status,
    (evaluation ->> 'reason'::text) AS evaluation_reason,
    (evaluation ->> 'mapping_profile'::text) AS mapping_profile,
    'publisher_product_version_statement_not_full_applicability'::text AS interpretation
   FROM evaluated;


ALTER VIEW evidence_pipeline.current_inventory_product_evaluations OWNER TO tm_mock_owner;

--
-- Name: VIEW current_inventory_product_evaluations; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_inventory_product_evaluations IS 'Explicit read-only Windows inventory identity and pinned device facts evaluated against independently selected CNA product/version statements. No Defender finding is required. Original aliases, versions, tenants, origins, source scopes and receipts remain separate. Unknown identity or unsupported/conflicting conditions are not a match. This does not establish patch applicability, remediation, exploitability, business role or conflict precedence.';


--
-- Name: current_msrc_advisory_patch_fixes; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_msrc_advisory_patch_fixes AS
 SELECT c.connection_id,
    c.collection_attempt_id,
    c.collected_at,
    c.native_id,
    c.receipt_id,
    p.id AS patch_id,
    p.source_patch_id,
    p.source_product_id,
    p.product_names,
    a.software_product,
    a.version_expression,
    a.architecture,
    c.origin,
    c.source_url,
    c.licence_or_provenance
   FROM ((evidence_pipeline.current_msrc_advisory_claims c
     JOIN evidence.patch_applicability a ON ((a.receipt_id = c.receipt_id)))
     JOIN evidence.patches p ON (((p.id = a.patch_id) AND (p.receipt_id = c.receipt_id))));


ALTER VIEW evidence_pipeline.current_msrc_advisory_patch_fixes OWNER TO tm_mock_owner;

--
-- Name: current_msrc_advisory_patch_replacements; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_msrc_advisory_patch_replacements AS
 SELECT c.native_id,
    c.connection_id,
    c.collection_attempt_id,
    c.collected_at,
    c.receipt_id,
    p.id AS patch_id,
    p.source_patch_id,
    p.source_product_id,
    p.product_names,
    old.id AS superseded_patch_id,
    old.source_patch_id AS superseded_kb,
    c.origin,
    c.source_url,
    c.licence_or_provenance
   FROM (((evidence_pipeline.current_msrc_advisory_claims c
     JOIN evidence.patch_replacements r ON ((r.receipt_id = c.receipt_id)))
     JOIN LATERAL ( SELECT p_1.id,
            p_1.source_patch_id,
            p_1.source_product_id,
            p_1.product_names
           FROM evidence.patches p_1
          WHERE ((p_1.id = r.patch_id) AND (p_1.receipt_id = c.receipt_id))
         OFFSET 0) p ON (true))
     JOIN LATERAL ( SELECT old_1.id,
            old_1.source_patch_id
           FROM evidence.patches old_1
          WHERE ((old_1.id = r.superseded_patch_id) AND (old_1.receipt_id = c.receipt_id))
         OFFSET 0) old ON (true));


ALTER VIEW evidence_pipeline.current_msrc_advisory_patch_replacements OWNER TO tm_mock_owner;

--
-- Name: current_native_inventory_identities; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_native_inventory_identities AS
 SELECT i.connection_id,
    i.collection_attempt_id,
    i.started_at,
    i.finished_at,
    i.source_name,
    i.scope_reference,
    i.tenant_id,
    i.origin,
    i.device_attempt_id,
    i.provider_device_id,
    i.machine_guid,
    i.entra_device_id,
    i.receipt_id,
    i.kind,
    i.native_id,
    i.product_name,
    i.version,
    i.publisher,
    i.facts,
    i.coverage,
    i.licence_or_provenance,
    i.content_hash,
    d.receipt_id AS device_receipt_id,
    d.operating_system,
    a.finished_at AS device_collected_at,
    (i.facts || jsonb_build_object('source', i.source_name, 'product', i.product_name, 'platform', 'windows', 'operating_system', d.operating_system)) AS pinned_facts,
    evidence_pipeline.recognize_windows_inventory((i.facts || jsonb_build_object('source', i.source_name, 'product', i.product_name, 'platform', 'windows', 'operating_system', d.operating_system))) AS recognition
   FROM (((evidence_pipeline.current_windows_inventory i
     JOIN evidence.collection_attempts a ON ((a.id = i.device_attempt_id)))
     JOIN evidence.observation_receipts r ON ((r.collection_attempt_id = a.id)))
     JOIN evidence.device_observations d ON (((d.receipt_id = r.id) AND (d.provider_device_id = i.provider_device_id))));


ALTER VIEW evidence_pipeline.current_native_inventory_identities OWNER TO tm_mock_owner;

--
-- Name: VIEW current_native_inventory_identities; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_native_inventory_identities IS 'Every native registry/Appx observation with exact pinned device history. Unsupported identities, missing publishers, staged-only packages and resource packages remain unknown; raw facts remain inspectable. Source boundaries are retained, not merged with Intune. Recognition is not vulnerability or patch applicability.';


