--
-- Name: current_native_inventory_product_evaluations; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_native_inventory_product_evaluations AS
 WITH candidates AS MATERIALIZED (
         SELECT c.connection_id,
            c.collection_attempt_id,
            c.collected_at,
            c.receipt_id,
            c.cve_id,
            c.record_state,
            c.data_version,
            c.source_metadata,
            c.origin,
            c.source_url,
            c.licence_or_provenance,
            c.contributor_kind,
            c.contributor_index,
            c.organization_id,
            c.provider_name,
            c.source_fields
           FROM evidence_pipeline.current_cve_contributions c
          WHERE ((c.contributor_kind = 'cna'::text) AND (c.record_state = 'PUBLISHED'::text) AND (c.provider_name = ANY (ARRAY['vmware'::text, 'microsoft'::text])) AND (EXISTS ( SELECT 1
                   FROM jsonb_array_elements(
                        CASE
                            WHEN (jsonb_typeof((c.source_fields -> 'affected'::text)) = 'array'::text) THEN (c.source_fields -> 'affected'::text)
                            ELSE '[]'::jsonb
                        END) e(value)
                  WHERE (((c.provider_name = 'vmware'::text) AND ((e.value ->> 'vendor'::text) = 'VMware'::text) AND ((e.value ->> 'product'::text) = ANY (ARRAY['Tools'::text, 'VMware tools'::text, 'VMware Tools'::text]))) OR ((c.provider_name = 'microsoft'::text) AND ((e.value ->> 'vendor'::text) = 'Microsoft'::text) AND ((e.value ->> 'product'::text) = ANY (ARRAY['Microsoft Edge (Chromium-based)'::text, 'OneDrive for Windows'::text, 'Microsoft Teams for Desktop'::text])))))))
        ), inputs AS (
         SELECT i.connection_id,
            i.tenant_id,
            i.origin AS inventory_origin,
            i.provider_device_id,
            i.receipt_id AS inventory_receipt_id,
            i.native_id,
            i.kind,
            i.facts,
            i.collection_attempt_id AS inventory_attempt_id,
            i.device_attempt_id,
            i.device_receipt_id,
            i.finished_at AS inventory_collected_at,
            i.device_collected_at,
            i.product_name,
            i.publisher,
            i.version,
            i.operating_system,
            c.cve_id,
            c.connection_id AS public_connection_id,
            c.receipt_id AS public_receipt_id,
            c.collected_at AS public_collected_at,
            c.origin AS public_origin,
            c.source_url,
            c.licence_or_provenance,
            c.organization_id,
            c.provider_name,
            c.source_fields,
            i.pinned_facts
           FROM (evidence_pipeline.current_native_inventory_identities i
             LEFT JOIN candidates c ON (((i.source_name = 'Windows inventory'::text) AND (((c.provider_name = 'vmware'::text) AND (i.product_name = 'VMware Tools'::text) AND (i.publisher = ANY (ARRAY['VMware, Inc.'::text, 'Broadcom Inc.'::text]))) OR ((c.provider_name = 'microsoft'::text) AND (((i.product_name = ANY (ARRAY['Microsoft Edge'::text, 'Microsoft OneDrive'::text])) AND (i.publisher = 'Microsoft Corporation'::text)) OR ((i.product_name = 'MSTeams'::text) AND (i.publisher = 'CN=Microsoft Corporation, O=Microsoft Corporation, L=Redmond, S=Washington, C=US'::text))) AND (EXISTS ( SELECT 1
                   FROM jsonb_array_elements((c.source_fields -> 'affected'::text)) app(value)
                  WHERE (((app.value ->> 'vendor'::text) = 'Microsoft'::text) AND ((app.value ->> 'product'::text) =
                        CASE i.product_name
                            WHEN 'Microsoft Edge'::text THEN 'Microsoft Edge (Chromium-based)'::text
                            WHEN 'Microsoft OneDrive'::text THEN 'OneDrive for Windows'::text
                            WHEN 'MSTeams'::text THEN 'Microsoft Teams for Desktop'::text
                            ELSE NULL::text
                        END)))))) AND ((c.origin = 'public'::text) OR (c.origin = i.origin)))))
        ), evaluated AS (
         SELECT inputs.connection_id,
            inputs.tenant_id,
            inputs.inventory_origin,
            inputs.provider_device_id,
            inputs.inventory_receipt_id,
            inputs.native_id,
            inputs.kind,
            inputs.facts,
            inputs.inventory_attempt_id,
            inputs.device_attempt_id,
            inputs.device_receipt_id,
            inputs.inventory_collected_at,
            inputs.device_collected_at,
            inputs.product_name,
            inputs.publisher,
            inputs.version,
            inputs.operating_system,
            inputs.cve_id,
            inputs.public_connection_id,
            inputs.public_receipt_id,
            inputs.public_collected_at,
            inputs.public_origin,
            inputs.source_url,
            inputs.licence_or_provenance,
            inputs.organization_id,
            inputs.provider_name,
            inputs.source_fields,
            inputs.pinned_facts,
                CASE
                    WHEN (inputs.product_name = ANY (ARRAY['Microsoft OneDrive'::text, 'MSTeams'::text])) THEN evidence_pipeline.windows_app_inventory_status(inputs.source_fields, inputs.provider_name, inputs.pinned_facts)
                    WHEN (inputs.product_name = 'Microsoft Edge'::text) THEN evidence_pipeline.edge_inventory_status(inputs.source_fields, inputs.provider_name, inputs.pinned_facts)
                    ELSE evidence_pipeline.inventory_product_status(inputs.source_fields, inputs.provider_name, inputs.pinned_facts)
                END AS evaluation
           FROM inputs
        )
 SELECT connection_id,
    tenant_id,
    inventory_origin,
    provider_device_id,
    inventory_receipt_id,
    native_id,
    kind,
    facts,
    inventory_attempt_id,
    device_attempt_id,
    device_receipt_id,
    inventory_collected_at,
    device_collected_at,
    product_name,
    publisher,
    version,
    operating_system,
    cve_id,
    public_connection_id,
    public_receipt_id,
    public_collected_at,
    public_origin,
    source_url,
    licence_or_provenance,
    organization_id,
    provider_name,
    source_fields,
    pinned_facts,
    evaluation,
    (evaluation ->> 'state'::text) AS source_product_version_status,
    (evaluation ->> 'reason'::text) AS evaluation_reason,
    (evaluation ->> 'mapping_profile'::text) AS mapping_profile,
    'publisher_product_version_statement_not_full_applicability'::text AS interpretation
   FROM evaluated;


ALTER VIEW evidence_pipeline.current_native_inventory_product_evaluations OWNER TO tm_mock_owner;

--
-- Name: current_native_media_evaluations; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_native_media_evaluations AS
 SELECT i.connection_id,
    i.collection_attempt_id,
    i.started_at,
    i.finished_at,
    i.source_name,
    i.scope_reference,
    i.tenant_id,
    i.origin,
    i.device_attempt_id,
    i.provider_device_id,
    i.machine_guid,
    i.entra_device_id,
    i.receipt_id,
    i.kind,
    i.native_id,
    i.product_name,
    i.version,
    i.publisher,
    i.facts,
    i.coverage,
    i.licence_or_provenance,
    i.content_hash,
    i.device_receipt_id,
    i.operating_system,
    i.device_collected_at,
    i.pinned_facts,
    i.recognition,
    c.cve_id,
    c.connection_id AS public_connection_id,
    c.receipt_id AS public_receipt_id,
    c.collected_at AS public_collected_at,
    c.origin AS public_origin,
    c.source_url,
    c.licence_or_provenance AS public_licence_or_provenance,
    c.provider_name,
    c.source_fields,
    evidence_pipeline.media_inventory_status(c.source_fields, c.provider_name, i.pinned_facts) AS evaluation,
        CASE
            WHEN (c.provider_name = 'microsoft'::text) THEN evidence_pipeline.media_cpe_status((c.source_fields -> 'cpeApplicability'::text), i.pinned_facts)
            ELSE jsonb_build_object('state', 'unknown', 'reason', 'missing_published_microsoft_cna_evidence')
        END AS cpe_evaluation
   FROM (evidence_pipeline.current_native_inventory_identities i
     LEFT JOIN evidence_pipeline.current_cve_contributions c ON (((c.contributor_kind = 'cna'::text) AND (c.record_state = 'PUBLISHED'::text) AND (c.provider_name = 'microsoft'::text) AND ((c.origin = 'public'::text) OR (c.origin = i.origin)) AND (EXISTS ( SELECT 1
           FROM jsonb_array_elements(
                CASE
                    WHEN (jsonb_typeof((c.source_fields -> 'affected'::text)) = 'array'::text) THEN (c.source_fields -> 'affected'::text)
                    ELSE '[]'::jsonb
                END) e(value)
          WHERE (((e.value ->> 'vendor'::text) = 'Microsoft'::text) AND ((e.value ->> 'product'::text) =
                CASE i.product_name
                    WHEN 'Microsoft.AV1VideoExtension'::text THEN 'AV1 Video Extension'::text
                    WHEN 'Microsoft.HEIFImageExtension'::text THEN 'HEIF Image Extension'::text
                    WHEN 'Microsoft.RawImageExtension'::text THEN 'Raw Image Extension'::text
                    WHEN 'Microsoft.WebMediaExtensions'::text THEN 'Web Media Extensions'::text
                    WHEN 'Microsoft.WebpImageExtension'::text THEN 'WebP Image Extension'::text
                    WHEN 'Microsoft.MPEG2VideoExtension'::text THEN 'MPEG-2 Video Extension'::text
                    ELSE NULL::text
                END)))))))
  WHERE (i.product_name = ANY (ARRAY['Microsoft.AV1VideoExtension'::text, 'Microsoft.HEIFImageExtension'::text, 'Microsoft.RawImageExtension'::text, 'Microsoft.WebMediaExtensions'::text, 'Microsoft.WebpImageExtension'::text, 'Microsoft.MPEG2VideoExtension'::text]));


ALTER VIEW evidence_pipeline.current_native_media_evaluations OWNER TO tm_mock_owner;

--
-- Name: VIEW current_native_media_evaluations; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_native_media_evaluations IS 'Exact installed AV1 package and collected manifest identity evaluated against independently collected Microsoft CNA statements. Keeps pinned device, inventory and public receipts, scopes and dates separate. Unknown conditions and missing unaffected defaults remain unknown. Bundle observations remain visible but cannot establish installed-product matching. No patch applicability claim.';


--
-- Name: current_native_resource_packages; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_native_resource_packages AS
 SELECT r.connection_id,
    r.collection_attempt_id,
    r.started_at,
    r.finished_at,
    r.source_name,
    r.scope_reference,
    r.tenant_id,
    r.origin,
    r.device_attempt_id,
    r.provider_device_id,
    r.machine_guid,
    r.entra_device_id,
    r.receipt_id,
    r.kind,
    r.native_id,
    r.product_name,
    r.version,
    r.publisher,
    r.facts,
    r.coverage,
    r.licence_or_provenance,
    r.content_hash,
    r.device_receipt_id,
    r.operating_system,
    r.device_collected_at,
    r.pinned_facts,
    r.recognition,
    c.candidate_count,
    c.parent_receipt_ids,
        CASE
            WHEN (c.candidate_count = 1) THEN 'associated'::text
            ELSE 'unknown'::text
        END AS association_state,
        CASE
            WHEN (c.candidate_count = 1) THEN 'exact_reported_family_publisher_version'::text
            WHEN ((r.facts -> 'is_bundle'::text) IS NULL) THEN 'missing_reported_bundle_flag'::text
            WHEN (c.candidate_count = 0) THEN 'no_supported_observed_parent'::text
            ELSE 'ambiguous_observed_parents'::text
        END AS association_reason,
        CASE
            WHEN (c.candidate_count = 1) THEN c.shared_installed_user
            ELSE NULL::boolean
        END AS shared_installed_user,
    'unknown'::text AS applicability,
    'https://learn.microsoft.com/en-us/windows/apps/desktop/modernize/package-identity-overview'::text AS identity_reference
   FROM (evidence_pipeline.current_native_inventory_identities r
     CROSS JOIN LATERAL ( SELECT count(*) AS candidate_count,
            to_jsonb(COALESCE(array_agg((p.receipt_id)::text ORDER BY p.receipt_id), ARRAY[]::text[])) AS parent_receipt_ids,
            bool_or((EXISTS ( SELECT 1
                   FROM (jsonb_array_elements((r.facts -> 'user_states'::text)) ru(value)
                     JOIN jsonb_array_elements((p.facts -> 'user_states'::text)) pu(value) ON (((pu.value ->> 'sid'::text) = (ru.value ->> 'sid'::text))))
                  WHERE (((ru.value ->> 'install_state'::text) = 'Installed'::text) AND ((pu.value ->> 'install_state'::text) = 'Installed'::text))))) AS shared_installed_user
           FROM evidence_pipeline.current_native_inventory_identities p
          WHERE ((p.connection_id = r.connection_id) AND (p.collection_attempt_id = r.collection_attempt_id) AND (p.tenant_id = r.tenant_id) AND (p.provider_device_id = r.provider_device_id) AND (p.device_attempt_id = r.device_attempt_id) AND (p.device_receipt_id = r.device_receipt_id) AND evidence_pipeline.resource_package_pair(r.pinned_facts, p.pinned_facts))) c)
  WHERE ((r.kind = 'appx'::text) AND ((r.facts -> 'is_resource_package'::text) = 'true'::jsonb));


ALTER VIEW evidence_pipeline.current_native_resource_packages OWNER TO tm_mock_owner;

--
-- Name: VIEW current_native_resource_packages; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_native_resource_packages IS 'Every current resource observation with exact same-snapshot, tenant, source and pinned-device parent candidates. Bundles are excluded only by an explicit reported flag; old observations without it stay unknown. One observed parent establishes a reported package-family/version association, not a dependency, installed application or vulnerability claim. Shared Installed user evidence is separate; false means no such shared observation, not absence of the product. Multiple candidates remain ambiguous. No evidence is collapsed or removed from completeness.';


--
-- Name: current_native_runtime_releases; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_native_runtime_releases AS
 SELECT connection_id,
    collection_attempt_id,
    started_at,
    finished_at,
    source_name,
    scope_reference,
    tenant_id,
    origin,
    device_attempt_id,
    provider_device_id,
    machine_guid,
    entra_device_id,
    receipt_id,
    kind,
    native_id,
    product_name,
    version,
    publisher,
    facts,
    coverage,
    licence_or_provenance,
    content_hash,
    device_receipt_id,
    operating_system,
    device_collected_at,
    pinned_facts,
    recognition,
    evidence_pipeline.windows_runtime_release(pinned_facts) AS release_mapping
   FROM evidence_pipeline.current_native_inventory_identities i
  WHERE (product_name ~~ 'Microsoft.WindowsAppRuntime.%'::text);


ALTER VIEW evidence_pipeline.current_native_runtime_releases OWNER TO tm_mock_owner;

--
-- Name: VIEW current_native_runtime_releases; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_native_runtime_releases IS 'Every retained native Windows App Runtime observation, with exact publisher correspondence or explicit unknown. Staged-only, resource, conflicting-family and non-framework observations cannot establish an installed runtime release. Preserves pinned device/source history and does not claim vulnerability or patch applicability.';


--
-- Name: current_nvd_source_claims; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_nvd_source_claims AS
 WITH selected AS (
         SELECT DISTINCT ON (a.connection_id) a.connection_id,
            a.id,
            a.finished_at
           FROM (evidence.collection_attempts a
             JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
          WHERE ((c.source_name = 'NVD'::text) AND (c.input_kind = 'vulnerabilities'::text) AND (c.tenant_id IS NULL) AND a.complete AND (a.outcome = 'success'::text))
          ORDER BY a.connection_id, a.finished_at DESC, a.started_at DESC, a.id DESC
        )
 SELECT s.connection_id,
    s.id AS collection_attempt_id,
    s.finished_at AS collected_at,
    r.id AS receipt_id,
    rev.source_record_id AS cve_id,
    rev.origin,
    rev.source_url,
    rev.licence_or_provenance,
    ((p.claim)::jsonb -> 'raw'::text) AS source_fields
   FROM (((selected s
     JOIN evidence.observation_receipts r ON ((r.collection_attempt_id = s.id)))
     JOIN evidence.source_revisions rev ON (((rev.id = r.source_revision_id) AND (rev.connection_id = s.connection_id))))
     JOIN evidence_pipeline.public_claims p ON ((p.source_revision_id = rev.id)));


ALTER VIEW evidence_pipeline.current_nvd_source_claims OWNER TO tm_mock_owner;

--
-- Name: current_os_classes; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_os_classes AS
 SELECT d.provider_device_id,
    d.connection_id,
    d.source_name,
    d.tenant_id,
    d.origin,
    d.computer_key,
    d.operating_system AS source_value,
    d.selected_attempt_id,
        CASE
            WHEN ((d.source_name = 'Defender'::text) AND (d.operating_system = ANY (ARRAY['Windows7'::text, 'Windows8'::text, 'Windows8.1'::text, 'Windows10'::text, 'Windows11'::text]))) THEN 'Windows client'::text
            WHEN ((d.source_name = 'Defender'::text) AND (d.operating_system = ANY (ARRAY['WindowsServer2008'::text, 'WindowsServer2008R2'::text, 'WindowsServer2012'::text, 'WindowsServer2012R2'::text, 'WindowsServer2016'::text, 'WindowsServer2019'::text, 'WindowsServer2022'::text, 'WindowsServer2025'::text]))) THEN 'Windows Server'::text
            ELSE NULL::text
        END AS derived_os_class,
        CASE
            WHEN ((d.source_name = 'Defender'::text) AND (d.operating_system = ANY (ARRAY['Windows7'::text, 'Windows8'::text, 'Windows8.1'::text, 'Windows10'::text, 'Windows11'::text, 'WindowsServer2008'::text, 'WindowsServer2008R2'::text, 'WindowsServer2012'::text, 'WindowsServer2012R2'::text, 'WindowsServer2016'::text, 'WindowsServer2019'::text, 'WindowsServer2022'::text, 'WindowsServer2025'::text]))) THEN 'explicit_defender_os_platform'::text
            ELSE 'os_value_does_not_establish_supported_class'::text
        END AS derivation_reason,
    'defender-os-platform-v1'::text AS derivation_version,
    NULL::text AS device_purpose,
    c.source_device_type,
    c.selected_type AS manual_correction,
    c.reason AS manual_reason,
    c.decision_id,
    c.decided_at
   FROM (evidence_pipeline.current_computer_links d
     LEFT JOIN evidence_pipeline.current_classifications c USING (provider_device_id));


ALTER VIEW evidence_pipeline.current_os_classes OWNER TO tm_mock_owner;

--
-- Name: VIEW current_os_classes; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_os_classes IS 'Conservative exact Defender OS platform distinction. Never infers business role, merges conflicts or overrides manual corrections. Ambiguous and unlisted values remain unknown. Derived values are excluded from evidence completeness.';


