CREATE VIEW evidence_pipeline.current_osv_relationships AS
 SELECT a.connection_id,
    a.collection_attempt_id,
    a.receipt_id,
    a.advisory_id,
    a.withdrawn_text,
    k.relationship_kind,
    ((link.ordinality - 1))::integer AS relationship_index,
    (link.value #>> '{}'::text[]) AS target_id,
    a.origin,
    a.source_url,
    a.licence_or_provenance,
