--
-- Name: ubuntu_repository_snapshots; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.ubuntu_repository_snapshots (
    source_name text NOT NULL,
    run_id uuid NOT NULL,
    origin text NOT NULL,
    repository_commit text NOT NULL,
    reference_observed_at timestamp with time zone NOT NULL,
    reference_payload jsonb NOT NULL,
    members jsonb NOT NULL,
    CONSTRAINT ubuntu_repository_snapshots_check CHECK (COALESCE((((reference_payload ->> 'ref'::text) = 'refs/heads/main'::text) AND (((reference_payload -> 'object'::text) ->> 'type'::text) = 'commit'::text) AND (((reference_payload -> 'object'::text) ->> 'sha'::text) = repository_commit)), false)),
    CONSTRAINT ubuntu_repository_snapshots_members_check CHECK (((jsonb_typeof(members) = 'array'::text) AND (jsonb_array_length(members) <= 1000000))),
    CONSTRAINT ubuntu_repository_snapshots_origin_check CHECK ((origin = ANY (ARRAY['public'::text, 'synthetic'::text]))),
    CONSTRAINT ubuntu_repository_snapshots_repository_commit_check CHECK (((repository_commit ~ '^[a-f0-9]{40}$'::text) AND (repository_commit <> '0000000000000000000000000000000000000000'::text))),
    CONSTRAINT ubuntu_repository_snapshots_source_name_check CHECK ((source_name = 'Ubuntu'::text))
);


ALTER TABLE evidence_pipeline.ubuntu_repository_snapshots OWNER TO tm_mock_owner;

--
-- Name: current_ubuntu_repository_snapshot; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_ubuntu_repository_snapshot AS
 SELECT DISTINCT ON (origin) source_name,
    run_id,
    origin,
    repository_commit,
    reference_observed_at,
    reference_payload,
    members
   FROM evidence_pipeline.ubuntu_repository_snapshots
  ORDER BY origin, reference_observed_at DESC, run_id DESC;


ALTER VIEW evidence_pipeline.current_ubuntu_repository_snapshot OWNER TO tm_mock_owner;

--
-- Name: current_ubuntu_repository_advisories; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_ubuntu_repository_advisories AS
 SELECT s.source_name,
    s.run_id,
    s.repository_commit,
    s.reference_observed_at,
    (m.member ->> 'path'::text) AS repository_path,
    o.receipt_id,
    o.advisory_id,
    o.modified_text,
    o.withdrawn_text,
    o.source_fields,
    s.origin,
    rev.source_url,
    rev.licence_or_provenance
   FROM ((((evidence_pipeline.current_ubuntu_repository_snapshot s
     CROSS JOIN LATERAL jsonb_array_elements(s.members) m(member))
     JOIN evidence.osv_advisory_observations o ON ((o.receipt_id = ((m.member ->> 'receipt_id'::text))::uuid)))
     JOIN evidence.observation_receipts r ON ((r.id = o.receipt_id)))
     JOIN evidence.source_revisions rev ON ((rev.id = r.source_revision_id)));


ALTER VIEW evidence_pipeline.current_ubuntu_repository_advisories OWNER TO tm_mock_owner;

--
-- Name: current_ubuntu_repository_packages; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
