    a.advisory_id,
    a.withdrawn_text,
    p.package_index,
    p.package_name,
    p.ecosystem,
    p.purl,
    p.source_fields,
    a.origin,
    a.source_url,
    a.licence_or_provenance
   FROM (evidence_pipeline.current_ubuntu_repository_advisories a
     JOIN evidence.osv_affected_packages p ON ((p.receipt_id = a.receipt_id)));


