--
-- Name: current_ubuntu_repository_relationships; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_ubuntu_repository_relationships AS
 SELECT a.source_name,
    a.run_id,
    a.repository_commit,
    a.receipt_id,
    a.advisory_id,
    a.withdrawn_text,
    k.relationship_kind,
