    a.origin,
    a.source_url,
    a.licence_or_provenance
   FROM ((evidence_pipeline.current_ubuntu_repository_advisories a
     CROSS JOIN ( VALUES ('aliases'::text,'alias'::text), ('upstream'::text,'upstream'::text), ('related'::text,'related'::text)) k(field_name, relationship_kind))
     CROSS JOIN LATERAL jsonb_array_elements(
        CASE
            WHEN (jsonb_typeof((a.source_fields -> k.field_name)) = 'array'::text) THEN (a.source_fields -> k.field_name)
            ELSE '[]'::jsonb
        END) WITH ORDINALITY link(value, ordinality));


