--
-- Name: current_vmware_tools_cna_evaluations; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_vmware_tools_cna_evaluations AS
 WITH inputs AS (
         SELECT f.finding_id,
            f.connection_id,
            f.tenant_id,
            fs.origin AS device_origin,
            f.provider_device_id,
            f.receipt_id AS finding_receipt_id,
            f.source_finding_id,
            f.cve_id,
            f.device_attempt_id,
            d.receipt_id AS device_receipt_id,
            f.selected_finished_at AS finding_collected_at,
            da.finished_at AS device_collected_at,
            f.product_name,
            f.publisher,
            f.version,
            f.fixing_patch_reference,
            c.connection_id AS public_connection_id,
            c.receipt_id AS public_receipt_id,
            c.collected_at AS public_collected_at,
            c.origin AS public_origin,
            c.source_url,
            c.licence_or_provenance,
            c.organization_id,
            c.provider_name,
            c.source_fields,
            jsonb_build_object('product', f.product_name, 'publisher', f.publisher, 'version', f.version, 'operating_system', d.operating_system, 'release', d.release_label, 'os_build', d.os_build, 'os_architecture', d.os_architecture, 'os_processor', d.os_processor) AS pinned_facts
           FROM ((((((evidence_pipeline.current_findings f
             JOIN evidence.observation_receipts fr ON ((fr.id = f.receipt_id)))
             JOIN evidence.source_revisions fs ON ((fs.id = fr.source_revision_id)))
             JOIN evidence.collection_attempts da ON ((da.id = f.device_attempt_id)))
             JOIN evidence.observation_receipts dr ON ((dr.collection_attempt_id = da.id)))
             JOIN evidence.device_observations d ON (((d.receipt_id = dr.id) AND (d.provider_device_id = f.provider_device_id))))
             LEFT JOIN evidence_pipeline.current_cve_contributions c ON (((c.cve_id = f.cve_id) AND (c.contributor_kind = 'cna'::text) AND (c.record_state = 'PUBLISHED'::text) AND ((c.origin = 'public'::text) OR (c.origin = fs.origin)))))
          WHERE (f.source_name = 'Defender'::text)
        ), evaluated AS (
         SELECT inputs.finding_id,
            inputs.connection_id,
            inputs.tenant_id,
            inputs.device_origin,
            inputs.provider_device_id,
            inputs.finding_receipt_id,
            inputs.source_finding_id,
            inputs.cve_id,
            inputs.device_attempt_id,
            inputs.device_receipt_id,
            inputs.finding_collected_at,
            inputs.device_collected_at,
            inputs.product_name,
            inputs.publisher,
            inputs.version,
            inputs.fixing_patch_reference,
            inputs.public_connection_id,
            inputs.public_receipt_id,
            inputs.public_collected_at,
            inputs.public_origin,
            inputs.source_url,
            inputs.licence_or_provenance,
            inputs.organization_id,
            inputs.provider_name,
            inputs.source_fields,
            inputs.pinned_facts,
                CASE
                    WHEN (inputs.public_receipt_id IS NULL) THEN evidence_pipeline.vmware_tools_result('unknown'::text, 'no_published_cna_evidence'::text)
                    WHEN ((inputs.source_fields ? 'cpeApplicability'::text) OR (inputs.source_fields ? 'configurations'::text)) THEN evidence_pipeline.vmware_tools_result('unknown'::text, 'additional_cna_configuration_requires_evaluation'::text)
                    ELSE evidence_pipeline.vmware_tools_status((inputs.source_fields -> 'affected'::text), inputs.provider_name, inputs.pinned_facts)
                END AS evaluation
           FROM inputs
          WHERE ((inputs.product_name = 'tools'::text) AND (inputs.publisher = 'vmware'::text))
        )
 SELECT finding_id,
    connection_id,
    tenant_id,
    device_origin,
    provider_device_id,
    finding_receipt_id,
    source_finding_id,
    cve_id,
    device_attempt_id,
    device_receipt_id,
    finding_collected_at,
    device_collected_at,
    product_name,
    publisher,
    version,
    fixing_patch_reference,
    public_connection_id,
    public_receipt_id,
    public_collected_at,
    public_origin,
    source_url,
    licence_or_provenance,
    organization_id,
    provider_name,
    source_fields,
    pinned_facts,
    evaluation,
    (evaluation ->> 'state'::text) AS source_product_version_status,
    (evaluation ->> 'reason'::text) AS evaluation_reason,
    'publisher_product_version_statement_not_full_applicability'::text AS interpretation
   FROM evaluated;


ALTER VIEW evidence_pipeline.current_vmware_tools_cna_evaluations OWNER TO tm_mock_owner;

--
-- Name: VIEW current_vmware_tools_cna_evaluations; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_vmware_tools_cna_evaluations IS 'VMware CNA product/version statements against pinned Defender finding and device receipts. Environmental prerequisites, independent device applicability, remediation and exploitability are not established. Public source scopes remain separate assertions; original source fields, dates and statement indexes remain inspectable.';


--
-- Name: current_vulnerability_completeness; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_vulnerability_completeness AS
 SELECT connection_id,
    selected_attempt_id,
    receipt_id,
    device_attempt_id,
    provider_device_id,
    input_kind,
    definition_id,
    origin,
    count(*) FILTER (WHERE populated) AS completeness,
    count(*) FILTER (WHERE (applicability = 'applicable'::text)) AS completeness_total,
    count(*) FILTER (WHERE (applicability = 'unknown'::text)) AS applicability_unknown_total
   FROM evidence_pipeline.current_vulnerability_completeness_cells
  GROUP BY connection_id, selected_attempt_id, receipt_id, device_attempt_id, provider_device_id, input_kind, definition_id, origin;


ALTER VIEW evidence_pipeline.current_vulnerability_completeness OWNER TO tm_mock_owner;

--
-- Name: VIEW current_vulnerability_completeness; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_vulnerability_completeness IS 'Source findings and baseline field coverage, kept separate. Null-CVE baseline rows have unknown CVE/severity/CVSS applicability. Excludes inferred patch applicability; does not apply subsequent events or establish current remediation.';


--
-- Name: current_windows_bundle_members; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_windows_bundle_members AS
 SELECT m.connection_id,
    m.collection_attempt_id,
    m.started_at,
    m.finished_at,
    m.source_name,
    m.scope_reference,
    m.tenant_id,
    m.origin,
    m.device_attempt_id,
    m.provider_device_id,
    m.machine_guid,
    m.entra_device_id,
    m.receipt_id,
    m.kind,
    m.native_id,
    m.product_name,
    m.version,
    m.publisher,
    m.facts,
    m.coverage,
    m.licence_or_provenance,
    m.content_hash,
    p.receipt_id AS bundle_receipt_id,
    c.candidate_count,
    c.package_receipt_ids,
        CASE
            WHEN ((m.facts -> 'is_stub'::text) = 'true'::jsonb) THEN 'unknown'::text
            WHEN (c.candidate_count = 1) THEN 'associated'::text
            ELSE 'unknown'::text
        END AS association_state,
        CASE
            WHEN ((m.facts -> 'is_stub'::text) = 'true'::jsonb) THEN 'declared_stub_package'::text
            WHEN (c.candidate_count = 1) THEN 'explicit_bundle_member_and_observed_package'::text
            WHEN (c.candidate_count = 0) THEN 'no_matching_observed_package'::text
            ELSE 'ambiguous_observed_packages'::text
        END AS association_reason,
        CASE
            WHEN ((c.candidate_count = 1) AND ((m.facts -> 'is_stub'::text) = 'false'::jsonb)) THEN c.shared_installed_user
            ELSE NULL::boolean
        END AS shared_installed_user,
    'unknown'::text AS applicability
   FROM ((evidence_pipeline.current_windows_inventory_evidence m
     JOIN evidence_pipeline.current_windows_inventory p ON (((p.collection_attempt_id = m.collection_attempt_id) AND (p.connection_id = m.connection_id) AND (p.tenant_id = m.tenant_id) AND (p.device_attempt_id = m.device_attempt_id) AND (p.provider_device_id = m.provider_device_id) AND (p.native_id = (m.facts ->> 'bundle_native_id'::text)) AND (p.kind = 'appx'::text) AND ((p.facts -> 'is_bundle'::text) = 'true'::jsonb))))
     CROSS JOIN LATERAL ( SELECT count(*) AS candidate_count,
            to_jsonb(COALESCE(array_agg((i.receipt_id)::text ORDER BY i.receipt_id), ARRAY[]::text[])) AS package_receipt_ids,
            bool_or((EXISTS ( SELECT 1
                   FROM (jsonb_array_elements((p.facts -> 'user_states'::text)) bu(value)
                     JOIN jsonb_array_elements((i.facts -> 'user_states'::text)) iu(value) ON (((iu.value ->> 'sid'::text) = (bu.value ->> 'sid'::text))))
                  WHERE (((bu.value ->> 'install_state'::text) = 'Installed'::text) AND ((iu.value ->> 'install_state'::text) = 'Installed'::text))))) AS shared_installed_user
           FROM evidence_pipeline.current_windows_inventory i
          WHERE ((i.collection_attempt_id = m.collection_attempt_id) AND (i.connection_id = m.connection_id) AND (i.tenant_id = m.tenant_id) AND (i.device_attempt_id = m.device_attempt_id) AND (i.provider_device_id = m.provider_device_id) AND (i.kind = 'appx'::text) AND ((i.facts -> 'is_bundle'::text) = 'false'::jsonb) AND (lower(i.product_name) = lower(m.product_name)) AND (i.publisher = m.publisher) AND (lower((i.facts ->> 'family_name'::text)) = lower((m.facts ->> 'family_name'::text))) AND (i.version = m.version) AND (lower((i.facts ->> 'architecture'::text)) = (m.facts ->> 'architecture'::text)) AND (lower((i.facts ->> 'resource_id'::text)) = lower((m.facts ->> 'resource_id'::text))) AND (((i.facts -> 'is_resource_package'::text) = 'true'::jsonb) = ((m.facts ->> 'member_type'::text) = 'resource'::text)))) c)
  WHERE (m.kind = 'appx_bundle_member'::text);


ALTER VIEW evidence_pipeline.current_windows_bundle_members OWNER TO tm_mock_owner;

--
-- Name: VIEW current_windows_bundle_members; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_windows_bundle_members IS 'Explicit bundle declarations and same-collection observed package associations. Membership is separate from Installed user evidence and applicability; missing observations do not prove absence. Resource IDs are explicit, not parsed from package names. Declarations do not enter installed-inventory completeness denominators.';


--
-- Name: current_windows_cna_evaluations; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_windows_cna_evaluations AS
 WITH inputs AS (
         SELECT f.finding_id,
            f.connection_id,
            f.tenant_id,
            fs.origin AS device_origin,
            f.provider_device_id,
            f.receipt_id AS finding_receipt_id,
            f.source_finding_id,
            f.cve_id,
            f.device_attempt_id,
            d.receipt_id AS device_receipt_id,
            f.selected_finished_at AS finding_collected_at,
            da.finished_at AS device_collected_at,
            f.product_name,
            f.publisher,
            f.version,
            f.fixing_patch_reference,
            c.connection_id AS public_connection_id,
            c.receipt_id AS public_receipt_id,
            c.collected_at AS public_collected_at,
            c.origin AS public_origin,
            c.source_url,
            c.licence_or_provenance,
            c.organization_id,
            c.provider_name,
            c.source_fields,
            jsonb_build_object('product', f.product_name, 'publisher', f.publisher, 'version', f.version, 'operating_system', d.operating_system, 'release', d.release_label, 'os_build', d.os_build, 'os_architecture', d.os_architecture, 'os_processor', d.os_processor) AS pinned_facts
           FROM ((((((evidence_pipeline.current_findings f
             JOIN evidence.observation_receipts fr ON ((fr.id = f.receipt_id)))
             JOIN evidence.source_revisions fs ON ((fs.id = fr.source_revision_id)))
             JOIN evidence.collection_attempts da ON ((da.id = f.device_attempt_id)))
             JOIN evidence.observation_receipts dr ON ((dr.collection_attempt_id = da.id)))
             JOIN evidence.device_observations d ON (((d.receipt_id = dr.id) AND (d.provider_device_id = f.provider_device_id))))
             LEFT JOIN evidence_pipeline.current_cve_contributions c ON (((c.cve_id = f.cve_id) AND (c.contributor_kind = 'cna'::text) AND (c.record_state = 'PUBLISHED'::text) AND ((c.origin = 'public'::text) OR (c.origin = fs.origin)))))
          WHERE (f.source_name = 'Defender'::text)
        ), evaluated AS (
         SELECT inputs.finding_id,
            inputs.connection_id,
            inputs.tenant_id,
            inputs.device_origin,
            inputs.provider_device_id,
            inputs.finding_receipt_id,
            inputs.source_finding_id,
            inputs.cve_id,
            inputs.device_attempt_id,
            inputs.device_receipt_id,
            inputs.finding_collected_at,
            inputs.device_collected_at,
            inputs.product_name,
            inputs.publisher,
            inputs.version,
            inputs.fixing_patch_reference,
            inputs.public_connection_id,
            inputs.public_receipt_id,
            inputs.public_collected_at,
            inputs.public_origin,
            inputs.source_url,
            inputs.licence_or_provenance,
            inputs.organization_id,
            inputs.provider_name,
            inputs.source_fields,
            inputs.pinned_facts,
                CASE
                    WHEN (inputs.public_receipt_id IS NULL) THEN jsonb_build_object('state', 'unknown', 'reason', 'no_published_cna_evidence', 'entries', '[]'::jsonb)
                    ELSE evidence_pipeline.windows_cna_record_status(inputs.source_fields, inputs.provider_name, inputs.pinned_facts)
                END AS evaluation
           FROM inputs
        )
 SELECT finding_id,
    connection_id,
    tenant_id,
    device_origin,
    provider_device_id,
    finding_receipt_id,
    source_finding_id,
    cve_id,
    device_attempt_id,
    device_receipt_id,
    finding_collected_at,
    device_collected_at,
    product_name,
    publisher,
    version,
    fixing_patch_reference,
    public_connection_id,
    public_receipt_id,
    public_collected_at,
    public_origin,
    source_url,
    licence_or_provenance,
    organization_id,
    provider_name,
    source_fields,
    pinned_facts,
    evaluation,
    (evaluation ->> 'state'::text) AS evaluated_vulnerability_status,
    (evaluation ->> 'reason'::text) AS evaluation_reason,
    'publisher_version_statement_not_patch_installation'::text AS interpretation
   FROM evaluated;


ALTER VIEW evidence_pipeline.current_windows_cna_evaluations OWNER TO tm_mock_owner;

--
-- Name: VIEW current_windows_cna_evaluations; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_windows_cna_evaluations IS 'Microsoft CNA product/version status evaluated against original finding and pinned device receipts. Separate public scopes remain separate assertions; no cross-source precedence, latest-device substitution, patch installation or exploitation claim. CPE conditions use three-valued Boolean evaluation and require a vulnerable-product witness. Conflicts, unsupported conditions and textual configurations stay unknown. Original fields and statement indexes remain inspectable.';


--
-- Name: current_windows_nvd_evaluations; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_windows_nvd_evaluations AS
 WITH nvd AS MATERIALIZED (
         SELECT current_nvd_source_claims.connection_id,
            current_nvd_source_claims.collection_attempt_id,
            current_nvd_source_claims.collected_at,
            current_nvd_source_claims.receipt_id,
            current_nvd_source_claims.cve_id,
            current_nvd_source_claims.origin,
            current_nvd_source_claims.source_url,
            current_nvd_source_claims.licence_or_provenance,
            current_nvd_source_claims.source_fields
           FROM evidence_pipeline.current_nvd_source_claims
        ), inputs AS (
         SELECT f.finding_id,
            f.connection_id,
            f.tenant_id,
            fs.origin AS device_origin,
            f.provider_device_id,
            f.receipt_id AS finding_receipt_id,
            f.source_finding_id,
            f.cve_id,
            f.device_attempt_id,
            d.receipt_id AS device_receipt_id,
            f.selected_finished_at AS finding_collected_at,
            da.finished_at AS device_collected_at,
            f.product_name,
            f.publisher,
            f.version,
            f.fixing_patch_reference,
            n.connection_id AS public_connection_id,
            n.receipt_id AS public_receipt_id,
            n.collected_at AS public_collected_at,
            n.origin AS public_origin,
            n.source_url,
            n.licence_or_provenance,
            n.source_fields,
            jsonb_build_object('product', f.product_name, 'publisher', f.publisher, 'version', f.version, 'operating_system', d.operating_system, 'release', d.release_label, 'os_build', d.os_build, 'os_architecture', d.os_architecture, 'os_processor', d.os_processor) AS pinned_facts
           FROM ((((((evidence_pipeline.current_findings f
             JOIN evidence.observation_receipts fr ON ((fr.id = f.receipt_id)))
             JOIN evidence.source_revisions fs ON ((fs.id = fr.source_revision_id)))
             JOIN evidence.collection_attempts da ON ((da.id = f.device_attempt_id)))
             JOIN evidence.observation_receipts dr ON ((dr.collection_attempt_id = da.id)))
             JOIN evidence.device_observations d ON (((d.receipt_id = dr.id) AND (d.provider_device_id = f.provider_device_id))))
             LEFT JOIN nvd n ON (((n.cve_id = f.cve_id) AND ((n.origin = 'public'::text) OR (n.origin = fs.origin)))))
          WHERE (f.source_name = 'Defender'::text)
        ), evaluated AS (
         SELECT inputs.finding_id,
            inputs.connection_id,
            inputs.tenant_id,
            inputs.device_origin,
            inputs.provider_device_id,
            inputs.finding_receipt_id,
            inputs.source_finding_id,
            inputs.cve_id,
            inputs.device_attempt_id,
            inputs.device_receipt_id,
            inputs.finding_collected_at,
            inputs.device_collected_at,
            inputs.product_name,
            inputs.publisher,
            inputs.version,
            inputs.fixing_patch_reference,
            inputs.public_connection_id,
            inputs.public_receipt_id,
            inputs.public_collected_at,
            inputs.public_origin,
            inputs.source_url,
            inputs.licence_or_provenance,
            inputs.source_fields,
            inputs.pinned_facts,
                CASE
                    WHEN (inputs.public_receipt_id IS NULL) THEN jsonb_build_object('state', 'unknown', 'reason', 'no_retained_nvd_evidence')
                    WHEN ((inputs.source_fields ->> 'vulnStatus'::text) = 'Rejected'::text) THEN jsonb_build_object('state', 'unknown', 'reason', 'rejected_nvd_record')
                    ELSE evidence_pipeline.windows_cpe_status((inputs.source_fields -> 'configurations'::text), inputs.pinned_facts)
                END AS evaluation
           FROM inputs
        )
 SELECT finding_id,
    connection_id,
    tenant_id,
    device_origin,
    provider_device_id,
    finding_receipt_id,
    source_finding_id,
    cve_id,
    device_attempt_id,
    device_receipt_id,
    finding_collected_at,
    device_collected_at,
    product_name,
    publisher,
    version,
    fixing_patch_reference,
    public_connection_id,
    public_receipt_id,
    public_collected_at,
    public_origin,
    source_url,
    licence_or_provenance,
    source_fields,
    pinned_facts,
    evaluation,
    (evaluation ->> 'state'::text) AS configuration_state,
    (evaluation ->> 'reason'::text) AS evaluation_reason,
    'NVD_configuration_statement_not_patch_installation'::text AS interpretation
   FROM evaluated;


ALTER VIEW evidence_pipeline.current_windows_nvd_evaluations OWNER TO tm_mock_owner;

--
-- Name: VIEW current_windows_nvd_evaluations; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_windows_nvd_evaluations IS 'Evaluate retained NVD configurations against original finding and pinned device receipts. A match requires a vulnerable-product witness. Exclusion concerns the selected configuration only. Missing prerequisites remain unknown. Separate public scopes remain separate assertions; no CNA precedence, missing-patch confirmation or latest-device substitution.';


--
-- Name: windows_os_reviews; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.windows_os_reviews (
    id uuid NOT NULL,
    inventory_attempt_id uuid NOT NULL,
    input_fingerprint text NOT NULL,
    engine_fingerprint text NOT NULL,
    original_bytes bytea NOT NULL,
    report jsonb NOT NULL,
    stored_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT windows_os_reviews_check CHECK (((octet_length(original_bytes) <= 33554432) AND (encode(sha256(original_bytes), 'hex'::text) = input_fingerprint))),
    CONSTRAINT windows_os_reviews_engine_fingerprint_check CHECK ((engine_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT windows_os_reviews_input_fingerprint_check CHECK ((input_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT windows_os_reviews_report_check CHECK (((jsonb_typeof(report) = 'object'::text) AND (NOT ((report ->> 'contract'::text) IS DISTINCT FROM 'triagemate-windows-os-evidence-v1'::text)) AND ((report ->> 'origin'::text) = ANY (ARRAY['lab'::text, 'synthetic'::text])) AND ((report ->> 'identity_state'::text) = ANY (ARRAY['selected_from_compatible_retained_evidence'::text, 'unresolved'::text])) AND (NOT ((report ->> 'architecture'::text) IS DISTINCT FROM 'x64'::text)) AND (NOT (jsonb_typeof((report -> 'providers'::text)) IS DISTINCT FROM 'array'::text)) AND (NOT (jsonb_typeof((report -> 'installed_updates'::text)) IS DISTINCT FROM 'array'::text))))
);


ALTER TABLE evidence_pipeline.windows_os_reviews OWNER TO tm_mock_owner;

--
-- Name: windows_os_review_history; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.windows_os_review_history AS
 SELECT r.id AS review_id,
    r.inventory_attempt_id,
    r.input_fingerprint,
    r.engine_fingerprint,
    r.stored_at,
    a.connection_id,
    (r.report ->> 'origin'::text) AS origin,
    ((r.report -> 'binding'::text) ->> 'tenant_id'::text) AS tenant_id,
    ((r.report -> 'binding'::text) ->> 'device_id'::text) AS entra_device_id,
    ((r.report -> 'binding'::text) ->> 'machine_guid'::text) AS machine_guid,
    ((r.report ->> 'native_observed_at'::text))::timestamp with time zone AS native_observed_at,
    ((r.report ->> 'provider_observed_at'::text))::timestamp with time zone AS provider_observed_at,
    (r.report ->> 'windows_version'::text) AS windows_version,
    (r.report ->> 'product_label'::text) AS product_label,
    (r.report ->> 'selected_native_device_id'::text) AS selected_native_device_id,
    (r.report ->> 'identity_state'::text) AS identity_state,
    r.report
   FROM (evidence_pipeline.windows_os_reviews r
     JOIN evidence.collection_attempts a ON ((a.id = r.inventory_attempt_id)));


ALTER VIEW evidence_pipeline.windows_os_review_history OWNER TO tm_mock_owner;

--
-- Name: current_windows_os_reviews; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_windows_os_reviews AS
 WITH ranked AS (
         SELECT h.review_id,
            h.inventory_attempt_id,
            h.input_fingerprint,
            h.engine_fingerprint,
            h.stored_at,
            h.connection_id,
            h.origin,
            h.tenant_id,
            h.entra_device_id,
            h.machine_guid,
            h.native_observed_at,
            h.provider_observed_at,
            h.windows_version,
            h.product_label,
            h.selected_native_device_id,
            h.identity_state,
            h.report,
            dense_rank() OVER (PARTITION BY h.origin, h.tenant_id, h.entra_device_id, h.machine_guid ORDER BY h.provider_observed_at DESC, h.native_observed_at DESC) AS recency
           FROM evidence_pipeline.windows_os_review_history h
        ), latest AS (
         SELECT ranked.review_id,
            ranked.inventory_attempt_id,
            ranked.input_fingerprint,
            ranked.engine_fingerprint,
            ranked.stored_at,
            ranked.connection_id,
            ranked.origin,
            ranked.tenant_id,
            ranked.entra_device_id,
            ranked.machine_guid,
            ranked.native_observed_at,
            ranked.provider_observed_at,
            ranked.windows_version,
            ranked.product_label,
            ranked.selected_native_device_id,
            ranked.identity_state,
            ranked.report,
            ranked.recency,
            count(*) OVER (PARTITION BY ranked.origin, ranked.tenant_id, ranked.entra_device_id, ranked.machine_guid) AS competing_reviews
           FROM ranked
          WHERE (ranked.recency = 1)
        )
 SELECT review_id,
    inventory_attempt_id,
    input_fingerprint,
    stored_at,
    connection_id,
    origin,
    tenant_id,
    entra_device_id,
    machine_guid,
    native_observed_at,
    provider_observed_at,
    windows_version,
    product_label,
    selected_native_device_id,
        CASE
            WHEN (competing_reviews > 1) THEN 'conflicting_reviews'::text
            WHEN (EXISTS ( SELECT 1
               FROM evidence_pipeline.current_windows_inventory_runs i
              WHERE ((i.origin = l.origin) AND (i.tenant_id = l.tenant_id) AND ((i.entra_device_id)::text = l.entra_device_id) AND ((i.machine_guid)::text = l.machine_guid) AND (i.finished_at > l.native_observed_at)))) THEN 'newer_inventory_requires_review'::text
            ELSE identity_state
        END AS identity_state,
    report
   FROM latest l;


ALTER VIEW evidence_pipeline.current_windows_os_reviews OWNER TO tm_mock_owner;

--
-- Name: VIEW current_windows_os_reviews; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_windows_os_reviews IS 'Dated offline Windows evidence; conflicting reviews or newer inventory block current selection. Empty missing-update exports are not full patch compliance.';


--
-- Name: current_windows_os_findings; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_windows_os_findings AS
 SELECT r.review_id,
    r.origin,
    r.selected_native_device_id,
    r.provider_observed_at,
    (f.value ->> 'cveId'::text) AS cve_id,
    (f.value ->> 'softwareName'::text) AS product_name,
    (f.value ->> 'softwareVendor'::text) AS publisher,
    (f.value ->> 'softwareVersion'::text) AS version,
    (f.value ->> 'vulnerabilitySeverityLevel'::text) AS source_severity_label,
    f.value AS source_finding
   FROM (evidence_pipeline.current_windows_os_reviews r
     CROSS JOIN LATERAL jsonb_array_elements(COALESCE(NULLIF((r.report -> 'device_findings'::text), 'null'::jsonb), '[]'::jsonb)) f(value))
  WHERE (r.identity_state = 'selected_from_compatible_retained_evidence'::text);


ALTER VIEW evidence_pipeline.current_windows_os_findings OWNER TO tm_mock_owner;

--
-- Name: current_windows_os_provider_evidence; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_windows_os_provider_evidence AS
 SELECT r.review_id,
    r.origin,
    r.tenant_id,
    r.entra_device_id,
    r.windows_version,
    r.identity_state,
    r.native_observed_at,
    r.provider_observed_at,
    p.value AS provider_evidence,
    (p.value ->> 'native_device_id'::text) AS native_device_id,
    (p.value ->> 'state'::text) AS evidence_state
   FROM (evidence_pipeline.current_windows_os_reviews r
     CROSS JOIN LATERAL jsonb_array_elements((r.report -> 'providers'::text)) p(value));


ALTER VIEW evidence_pipeline.current_windows_os_provider_evidence OWNER TO tm_mock_owner;

--
-- Name: current_windows_os_replacement_evidence; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_windows_os_replacement_evidence AS
 WITH applicable AS MATERIALIZED (
         SELECT DISTINCT a.patch_id,
            a.receipt_id,
            a.software_product
           FROM evidence.patch_applicability a
          WHERE (a.software_product IN ( SELECT current_windows_os_reviews.product_label
                   FROM evidence_pipeline.current_windows_os_reviews))
        ), claims AS MATERIALIZED (
         SELECT c.receipt_id,
            c.origin,
            c.source_url,
            c.collected_at
           FROM evidence_pipeline.current_msrc_update_claims c
          WHERE (c.receipt_id IN ( SELECT applicable.receipt_id
                   FROM applicable))
        ), products AS MATERIALIZED (
         SELECT DISTINCT r.review_id,
            a.receipt_id,
            a.patch_id,
            p_1.source_product_id,
            p_1.source_patch_id,
            a.software_product,
            c.origin,
            c.source_url,
            c.collected_at
           FROM (((applicable a
             JOIN claims c USING (receipt_id))
             JOIN evidence.patches p_1 ON (((p_1.id = a.patch_id) AND (p_1.receipt_id = a.receipt_id))))
             JOIN evidence_pipeline.current_windows_os_reviews r ON (((a.software_product = r.product_label) AND ((c.origin = 'public'::text) OR ((r.origin = 'synthetic'::text) AND (c.origin = 'synthetic'::text))))))
          WHERE (r.identity_state = 'selected_from_compatible_retained_evidence'::text)
        )
 SELECT DISTINCT f.review_id,
    f.source_patch_id AS replacing_kb,
    old.source_patch_id AS replaced_kb,
    f.software_product AS product_label,
    f.collected_at,
    f.source_url,
    f.receipt_id,
    f.origin AS source_origin
   FROM ((products f
     JOIN evidence.patch_replacements p ON (((p.patch_id = f.patch_id) AND (p.receipt_id = f.receipt_id))))
     JOIN evidence.patches old ON (((old.id = p.superseded_patch_id) AND (old.receipt_id = f.receipt_id) AND (old.source_product_id = f.source_product_id))));


ALTER VIEW evidence_pipeline.current_windows_os_replacement_evidence OWNER TO tm_mock_owner;

--
-- Name: current_windows_os_update_status; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_windows_os_update_status AS
 WITH RECURSIVE selected AS (
         SELECT current_windows_os_reviews.review_id,
            current_windows_os_reviews.inventory_attempt_id,
            current_windows_os_reviews.input_fingerprint,
            current_windows_os_reviews.stored_at,
            current_windows_os_reviews.connection_id,
            current_windows_os_reviews.origin,
            current_windows_os_reviews.tenant_id,
            current_windows_os_reviews.entra_device_id,
            current_windows_os_reviews.machine_guid,
            current_windows_os_reviews.native_observed_at,
            current_windows_os_reviews.provider_observed_at,
            current_windows_os_reviews.windows_version,
            current_windows_os_reviews.product_label,
            current_windows_os_reviews.selected_native_device_id,
            current_windows_os_reviews.identity_state,
            current_windows_os_reviews.report
           FROM evidence_pipeline.current_windows_os_reviews
          WHERE (current_windows_os_reviews.identity_state = 'selected_from_compatible_retained_evidence'::text)
        ), installed AS (
         SELECT r.review_id,
            r.inventory_attempt_id,
            r.input_fingerprint,
            r.stored_at,
            r.connection_id,
            r.origin,
            r.tenant_id,
            r.entra_device_id,
            r.machine_guid,
            r.native_observed_at,
            r.provider_observed_at,
            r.windows_version,
            r.product_label,
            r.selected_native_device_id,
            r.identity_state,
            r.report,
            (k.value ->> 'kb'::text) AS installed_kb,
            k.value AS k
           FROM (selected r
             CROSS JOIN LATERAL jsonb_array_elements((r.report -> 'installed_updates'::text)) k(value))
        ), edges AS MATERIALIZED (
         SELECT DISTINCT current_windows_os_replacement_evidence.review_id,
            current_windows_os_replacement_evidence.product_label,
            current_windows_os_replacement_evidence.replacing_kb AS newer,
                CASE
                    WHEN (current_windows_os_replacement_evidence.replaced_kb ~~ 'KB%'::text) THEN current_windows_os_replacement_evidence.replaced_kb
                    ELSE ('KB'::text || current_windows_os_replacement_evidence.replaced_kb)
                END AS older
           FROM evidence_pipeline.current_windows_os_replacement_evidence
        ), ancestors(review_id, origin, installed_kb, product_label, kb) AS (
         SELECT installed.review_id,
            installed.origin,
            installed.installed_kb,
            installed.product_label,
            installed.installed_kb
           FROM installed
        UNION
         SELECT a.review_id,
            a.origin,
            a.installed_kb,
            a.product_label,
            e.older
           FROM (ancestors a
             JOIN edges e ON (((e.product_label = a.product_label) AND (e.newer = a.kb) AND (e.review_id = a.review_id))))
        ), historical AS (
         SELECT DISTINCT r.review_id,
                CASE
                    WHEN (m.source_patch_id ~~ 'KB%'::text) THEN m.source_patch_id
                    ELSE ('KB'::text || m.source_patch_id)
                END AS kb
           FROM (((selected r
             JOIN evidence_pipeline.current_computer_links d ON (((d.origin = r.origin) AND (d.microsoft_registration_id = r.entra_device_id))))
             JOIN evidence.microsoft_tenants t ON (((t.id = d.tenant_id) AND (t.external_tenant_id = r.tenant_id))))
             JOIN evidence_pipeline.current_defender_missing_updates m USING (provider_device_id))
          WHERE ((d.native_device_id <> r.selected_native_device_id) AND (m.product_names @> ARRAY['windows_11'::text]))
        )
 SELECT i.review_id,
    i.origin,
    i.installed_kb AS kb,
    'Observed installed'::text AS status,
    i.installed_kb AS observed_installed_replacement,
    i.native_observed_at,
    i.provider_observed_at,
    i.product_label,
    'Bounded native HotFix observation; not exhaustive installed-update inventory'::text AS evidence_basis
   FROM installed i
UNION ALL
 SELECT r.review_id,
    r.origin,
    h.kb,
        CASE
            WHEN (a.kb IS NOT NULL) THEN 'Historical update replaced by observed installed update'::text
            ELSE 'Historical candidate; current applicability unknown'::text
        END AS status,
    a.installed_kb AS observed_installed_replacement,
    r.native_observed_at,
    r.provider_observed_at,
    r.product_label,
        CASE
            WHEN (a.kb IS NOT NULL) THEN 'Explicit same-product MSRC replacement path; not a per-CVE remediation verdict'::text
            ELSE 'Different provider identity; no supported replacement path or current applicability established'::text
        END AS evidence_basis
   FROM ((historical h
     JOIN selected r USING (review_id))
     LEFT JOIN ancestors a ON (((a.review_id = h.review_id) AND (a.kb = h.kb))))
  WHERE (NOT (EXISTS ( SELECT 1
           FROM installed i
          WHERE ((i.review_id = h.review_id) AND (i.installed_kb = h.kb)))))
UNION ALL
 SELECT r.review_id,
    r.origin,
        CASE
            WHEN ((m.value ->> 'id'::text) ~~ 'KB%'::text) THEN (m.value ->> 'id'::text)
            ELSE ('KB'::text || (m.value ->> 'id'::text))
        END AS kb,
    'Source reported missing; applicability not independently verified'::text AS status,
    NULL::text AS observed_installed_replacement,
    r.native_observed_at,
    r.provider_observed_at,
    r.product_label,
    'Exact selected Defender endpoint; product labels and source record retained in review'::text AS evidence_basis
   FROM (selected r
     CROSS JOIN LATERAL jsonb_array_elements((r.report -> 'missing_updates'::text)) m(value))
  WHERE ((m.value -> 'productsNames'::text) @> '["windows_11"]'::jsonb);


ALTER VIEW evidence_pipeline.current_windows_os_update_status OWNER TO tm_mock_owner;

--
-- Name: VIEW current_windows_os_update_status; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.current_windows_os_update_status IS 'Observed installed and historical candidate status with exact product-scoped replacement paths; no patch execution, best-patch selection or exhaustive applicability claim.';


--
-- Name: current_windows_runtime_releases; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.current_windows_runtime_releases AS
 SELECT inventory_id,
    connection_id,
    source_name,
    tenant_id,
    selected_attempt_id,
    selected_finished_at,
    latest_outcome,
    device_attempt_id,
    receipt_id,
    source_application_id,
    software_id,
    product_name,
