    observed_device_count,
    provider_device_id,
    software_observation_id,
    inventory_origin,
    device_receipt_id,
    operating_system,
    recognition,
    evidence_pipeline.windows_runtime_release((recognition -> 'inventory'::text)) AS release_mapping
   FROM evidence_pipeline.current_inventory_identities i
  WHERE (product_name ~~ 'Microsoft.WindowsAppRuntime.%'::text);


ALTER VIEW evidence_pipeline.current_windows_runtime_releases OWNER TO tm_mock_owner;

--
-- Name: VIEW current_windows_runtime_releases; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
