COMMENT ON VIEW evidence_pipeline.current_windows_runtime_releases IS 'Reported Intune Windows App Runtime observations and exact pinned publisher correspondences. Unsupported families and versions remain unknown; original facts, tenants, scopes and receipts remain separate. A package version is not decoded into an SDK version or applicability claim.';


--
-- Name: cvrf_batches; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.cvrf_batches (
    receipt_id uuid NOT NULL,
    row_count integer NOT NULL,
    CONSTRAINT cvrf_batches_row_count_check CHECK ((row_count >= 0))
);


ALTER TABLE evidence_pipeline.cvrf_batches OWNER TO tm_mock_owner;

--
-- Name: cvrf_projection; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.cvrf_projection (
    receipt_id uuid NOT NULL,
    row_index integer NOT NULL,
    table_name text NOT NULL,
    entity_id uuid NOT NULL,
    CONSTRAINT cvrf_projection_row_index_check CHECK ((row_index >= 0)),
    CONSTRAINT cvrf_projection_table_name_check CHECK ((table_name = ANY (ARRAY['patches'::text, 'patch_vulnerabilities'::text, 'patch_applicability'::text, 'patch_replacements'::text])))
);


ALTER TABLE evidence_pipeline.cvrf_projection OWNER TO tm_mock_owner;

--
-- Name: enrichment_causes; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.enrichment_causes AS
 WITH observations AS (
         SELECT vulnerability_findings.receipt_id,
            vulnerability_findings.cve_id
           FROM evidence.vulnerability_findings
        UNION
         SELECT assessment_observations.receipt_id,
            assessment_observations.cve_id
           FROM evidence_pipeline.assessment_observations
          WHERE ((assessment_observations.event_kind IS NULL) OR (assessment_observations.event_kind = ANY (ARRAY['New'::text, 'Updated'::text])))
        )
 SELECT o.receipt_id,
    o.cve_id,
    r.collection_attempt_id,
    a.finished_at,
        CASE
            WHEN (rev.origin = 'synthetic'::text) THEN 'synthetic'::text
            ELSE 'public'::text
        END AS origin
   FROM (((((observations o
     JOIN evidence.observation_receipts r ON ((r.id = o.receipt_id)))
     JOIN evidence.source_revisions rev ON ((rev.id = r.source_revision_id)))
     JOIN evidence.collection_attempts a ON ((a.id = r.collection_attempt_id)))
     JOIN evidence.source_connections c ON (((c.id = a.connection_id) AND (c.id = rev.connection_id))))
     JOIN evidence_pipeline.authorized_connections allowed ON (((allowed.connection_id = c.id) AND (allowed.origin = rev.origin))))
  WHERE (a.complete AND (a.outcome = 'success'::text) AND (c.source_name = 'Defender'::text) AND (c.input_kind = ANY (ARRAY['findings'::text, 'vulnerability_baseline'::text, 'vulnerability_events'::text])) AND (o.cve_id ~ '^CVE-[0-9]{4}-[0-9]{4,19}$'::text));


ALTER VIEW evidence_pipeline.enrichment_causes OWNER TO tm_mock_owner;

--
-- Name: enrichment_requests; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.enrichment_requests (
    id uuid NOT NULL,
    source_name text NOT NULL,
    input_kind text NOT NULL,
    cve_id text NOT NULL,
    origin text NOT NULL,
    cause_receipt_id uuid NOT NULL,
    requested_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT enrichment_requests_origin_check CHECK ((origin = ANY (ARRAY['synthetic'::text, 'public'::text]))),
    CONSTRAINT enrichment_source CHECK ((((((source_name = 'NVD'::text) AND (input_kind = 'vulnerabilities'::text)) OR ((source_name = 'MSRC'::text) AND (input_kind = 'advisories'::text))) OR ((source_name = 'CVE'::text) AND (input_kind = 'records'::text))) OR ((source_name = 'CISA'::text) AND (input_kind = 'vulnrichment'::text))))
);


ALTER TABLE evidence_pipeline.enrichment_requests OWNER TO tm_mock_owner;

--
-- Name: TABLE enrichment_requests; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON TABLE evidence_pipeline.enrichment_requests IS 'Immutable source/CVE requests caused by successful finding evidence. Discovery performs no network requests; synthetic and public requests remain separate.';


--
-- Name: enrichment_runs; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.enrichment_runs (
    request_id uuid NOT NULL,
    execution_id uuid NOT NULL,
    connection_id uuid NOT NULL,
    started_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT enrichment_runs_check CHECK ((connection_id = request_id))
);


ALTER TABLE evidence_pipeline.enrichment_runs OWNER TO tm_mock_owner;

--
-- Name: enrichment_request_status; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.enrichment_request_status AS
 SELECT q.id,
    q.source_name,
    q.input_kind,
    q.cve_id,
    q.origin,
    q.cause_receipt_id,
    q.requested_at,
    run.execution_id,
    run.started_at,
    a.finished_at,
    a.error_code,
        CASE
            WHEN (run.request_id IS NULL) THEN 'queued'::text
            WHEN (a.id IS NULL) THEN 'started'::text
            WHEN (a.complete AND (a.outcome = 'success'::text)) THEN
            CASE
                WHEN (EXISTS ( SELECT 1
                   FROM (evidence.observation_receipts r
                     JOIN evidence.source_revisions rev ON ((rev.id = r.source_revision_id)))
                  WHERE ((r.collection_attempt_id = a.id) AND ((rev.source_record_id <> q.cve_id) OR (rev.origin <> q.origin))))) THEN 'invalid'::text
                WHEN (EXISTS ( SELECT 1
                   FROM ((evidence.observation_receipts r
                     JOIN evidence.source_revisions rev ON ((rev.id = r.source_revision_id)))
                     JOIN evidence_pipeline.public_claims claim ON ((claim.source_revision_id = rev.id)))
                  WHERE ((r.collection_attempt_id = a.id) AND (rev.source_record_id = q.cve_id) AND (rev.origin = q.origin)))) THEN 'succeeded'::text
                WHEN (NOT (EXISTS ( SELECT 1
                   FROM evidence.observation_receipts r
                  WHERE (r.collection_attempt_id = a.id)))) THEN 'not_found'::text
                ELSE 'invalid'::text
            END
            WHEN (a.error_code = 'public_not_found'::text) THEN 'not_found'::text
            WHEN (a.error_code = ANY (ARRAY['public_gone'::text, 'public_access_denied'::text, 'public_rate_limited'::text, 'public_unavailable'::text])) THEN 'unavailable'::text
            WHEN (a.error_code = ANY (ARRAY['invalid_public_payload'::text, 'invalid_public_input'::text])) THEN 'invalid'::text
            ELSE 'failed'::text
        END AS state
   FROM ((evidence_pipeline.enrichment_requests q
     LEFT JOIN evidence_pipeline.enrichment_runs run ON ((run.request_id = q.id)))
     LEFT JOIN evidence.collection_attempts a ON (((a.id = run.execution_id) AND (a.connection_id = run.connection_id))));


ALTER VIEW evidence_pipeline.enrichment_request_status OWNER TO tm_mock_owner;

--
-- Name: VIEW enrichment_request_status; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.enrichment_request_status IS 'Success requires a committed matching source record. Started without a completed attempt does not prove a worker is still running. No automatic retry of started or failed work.';


--
-- Name: historical_event_completeness_definition; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.historical_event_completeness_definition AS
 SELECT 'historical-event-v1'::text AS definition_id,
    field_name
   FROM ( VALUES ('source_record_id'::text), ('source_device_id'::text), ('cve_id'::text), ('event_kind'::text), ('event_time'::text), ('software_vendor'::text), ('software_name'::text), ('software_version'::text), ('rbac_group_id'::text), ('deviceName'::text), ('osPlatform'::text), ('osVersion'::text), ('osArchitecture'::text), ('rbacGroupName'::text), ('vulnerabilitySeverityLevel'::text), ('exploitabilityLevel'::text), ('recommendationReference'::text), ('recommendedSecurityUpdate'::text), ('recommendedSecurityUpdateId'::text), ('recommendedSecurityUpdateUrl'::text), ('firstSeenTimestamp'::text), ('lastSeenTimestamp'::text), ('cvssScore'::text), ('isOnboarded'::text), ('securityUpdateAvailable'::text), ('diskPaths'::text), ('registryPaths'::text)) fields(field_name);


ALTER VIEW evidence_pipeline.historical_event_completeness_definition OWNER TO tm_mock_owner;

--
-- Name: vulnerability_event_history; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.vulnerability_event_history AS
 SELECT DISTINCT ON (a.connection_id, o.event_fingerprint) a.connection_id,
    o.provider_device_id,
    o.cve_id,
    o.instance_key,
    o.event_fingerprint,
    o.event_kind,
    o.event_time_text,
    o.event_time_utc,
    o.claim,
    o.receipt_id,
    a.finished_at AS collected_at,
    rev.origin,
    rev.licence_or_provenance
   FROM (((evidence_pipeline.assessment_observations o
     JOIN evidence.observation_receipts r ON ((r.id = o.receipt_id)))
     JOIN evidence.collection_attempts a ON ((a.id = r.collection_attempt_id)))
     JOIN evidence.source_revisions rev ON ((rev.id = r.source_revision_id)))
  WHERE (o.event_kind IS NOT NULL)
  ORDER BY a.connection_id, o.event_fingerprint, a.finished_at, r.id;


ALTER VIEW evidence_pipeline.vulnerability_event_history OWNER TO tm_mock_owner;

--
-- Name: historical_event_completeness_cells; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.historical_event_completeness_cells AS
 WITH facts AS (
         SELECT h.connection_id,
            h.event_fingerprint,
            h.receipt_id,
            h.origin,
            h.provider_device_id,
            h.event_time_utc,
            h.collected_at,
            (jsonb_build_object('source_record_id', (h.claim -> 'source_record_id'::text), 'source_device_id', (h.claim -> 'native_device_id'::text), 'cve_id', h.cve_id, 'event_kind', h.event_kind, 'event_time', h.event_time_text, 'software_vendor', (h.claim #> '{product,publisher}'::text[]), 'software_name', (h.claim #> '{product,product_name}'::text[]), 'software_version', (h.claim #> '{product,version}'::text[]), 'rbac_group_id', (h.claim -> 'rbac_group_id'::text)) || COALESCE(( SELECT jsonb_object_agg((pair.value ->> 0), (pair.value -> 1)) AS jsonb_object_agg
                   FROM jsonb_array_elements((h.claim -> 'fields'::text)) pair(value)), '{}'::jsonb)) AS fields
           FROM evidence_pipeline.vulnerability_event_history h
        ), cells AS (
         SELECT f.connection_id,
            f.event_fingerprint,
            f.receipt_id,
            f.origin,
            f.provider_device_id,
            f.event_time_utc,
            f.collected_at,
            d.definition_id,
            d.field_name,
            'applicable'::text AS applicability,
            'source_event_contract'::text AS applicability_reason,
            (f.fields -> d.field_name) AS value
           FROM (facts f
             CROSS JOIN evidence_pipeline.historical_event_completeness_definition d)
        )
 SELECT connection_id,
    event_fingerprint,
    receipt_id,
    origin,
    provider_device_id,
    event_time_utc,
    collected_at,
    definition_id,
    field_name,
    applicability,
    applicability_reason,
    value,
        CASE
            WHEN ((value IS NULL) OR (value = 'null'::jsonb) OR (value = '""'::jsonb)) THEN false
            WHEN (jsonb_typeof(value) = 'array'::text) THEN ((jsonb_array_length(value) = 0) OR (EXISTS ( SELECT 1
               FROM jsonb_array_elements(cells.value) element(value)
              WHERE ((element.value <> 'null'::jsonb) AND (element.value <> '""'::jsonb)))))
            ELSE true
        END AS populated
   FROM cells;


ALTER VIEW evidence_pipeline.historical_event_completeness_cells OWNER TO tm_mock_owner;

--
-- Name: VIEW historical_event_completeness_cells; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.historical_event_completeness_cells IS 'Separate historical measure; not included in current whole-product completeness. One source event fingerprint per connection, preserving tenant/origin and first retained provenance. Collection repeats do not add cells. Source identifiers and reported facts are eligible; internal keys, collection timestamps, derived joins and fingerprints are inspection metadata only. Known false, zero and explicitly empty sets are populated; blank/null values and all-null change pairs are not. Missing optional source fields remain missing, not silently inapplicable.';


--
-- Name: input_device_scopes; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.input_device_scopes (
    input_connection_id uuid NOT NULL,
    device_connection_id uuid NOT NULL,
    CONSTRAINT input_device_scopes_check CHECK ((input_connection_id <> device_connection_id))
);


ALTER TABLE evidence_pipeline.input_device_scopes OWNER TO tm_mock_owner;

--
-- Name: installation; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.installation (
    singleton boolean NOT NULL,
    version text NOT NULL,
    artifacts jsonb NOT NULL,
    signature jsonb NOT NULL,
    CONSTRAINT installation_singleton_check CHECK (singleton)
);


ALTER TABLE evidence_pipeline.installation OWNER TO tm_mock_owner;

--
-- Name: notification_episodes; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.notification_episodes AS
 WITH ordered AS (
         SELECT a.id,
            a.connection_id,
            a.started_at,
            a.finished_at,
            a.outcome,
            a.complete,
            a.error_code,
            a.safe_error_detail,
            a.revision,
            a.input_fingerprint,
            c.scope_reference,
            ((a.error_code = 'public_not_found'::text) AND (c.tenant_id IS NULL)) AS source_absent,
            count(*) FILTER (WHERE (a.complete AND (a.outcome = 'success'::text))) OVER (PARTITION BY a.connection_id ORDER BY a.finished_at, a.started_at, a.id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS success_group
           FROM ((evidence.collection_attempts a
             JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
             JOIN evidence_pipeline.authorized_connections permitted ON ((permitted.connection_id = c.id)))
        ), failures AS (
         SELECT ordered.connection_id,
            ordered.scope_reference,
            ordered.success_group,
            (array_agg(ordered.id ORDER BY ordered.finished_at, ordered.started_at, ordered.id))[1] AS first_failure_id,
            (array_agg(ordered.id ORDER BY ordered.finished_at DESC, ordered.started_at DESC, ordered.id DESC))[1] AS latest_failure_id,
            array_agg(ordered.id ORDER BY ordered.finished_at, ordered.started_at, ordered.id) AS failure_ids,
            min(ordered.finished_at) AS episode_started_at,
            (count(*))::integer AS failure_count,
            (count(*) FILTER (WHERE (NOT COALESCE(ordered.source_absent, false))) = 0) AS only_source_absence
           FROM ordered
          WHERE (ordered.outcome = 'failure'::text)
          GROUP BY ordered.connection_id, ordered.scope_reference, ordered.success_group
        ), identified AS (
         SELECT f_1.connection_id,
            f_1.scope_reference,
            f_1.success_group,
            f_1.first_failure_id,
            f_1.latest_failure_id,
            f_1.failure_ids,
            f_1.episode_started_at,
            f_1.failure_count,
            f_1.only_source_absence,
            (substr(encode(sha256(convert_to(((('triagemate-collection-notification-v1:'::text || (f_1.connection_id)::text) || ':'::text) || (f_1.first_failure_id)::text), 'UTF8'::name)), 'hex'::text), 1, 32))::uuid AS id
           FROM failures f_1
        )
 SELECT f.id,
    f.connection_id,
    f.scope_reference,
    'collection-failure'::text AS category,
        CASE
            WHEN f.only_source_absence THEN 'high'::text
            ELSE 'critical'::text
        END AS urgency,
    f.episode_started_at,
    f.first_failure_id,
    f.latest_failure_id,
    f.failure_count,
    f.failure_ids,
        CASE
            WHEN (recovery.id IS NULL) THEN 'unresolved'::text
            ELSE 'resolved'::text
        END AS status,
    recovery.finished_at AS resolved_at,
    recovery.id AS recovery_attempt_id,
    ('System/TriageMate/Notifiations/collection-'::text || (f.id)::text) AS page_path
   FROM ((identified f
     JOIN evidence.collection_attempts last_failure ON ((last_failure.id = f.latest_failure_id)))
     LEFT JOIN LATERAL ( SELECT a.id,
            a.finished_at
           FROM evidence.collection_attempts a
          WHERE ((a.connection_id = f.connection_id) AND a.complete AND (a.outcome = 'success'::text) AND (ROW(a.finished_at, a.started_at, a.id) > ROW(last_failure.finished_at, last_failure.started_at, last_failure.id)))
          ORDER BY a.finished_at, a.started_at, a.id
         LIMIT 1) recovery ON (true));


ALTER VIEW evidence_pipeline.notification_episodes OWNER TO tm_mock_owner;

