            WHEN ((((document -> 'control'::text) ->> 'desired'::text) <> 'running'::text) AND (jsonb_array_length(((document -> 'control'::text) -> 'active'::text)) > 0)) THEN 'draining'::text
            ELSE ((document -> 'control'::text) ->> 'desired'::text)
        END AS state,
    jsonb_array_length(((document -> 'control'::text) -> 'active'::text)) AS active_runs
   FROM evidence_pipeline.operation_checkpoints;


