--
-- Name: product_collection_coverage; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.product_collection_coverage AS
 SELECT c.connection_id,
    c.source_name,
    c.input_kind,
    c.scope_reference,
    a.origin,
    c.latest_outcome,
    c.latest_finished_at,
    c.selected_attempt_id,
    c.selected_finished_at,
        CASE
            WHEN (c.selected_attempt_id IS NULL) THEN 'not_collected'::text
            WHEN (c.latest_outcome = 'failure'::text) THEN 'last_success_retained'::text
            ELSE 'collected'::text
        END AS collection_state,
        CASE
            WHEN ((c.source_name = 'Windows inventory'::text) AND (c.input_kind = 'software_inventory'::text)) THEN 'windows-inventory'::text
            WHEN ((c.source_name = 'Microsoft Update Catalog'::text) AND (c.input_kind = 'updates'::text)) THEN 'catalog-update'::text
            WHEN (c.source_name = ANY (ARRAY['Exploit-DB'::text, 'CTID'::text, 'MITRE ATT&CK'::text])) THEN 'public-reference'::text
            WHEN ((c.input_kind = 'devices'::text) AND (c.source_name = ANY (ARRAY['Entra'::text, 'Intune'::text, 'Defender'::text]))) THEN 'device'::text
            WHEN ((c.source_name = 'Defender'::text) AND (c.input_kind = 'antivirus'::text)) THEN 'antivirus'::text
            WHEN ((c.source_name = 'Intune'::text) AND (c.input_kind = 'update_status'::text)) THEN 'update-status'::text
            WHEN ((c.source_name = 'Defender'::text) AND (c.input_kind = 'missing_patches'::text)) THEN 'missing-patch'::text
            WHEN ((c.source_name = 'Defender'::text) AND (c.input_kind = 'recommendations'::text)) THEN 'device-recommendation'::text
            WHEN ((c.source_name = 'Defender'::text) AND (c.input_kind = 'vulnerability_catalogue'::text)) THEN 'vulnerability-catalogue'::text
            WHEN ((c.input_kind = 'software'::text) AND (c.source_name = 'Intune'::text)) THEN 'software'::text
            WHEN ((c.input_kind = ANY (ARRAY['findings'::text, 'vulnerability_baseline'::text])) AND (c.source_name = 'Defender'::text)) THEN 'vulnerability'::text
            WHEN ((c.source_name = ANY (ARRAY['FIRST'::text, 'CISA'::text, 'NVD'::text, 'MSRC'::text])) AND (c.input_kind = ANY (ARRAY['epss'::text, 'kev'::text, 'vulnerabilities'::text, 'advisories'::text, 'security_updates'::text]))) THEN 'public'::text
            WHEN ((c.source_name = ANY (ARRAY['Debian'::text, 'Apache HTTP Server'::text, 'Apache Tomcat'::text, 'Samba'::text, 'Cisco'::text, 'Palo Alto Networks'::text, 'Red Hat'::text, 'OSV'::text, 'GitHub'::text, 'Ubuntu'::text, 'CVE'::text])) OR ((c.source_name = 'CISA'::text) AND (c.input_kind = 'vulnrichment'::text))) THEN 'public-native'::text
            ELSE NULL::text
        END AS completeness_domain
   FROM (evidence_pipeline.collection_status c
     JOIN evidence_pipeline.authorized_connections a USING (connection_id));


ALTER VIEW evidence_pipeline.product_collection_coverage OWNER TO tm_mock_owner;

--
-- Name: product_completeness_coverage; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.product_completeness_coverage AS
 SELECT c.connection_id,
    c.source_name,
    c.input_kind,
    c.scope_reference,
    c.origin,
    c.latest_outcome,
    c.latest_finished_at,
    c.selected_attempt_id,
    c.selected_finished_at,
    c.collection_state,
        CASE
            WHEN ((c.source_name = 'Defender'::text) AND (c.input_kind = 'vulnerability_events'::text)) THEN 'historical-event'::text
            ELSE c.completeness_domain
        END AS completeness_domain,
    x.eligible_cells,
    x.unknown_applicability,
        CASE
            WHEN ((c.source_name = 'Defender'::text) AND (c.input_kind = 'vulnerability_events'::text)) THEN
            CASE
                WHEN (x.eligible_cells = 0) THEN 'Not assessable: no historical events'::text
                ELSE 'Separate historical definition; excluded from current whole-product'::text
            END
            WHEN (c.completeness_domain IS NULL) THEN 'Definition unfinished'::text
            WHEN (c.selected_attempt_id IS NULL) THEN 'Not assessable: no successful collection'::text
            WHEN ((x.eligible_cells = 0) AND (x.unknown_applicability = 0)) THEN 'Not assessable: no eligible evidence cells'::text
            ELSE 'Provisional definition'::text
        END AS completeness_assessment
   FROM (evidence_pipeline.product_collection_coverage c
     CROSS JOIN LATERAL ( SELECT count(*) FILTER (WHERE (selected.applicability = 'applicable'::text)) AS eligible_cells,
            count(*) FILTER (WHERE (selected.applicability = 'unknown'::text)) AS unknown_applicability
           FROM ( SELECT e.applicability
                   FROM evidence_pipeline.current_product_completeness_cells e
                  WHERE (e.scope_connections && ARRAY[c.connection_id])
                UNION ALL
                 SELECT h.applicability
                   FROM evidence_pipeline.historical_event_completeness_cells h
                  WHERE ((h.connection_id = c.connection_id) AND (c.source_name = 'Defender'::text) AND (c.input_kind = 'vulnerability_events'::text))) selected) x);


ALTER VIEW evidence_pipeline.product_completeness_coverage OWNER TO tm_mock_owner;

