    associations_hash text NOT NULL,
    CONSTRAINT recommendation_runs_associations_hash_check CHECK ((associations_hash ~ '^[0-9a-f]{64}$'::text))
);


ALTER TABLE evidence_pipeline.recommendation_runs OWNER TO tm_mock_owner;

--
-- Name: recommendation_device_references; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.recommendation_device_references AS
 SELECT a.connection_id,
    r.collection_attempt_id,
    c.receipt_id,
    rec.id AS recommendation_id,
    native.value AS source_native_device_id,
    p.id AS provider_device_id,
        CASE
            WHEN (p.id IS NULL) THEN 'unbound'::text
            ELSE 'bound'::text
        END AS link_state
   FROM (((((((evidence_pipeline.recommendation_claims c
     JOIN evidence.observation_receipts r ON ((r.id = c.receipt_id)))
     JOIN evidence.collection_attempts a ON ((a.id = r.collection_attempt_id)))
     JOIN evidence_pipeline.recommendation_runs run ON ((run.attempt_id = a.id)))
     JOIN evidence_pipeline.recommendation_bindings b ON ((b.connection_id = a.connection_id)))
     JOIN evidence.recommendations rec ON ((rec.receipt_id = c.receipt_id)))
     CROSS JOIN LATERAL jsonb_array_elements_text((c.claim -> 'native_device_ids'::text)) native(value))
     LEFT JOIN evidence.provider_devices p ON (((p.connection_id = b.device_connection_id) AND (p.native_device_id = native.value) AND (EXISTS ( SELECT 1
           FROM (evidence.device_observations obs
             JOIN evidence.observation_receipts dr ON (((dr.id = obs.receipt_id) AND (dr.collection_attempt_id = run.device_attempt_id))))
          WHERE (obs.provider_device_id = p.id))))));


ALTER VIEW evidence_pipeline.recommendation_device_references OWNER TO tm_mock_owner;

--
-- Name: selected_component_checks; Type: TABLE; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE TABLE evidence_pipeline.selected_component_checks (
    id uuid NOT NULL,
    inventory_attempt_id uuid NOT NULL,
    evidence_fingerprint text NOT NULL,
    engine_fingerprint text NOT NULL,
    capture_sha256 text NOT NULL,
    capture bytea NOT NULL,
    report jsonb NOT NULL,
    supporting_sources jsonb NOT NULL,
    stored_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT selected_component_checks_capture_sha256_check CHECK ((capture_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT selected_component_checks_check CHECK ((encode(sha256(capture), 'hex'::text) = capture_sha256)),
    CONSTRAINT selected_component_checks_check1 CHECK (((jsonb_typeof(report) = 'object'::text) AND (NOT ((report ->> 'input_contract'::text) IS DISTINCT FROM 'triagemate-windows-component-observations-v1'::text)) AND (NOT ((report ->> 'defender_coverage'::text) IS DISTINCT FROM 'unverified'::text)) AND (NOT ((report ->> 'inventory_sha256'::text) IS DISTINCT FROM capture_sha256)) AND (NOT (jsonb_typeof((report -> 'rows'::text)) IS DISTINCT FROM 'array'::text)))),
    CONSTRAINT selected_component_checks_engine_fingerprint_check CHECK ((engine_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT selected_component_checks_evidence_fingerprint_check CHECK ((evidence_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT selected_component_checks_supporting_sources_check CHECK ((jsonb_typeof(supporting_sources) = 'object'::text))
);


ALTER TABLE evidence_pipeline.selected_component_checks OWNER TO tm_mock_owner;

--
-- Name: selected_component_history; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.selected_component_history AS
 SELECT s.id AS check_id,
    s.inventory_attempt_id,
    s.capture_sha256,
    s.engine_fingerprint,
    s.stored_at,
    a.connection_id,
    c.scope_reference,
    t.external_tenant_id AS tenant_id,
    (s.report ->> 'origin'::text) AS origin,
    (s.report ->> 'observed_at'::text) AS component_observed_at,
    a.finished_at AS inventory_collected_at,
    (s.report -> 'sources'::text) AS source_references,
    (s.report -> 'not_observed'::text) AS not_observed,
    (s.report ->> 'defender_coverage'::text) AS defender_coverage,
    r.value AS result
   FROM ((((evidence_pipeline.selected_component_checks s
     JOIN evidence.collection_attempts a ON ((a.id = s.inventory_attempt_id)))
     JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
     JOIN evidence.microsoft_tenants t ON ((t.id = c.tenant_id)))
     LEFT JOIN LATERAL jsonb_array_elements((s.report -> 'rows'::text)) r(value) ON (true));


ALTER VIEW evidence_pipeline.selected_component_history OWNER TO tm_mock_owner;

--
-- Name: VIEW selected_component_history; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.selected_component_history IS 'Separate selected-component capture time and facts, with optional exact identity/version association to an inventory snapshot. Association does not prove unchanged state between observation times or apply a verdict to another snapshot.';


--
-- Name: software_collection_coverage; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.software_collection_coverage AS
 SELECT c.connection_id,
    c.source_name,
    c.tenant_id,
    ac.origin,
    c.selected_attempt_id,
    c.selected_finished_at,
    c.latest_attempt_id,
    c.latest_outcome,
    x.device_attempt_id,
    d.selected_attempt_id AS current_device_attempt_id,
        CASE
            WHEN ((x.device_attempt_id IS NULL) OR (d.selected_attempt_id IS NULL)) THEN 'unknown'::text
            WHEN (x.device_attempt_id = d.selected_attempt_id) THEN 'current'::text
            ELSE 'older_snapshot'::text
        END AS device_dependency_state,
        CASE
            WHEN (x.collection_attempt_id IS NULL) THEN 'not_collected'::text
            WHEN (count(i.id) = 0) THEN 'complete_empty'::text
            ELSE 'complete_nonempty'::text
        END AS collection_state,
        CASE
            WHEN (x.collection_attempt_id IS NULL) THEN NULL::bigint
            ELSE count(i.id)
        END AS inventory_count
   FROM (((((evidence_pipeline.collection_status c
     JOIN evidence_pipeline.authorized_connections ac ON ((ac.connection_id = c.connection_id)))
     LEFT JOIN evidence_pipeline.exposure_snapshots x ON ((x.collection_attempt_id = c.selected_attempt_id)))
     LEFT JOIN evidence_pipeline.input_device_scopes b ON ((b.input_connection_id = c.connection_id)))
     LEFT JOIN evidence_pipeline.collection_status d ON ((d.connection_id = b.device_connection_id)))
     LEFT JOIN evidence_pipeline.software_inventory i ON ((i.collection_attempt_id = x.collection_attempt_id)))
  WHERE ((c.input_kind = 'software'::text) AND (c.source_name = 'Intune'::text))
  GROUP BY c.connection_id, c.source_name, c.tenant_id, ac.origin, c.selected_attempt_id, c.selected_finished_at, c.latest_attempt_id, c.latest_outcome, x.collection_attempt_id, x.device_attempt_id, d.selected_attempt_id;


ALTER VIEW evidence_pipeline.software_collection_coverage OWNER TO tm_mock_owner;

--
-- Name: VIEW software_collection_coverage; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.software_collection_coverage IS 'Registered Intune software inputs, not necessarily scheduled. Complete empty snapshots differ from no collection. Dependency age is relative to the currently selected device snapshot, not wall-clock freshness.';


--
-- Name: vulnerability_collection_coverage; Type: VIEW; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE VIEW evidence_pipeline.vulnerability_collection_coverage AS
 SELECT c.connection_id,
    c.input_kind,
    c.source_name,
    c.tenant_id,
    ac.origin,
    c.selected_attempt_id,
    c.selected_finished_at,
    c.latest_attempt_id,
    c.latest_outcome,
    COALESCE(x.device_attempt_id, a.device_attempt_id) AS device_attempt_id,
    d.selected_attempt_id AS current_device_attempt_id,
        CASE
            WHEN ((COALESCE(x.device_attempt_id, a.device_attempt_id) IS NULL) OR (d.selected_attempt_id IS NULL)) THEN 'unknown'::text
            WHEN (COALESCE(x.device_attempt_id, a.device_attempt_id) = d.selected_attempt_id) THEN 'current'::text
            ELSE 'older_snapshot'::text
        END AS device_dependency_state,
        CASE
            WHEN (c.selected_attempt_id IS NULL) THEN 'not_collected'::text
            WHEN (count(r.id) = 0) THEN 'complete_empty'::text
            ELSE 'complete_nonempty'::text
        END AS collection_state,
        CASE
            WHEN (c.selected_attempt_id IS NULL) THEN NULL::bigint
            ELSE count(r.id)
        END AS record_count
   FROM (((((((evidence_pipeline.collection_status c
     JOIN evidence_pipeline.authorized_connections ac ON ((ac.connection_id = c.connection_id)))
     LEFT JOIN evidence_pipeline.exposure_snapshots x ON ((x.collection_attempt_id = c.selected_attempt_id)))
     LEFT JOIN evidence_pipeline.assessment_runs a ON ((a.attempt_id = c.selected_attempt_id)))
     LEFT JOIN evidence_pipeline.input_device_scopes b ON ((b.input_connection_id = c.connection_id)))
     LEFT JOIN evidence_pipeline.assessment_bindings ab ON ((ab.connection_id = c.connection_id)))
     LEFT JOIN evidence_pipeline.collection_status d ON ((d.connection_id = COALESCE(b.device_connection_id, ab.device_connection_id))))
     LEFT JOIN evidence.observation_receipts r ON ((r.collection_attempt_id = c.selected_attempt_id)))
  WHERE ((c.source_name = 'Defender'::text) AND (c.input_kind = ANY (ARRAY['findings'::text, 'vulnerability_baseline'::text, 'vulnerability_events'::text])))
  GROUP BY c.connection_id, c.input_kind, c.source_name, c.tenant_id, ac.origin, c.selected_attempt_id, c.selected_finished_at, c.latest_attempt_id, c.latest_outcome, x.device_attempt_id, a.device_attempt_id, d.selected_attempt_id;


ALTER VIEW evidence_pipeline.vulnerability_collection_coverage OWNER TO tm_mock_owner;

--
-- Name: VIEW vulnerability_collection_coverage; Type: COMMENT; Schema: evidence_pipeline; Owner: tm_mock_owner
--

COMMENT ON VIEW evidence_pipeline.vulnerability_collection_coverage IS 'Registered Defender inputs. Empty event batches describe only that request window; empty snapshots are not proof a device is free of vulnerabilities. Latest failed attempts remain visible alongside last successful evidence.';


--
-- Name: completeness_fields; Type: TABLE; Schema: mock_support; Owner: tm_mock_owner
--

CREATE TABLE mock_support.completeness_fields (
    definition_id uuid NOT NULL,
    field_key text NOT NULL,
    value_kind text NOT NULL,
    CONSTRAINT completeness_fields_value_kind_check CHECK ((value_kind = ANY (ARRAY['boolean'::text, 'number'::text, 'text'::text])))
);


ALTER TABLE mock_support.completeness_fields OWNER TO tm_mock_owner;

--
-- Name: TABLE completeness_fields; Type: COMMENT; Schema: mock_support; Owner: tm_mock_owner
--

COMMENT ON TABLE mock_support.completeness_fields IS 'Mock-only support; not product policy.';


--
-- Name: findings; Type: VIEW; Schema: mock_support; Owner: tm_mock_owner
--

CREATE VIEW mock_support.findings AS
 SELECT id,
    title,
    asset,
    observation
   FROM ( VALUES ('SYN-001'::text,'Component update observation'::text,'fixture-host-a'::text,'Recorded'::text), ('SYN-002'::text,'Verification evidence gap'::text,'fixture-host-b'::text,NULL::text), ('SYN-003'::text,'Conflicting update observations'::text,'fixture-host-c'::text,'Conflicting records'::text)) legacy(id, title, asset, observation);


ALTER VIEW mock_support.findings OWNER TO tm_mock_owner;

--
-- Name: VIEW findings; Type: COMMENT; Schema: mock_support; Owner: tm_mock_owner
--

COMMENT ON VIEW mock_support.findings IS 'Mock-only legacy SQLite note compatibility; three synthetic display rows, not evidence.';


