-- Name: recommendation_devices defender_recommendation_device_insert; Type: POLICY; Schema: evidence; Owner: tm_mock_owner
--

CREATE POLICY defender_recommendation_device_insert ON evidence.recommendation_devices FOR INSERT TO tm_pipeline_writer WITH CHECK ((EXISTS ( SELECT 1
   FROM ((((((evidence.recommendations rec
     JOIN evidence_pipeline.recommendation_claims c ON ((c.receipt_id = rec.receipt_id)))
     JOIN evidence.observation_receipts r ON ((r.id = c.receipt_id)))
     JOIN evidence_pipeline.recommendation_runs run ON ((run.attempt_id = r.collection_attempt_id)))
     JOIN evidence.device_observations obs ON ((obs.provider_device_id = recommendation_devices.provider_device_id)))
     JOIN evidence.observation_receipts dr ON (((dr.id = obs.receipt_id) AND (dr.collection_attempt_id = run.device_attempt_id))))
     JOIN evidence.provider_devices p ON ((p.id = obs.provider_device_id)))
  WHERE ((rec.id = recommendation_devices.recommendation_id) AND (rec.receipt_id = recommendation_devices.receipt_id) AND ((c.claim -> 'native_device_ids'::text) ? p.native_device_id)))));


