   FROM evidence_pipeline.recommendation_claims c
  WHERE ((c.receipt_id = recommendations.receipt_id) AND ((c.claim ->> 'source_id'::text) = recommendations.source_recommendation_id) AND (((c.claim -> 'fields'::text) ->> 'title'::text) = recommendations.title))))));


