-- Name: advisory_cves msrcc_insert; Type: POLICY; Schema: evidence; Owner: tm_mock_owner
--

CREATE POLICY msrcc_insert ON evidence.advisory_cves FOR INSERT TO tm_pipeline_writer WITH CHECK ((EXISTS ( SELECT 1
   FROM (((((evidence.observation_receipts receipt
     JOIN evidence.collection_attempts attempt ON ((attempt.id = receipt.collection_attempt_id)))
     JOIN evidence.source_revisions revision ON (((revision.id = receipt.source_revision_id) AND (revision.connection_id = attempt.connection_id))))
     JOIN evidence_pipeline.public_claims claim ON ((claim.source_revision_id = revision.id)))
     JOIN evidence.source_connections c ON ((c.id = attempt.connection_id)))
     JOIN evidence_pipeline.authorized_connections authorized ON (((authorized.connection_id = c.id) AND (authorized.origin = revision.origin))))
  WHERE ((receipt.id = advisory_cves.receipt_id) AND attempt.complete AND (attempt.outcome = 'success'::text) AND (c.tenant_id IS NULL) AND (c.source_name = 'MSRC'::text) AND (c.input_kind = 'advisories'::text) AND (revision.source_record_id = advisory_cves.cve_id) AND (EXISTS ( SELECT 1
           FROM evidence.advisories p
          WHERE ((p.id = advisory_cves.advisory_id) AND (p.receipt_id = advisory_cves.receipt_id))))))));


