--
-- Name: assessment_observations assessment_observation_insert; Type: POLICY; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE POLICY assessment_observation_insert ON evidence_pipeline.assessment_observations FOR INSERT TO tm_pipeline_writer WITH CHECK ((EXISTS ( SELECT 1
   FROM (((evidence.observation_receipts r
     JOIN evidence_pipeline.assessment_runs run ON ((run.attempt_id = r.collection_attempt_id)))
     JOIN evidence.collection_attempts a ON ((a.id = run.attempt_id)))
     JOIN evidence_pipeline.assessment_bindings b ON ((b.connection_id = a.connection_id)))
  WHERE ((r.id = assessment_observations.receipt_id) AND (((assessment_observations.provider_device_id IS NOT NULL) AND (EXISTS ( SELECT 1
           FROM ((evidence.provider_devices p
             JOIN evidence.device_observations obs ON ((obs.provider_device_id = p.id)))
             JOIN evidence.observation_receipts dr ON (((dr.id = obs.receipt_id) AND (dr.collection_attempt_id = run.device_attempt_id))))
          WHERE ((p.id = assessment_observations.provider_device_id) AND (p.connection_id = b.device_connection_id) AND (p.native_device_id = (assessment_observations.claim ->> 'native_device_id'::text)))))) OR ((assessment_observations.provider_device_id IS NULL) AND (length((assessment_observations.claim ->> 'native_device_id'::text)) > 0) AND (NOT (EXISTS ( SELECT 1
           FROM ((evidence.provider_devices p
             JOIN evidence.device_observations obs ON ((obs.provider_device_id = p.id)))
             JOIN evidence.observation_receipts dr ON (((dr.id = obs.receipt_id) AND (dr.collection_attempt_id = run.device_attempt_id))))
          WHERE ((p.connection_id = b.device_connection_id) AND (p.native_device_id = (assessment_observations.claim ->> 'native_device_id'::text))))))))))));


