-- Name: assessment_runs assessment_run_insert; Type: POLICY; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE POLICY assessment_run_insert ON evidence_pipeline.assessment_runs FOR INSERT TO tm_pipeline_writer WITH CHECK ((EXISTS ( SELECT 1
   FROM (((((evidence.collection_attempts a
     JOIN evidence_pipeline.assessment_bindings b ON ((b.connection_id = a.connection_id)))
     JOIN evidence_pipeline.authorized_connections auth ON ((auth.connection_id = a.connection_id)))
     JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
     JOIN evidence.source_connections dc ON ((dc.id = b.device_connection_id)))
     JOIN evidence.collection_attempts d ON (((d.connection_id = b.device_connection_id) AND (d.id = assessment_runs.device_attempt_id))))
  WHERE ((c.source_name = 'Defender'::text) AND (dc.source_name = 'Defender'::text) AND (dc.input_kind = 'devices'::text) AND (c.tenant_id = dc.tenant_id) AND (c.input_kind = ANY (ARRAY['vulnerability_baseline'::text, 'vulnerability_events'::text])) AND (a.id = assessment_runs.attempt_id) AND a.complete AND (a.outcome = 'success'::text) AND d.complete AND (d.outcome = 'success'::text)))));


