     JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
     JOIN evidence_pipeline.authorized_connections auth ON ((auth.connection_id = c.id)))
     JOIN evidence.source_revisions rev ON (((rev.id = r.source_revision_id) AND (rev.connection_id = c.id))))
  WHERE ((r.id = catalogue_observations.receipt_id) AND (c.source_name = 'Defender'::text) AND (c.input_kind = 'vulnerability_catalogue'::text) AND (auth.origin = rev.origin) AND a.complete AND (a.outcome = 'success'::text)))));


