     JOIN evidence.source_connections c ON ((c.id = rev.connection_id)))
     JOIN evidence_pipeline.authorized_connections auth ON (((auth.connection_id = c.id) AND (auth.origin = rev.origin))))
  WHERE ((rev.id = public_claims.source_revision_id) AND (c.tenant_id IS NULL) AND (c.source_name = 'GitHub'::text) AND (c.input_kind = 'advisories'::text) AND (rev.source_record_id ~ '^GHSA(-[23456789cfghjmpqrvwx]{4}){3}$'::text) AND (rev.source_url = c.scope_reference) AND (c.scope_reference ~ '^https://raw[.]githubusercontent[.]com/github/advisory-database/[a-f0-9]{40}/advisories/(github-reviewed|unreviewed)/[0-9]{4}/(0[1-9]|1[0-2])/GHSA(-[23456789cfghjmpqrvwx]{4}){3}/GHSA(-[23456789cfghjmpqrvwx]{4}){3}[.]json$'::text) AND (c.scope_reference !~ '^https://raw[.]githubusercontent[.]com/github/advisory-database/0{40}/'::text) AND (c.scope_reference ~~ (((('%/'::text || rev.source_record_id) || '/'::text) || rev.source_record_id) || '.json'::text))))));


