CREATE POLICY public_claim_insert ON evidence_pipeline.public_claims FOR INSERT TO tm_pipeline_writer WITH CHECK ((EXISTS ( SELECT 1
   FROM ((evidence.source_revisions r
     JOIN evidence_pipeline.authorized_connections a ON (((a.connection_id = r.connection_id) AND (a.origin = r.origin))))
     JOIN evidence.source_connections c ON ((c.id = r.connection_id)))
  WHERE ((r.id = public_claims.source_revision_id) AND (c.tenant_id IS NULL) AND ((((c.source_name = 'FIRST'::text) AND (c.input_kind = 'epss'::text)) OR ((c.source_name = 'CISA'::text) AND (c.input_kind = 'kev'::text))) OR ((c.source_name = 'NVD'::text) AND (c.input_kind = 'vulnerabilities'::text)))))));


