--
-- Name: osv_query_advisory_links query_link_insert; Type: POLICY; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE POLICY query_link_insert ON evidence_pipeline.osv_query_advisory_links FOR INSERT TO tm_pipeline_writer WITH CHECK ((EXISTS ( SELECT 1
   FROM (((evidence_pipeline.osv_query_pages page
     JOIN evidence.collection_attempts a ON (((a.id = page.attempt_id) AND a.complete AND (a.outcome = 'success'::text))))
     JOIN evidence.observation_receipts r ON ((r.collection_attempt_id = a.id)))
     JOIN evidence_pipeline.public_claims p ON ((p.source_revision_id = r.source_revision_id)))
  WHERE ((page.attempt_id = osv_query_advisory_links.attempt_id) AND (page.page_index = osv_query_advisory_links.page_index) AND (r.id = osv_query_advisory_links.receipt_id) AND (((p.claim)::jsonb ->> 'adapter'::text) = 'osv-record-v1'::text) AND (page.record_hashes[(osv_query_advisory_links.record_index + 1)] = encode(sha256(convert_to(((((p.claim)::jsonb ->> 'source_document'::text))::jsonb)::text, 'UTF8'::name)), 'hex'::text))))));


--
-- Name: osv_query_pages query_page_insert; Type: POLICY; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE POLICY query_page_insert ON evidence_pipeline.osv_query_pages FOR INSERT TO tm_pipeline_writer WITH CHECK ((EXISTS ( SELECT 1
   FROM (evidence_pipeline.osv_query_batches b
     JOIN evidence.collection_attempts a ON ((a.id = b.attempt_id)))
  WHERE ((b.attempt_id = osv_query_pages.attempt_id) AND ((((((b.manifest)::jsonb -> 0) -> 'pages'::text) -> osv_query_pages.page_index) ->> 'fingerprint'::text) = encode(sha256(osv_query_pages.wire), 'hex'::text)) AND (osv_query_pages.record_hashes =
        CASE
            WHEN a.complete THEN evidence_pipeline.osv_query_record_hashes(osv_query_pages.wire)
            ELSE ARRAY[]::text[]
        END)))));


