CREATE POLICY recommendation_claim_insert ON evidence_pipeline.recommendation_claims FOR INSERT TO tm_pipeline_writer WITH CHECK ((EXISTS ( SELECT 1
   FROM (((evidence.observation_receipts r
     JOIN evidence_pipeline.recommendation_runs run ON ((run.attempt_id = r.collection_attempt_id)))
     JOIN evidence.collection_attempts a ON ((a.id = run.attempt_id)))
     JOIN evidence.source_revisions rev ON (((rev.id = r.source_revision_id) AND (rev.connection_id = a.connection_id))))
  WHERE ((r.id = recommendation_claims.receipt_id) AND (rev.source_record_id = (recommendation_claims.claim ->> 'source_id'::text))))));


