--
-- Name: recommendation_runs recommendation_run_insert; Type: POLICY; Schema: evidence_pipeline; Owner: tm_mock_owner
--

CREATE POLICY recommendation_run_insert ON evidence_pipeline.recommendation_runs FOR INSERT TO tm_pipeline_writer WITH CHECK ((EXISTS ( SELECT 1
   FROM ((((((evidence.collection_attempts a
     JOIN evidence_pipeline.recommendation_bindings b ON ((b.connection_id = a.connection_id)))
     JOIN evidence.source_connections c ON ((c.id = a.connection_id)))
     JOIN evidence.source_connections dc ON ((dc.id = b.device_connection_id)))
     JOIN evidence_pipeline.authorized_connections auth ON ((auth.connection_id = c.id)))
     JOIN evidence_pipeline.authorized_connections da ON (((da.connection_id = dc.id) AND (da.origin = auth.origin))))
     JOIN evidence.collection_attempts d ON ((d.connection_id = dc.id)))
  WHERE ((a.id = recommendation_runs.attempt_id) AND (d.id = recommendation_runs.device_attempt_id) AND (c.source_name = 'Defender'::text) AND (c.input_kind = 'recommendations'::text) AND (dc.source_name = 'Defender'::text) AND (dc.input_kind = 'devices'::text) AND (dc.tenant_id = c.tenant_id) AND a.complete AND (a.outcome = 'success'::text) AND d.complete AND (d.outcome = 'success'::text)))));


