CREATE POLICY vendor_advisory_synthetic_only ON evidence_pipeline.public_claims AS RESTRICTIVE FOR INSERT TO tm_pipeline_writer WITH CHECK ((NOT (EXISTS ( SELECT 1
   FROM (evidence.source_revisions r
     JOIN evidence.source_connections c ON ((c.id = r.connection_id)))
  WHERE ((r.id = public_claims.source_revision_id) AND (c.source_name = 'Cisco'::text) AND (r.origin <> 'synthetic'::text) AND (NOT ((c.tenant_id IS NULL) AND (r.source_url = c.scope_reference) AND evidence_pipeline.reference_source_allowed(c.source_name, c.input_kind, c.scope_reference) AND (c.scope_reference ~~ 'https://sec.cloudapps.cisco.com/security/center/content/CiscoSecurityAdvisory/%'::text) AND (r.source_record_id = split_part(c.scope_reference, '/'::text, 8)))))))));


